// Kronos (Alpha Roadmap Phase 9, "Platform Services" -- "Plugin
// marketplace (local only for alpha)").
void testScanLocalPluginDirectoryDiscoversRealManifests() {
    const char* dir = "test_plugin_directory";
    std::filesystem::create_directory(dir);

    {
        engine::studio::PluginManifest a;
        a.name = "Alpha Plugin";
        a.version = "1.0.0";
        check(a.saveToFile(std::string(dir) + "/alpha.manifest"), "real manifest A saves for the scan test");
    }
    {
        engine::studio::PluginManifest b;
        b.name = "Beta Plugin";
        b.version = "2.0.0";
        check(b.saveToFile(std::string(dir) + "/beta.manifest"), "real manifest B saves for the scan test");
    }
    {
        // A non-.manifest file in the same real directory must be
        // real-ignored, not misidentified as a plugin.
        std::ofstream out(std::string(dir) + "/readme.txt");
        out << "not a plugin manifest\n";
    }

    std::vector<engine::studio::DiscoveredPlugin> discovered = engine::studio::scanLocalPluginDirectory(dir);
    check(discovered.size() == 2, "scanLocalPluginDirectory() real-finds exactly the two real .manifest files, "
                                   "real-ignoring the non-manifest file in the same directory");

    bool foundAlpha = false, foundBeta = false;
    for (const auto& d : discovered) {
        check(d.parseSucceeded, "each real discovered manifest real-parses successfully");
        if (d.manifest.name == "Alpha Plugin") foundAlpha = true;
        if (d.manifest.name == "Beta Plugin") foundBeta = true;
    }
    check(foundAlpha && foundBeta, "both real manifests' real names are correctly parsed, not just counted");

    std::filesystem::remove_all(dir);
}

