// Kronos (Alpha Roadmap Phase 5, "Plugin System Expansion" -- "Plugin
// lifecycle events... onUnload"): real events.onUnload() coverage at the
// core::Scripting level, headless, no ECS/plugin machinery needed.
// Kronos (Alpha Completion Checklist, "Engine Validation Pass" -- "Validate
// all plugin lifecycle events"): events.onUpdate/onCollision/onInteract
// (and their C++ firing halves, Scripting::tick()/fireCollision()/
// fireInteract()) are the core scheduler/gameplay event bus every
// gameplay script and scripted plugin relies on -- and had genuinely zero
// direct test coverage anywhere before this, despite predating this
// session entirely. Closed here.
void testScriptingOnUpdateFiresEveryTickWithRealDt() {
    engine::core::Scripting scripting;
    check(scripting.initialize(), "onUpdate test: Scripting::initialize() succeeds");
    std::vector<std::string> output;
    scripting.setOutputCallback([&](const std::string& line) { output.push_back(line); });

    engine::core::ScriptId id = scripting.loadAndRun("UpdateTest", "events.onUpdate(function(dt)\n"
                                                                    "  print(\"tick dt=\" .. tostring(dt))\n"
                                                                    "end)\n");
    check(id != engine::core::kInvalidScript, "onUpdate test: the real script real-loads and real-registers a handler");

    bool sawTickBeforeAnyTick = false;
    for (const auto& line : output)
        if (line.find("tick dt=") != std::string::npos) sawTickBeforeAnyTick = true;
    check(!sawTickBeforeAnyTick, "onUpdate test: merely registering a real handler does NOT fire it before any real tick()");

    scripting.tick(0.25f);
    bool sawFirstTick = false;
    for (const auto& line : output)
        if (line.find("tick dt=0.25") != std::string::npos) sawFirstTick = true;
    check(sawFirstTick, "tick() really fires events.onUpdate() with the real dt passed to it");

    output.clear();
    scripting.tick(0.5f);
    scripting.tick(0.5f);
    int tickCount = 0;
    for (const auto& line : output)
        if (line.find("tick dt=") != std::string::npos) ++tickCount;
    check(tickCount == 2, "two real tick() calls really fire the real handler exactly twice, not once and not zero");

    scripting.shutdown();
}

