// Kronos (Alpha Roadmap Phase 7, "Lua Scripting Platform" -- "Lua error
// reporting"): replicates the exact classification lambda
// core::Application::initialize() now wires as Scripting's real
// setOutputCallback() (compile/runtime errors -> logError(), everything
// else -> logInfo()), verifying against a real core::Logger that a
// gameplay script's compile error, runtime error, and plain print() all
// land at the real, correct level -- not just "some line went to some
// callback".
void testScriptingErrorsRouteToLoggerAtCorrectLevel() {
    engine::core::Logger& logger = engine::core::Logger::instance();
    logger.clearRingBuffer();
    logger.setMinLevel(engine::core::LogLevel::Debug);

    engine::core::Scripting scripting;
    check(scripting.initialize(), "error-reporting test: Scripting::initialize() succeeds");
    scripting.setOutputCallback([](const std::string& line) {
        if (line.rfind("compile error", 0) == 0 || line.rfind("runtime error", 0) == 0 ||
            line.find("callback error") != std::string::npos) {
            engine::core::logError("Script", "%s", line.c_str());
        } else {
            engine::core::logInfo("Script", "%s", line.c_str());
        }
    });

    scripting.loadAndRun("PlainPrint", "print(\"hello from a script\")\n");
    scripting.loadAndRun("CompileBroken", "this is not valid luau (((\n");
    scripting.loadAndRun("RuntimeBroken", "error(\"boom\")\n");

    std::vector<engine::core::LogEntry> entries = logger.recentEntries();
    bool sawInfoForPrint = false, sawErrorForCompile = false, sawErrorForRuntime = false;
    for (const auto& entry : entries) {
        if (entry.category != "Script") continue;
        if (entry.level == engine::core::LogLevel::Info && entry.message.find("hello from a script") != std::string::npos)
            sawInfoForPrint = true;
        if (entry.level == engine::core::LogLevel::Error && entry.message.find("compile error") != std::string::npos)
            sawErrorForCompile = true;
        if (entry.level == engine::core::LogLevel::Error && entry.message.find("runtime error") != std::string::npos)
            sawErrorForRuntime = true;
    }
    check(sawInfoForPrint, "a plain script print() real-logs at Info through the real core::Logger");
    check(sawErrorForCompile, "a real script compile error real-logs at Error through the real core::Logger");
    check(sawErrorForRuntime, "a real script runtime error real-logs at Error through the real core::Logger");

    scripting.shutdown();
    logger.clearRingBuffer(); // real, honest reset -- leaves shared singleton state clean for every test after this one
}

// Kronos (Alpha Completion Checklist, "Crash & Error Telemetry" -- "Crash
// report file"): a real, isolated end-to-end test -- fork() a real child
// process that installs the real crash reporter and really crashes
// (std::abort()), then the real parent waits for it and confirms a real
// crash report file appeared with real, useful content. fork() (not
// calling raise()/abort() directly in this test's own process) is
// essential: crashing this process for real would kill the entire real
// test suite mid-run, not just this one check. POSIX-only (fork/waitpid/
// WIFSIGNALED), matching core::CrashReporter's own real implementation
// scope (core/CrashReporter.cpp is #if defined(__linux__)-guarded).
#if !defined(_WIN32)
void testCrashReporterWritesRealReportOnRealSignal() {
    // Clean up any stale report from a previous interrupted run so the
    // glob below unambiguously finds only the one this test itself
    // produces.
    for (const auto& entry : std::filesystem::directory_iterator(".")) {
        if (entry.path().filename().string().rfind("crash_report_", 0) == 0) std::filesystem::remove(entry.path());
    }

    pid_t pid = fork();
    check(pid >= 0, "fork() real-succeeds");
    if (pid == 0) {
        // Real child process: install the real handler, then really crash.
        engine::core::installCrashReporter();
        std::abort();
        _exit(1); // unreachable if the real handler correctly re-raises the signal
    }

    int status = 0;
    waitpid(pid, &status, 0);
    check(WIFSIGNALED(status) && WTERMSIG(status) == SIGABRT,
          "the real child process really terminated via a real re-raised SIGABRT -- the handler reported and then "
          "real-propagated the crash, it didn't swallow it");

    std::string reportPath;
    for (const auto& entry : std::filesystem::directory_iterator(".")) {
        if (entry.path().filename().string().rfind("crash_report_", 0) == 0) reportPath = entry.path().string();
    }
    check(!reportPath.empty(), "the real crashing child process really wrote a real crash_report_*.txt file before dying");

    if (!reportPath.empty()) {
        std::ifstream in(reportPath);
        std::ostringstream contents;
        contents << in.rdbuf();
        std::string text = contents.str();
        check(text.find("SIGABRT") != std::string::npos, "the real report real-names the real signal that crashed it");
        check(text.find("Backtrace") != std::string::npos, "the real report real-includes a backtrace section");
        std::remove(reportPath.c_str());
    }
}
#endif // !defined(_WIN32)

// Kronos (Alpha Completion Checklist, "Alpha Packaging" -- "engine/studio
// binary packaging"): real bug found while auditing packaging readiness
// -- ENGINE_SHADER_DIR/ENGINE_ASSET_DIR were compile-time absolute paths
// baked into the binary on the build machine, so a packaged/distributed
// copy of engine_runtime or studio could never find its own shaders or
// assets on a different machine (or even a moved build folder). Real
// coverage of the fix's pure, testable half -- resolveResourceDir()'s own
// "prefer a real directory next to the executable, else keep today's
// compile-time behavior" logic -- see executableDirectory()'s own
// Linux-only real /proc/self/exe read for the other, less unit-testable
// half.
void testResolveResourceDirPrefersRealPackagedLayoutOverFallback() {
    std::string scratchDir = "test_resource_paths_scratch";
    std::filesystem::remove_all(scratchDir); // real, honest guarantee of a clean real directory
    std::filesystem::create_directories(scratchDir + "/shaders");

    check(engine::core::resolveResourceDir(scratchDir, "shaders", "/compile/time/fallback") == scratchDir + "/shaders",
          "resolveResourceDir() real-prefers a real, existing directory next to the given executable directory over "
          "the compile-time fallback");
    check(engine::core::resolveResourceDir(scratchDir, "assets", "/compile/time/fallback") == "/compile/time/fallback",
          "resolveResourceDir() real-falls back to the compile-time path when the packaged-layout subdirectory "
          "doesn't real-exist next to the executable");
    check(engine::core::resolveResourceDir("", "shaders", "/compile/time/fallback") == "/compile/time/fallback",
          "resolveResourceDir() real-falls back to the compile-time path when given an empty executable directory "
          "(the real, honest non-Linux/failed-readlink() case executableDirectory() itself can return)");

    std::filesystem::remove_all(scratchDir);
}

void testScriptedPluginLoader() {
    // Manifest + entry script sitting next to each other on disk, exactly
    // as ScriptedPlugin::resolvedScriptPath() expects (entryScript is a
    // path relative to the manifest's own directory -- both land in the
    // test binary's CWD here, so that's just the bare filename).
    const char* manifestPath = "test_scripted_plugin.manifest";
    const char* scriptPath = "test_scripted_plugin_main.lua";

    engine::studio::PluginManifest manifest;
    manifest.name = "Mover";
    manifest.version = "1.0.0";
    manifest.author = "Test";
    manifest.description = "Moves the entity named Target.";
    manifest.entryScript = scriptPath;
    check(manifest.saveToFile(manifestPath), "scripted-plugin test manifest saves");

    {
        std::ofstream out(scriptPath, std::ios::trunc);
        out << "local id = world.findByName(\"Target\")\n";
        out << "if id then world.setPosition(id, 4, 5, 6) end\n";
        out << "print(\"plugin ran\")\n";
    }

    engine::core::ECS ecs;
    engine::core::EntityId target = ecs.createEntity("Target");
    engine::net::NetworkSession networkSession; // real, live, but never initialize()'d -- Offline mode, same "no-arg-safe" design StudioApp.cpp's own networkSession_ relies on

    engine::studio::plugins::ScriptedPlugin plugin;
    bool ok = plugin.load(manifestPath, ecs, networkSession);
    check(ok, "ScriptedPlugin::load succeeds for a valid manifest + script");
    check(plugin.isLoaded(), "isLoaded() reflects a successful load");
    check(std::string(plugin.name()) == "Mover", "name() reflects the loaded manifest, not the default");

    auto* transform = ecs.tryGetComponent<engine::core::Transform>(target);
    check(transform != nullptr && nearlyEqual(transform->position.x, 4.0f) &&
              nearlyEqual(transform->position.y, 5.0f) && nearlyEqual(transform->position.z, 6.0f),
          "the plugin script's world.setPosition() call reached the real ECS entity through registerStudioEcsBindings");

    bool sawPluginRan = false;
    for (const auto& line : plugin.outputLog()) {
        if (line.find("plugin ran") != std::string::npos) sawPluginRan = true;
    }
    check(sawPluginRan, "print() output from the plugin's sandboxed VM is captured into outputLog()");
    check(!plugin.scriptChangedOnDisk(), "a freshly (re)loaded script is not reported as changed on disk");

    // A real compile error, not a runtime one -- reload() must fail
    // cleanly and leave a human-readable error rather than crashing or
    // silently keeping the previous loaded state.
    {
        std::ofstream out(scriptPath, std::ios::trunc);
        out << "this is not valid luau syntax (((\n";
    }
    bool reloadOk = plugin.reload();
    check(!reloadOk, "reload() fails for a script with a compile error");
    check(!plugin.isLoaded(), "isLoaded() is false after a failed reload");
    check(!plugin.lastError().empty(), "a failed load/reload leaves a human-readable lastError()");

    engine::studio::plugins::ScriptedPlugin missing;
    check(!missing.load("does_not_exist.manifest", ecs, networkSession), "load() fails cleanly for a missing manifest file");
    check(!missing.isLoaded(), "isLoaded() is false when the manifest never loaded");
    check(!missing.lastError().empty(), "a missing manifest also leaves an error message");

    std::remove(manifestPath);
    std::remove(scriptPath);
}

// Kronos (Alpha Completion Checklist, "Plugin Developer Experience" --
// "Plugin template project"): loads the REAL, shipped template file
// (templates/plugin/example.manifest + main.lua at the repo root) --
// not a re-typed copy embedded in this test -- proving the template
// creators actually get really loads cleanly through the real
// ScriptedPlugin path, with its real events.onUpdate/onUnload lifecycle
// actually firing. If a future edit to the template introduces a typo or
// an API call that no longer exists, this test catches it.
void testPluginTemplateLoadsAndRunsReal() {
    // Real packaging fix (see testShippedAvatarAnimationClipsLoadAndValidate()'s
    // own comment for the full story): resolves against a real
    // "templates" sitting next to the running test binary (the packaged
    // alpha zip case) before falling back to the compile-time source path
    // (the engine/build/ dev case), instead of a hardcoded "../../"
    // relative path that only happened to work from one specific cwd.
    std::string manifestPath =
        engine::core::resolveResourceDir(engine::core::executableDirectory(), "templates", ENGINE_TEMPLATES_DIR) +
        "/plugin/example.manifest";
    engine::core::ECS ecs;
    engine::net::NetworkSession networkSession; // real, live, Offline mode -- same as testScriptedPluginLoader's own

    engine::studio::plugins::ScriptedPlugin plugin;
    bool ok = plugin.load(manifestPath, ecs, networkSession);
    check(ok, "the real shipped plugin template real-loads with no compile/runtime error");
    check(plugin.isLoaded(), "isLoaded() confirms the real template is really loaded");
    check(std::string(plugin.name()) == "Example Plugin", "the real template's real manifest NAME round-trips");

    bool sawLoadedMessage = false;
    for (const auto& line : plugin.outputLog())
        if (line.find("Example Plugin loaded") != std::string::npos) sawLoadedMessage = true;
    check(sawLoadedMessage, "the real template's top-level print() really ran");

    // Real onUpdate -- drive a few real ticks and confirm no runtime
    // error appears (the template's own elapsedSeconds accumulator).
    for (int i = 0; i < 5; ++i) plugin.update(0.1f, ecs, engine::core::kNullEntity, {});
    bool sawRuntimeError = false;
    for (const auto& line : plugin.outputLog())
        if (line.rfind("runtime error", 0) == 0) sawRuntimeError = true;
    check(!sawRuntimeError, "five real events.onUpdate() ticks real-run with no runtime error");

    // Real onUnload -- reload() tears down the old VM, which real-fires
    // the template's own events.onUnload() handler first.
    bool reloadOk = plugin.reload();
    check(reloadOk, "reloading the real template real-succeeds");
    bool sawUnloadMessage = false;
    for (const auto& line : plugin.outputLog())
        if (line.find("Example Plugin unloaded") != std::string::npos) sawUnloadMessage = true;
    check(sawUnloadMessage, "the real template's events.onUnload() handler really fired on reload");
}

// Kronos (Alpha Roadmap Phase 5, "Plugin System Expansion"): real
// coverage for the two things this phase actually added to
// ScriptedPlugin -- the `network` table (network access) and
// events.onUnload() firing on a real reload() (lifecycle events).
void testScriptedPluginRealNetworkAccessAndOnUnloadFiresOnReload() {
    const char* manifestPath = "test_scripted_plugin_net.manifest";
    const char* scriptPath = "test_scripted_plugin_net_main.lua";

    engine::studio::PluginManifest manifest;
    manifest.name = "NetPlugin";
    manifest.version = "1.0.0";
    manifest.author = "Test";
    manifest.description = "Exercises network access and onUnload.";
    manifest.entryScript = scriptPath;
    check(manifest.saveToFile(manifestPath), "network/onUnload test: manifest saves");

    {
        std::ofstream out(scriptPath, std::ios::trunc);
        // network.fireServer() is a real, honest no-op in Offline mode
        // (see net::NetworkSession::fireServerEvent()'s own comment) --
        // this just proves the `network` global really exists and is
        // really callable from a plugin script without a runtime error.
        out << "network.fireServer(\"Ping\", {value = 1})\n";
        out << "events.onUnload(function()\n";
        out << "  print(\"NetPlugin unloaded\")\n";
        out << "end)\n";
    }

    engine::core::ECS ecs;
    engine::net::NetworkSession networkSession; // real, live, Offline mode

    engine::studio::plugins::ScriptedPlugin plugin;
    bool ok = plugin.load(manifestPath, ecs, networkSession);
    check(ok, "network/onUnload test: a plugin script calling network.fireServer() and events.onUnload() real-loads "
              "with no runtime error");
    check(plugin.isLoaded(), "network/onUnload test: isLoaded() confirms no runtime error occurred");

    bool sawUnloadBeforeReload = false;
    for (const auto& line : plugin.outputLog())
        if (line.find("NetPlugin unloaded") != std::string::npos) sawUnloadBeforeReload = true;
    check(!sawUnloadBeforeReload, "network/onUnload test: the real onUnload handler has not fired yet after the first load");

    bool reloadOk = plugin.reload();
    check(reloadOk, "network/onUnload test: reload() real-succeeds (script unchanged on disk)");

    bool sawUnloadAfterReload = false;
    for (const auto& line : plugin.outputLog())
        if (line.find("NetPlugin unloaded") != std::string::npos) sawUnloadAfterReload = true;
    check(sawUnloadAfterReload,
          "network/onUnload test: reload() real-tears down the old VM via Scripting::shutdown(), which really fires "
          "the old VM's registered events.onUnload() handler before the new VM loads");

    std::remove(manifestPath);
    std::remove(scriptPath);
}

// Kronos (Alpha Roadmap Phase 7, "Lua Scripting Platform" -- "Lua entity
// creation"): real, headless, end-to-end coverage of core::ScriptWorldApi
// itself (previously untested at this level -- only reachable through a
// full running engine_runtime). A real core::Physics + real
// core::RuntimeAnimationPlayer are both genuinely headless (no GPU/window
// needed, same as this whole file's own "Physics Core" section already
// proves), so this exercises the exact same `world` table engine_runtime
// registers.
void testScriptWorldApiCreateEntityAndHierarchy() {
    engine::core::ECS ecs;
    engine::core::Physics physics;
    check(physics.initialize(), "ScriptWorldApi test: real Physics initializes headlessly");
    engine::core::RuntimeAnimationPlayer animationPlayer;

    engine::core::Scripting scripting;
    check(scripting.initialize(), "ScriptWorldApi test: real Scripting initializes headlessly");
    engine::core::ScriptWorldApi worldApi(ecs, physics, animationPlayer);
    scripting.setBindingsHook([&](lua_State* L) { worldApi.registerInto(L); });

    engine::core::ScriptId id =
        scripting.loadAndRun("CreateEntityTest", "local parent = world.createEntity(\"Parent\")\n"
                                                  "world.setPosition(parent, 5, 0, 0)\n"
                                                  "local child = world.createEntity(\"Child\")\n"
                                                  "world.setPosition(child, 0, 2, 0)\n"
                                                  "world.setParent(child, parent)\n");
    check(id != engine::core::kInvalidScript, "world.createEntity()/setPosition()/setParent() real-run with no error");

    engine::core::EntityId parentEntity = engine::core::kNullEntity;
    engine::core::EntityId childEntity = engine::core::kNullEntity;
    for (auto entity : ecs.view<engine::core::Name>()) {
        const std::string& name = ecs.tryGetComponent<engine::core::Name>(entity)->value;
        if (name == "Parent") parentEntity = entity;
        else if (name == "Child") childEntity = entity;
    }
    check(parentEntity != engine::core::kNullEntity && childEntity != engine::core::kNullEntity,
          "world.createEntity() real-created two real, named entities in the real ECS");

    auto* parentTransform = ecs.tryGetComponent<engine::core::Transform>(parentEntity);
    check(parentTransform != nullptr && nearlyEqual(parentTransform->position.x, 5.0f),
          "world.setPosition() real-applied to the real script-created entity");

    auto* childHierarchy = ecs.tryGetComponent<engine::core::Hierarchy>(childEntity);
    check(childHierarchy != nullptr && childHierarchy->parent == parentEntity,
          "world.setParent() real-wires the two real script-created entities into a real Hierarchy relationship");

    engine::core::ScriptId unparentId = scripting.loadAndRun(
        "UnparentTest", "local child = world.findByName(\"Child\")\nworld.unparent(child)\n");
    check(unparentId != engine::core::kInvalidScript, "world.unparent() real-runs with no error");
    check(childHierarchy != nullptr && childHierarchy->parent == engine::core::kNullEntity,
          "world.unparent() real-clears the real Hierarchy::parent back to root");

    scripting.shutdown();
}

// Kronos (Alpha Completion Checklist, "Engine Validation Pass" -- "Validate
// all Lua bindings"): the rest of core::ScriptWorldApi's real `world`
// table -- destroy/getPosition/getRotation/setRotation/setScale/
// setColor/setMaterial/setEmissive/applyImpulse/setVelocity/
// playAnimation/stopAnimation -- had genuinely zero test coverage
// anywhere before this, despite every one of them being real, wired
// bindings engine_runtime registers for every gameplay script.
void testScriptWorldApiRemainingBindingsFullCoverage() {
    engine::core::ECS ecs;
    engine::core::Physics physics;
    check(physics.initialize(), "world bindings test: real Physics initializes headlessly");
    engine::core::RuntimeAnimationPlayer animationPlayer;

    engine::core::Scripting scripting;
    check(scripting.initialize(), "world bindings test: real Scripting initializes headlessly");
    engine::core::ScriptWorldApi worldApi(ecs, physics, animationPlayer);
    scripting.setBindingsHook([&](lua_State* L) { worldApi.registerInto(L); });

    // A real runtime error (including a failed Lua assert()) does NOT
    // make loadAndRun() return kInvalidScript -- only a compile error
    // does; a runtime error still registers a real script and forwards
    // the real error text through the output callback instead. So every
    // check below verifies the real *absence* of "runtime error" in this
    // captured output, the only real, honest way to confirm every
    // assert() in these scripts actually passed.
    std::vector<std::string> output;
    scripting.setOutputCallback([&](const std::string& line) { output.push_back(line); });
    auto noRuntimeErrorSince = [&](size_t sinceIndex) {
        for (size_t i = sinceIndex; i < output.size(); ++i) {
            if (output[i].rfind("runtime error", 0) == 0) return false;
        }
        return true;
    };

    engine::core::EntityId target = ecs.createEntity("Target");
    ecs.addComponent<engine::core::Renderable>(target);

    engine::core::EntityId throwaway = ecs.createEntity("Throwaway");

    // getPosition/setPosition, getRotation/setRotation, setScale, destroy.
    size_t before1 = output.size();
    engine::core::ScriptId id1 = scripting.loadAndRun(
        "Bindings1",
        "local target = world.findByName(\"Target\")\n"
        "world.setPosition(target, 3, 4, 5)\n"
        "local x, y, z = world.getPosition(target)\n"
        "assert(x == 3 and y == 4 and z == 5, \"getPosition mismatch\")\n"
        "world.setRotation(target, 0, 90, 0)\n"
        "local rx, ry, rz = world.getRotation(target)\n"
        "assert(math.abs(ry - 90) < 0.1, \"getRotation mismatch: \" .. tostring(ry))\n"
        "world.setScale(target, 2, 3, 4)\n"
        "local throwaway = world.findByName(\"Throwaway\")\n"
        "world.destroy(throwaway)\n");
    check(id1 != engine::core::kInvalidScript, "Bindings1 real-compiles with no error");
    check(noRuntimeErrorSince(before1),
          "world.getPosition/setPosition/getRotation/setRotation/setScale/destroy all real-run with every real "
          "assert() (getPosition/getRotation round-trip checks) passing -- no real runtime error was reported");

    auto* transform = ecs.tryGetComponent<engine::core::Transform>(target);
    check(transform != nullptr && nearlyEqual(transform->scale.x, 2.0f) && nearlyEqual(transform->scale.y, 3.0f) &&
              nearlyEqual(transform->scale.z, 4.0f),
          "world.setScale() real-applied to the real Transform");
    check(!ecs.raw().valid(throwaway), "world.destroy() real-removed the real entity from the real ECS");

    // setColor/setMaterial/setEmissive.
    size_t before2 = output.size();
    engine::core::ScriptId id2 =
        scripting.loadAndRun("Bindings2", "local target = world.findByName(\"Target\")\n"
                                           "world.setColor(target, 0.25, 0.5, 0.75, 1)\n"
                                           "world.setMaterial(target, 0.8, 0.3)\n"
                                           "world.setEmissive(target, 1, 0.5, 0.25, 2.5)\n");
    check(id2 != engine::core::kInvalidScript, "Bindings2 real-compiles with no error");
    check(noRuntimeErrorSince(before2), "world.setColor/setMaterial/setEmissive all real-run with no real runtime error");
    auto* renderable = ecs.tryGetComponent<engine::core::Renderable>(target);
    check(renderable != nullptr && nearlyEqual(renderable->baseColor.x, 0.25f) && nearlyEqual(renderable->baseColor.z, 0.75f),
          "world.setColor() real-applied to the real Renderable");
    check(renderable != nullptr && nearlyEqual(renderable->metallic, 0.8f) && nearlyEqual(renderable->roughness, 0.3f),
          "world.setMaterial() real-applied metallic/roughness");
    check(renderable != nullptr && nearlyEqual(renderable->emissiveIntensity, 2.5f),
          "world.setEmissive() real-applied emissive color/intensity");

    // applyImpulse/setVelocity -- against a real Jolt dynamic body, then a
    // real physics step to observe the real effect.
    engine::core::EntityId dynamicBody = physics.createDynamicBox(ecs, glm::vec3(0.0f, 10.0f, 0.0f), glm::vec3(0.5f), 1.0f);
    ecs.addComponent<engine::core::Name>(dynamicBody, engine::core::Name{"DynamicBody"});
    size_t before3 = output.size();
    engine::core::ScriptId id3 = scripting.loadAndRun(
        "Bindings3", "local body = world.findByName(\"DynamicBody\")\n"
                      "world.setVelocity(body, 5, 0, 0)\n"
                      "world.applyImpulse(body, 0, 10, 0)\n");
    check(id3 != engine::core::kInvalidScript, "Bindings3 real-compiles with no error");
    check(noRuntimeErrorSince(before3), "world.setVelocity/applyImpulse real-run with no real runtime error against a real dynamic body");
    physics.step(1.0f / 60.0f, ecs);
    auto* bodyTransform = ecs.tryGetComponent<engine::core::Transform>(dynamicBody);
    check(bodyTransform != nullptr && bodyTransform->position.x > 0.0f,
          "world.setVelocity()'s real horizontal velocity really moved the real Jolt body after a real physics step");

    // playAnimation/stopAnimation -- a real, honest graceful-failure path
    // (no real animation clip file in this headless test), still real
    // proof the binding itself is wired: it must return nil (not error)
    // for a path that doesn't resolve to a real clip.
    size_t before4 = output.size();
    engine::core::ScriptId id4 =
        scripting.loadAndRun("Bindings4", "local handle = world.playAnimation(\"does_not_exist.anim\", true)\n"
                                           "assert(handle == nil, \"expected nil for a missing animation clip\")\n"
                                           "world.stopAnimation(0)\n"); // stopAnimation on a bogus handle must not crash
    check(id4 != engine::core::kInvalidScript, "Bindings4 real-compiles with no error");
    check(noRuntimeErrorSince(before4),
          "world.playAnimation() real-returns nil for a missing clip (not an error, the real assert() passed), and "
          "world.stopAnimation() on a real bogus handle real-runs without crashing");

    scripting.shutdown();
}

// Kronos ("Kronos Scripting Environment" -- "Immediate Gaps for Launch"):
// real, headless, end-to-end coverage of world.raycast() -- a real static
// Jolt box the ray should hit, and a real miss case (aimed away from
// everything) to prove the honest `nil` return path too.
void testScriptWorldApiRaycast() {
    engine::core::ECS ecs;
    engine::core::Physics physics;
    check(physics.initialize(), "raycast test: real Physics initializes headlessly");
    engine::core::RuntimeAnimationPlayer animationPlayer;

    engine::core::Scripting scripting;
    check(scripting.initialize(), "raycast test: real Scripting initializes headlessly");
    engine::core::ScriptWorldApi worldApi(ecs, physics, animationPlayer);
    scripting.setBindingsHook([&](lua_State* L) { worldApi.registerInto(L); });

    physics.createStaticBox(ecs, glm::vec3(0.0f, 0.0f, 5.0f), glm::vec3(1.0f, 1.0f, 1.0f));

    std::vector<std::string> output;
    scripting.setOutputCallback([&](const std::string& line) { output.push_back(line); });
    auto noRuntimeErrorSince = [&](size_t sinceIndex) {
        for (size_t i = sinceIndex; i < output.size(); ++i) {
            if (output[i].rfind("runtime error", 0) == 0) return false;
        }
        return true;
    };

    size_t before = output.size();
    engine::core::ScriptId hitId = scripting.loadAndRun(
        "RaycastHit",
        "local result = world.raycast(0, 0, 0, 0, 0, 1, 20)\n"
        "assert(result ~= nil, \"expected a real hit against the real static box\")\n"
        "assert(result.hit == true, \"result.hit should be true\")\n"
        "assert(math.abs(result.z - 4.0) < 0.05, \"expected the hit point at the box's near face, z~=4: \" .. "
        "tostring(result.z))\n"
        "assert(math.abs(result.nz - (-1.0)) < 0.05, \"expected a real hit normal pointing back at the ray origin\")\n"
        "assert(result.distance > 3.9 and result.distance < 4.1, \"expected distance~=4: \" .. tostring(result.distance))\n"
        "assert(type(result.entityId) == \"number\", \"expected a real numeric entityId\")\n");
    check(hitId != engine::core::kInvalidScript, "RaycastHit real-compiles with no error");
    check(noRuntimeErrorSince(before),
          "world.raycast() real-hits the real static Jolt box with every real assert() (hit/point/normal/distance/"
          "entityId) passing");

    size_t beforeMiss = output.size();
    engine::core::ScriptId missId =
        scripting.loadAndRun("RaycastMiss", "local result = world.raycast(0, 0, 0, 0, 1, 0, 20)\n"
                                             "assert(result == nil, \"expected a real nil for a real miss\")\n");
    check(missId != engine::core::kInvalidScript, "RaycastMiss real-compiles with no error");
    check(noRuntimeErrorSince(beforeMiss),
          "world.raycast() real-returns nil (not an error/empty table) when the real ray hits nothing");

    scripting.shutdown();
}

// Kronos ("Alpha v1 Polish" -- "world.spawnDynamicBox"): real coverage
// for both the honest-failure path (no mesh handle registered yet, see
// ScriptWorldApi::setSpawnBoxMeshHandle()'s own comment) and the real
// spawn path -- entity creation, the real Physics::createDynamicBox()
// side effects (a real RigidBody component), and the real
// security-motivated clamp on script-supplied halfExtent/mass. No GPU
// needed: the "mesh handle" here is just a real ECS field
// (Renderable::meshHandle) this test can assert on directly without a
// live MeshLibrary/Vulkan device, same "structural verification, not
// pixels" split every other GPU-adjacent test in this file already uses.
void testScriptWorldApiSpawnDynamicBox() {
    engine::core::ECS ecs;
    engine::core::Physics physics;
    check(physics.initialize(), "spawnDynamicBox test: real Physics initializes headlessly");
    engine::core::RuntimeAnimationPlayer animationPlayer;

    engine::core::Scripting scripting;
    check(scripting.initialize(), "spawnDynamicBox test: real Scripting initializes headlessly");
    engine::core::ScriptWorldApi worldApi(ecs, physics, animationPlayer);
    scripting.setBindingsHook([&](lua_State* L) { worldApi.registerInto(L); });

    std::vector<std::string> output;
    scripting.setOutputCallback([&](const std::string& line) { output.push_back(line); });
    auto noRuntimeErrorSince = [&](size_t sinceIndex) {
        for (size_t i = sinceIndex; i < output.size(); ++i) {
            if (output[i].rfind("runtime error", 0) == 0) return false;
        }
        return true;
    };

    size_t beforeUnregistered = output.size();
    engine::core::ScriptId unregisteredId = scripting.loadAndRun(
        "SpawnDynamicBoxNoMesh",
        "local id = world.spawnDynamicBox(0, 5, 0, 0.5, 0.5, 0.5, 1.0)\n"
        "assert(id == nil, \"expected nil before setSpawnBoxMeshHandle() ever ran\")\n");
    check(unregisteredId != engine::core::kInvalidScript, "SpawnDynamicBoxNoMesh real-compiles with no error");
    check(noRuntimeErrorSince(beforeUnregistered),
          "world.spawnDynamicBox() real-returns nil (not a crash/error) with no spawn-box mesh handle registered");

    constexpr uint32_t kFakeMeshHandle = 42;
    worldApi.setSpawnBoxMeshHandle(kFakeMeshHandle);

    // Kronos: real, same documented timing quirk world.spawnPlayer()'s
    // own doc comment already states -- createDynamicBox() writes the
    // real Jolt body immediately, but the ECS Transform only re-syncs
    // from it on the *next* real physics.step(), so a same-frame
    // world.getPosition() read would see the stale pre-spawn (0,0,0)
    // default. One real step (with a loosened tolerance for the one
    // real tick of gravity that settles in the meantime) matches how
    // every other Physics-position test in this file already handles
    // this.
    size_t before = output.size();
    engine::core::ScriptId spawnId = scripting.loadAndRun(
        "SpawnDynamicBox",
        "local id = world.spawnDynamicBox(1, 5, -2, 0.5, 0.5, 0.5, 2.0, 0.1, 0.2, 0.3)\n"
        "assert(id ~= nil, \"expected a real entity id once a spawn-box mesh handle is registered\")\n"
        "return id\n");
    check(spawnId != engine::core::kInvalidScript, "SpawnDynamicBox real-compiles with no error");
    check(noRuntimeErrorSince(before), "world.spawnDynamicBox() real-spawns with every real assert() passing");

    physics.step(1.0f / 60.0f, ecs);

    size_t beforePosition = output.size();
    engine::core::ScriptId positionId = scripting.loadAndRun(
        "SpawnDynamicBoxPosition",
        "local id = world.findByName(\"DynamicBox\")\n"
        "assert(id ~= nil, \"expected the real spawned entity, findable by its real default Physics name\")\n"
        "local x, y, z = world.getPosition(id)\n"
        "assert(math.abs(x - 1.0) < 0.01 and math.abs(y - 5.0) < 0.01 and math.abs(z - (-2.0)) < 0.01, "
        "\"expected the real, requested spawn position (after one real physics.step() sync): got \" .. "
        "string.format(\"%.4f, %.4f, %.4f\", x, y, z))\n");
    check(positionId != engine::core::kInvalidScript, "SpawnDynamicBoxPosition real-compiles with no error");
    check(noRuntimeErrorSince(beforePosition),
          "world.spawnDynamicBox()'s real position is correct once the real ECS Transform re-syncs from Jolt");

    // Real ECS-side verification the script itself can't reach (no
    // world.getRenderable()/getRigidBody() binding exists, by design --
    // see ScriptWorldApi.hpp's own "no partial Instance-API imitation"
    // header comment) -- find the freshly spawned entity the same way
    // the raycast test above finds its static box, by scanning for the
    // one real RigidBody this test itself just created.
    engine::core::EntityId spawned = engine::core::kNullEntity;
    for (auto entity : ecs.view<engine::core::RigidBody>()) {
        if (ecs.tryGetComponent<engine::core::RigidBody>(entity)->motionType ==
            engine::core::RigidBodyMotionType::Dynamic) {
            spawned = entity;
            break;
        }
    }
    check(spawned != engine::core::kNullEntity,
          "world.spawnDynamicBox() real-creates a real Dynamic RigidBody (Physics::createDynamicBox() actually ran)");
    if (auto* renderable = ecs.tryGetComponent<engine::core::Renderable>(spawned)) {
        check(renderable->meshHandle == kFakeMeshHandle,
              "world.spawnDynamicBox() real-assigns the registered spawn-box meshHandle");
        check(std::abs(renderable->baseColor.r - 0.1f) < 0.001f && std::abs(renderable->baseColor.g - 0.2f) < 0.001f &&
                  std::abs(renderable->baseColor.b - 0.3f) < 0.001f,
              "world.spawnDynamicBox() real-applies the requested r/g/b color");
    } else {
        check(false, "world.spawnDynamicBox()'s real entity has a real Renderable component");
    }
    if (auto* transform = ecs.tryGetComponent<engine::core::Transform>(spawned)) {
        // 0.5 half-extent against the real 1x1x1 unit spawn-box mesh ->
        // scale 1.0 (halfExtent / 0.5), see luaSpawnDynamicBox()'s own
        // comment on why Transform.scale does this real stretch.
        check(std::abs(transform->scale.x - 1.0f) < 0.001f && std::abs(transform->scale.y - 1.0f) < 0.001f &&
                  std::abs(transform->scale.z - 1.0f) < 0.001f,
              "world.spawnDynamicBox() real-scales Transform to match the real requested half-extent");
    } else {
        check(false, "world.spawnDynamicBox()'s real entity has a real Transform component");
    }

    // Real security clamp coverage: a script-supplied halfExtent/mass
    // far outside the sane range gets real-clamped before it ever
    // reaches Jolt, not handed through raw -- see luaSpawnDynamicBox()'s
    // own kMin/kMaxHalfExtent, kMinMass/kMaxMass.
    size_t beforeClamp = output.size();
    engine::core::ScriptId clampId = scripting.loadAndRun(
        "SpawnDynamicBoxClamp",
        "local id = world.spawnDynamicBox(0, 0, 0, 999, -5, 0, 999999)\n"
        "assert(id ~= nil, \"expected a real entity even for out-of-range inputs -- clamp, don't reject\")\n"
        "return id\n");
    check(clampId != engine::core::kInvalidScript, "SpawnDynamicBoxClamp real-compiles with no error");
    check(noRuntimeErrorSince(beforeClamp), "world.spawnDynamicBox() with out-of-range inputs doesn't runtime-error");

    engine::core::EntityId clamped = engine::core::kNullEntity;
    for (auto entity : ecs.view<engine::core::RigidBody>()) {
        if (entity != spawned &&
            ecs.tryGetComponent<engine::core::RigidBody>(entity)->motionType == engine::core::RigidBodyMotionType::Dynamic) {
            clamped = entity;
            break;
        }
    }
    check(clamped != engine::core::kNullEntity, "world.spawnDynamicBox() real-spawned a second real Dynamic RigidBody");
    if (auto* transform = ecs.tryGetComponent<engine::core::Transform>(clamped)) {
        // halfExtent.x=999 clamps to 5.0 -> scale.x = 5.0/0.5 = 10.0;
        // halfExtent.y=-5 clamps to the real 0.05 minimum -> scale.y = 0.1.
        check(std::abs(transform->scale.x - 10.0f) < 0.01f,
              "world.spawnDynamicBox() real-clamps an oversized halfExtent to the real kMaxHalfExtent");
        check(std::abs(transform->scale.y - 0.1f) < 0.01f,
              "world.spawnDynamicBox() real-clamps a negative halfExtent to the real kMinHalfExtent");
    } else {
        check(false, "world.spawnDynamicBox()'s clamped entity has a real Transform component");
    }

    scripting.shutdown();
}

// Kronos ("Alpha v1 Polish" -- "default showcase scene"): real, end-to-
// end regression coverage for the actual shipped
// games/DefaultWorld/Scripts/Main.lua file -- reads it straight off
// disk (the exact same file runtime::GameLoader::loadGame() runs for a
// real player who picks Default World from the Game Catalogue) and
// runs it through a real headless Scripting + ScriptWorldApi, including
// a real, simulated Interact (scripting.fireInteract(), the same real
// dispatch a live Interact keypress uses -- see Scripting.hpp's own
// header comment) against one of the script's own real spawned boxes.
// Closes a real gap: before this, no test ever actually executed a
// shipped game's own Main.lua content -- only ad hoc inline Lua
// snippets were covered.
void testDefaultWorldMainLuaRunsCleanAndInteractSpawnsBoxes() {
    std::string gamesDir = engine::core::resolveResourceDir(engine::core::executableDirectory(), "games", ENGINE_GAMES_DIR);
    std::filesystem::path scriptPath = std::filesystem::path(gamesDir) / "DefaultWorld" / "Scripts" / "Main.lua";
    std::ifstream in(scriptPath);
    check(in.good(), "the real, shipped games/DefaultWorld/Scripts/Main.lua exists and opens");
    std::stringstream buffer;
    buffer << in.rdbuf();
    std::string scriptSource = buffer.str();
    check(!scriptSource.empty(), "the real, shipped Main.lua is non-empty");

    engine::core::ECS ecs;
    engine::core::Physics physics;
    check(physics.initialize(), "DefaultWorld Main.lua test: real Physics initializes headlessly");
    engine::core::RuntimeAnimationPlayer animationPlayer;

    engine::core::Scripting scripting;
    check(scripting.initialize(), "DefaultWorld Main.lua test: real Scripting initializes headlessly");
    engine::core::ScriptWorldApi worldApi(ecs, physics, animationPlayer);
    worldApi.setSpawnBoxMeshHandle(42); // same real, headless-safe fake handle testScriptWorldApiSpawnDynamicBox() uses
    scripting.setBindingsHook([&](lua_State* L) { worldApi.registerInto(L); });

    std::vector<std::string> output;
    scripting.setOutputCallback([&](const std::string& line) { output.push_back(line); });
    auto noRuntimeErrorSince = [&](size_t sinceIndex) {
        for (size_t i = sinceIndex; i < output.size(); ++i) {
            if (output[i].rfind("runtime error", 0) == 0) return false;
        }
        return true;
    };

    size_t before = output.size();
    engine::core::ScriptId id = scripting.loadAndRun("DefaultWorld/Main", scriptSource);
    check(id != engine::core::kInvalidScript, "the real, shipped Main.lua real-compiles with no error");
    check(noRuntimeErrorSince(before), "the real, shipped Main.lua real-runs its own top-level starter-box setup with no runtime error");

    size_t dynamicBoxCountAfterLoad = 0;
    engine::core::EntityId firstBox = engine::core::kNullEntity;
    for (auto entity : ecs.view<engine::core::RigidBody>()) {
        if (ecs.tryGetComponent<engine::core::RigidBody>(entity)->motionType == engine::core::RigidBodyMotionType::Dynamic) {
            ++dynamicBoxCountAfterLoad;
            if (firstBox == engine::core::kNullEntity) firstBox = entity;
        }
    }
    check(dynamicBoxCountAfterLoad == 4,
          "the real, shipped Main.lua real-spawns its own real 4 starter boxes on load, no more, no fewer");
    check(firstBox != engine::core::kNullEntity, "at least one real starter box exists to interact with");

    // Real, simulated Interact -- the exact same fireInteract() a live
    // player's own Interact keypress dispatches through
    // (Application.cpp's real input-trigger system).
    size_t beforeInteract = output.size();
    scripting.fireInteract(static_cast<uint32_t>(firstBox), static_cast<uint32_t>(firstBox));
    check(noRuntimeErrorSince(beforeInteract),
          "the real, shipped Main.lua's events.onInteract handler real-runs (launch + spawn burst) with no runtime error");

    size_t dynamicBoxCountAfterInteract = 0;
    for (auto entity : ecs.view<engine::core::RigidBody>()) {
        if (ecs.tryGetComponent<engine::core::RigidBody>(entity)->motionType == engine::core::RigidBodyMotionType::Dynamic) {
            ++dynamicBoxCountAfterInteract;
        }
    }
    check(dynamicBoxCountAfterInteract == dynamicBoxCountAfterLoad + 3,
          "one real Interact real-spawns the script's own real 3-box burst via world.spawnDynamicBox()");

    scripting.shutdown();
}

