// The real, full client/server round trip -- the SAME shipped file loaded
// on both a real server Scripting/NetworkSession and a real client
// Scripting/NetworkSession, exactly as the example's own header comment
// claims a creator can do. Mirrors
// testScriptNetworkApiRealFireServerReachesLuauHandler's real-socket
// pattern rather than stubbing the transport.
void testLuaExampleNetworkedPingRealRoundTrip() {
    std::string source = readExampleLuaFile(exampleLuaPath("networked_ping.lua").c_str());
    check(!source.empty(), "networked_ping.lua example: the real shipped file real-reads");

    constexpr uint16_t kTestPort = 17786;
    engine::core::ECS serverEcs, clientEcs;
    engine::net::NetworkSession serverSession, clientSession;

    engine::net::NetworkSession::Config serverConfig;
    serverConfig.mode = engine::net::NetworkMode::Server;
    serverConfig.port = kTestPort;
    check(serverSession.initialize(serverConfig), "networked_ping.lua example: real server real-starts");
    serverSession.setOnPlayerJoin([](engine::core::ECS& ecs, engine::net::PlayerId player) -> engine::core::EntityId {
        engine::core::EntityId entity = ecs.createEntity("PingExamplePlayer" + std::to_string(player));
        ecs.addComponent<engine::core::Transform>(entity);
        return entity;
    });

    engine::core::Scripting serverScripting;
    check(serverScripting.initialize(), "networked_ping.lua example: real server Scripting real-initializes");
    engine::core::ScriptNetworkApi serverNetworkApi(serverSession, serverScripting);
    std::vector<std::string> serverOutput;
    serverScripting.setOutputCallback([&](const std::string& line) { serverOutput.push_back(line); });
    serverScripting.setBindingsHook([&](lua_State* L) {
        engine::studio::registerStudioEcsBindings(L, serverEcs);
        serverNetworkApi.registerInto(L);
    });

    engine::net::NetworkSession::Config clientConfig;
    clientConfig.mode = engine::net::NetworkMode::Client;
    clientConfig.serverAddress = "127.0.0.1";
    clientConfig.port = kTestPort;
    check(clientSession.initialize(clientConfig), "networked_ping.lua example: real client real-connects");

    engine::core::EntityId clientAvatar = clientEcs.createEntity("LocalPingExample");
    clientEcs.addComponent<engine::core::Transform>(clientAvatar);

    bool handshook = false;
    for (int i = 0; i < 300 && !handshook; ++i) {
        serverSession.tick(0.05f, serverEcs, engine::core::kNullEntity);
        clientSession.sampleLocalInput(clientEcs, clientAvatar, glm::vec3(0.0f), false, false, 0.0f, 0.0f, 0.05f);
        clientSession.tick(0.05f, clientEcs, clientAvatar);
        handshook = clientSession.localPlayerId() != engine::net::kInvalidPlayer;
        if (!handshook) std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }
    check(handshook, "networked_ping.lua example: the real client really completes its real handshake");

    // The real server half: same shipped source, loaded on the server side
    // (its network.fireServer() call is a real, honest no-op outside
    // Client mode -- only the onServerEvent registration matters here).
    engine::core::ScriptId serverScriptId = serverScripting.loadAndRun("NetworkedPingServer", source);
    check(serverScriptId != engine::core::kInvalidScript, "networked_ping.lua example: the real shipped file real-compiles server-side");

    engine::core::Scripting clientScripting;
    check(clientScripting.initialize(), "networked_ping.lua example: real client Scripting real-initializes");
    engine::core::ScriptNetworkApi clientNetworkApi(clientSession, clientScripting);
    std::vector<std::string> clientOutput;
    clientScripting.setOutputCallback([&](const std::string& line) { clientOutput.push_back(line); });
    clientScripting.setBindingsHook([&](lua_State* L) {
        engine::studio::registerStudioEcsBindings(L, clientEcs);
        clientNetworkApi.registerInto(L);
    });

    // The real client half: same shipped source, loaded on the client side
    // -- its own top-level pingServer() call at the bottom of the file
    // real-fires network.fireServer("Ping", ...) immediately on load.
    engine::core::ScriptId clientScriptId = clientScripting.loadAndRun("NetworkedPingClient", source);
    check(clientScriptId != engine::core::kInvalidScript, "networked_ping.lua example: the real shipped file real-compiles client-side");

    bool sawPong = false;
    for (int i = 0; i < 200 && !sawPong; ++i) {
        serverSession.tick(0.05f, serverEcs, engine::core::kNullEntity);
        clientSession.tick(0.05f, clientEcs, clientAvatar);
        for (const auto& line : clientOutput)
            if (line.find("received Pong") != std::string::npos) sawPong = true;
        if (!sawPong) std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }
    check(sawPong, "networked_ping.lua example: the real shipped file's own client-side Ping really reached the real "
                   "shipped file's own server-side handler, which really broadcast a real Pong the same shipped "
                   "file's own client-side handler really received -- the full real round trip works exactly as its "
                   "own header comment claims");

    bool sawRuntimeError = false;
    for (const auto& line : serverOutput)
        if (line.rfind("runtime error", 0) == 0) sawRuntimeError = true;
    for (const auto& line : clientOutput)
        if (line.rfind("runtime error", 0) == 0) sawRuntimeError = true;
    check(!sawRuntimeError, "networked_ping.lua example: no runtime error on either the real server or real client side");

    serverScripting.shutdown();
    clientScripting.shutdown();
}

// Kronos (Alpha Roadmap Phase 3, "Component system") -- real Script
// component wiring. This replicates the exact scan core::Application's
// pre-tick hook runs (see Application.cpp: "any live Script component
// with autoRun and no scriptId yet gets real-loaded"), driven here by a
// headless core::Scripting instance instead of a live windowed
// Application, so the real end-to-end mechanism (attach source -> auto-
// load -> script finds and mutates its own entity by Name) gets real
// test coverage without needing a window/GPU.
void testScriptComponentAutoRun() {
    engine::core::ECS ecs;
    engine::core::EntityId target = ecs.createEntity("ScriptedEntity");

    engine::core::Scripting scripting;
    check(scripting.initialize(), "Scripting::initialize() succeeds headlessly");
    scripting.setBindingsHook(
        [&ecs](lua_State* L) { engine::studio::registerStudioEcsBindings(L, ecs); });

    auto& script = ecs.addComponent<engine::core::Script>(target);
    script.source = "local id = world.findByName(\"ScriptedEntity\")\n"
                     "if id then world.setPosition(id, 7, 8, 9) end\n";
    check(script.scriptId == engine::core::kInvalidScript, "a freshly-attached Script starts unloaded");
    check(script.autoRun, "Script::autoRun defaults to true");

    auto scriptView = ecs.view<engine::core::Script>();
    for (auto entity : scriptView) {
        auto& s = scriptView.get<engine::core::Script>(entity);
        if (s.autoRun && s.scriptId == engine::core::kInvalidScript && !s.source.empty()) {
            const auto* name = ecs.tryGetComponent<engine::core::Name>(entity);
            std::string chunkName = (name != nullptr && !name->value.empty()) ? name->value : "Script";
            s.scriptId = scripting.loadAndRun(chunkName, s.source);
        }
    }

    check(script.scriptId != engine::core::kInvalidScript,
          "the auto-run scan real-loads the script and records a valid ScriptId");

    auto* transform = ecs.tryGetComponent<engine::core::Transform>(target);
    check(transform != nullptr && nearlyEqual(transform->position.x, 7.0f) && nearlyEqual(transform->position.y, 8.0f) &&
              nearlyEqual(transform->position.z, 9.0f),
          "the script's own world.setPosition() call real-reached its own entity via world.findByName(Name)");

    // A second scan pass must not reload it -- scriptId is already valid.
    engine::core::ScriptId idAfterFirstRun = script.scriptId;
    for (auto entity : scriptView) {
        auto& s = scriptView.get<engine::core::Script>(entity);
        if (s.autoRun && s.scriptId == engine::core::kInvalidScript && !s.source.empty()) {
            s.scriptId = scripting.loadAndRun("Script", s.source);
        }
    }
    check(script.scriptId == idAfterFirstRun, "a Script with a valid scriptId is never reloaded by a later scan pass");

    scripting.shutdown();
}

// Kronos (Alpha Roadmap Phase 7, "Lua Scripting Platform" -- "Lua hot-
// reload"): replicates the exact updated scan Application.cpp now runs
// (source changed since loadedSource -> real-unload the stale scriptId,
// real-reload the new source) against a headless core::Scripting, proving
// a gameplay Script component's source can really change at runtime and
// take effect without restarting the process.
void testScriptComponentHotReloadsOnSourceChange() {
    engine::core::ECS ecs;
    engine::core::EntityId target = ecs.createEntity("HotReloadEntity");

    engine::core::Scripting scripting;
    check(scripting.initialize(), "hot-reload test: Scripting::initialize() succeeds");
    scripting.setBindingsHook(
        [&ecs](lua_State* L) { engine::studio::registerStudioEcsBindings(L, ecs); });

    auto& script = ecs.addComponent<engine::core::Script>(target);
    script.source = "local id = world.findByName(\"HotReloadEntity\")\n"
                     "world.setPosition(id, 1, 0, 0)\n";

    auto scan = [&]() {
        auto scriptView = ecs.view<engine::core::Script>();
        for (auto entity : scriptView) {
            auto& s = scriptView.get<engine::core::Script>(entity);
            if (s.autoRun && !s.source.empty() && s.source != s.loadedSource) {
                if (s.scriptId != engine::core::kInvalidScript) scripting.unload(s.scriptId);
                s.scriptId = scripting.loadAndRun("HotReloadEntity", s.source);
                s.loadedSource = s.source;
            }
        }
    };

    scan();
    auto* transform = ecs.tryGetComponent<engine::core::Transform>(target);
    check(transform != nullptr && nearlyEqual(transform->position.x, 1.0f), "the real initial source real-runs");
    engine::core::ScriptId firstScriptId = script.scriptId;

    // A second scan pass with unchanged source must NOT reload.
    scan();
    check(script.scriptId == firstScriptId, "an unchanged source is never reloaded by a later scan pass");

    // Change the source -- a real hot-reload must pick this up.
    script.source = "local id = world.findByName(\"HotReloadEntity\")\n"
                     "world.setPosition(id, 9, 0, 0)\n";
    scan();
    check(script.scriptId != engine::core::kInvalidScript && script.scriptId != firstScriptId,
          "a real source change real-triggers a fresh loadAndRun() with a new ScriptId, not a no-op");
    check(nearlyEqual(transform->position.x, 9.0f),
          "the real hot-reloaded script's new source really ran and really mutated the entity again");

    scripting.shutdown();
}

// Kronos (Alpha Completion Checklist, "Lua Creator Experience" -- "Lua
// hot-reload stability"): a real regression test for a genuine, previously
// undetected use-after-free found while auditing this item.
// Scripting::unload()'s own old comment claimed leaving stale
// parked_/onUpdateCallbacks_/etc. entries behind was safe because "nothing
// yet calls unload() outside of shutdown" -- but Application.cpp's real
// hot-reload path (exercised right above by
// testScriptComponentHotReloadsOnSourceChange) already does exactly that,
// on a SHARED Scripting instance holding other live scripts, meaning a
// full shutdown() isn't an option. The previous test above never caught
// this because its own script never registered an events.onUpdate
// handler; this test's script does -- the same real pattern
// examples/lua/moving_platform.lua ships. Before the fix, the second
// tick() below would resume a dangling lua_State (freed by unload()'s
// lua_close()) via the stale callback still in onUpdateCallbacks_.
void testScriptingUnloadPurgesStaleCallbacksAndParkedThreads() {
    engine::core::Scripting scripting;
    check(scripting.initialize(), "unload-safety test: Scripting::initialize() succeeds");
    std::vector<std::string> output;
    scripting.setOutputCallback([&](const std::string& line) { output.push_back(line); });

    engine::core::ScriptId firstId =
        scripting.loadAndRun("First", "events.onUpdate(function(dt) print(\"first tick\") end)\n");
    check(firstId != engine::core::kInvalidScript, "unload-safety test: the real first script real-loads");

    scripting.tick(0.1f);
    bool sawFirstTick = false;
    for (const auto& line : output)
        if (line == "first tick") sawFirstTick = true;
    check(sawFirstTick, "unload-safety test: the real first script's onUpdate handler really fires before unload");

    // Real hot-reload: unload the first script (freeing its real lua_State
    // via lua_close()), then load a second, unrelated script into the same
    // still-live Scripting instance -- exactly Application.cpp's own
    // hot-reload sequence.
    scripting.unload(firstId);
    output.clear();
    engine::core::ScriptId secondId =
        scripting.loadAndRun("Second", "events.onUpdate(function(dt) print(\"second tick\") end)\n");
    check(secondId != engine::core::kInvalidScript, "unload-safety test: the real second script real-loads after unload()");

    // The real safety check: a second real tick() call must not touch the
    // first script's freed VM (a debug/ASan build would abort on the
    // use-after-free the old code left behind) and must fire ONLY the
    // still-live second script's handler.
    scripting.tick(0.1f);
    bool sawFirstTickAgain = false, sawSecondTick = false;
    for (const auto& line : output) {
        if (line == "first tick") sawFirstTickAgain = true;
        if (line == "second tick") sawSecondTick = true;
    }
    check(!sawFirstTickAgain,
          "unload-safety test: the unloaded first script's stale onUpdate callback was really purged, not left "
          "dangling in onUpdateCallbacks_");
    check(sawSecondTick, "unload-safety test: the still-live second script's own onUpdate handler still really fires");

    // Same real coverage for a parked task.wait() coroutine: unload()ing a
    // script with an outstanding wait must not leave a dangling thread in
    // parked_ for the next tick() to resume.
    engine::core::ScriptId waitingId =
        scripting.loadAndRun("Waiting", "task.wait(1000)\nprint(\"should never resume\")\n");
    check(waitingId != engine::core::kInvalidScript, "unload-safety test: the real task.wait() script real-loads and real-parks");
    scripting.unload(waitingId);
    output.clear();
    // A tick() with a large dt would resume any still-parked thread whose
    // wake time has passed -- proving the parked_ entry was really purged,
    // not just coincidentally never due to wake.
    scripting.tick(2000.0f);
    bool sawShouldNeverResume = false;
    for (const auto& line : output)
        if (line == "should never resume") sawShouldNeverResume = true;
    check(!sawShouldNeverResume,
          "unload-safety test: the unloaded script's real parked task.wait() coroutine was really purged from "
          "parked_, not left dangling for a later tick() to resume");

    scripting.shutdown();
}

// Kronos ("Active Joining UI" -- Scripting event hooks): pure, real
// coverage of the mechanical event-bus extension -- same shape
// testScriptingFireCollisionReachesRegisteredHandler()/
// testScriptingOnUnloadFiresOnShutdown() already establish.
void testScriptingEventsOnSessionJoinAndLeaveFire() {
    engine::core::Scripting scripting;
    check(scripting.initialize(), "session events test: Scripting::initialize() succeeds");
    std::vector<std::string> output;
    scripting.setOutputCallback([&](const std::string& line) { output.push_back(line); });

    engine::core::ScriptId id = scripting.loadAndRun(
        "SessionEvents", "events.onSessionJoin(function() print(\"joined\") end)\n"
                          "events.onSessionLeave(function() print(\"left\") end)\n");
    check(id != engine::core::kInvalidScript,
          "session events test: the real script real-loads and real-registers both handlers");

    bool sawJoinBeforeFire = false;
    for (const auto& line : output)
        if (line == "joined") sawJoinBeforeFire = true;
    check(!sawJoinBeforeFire, "session events test: merely registering a real handler does NOT fire it");

    scripting.fireSessionJoin();
    bool sawJoin = false;
    for (const auto& line : output)
        if (line == "joined") sawJoin = true;
    check(sawJoin, "fireSessionJoin() really reaches the real registered events.onSessionJoin() handler");

    bool sawLeaveTooEarly = false;
    for (const auto& line : output)
        if (line == "left") sawLeaveTooEarly = true;
    check(!sawLeaveTooEarly, "session events test: firing onSessionJoin does NOT also fire onSessionLeave");

    scripting.fireSessionLeave();
    bool sawLeave = false;
    for (const auto& line : output)
        if (line == "left") sawLeave = true;
    check(sawLeave, "fireSessionLeave() really reaches the real registered events.onSessionLeave() handler");

    scripting.shutdown();
}

void testScriptingEventsOnPlayerJoinAndLeavePassIdAndName() {
    engine::core::Scripting scripting;
    check(scripting.initialize(), "player events test: Scripting::initialize() succeeds");
    std::vector<std::string> output;
    scripting.setOutputCallback([&](const std::string& line) { output.push_back(line); });

    engine::core::ScriptId id = scripting.loadAndRun(
        "PlayerEvents",
        "events.onPlayerJoin(function(id, name) print(\"joined \" .. tostring(id) .. \" \" .. name) end)\n"
        "events.onPlayerLeave(function(id, name) print(\"left \" .. tostring(id) .. \" \" .. name) end)\n");
    check(id != engine::core::kInvalidScript,
          "player events test: the real script real-loads and real-registers both handlers");

    scripting.firePlayerJoin(42, "Alice");
    bool sawJoin = false;
    for (const auto& line : output)
        if (line == "joined 42 Alice") sawJoin = true;
    check(sawJoin, "firePlayerJoin() really reaches the real registered handler with the real id and real name");

    scripting.firePlayerLeave(42, "Alice");
    bool sawLeave = false;
    for (const auto& line : output)
        if (line == "left 42 Alice") sawLeave = true;
    check(sawLeave, "firePlayerLeave() really reaches the real registered handler with the real id and real name");

    scripting.shutdown();
}

// Kronos ("Active Joining UI"): direct regression test for the purge-fix
// extension -- the single easiest thing to have regressed while adding
// these four new callback vectors (see Scripting::unload()'s own
// comment). Same structure as testScriptingUnloadPurgesStaleCallbacksAndParkedThreads
// above, applied to the two new vectors that test doesn't cover.
void testScriptingUnloadPurgesSessionAndPlayerCallbacksForThatScriptOnly() {
    engine::core::Scripting scripting;
    check(scripting.initialize(), "session/player purge test: Scripting::initialize() succeeds");
    std::vector<std::string> output;
    scripting.setOutputCallback([&](const std::string& line) { output.push_back(line); });

    engine::core::ScriptId firstId = scripting.loadAndRun(
        "FirstPS", "events.onSessionJoin(function() print(\"first session join\") end)\n"
                   "events.onPlayerJoin(function(id, name) print(\"first player join\") end)\n");
    check(firstId != engine::core::kInvalidScript, "session/player purge test: the real first script real-loads");

    scripting.unload(firstId);
    output.clear();
    engine::core::ScriptId secondId = scripting.loadAndRun(
        "SecondPS", "events.onSessionJoin(function() print(\"second session join\") end)\n"
                    "events.onPlayerJoin(function(id, name) print(\"second player join\") end)\n");
    check(secondId != engine::core::kInvalidScript,
          "session/player purge test: the real second script real-loads after unload()");

    scripting.fireSessionJoin();
    scripting.firePlayerJoin(1, "X");
    bool sawFirstSessionJoin = false, sawSecondSessionJoin = false;
    bool sawFirstPlayerJoin = false, sawSecondPlayerJoin = false;
    for (const auto& line : output) {
        if (line == "first session join") sawFirstSessionJoin = true;
        if (line == "second session join") sawSecondSessionJoin = true;
        if (line.rfind("first player join", 0) == 0) sawFirstPlayerJoin = true;
        if (line.rfind("second player join", 0) == 0) sawSecondPlayerJoin = true;
    }
    check(!sawFirstSessionJoin,
          "the unloaded first script's stale onSessionJoin callback was really purged, not left dangling");
    check(sawSecondSessionJoin, "the still-live second script's own onSessionJoin handler still really fires");
    check(!sawFirstPlayerJoin,
          "the unloaded first script's stale onPlayerJoin callback was really purged, not left dangling");
    check(sawSecondPlayerJoin, "the still-live second script's own onPlayerJoin handler still really fires");

    scripting.shutdown();
}

void testSceneFileSaveLoadRoundTrip() {
    engine::core::SceneFile file;
    file.cameraPosition = {1.0f, 2.0f, 3.0f};
    file.cameraYawDegrees = 45.0f;
    file.cameraPitchDegrees = -15.0f;
    file.cameraFovDegrees = 70.0f;

    engine::core::SceneEntityRecord withMesh;
    withMesh.name = "Box1";
    withMesh.position = {1.0f, 2.0f, 3.0f};
    withMesh.rotation = glm::quat(0.7071f, 0.0f, 0.7071f, 0.0f);
    withMesh.scale = {2.0f, 2.0f, 2.0f};
    withMesh.hasRenderable = true;
    withMesh.baseColor = {0.5f, 0.6f, 0.7f, 1.0f};
    withMesh.metallic = 0.25f;
    withMesh.roughness = 0.75f;
    withMesh.normalIntensity = 1.5f;
    withMesh.emissiveColor = {1.0f, 0.5f, 0.0f};
    withMesh.emissiveIntensity = 2.0f;
    withMesh.castsShadow = false;
    withMesh.instanced = true;
    withMesh.hasMeshSource = true;
    withMesh.meshSource.kind = engine::core::MeshSourceKind::Capsule;
    withMesh.meshSource.params = {0.5f, 1.0f, 0.0f};
    file.entities.push_back(withMesh);

    engine::core::SceneEntityRecord withObj;
    withObj.name = "Imported Model";
    withObj.hasRenderable = true;
    withObj.hasMeshSource = true;
    withObj.meshSource.kind = engine::core::MeshSourceKind::Obj;
    withObj.meshSource.path = "assets/models/my prop.obj"; // spaces on purpose -- exercises the trailing-string parse path
    file.entities.push_back(withObj);

    engine::core::SceneEntityRecord withEmitter;
    withEmitter.name = "Sparks";
    withEmitter.hasParticleEmitter = true;
    withEmitter.emitter.emissionRate = 42.0f;
    withEmitter.emitter.looping = false;
    withEmitter.emitter.colorStart = {1.0f, 0.0f, 0.0f, 1.0f};
    file.entities.push_back(withEmitter);

    engine::core::SceneEntityRecord withLight;
    withLight.name = "KeyLight";
    withLight.hasLight = true;
    withLight.light.enabled = false;
    withLight.light.color = {1.0f, 0.5f, 0.25f};
    withLight.light.intensity = 3.5f;
    withLight.light.radius = 12.0f;
    file.entities.push_back(withLight);

    const char* path = "test_scene.scene";
    check(file.saveToFile(path), "scene file saves");

    engine::core::SceneFile loaded;
    check(loaded.loadFromFile(path), "scene file loads");
    check(loaded.entities.size() == 4, "all four entity records round-trip");
    check(nearlyEqual(loaded.cameraPosition.x, 1.0f) && nearlyEqual(loaded.cameraFovDegrees, 70.0f),
          "camera pose round-trips");

    if (loaded.entities.size() == 4) {
        check(loaded.entities[0].name == "Box1", "entity name round-trips");
        check(nearlyEqual(loaded.entities[0].position.z, 3.0f), "entity position round-trips");
        check(loaded.entities[0].hasMeshSource &&
                  loaded.entities[0].meshSource.kind == engine::core::MeshSourceKind::Capsule,
              "procedural mesh source kind round-trips");
        check(nearlyEqual(loaded.entities[0].meshSource.params.y, 1.0f), "mesh source params round-trip");
        check(loaded.entities[0].instanced && !loaded.entities[0].castsShadow, "renderable bool flags round-trip");

        check(loaded.entities[1].meshSource.kind == engine::core::MeshSourceKind::Obj,
              "imported mesh source kind round-trips");
        check(loaded.entities[1].meshSource.path == "assets/models/my prop.obj",
              "mesh source path with spaces round-trips");

        check(loaded.entities[2].hasParticleEmitter && nearlyEqual(loaded.entities[2].emitter.emissionRate, 42.0f),
              "particle emitter settings round-trip");
        check(!loaded.entities[2].emitter.looping, "particle emitter bool field round-trips");

        check(loaded.entities[3].hasLight && !loaded.entities[3].light.enabled,
              "light presence + enabled flag round-trip");
        check(nearlyEqual(loaded.entities[3].light.intensity, 3.5f) && nearlyEqual(loaded.entities[3].light.radius, 12.0f),
              "light intensity/radius round-trip");
        check(nearlyEqual(loaded.entities[3].light.color.y, 0.5f), "light color round-trips");
    }

    std::remove(path);
}

// Kronos ("Game Catalogue Overhaul", Phase 1): SceneFile's own class
// comment used to list RigidBody as a stated, deliberate gap -- this is
// the real regression coverage for closing it, exercising every real
// ColliderShapeKind, mirroring testSceneFileSaveLoadRoundTrip()'s own
// per-field-then-round-trip discipline.
void testSceneFileRigidBodyColliderRoundTrip() {
    // A real fixture .obj on disk -- ColliderShape::validate() (reused
    // below, not reimplemented) checks Mesh colliders' path actually
    // resolves, so this needs to be a genuine file, same as
    // testSaveObjRoundTripsThroughLoadObjWithRealGeometry()'s own fixture.
    auto box = engine::core::EditableMesh::createBox({0.5f, 0.5f, 0.5f});
    const char* meshPath = "test_scene_collider.obj";
    check(engine::core::saveObj(meshPath, box.vertices(), box.indices()), "collider mesh fixture .obj saves");

    engine::core::SceneFile file;

    engine::core::SceneEntityRecord staticBox;
    staticBox.name = "Ground";
    staticBox.hasRigidBody = true;
    staticBox.motionType = engine::core::RigidBodyMotionType::Static;
    staticBox.hasColliderShape = true;
    staticBox.colliderShape.kind = engine::core::ColliderShapeKind::Box;
    staticBox.colliderShape.params = {5.0f, 0.5f, 5.0f};
    file.entities.push_back(staticBox);

    engine::core::SceneEntityRecord dynamicSphere;
    dynamicSphere.name = "Ball";
    dynamicSphere.hasRigidBody = true;
    dynamicSphere.motionType = engine::core::RigidBodyMotionType::Dynamic;
    dynamicSphere.hasColliderShape = true;
    dynamicSphere.colliderShape.kind = engine::core::ColliderShapeKind::Sphere;
    dynamicSphere.colliderShape.params = {0.75f, 0.0f, 0.0f};
    file.entities.push_back(dynamicSphere);

    engine::core::SceneEntityRecord kinematicCapsule;
    kinematicCapsule.name = "Platform";
    kinematicCapsule.hasRigidBody = true;
    kinematicCapsule.motionType = engine::core::RigidBodyMotionType::Kinematic;
    kinematicCapsule.hasColliderShape = true;
    kinematicCapsule.colliderShape.kind = engine::core::ColliderShapeKind::Capsule;
    kinematicCapsule.colliderShape.params = {0.4f, 1.2f, 0.0f};
    file.entities.push_back(kinematicCapsule);

    engine::core::SceneEntityRecord meshCollider;
    meshCollider.name = "Terrain";
    meshCollider.hasRigidBody = true;
    meshCollider.motionType = engine::core::RigidBodyMotionType::Static;
    meshCollider.hasColliderShape = true;
    meshCollider.colliderShape.kind = engine::core::ColliderShapeKind::Mesh;
    meshCollider.colliderShape.path = meshPath;
    file.entities.push_back(meshCollider);

    engine::core::SceneEntityRecord noPhysics;
    noPhysics.name = "Decoration";
    file.entities.push_back(noPhysics);

    const char* path = "test_scene_physics.scene";
    check(file.saveToFile(path), "scene file with physics data saves");

    engine::core::SceneFile loaded;
    check(loaded.loadFromFile(path), "scene file with physics data loads");
    check(loaded.entities.size() == 5, "all five entity records round-trip");

    if (loaded.entities.size() == 5) {
        check(loaded.entities[0].hasRigidBody && loaded.entities[0].motionType == engine::core::RigidBodyMotionType::Static,
              "static box rigid body + motion type round-trip");
        check(loaded.entities[0].hasColliderShape &&
                  loaded.entities[0].colliderShape.kind == engine::core::ColliderShapeKind::Box,
              "box collider kind round-trips");
        check(nearlyEqual(loaded.entities[0].colliderShape.params.x, 5.0f) &&
                  nearlyEqual(loaded.entities[0].colliderShape.params.y, 0.5f),
              "box collider half-extents round-trip");
        std::string boxError;
        check(loaded.entities[0].colliderShape.validate(boxError), "round-tripped box collider real-validates");

        check(loaded.entities[1].motionType == engine::core::RigidBodyMotionType::Dynamic,
              "dynamic motion type round-trips");
        check(loaded.entities[1].colliderShape.kind == engine::core::ColliderShapeKind::Sphere,
              "sphere collider kind round-trips");
        check(nearlyEqual(loaded.entities[1].colliderShape.params.x, 0.75f), "sphere collider radius round-trips");

        check(loaded.entities[2].motionType == engine::core::RigidBodyMotionType::Kinematic,
              "kinematic motion type round-trips");
        check(loaded.entities[2].colliderShape.kind == engine::core::ColliderShapeKind::Capsule,
              "capsule collider kind round-trips");
        check(nearlyEqual(loaded.entities[2].colliderShape.params.x, 0.4f) &&
                  nearlyEqual(loaded.entities[2].colliderShape.params.y, 1.2f),
              "capsule collider radius/half-height round-trip");

        check(loaded.entities[3].colliderShape.kind == engine::core::ColliderShapeKind::Mesh,
              "mesh collider kind round-trips");
        check(loaded.entities[3].colliderShape.path == meshPath, "mesh collider path round-trips");
        std::string meshError;
        check(loaded.entities[3].colliderShape.validate(meshError),
              "round-tripped mesh collider real-validates against the real fixture file on disk");

        check(!loaded.entities[4].hasRigidBody && !loaded.entities[4].hasColliderShape,
              "an entity with no physics data round-trips with hasRigidBody/hasColliderShape both false, not "
              "defaulted to true");
    }

    std::remove(path);
    std::remove(meshPath);
}

void testProjectFileSaveLoadRoundTrip() {
    engine::core::ProjectFile project;
    project.name = "My Game";
    project.version = "0.3.0";
    project.scenePaths = {"scenes/main.scene", "scenes/lobby.scene"};
    project.activeSceneIndex = 1;
    project.touch();
    check(project.createdAtUnixSeconds > 0, "touch() stamps createdAtUnixSeconds on first call");
    check(project.modifiedAtUnixSeconds == project.createdAtUnixSeconds, "first touch() sets created == modified");

    const char* path = "test_project.project";
    check(project.saveToFile(path), "project file saves");

    engine::core::ProjectFile loaded;
    check(loaded.loadFromFile(path), "project file loads");
    check(loaded.name == "My Game", "project name round-trips");
    check(loaded.scenePaths.size() == 2 && loaded.scenePaths[1] == "scenes/lobby.scene",
          "scene path list round-trips");
    check(loaded.activeSceneIndex == 1, "active scene index round-trips");
    check(loaded.createdAtUnixSeconds == project.createdAtUnixSeconds, "timestamps round-trip");

    int64_t firstCreated = project.createdAtUnixSeconds;
    project.touch();
    check(project.createdAtUnixSeconds == firstCreated, "a second touch() leaves createdAtUnixSeconds unchanged");

    std::remove(path);
}

// Kronos (Alpha Completion Checklist, "Project System Finalization" --
// "versioning"): real coverage of the previously-nonexistent semver
// compatibility check -- version used to be a purely decorative,
// unchecked string field (see ProjectFile.hpp's own comment on
// isCompatibleVersion()).
// Kronos (Alpha Completion Checklist, "Alpha Packaging" -- "default
// project template"): loads the *actual shipped* files under
// ../../templates/project/ (generated once via the engine's own real
// SceneFile::saveToFile()/ProjectFile::saveToFile(), not hand-typed, to
// avoid a subtle format mismatch) through the real loaders, matching
// testPluginTemplateLoadsAndRunsReal's own "verify the real shipped
// file, not a re-typed copy" discipline.
void testDefaultProjectTemplateLoadsReal() {
    // Real packaging fix (see testShippedAvatarAnimationClipsLoadAndValidate()'s
    // own comment for the full story) -- same resolveResourceDir()
    // treatment as the plugin template and Lua examples above, instead of
    // a hardcoded "../../" relative path.
    std::string templateDir =
        engine::core::resolveResourceDir(engine::core::executableDirectory(), "templates", ENGINE_TEMPLATES_DIR) +
        "/project";
    engine::core::ProjectFile project;
    check(project.loadFromFile(templateDir + "/default.project"),
          "default project template: the real shipped .project file real-loads");
    check(project.isCompatibleVersion(), "default project template: its own shipped VERSION is real-compatible with "
                                          "this build's kProjectFormatVersion");
    check(project.scenePaths.size() == 1 && project.scenePaths[0] == "default.scene",
          "default project template: its real scenePaths list really references its own real default.scene");
    check(project.activeSceneIndex == 0, "default project template: its real activeSceneIndex points at that scene");

    engine::core::SceneFile scene;
    check(scene.loadFromFile(templateDir + "/default.scene"),
          "default project template: the real shipped .scene file real-loads");
    check(scene.entities.size() == 3, "default project template: its real scene really has all three shipped entities");

    bool sawGround = false, sawBox = false, sawLight = false;
    for (const auto& entity : scene.entities) {
        if (entity.name == "Ground") {
            sawGround = entity.hasRenderable && entity.hasMeshSource;
        } else if (entity.name == "StarterBox") {
            sawBox = entity.hasRenderable && entity.hasMeshSource;
        } else if (entity.name == "SunLight") {
            sawLight = entity.hasLight && entity.light.enabled;
        }
    }
    check(sawGround, "default project template: \"Ground\" real-loads with a real Renderable + MeshSource");
    check(sawBox, "default project template: \"StarterBox\" real-loads with a real Renderable + MeshSource");
    check(sawLight, "default project template: \"SunLight\" real-loads with a real, enabled Light");
}

void testProjectFileVersionCompatibility() {
    engine::core::ProjectFile matching;
    matching.version = engine::core::kProjectFormatVersion;
    check(matching.isCompatibleVersion(), "a project saved with the real current format version is real-compatible");

    engine::core::ProjectFile sameMajorDifferentMinor;
    sameMajorDifferentMinor.version = "1.9.3";
    check(sameMajorDifferentMinor.isCompatibleVersion(),
          "real semver rule: a same-major, different-minor/patch version is still real-compatible");

    engine::core::ProjectFile higherMajor;
    higherMajor.version = "99.0.0";
    check(!higherMajor.isCompatibleVersion(),
          "real semver rule: a different major version is real-incompatible, not silently accepted");

    engine::core::ProjectFile olderMajor;
    olderMajor.version = "0.9.0";
    check(!olderMajor.isCompatibleVersion(), "a lower major version is also real-incompatible, not just a higher one");

    engine::core::ProjectFile garbage;
    garbage.version = "not-a-version";
    check(!garbage.isCompatibleVersion(),
          "an unparseable version string is real-treated as incompatible, not guessed at or silently allowed through");

    engine::core::ProjectFile empty;
    empty.version = "";
    check(!empty.isCompatibleVersion(), "an empty version string is real-treated as incompatible");
}

// Kronos (Alpha Completion Checklist, "Project System Finalization" --
// "auto-backup"/"recovery"): real coverage of the new project-level
// recovery-file primitives, mirroring
// core::SceneManager::recoveryPathFor()/hasRecoveryFile()'s own
// already-tested real behavior for scene content.
void testProjectFileRecoveryPathHelpers() {
    const char* path = "test_project_recovery.project";
    std::string recoveryPath = engine::core::ProjectFile::recoveryPathFor(path);
    check(recoveryPath == std::string(path) + ".autosave",
          "recoveryPathFor() real-appends the same \".autosave\" suffix SceneManager's own scene recovery uses");

    std::remove(recoveryPath.c_str()); // real, honest guarantee this doesn't already exist from a previous run
    check(!engine::core::ProjectFile::hasRecoveryFile(path),
          "hasRecoveryFile() real-reports false when no real recovery file exists yet");

    engine::core::ProjectFile snapshot;
    snapshot.name = "Recovery Test Project";
    check(snapshot.saveToFile(recoveryPath), "a real snapshot really writes to the real recovery path");
    check(engine::core::ProjectFile::hasRecoveryFile(path),
          "hasRecoveryFile() real-reports true once a real recovery file exists at that real path");

    std::remove(recoveryPath.c_str());
    check(!engine::core::ProjectFile::hasRecoveryFile(path),
          "hasRecoveryFile() real-reports false again after the real recovery file is removed");
}

// Kronos (Alpha Roadmap Phase 9, "Platform Services" -- "Account system
// (simple local profiles first)").
// Kronos ("Branding + Release Prep" -- "Basic README generator
// (Studio)"): real, pure coverage over core::generateProjectReadme() --
// real project metadata produces real, correct content, and an empty
// project honestly says so rather than fabricating scene names.
void testGenerateProjectReadmeIncludesRealMetadata() {
    engine::core::ProjectFile project;
    project.name = "My Cool Game";
    project.createdAtUnixSeconds = 1700000000;
    project.modifiedAtUnixSeconds = 1700100000;
    project.scenePaths = {"scenes/main.scene", "scenes/lobby.scene"};
    project.activeSceneIndex = 1;

    std::string readme = engine::core::generateProjectReadme(project);
    check(readme.find("My Cool Game") != std::string::npos, "the real project name real-appears in the generated README");
    check(readme.find("scenes/main.scene") != std::string::npos && readme.find("scenes/lobby.scene") != std::string::npos,
          "every real scene path real-appears in the generated README");
    check(readme.find("scenes/lobby.scene (active)") != std::string::npos,
          "the real, currently-active scene is real-marked as such");
    check(readme.find(engine::core::kKronosVersion) != std::string::npos,
          "the real, current Kronos version real-appears in the generated README");

    engine::core::ProjectFile emptyProject;
    emptyProject.name = "Empty Project";
    std::string emptyReadme = engine::core::generateProjectReadme(emptyProject);
    check(emptyReadme.find("No scenes yet") != std::string::npos,
          "a real project with no scenes gets an honest 'No scenes yet' line, not fabricated content");
}

