void testTransactionLogSaveLoadRoundTrip() {
    engine::marketplace::TransactionLog log;
    log.record(engine::marketplace::TransactionRecord{111, "wizard_hat_01", "Wizard Hat, Deluxe", 150, "Hat Maker, Inc.",
                                                        1700000000});
    log.record(engine::marketplace::TransactionRecord{222, "cool_shades_02", "Cool Shades", 75, "ShadesCo", 1700000100});

    const char* path = "test_transaction_log.transactions";
    check(log.saveToFile(path), "a real transaction log saves");

    engine::marketplace::TransactionLog loaded;
    check(loaded.loadFromFile(path), "a real transaction log file loads");
    check(loaded.size() == 2, "both real transaction records round-trip");
    check(loaded.records()[0].buyerProfileId == 111 && loaded.records()[0].itemId == "wizard_hat_01" &&
              loaded.records()[0].itemName == "Wizard Hat, Deluxe" && loaded.records()[0].priceCredits == 150 &&
              loaded.records()[0].sellerCreatorId == "Hat Maker, Inc." && loaded.records()[0].timestampUnixSeconds == 1700000000,
          "the real first record's fields (including real free-text fields with commas) round-trip exactly");
    check(loaded.recordsForBuyer(222).size() == 1 && loaded.recordsForBuyer(222)[0].itemId == "cool_shades_02",
          "recordsForBuyer() real-filters to exactly the real buyer's own real records");
    check(loaded.recordsForBuyer(999).empty(), "recordsForBuyer() real-returns empty for a real buyer with no records");

    std::remove(path);
}

// Kronos ("Creator Identity + Marketplace Publishing Pipeline"): real,
// pure coverage over TransactionLog::recordPublish()/publishRecordsForCreator()
// -- a real, separate publish-event kind that coexists in the same real
// ledger file alongside purchase TransactionRecords, without either kind
// corrupting the other.
void testTransactionLogPublishRecordsCoexistWithPurchaseRecords() {
    engine::marketplace::TransactionLog log;
    log.record(engine::marketplace::TransactionRecord{111, "wizard_hat_01", "Wizard Hat", 150, "creator_1", 1700000000});
    log.recordPublish(engine::marketplace::PublishRecord{"creator_1", "wizard_hat_01", "Wizard Hat", 1699999000,
                                                           "Approved", "Head"});
    log.recordPublish(
        engine::marketplace::PublishRecord{"creator_2", "sus_item", "Sus Item", 1699999500, "UnderReview", "Torso"});

    const char* path = "test_transaction_log_publish.transactions";
    check(log.saveToFile(path), "a real transaction log with both record kinds saves");

    engine::marketplace::TransactionLog loaded;
    check(loaded.loadFromFile(path), "a real transaction log with both record kinds loads");
    check(loaded.size() == 1, "the real purchase record kind is unaffected by the real publish records sharing the file");
    check(loaded.publishRecords().size() == 2, "both real publish records round-trip");
    check(loaded.publishRecords()[0].creatorId == "creator_1" && loaded.publishRecords()[0].itemId == "wizard_hat_01" &&
              loaded.publishRecords()[0].itemName == "Wizard Hat" &&
              loaded.publishRecords()[0].timestampUnixSeconds == 1699999000 &&
              loaded.publishRecords()[0].moderationStatus == "Approved" && loaded.publishRecords()[0].category == "Head",
          "the real first publish record's fields (including the real, new category field) round-trip exactly");
    check(loaded.publishRecordsForCreator("creator_2").size() == 1 &&
              loaded.publishRecordsForCreator("creator_2")[0].moderationStatus == "UnderReview",
          "publishRecordsForCreator() real-filters to exactly the real creator's own real publish records");
    check(loaded.publishRecordsForCreator("creator_nobody").empty(),
          "publishRecordsForCreator() real-returns empty for a real creator with no publish records");

    std::remove(path);
}

// Kronos ("Creator Payout Ledger + Ratings Submission + Marketplace
// Moderation v3" -- "Marketplace Moderation v3" -- "backward
// compatibility"): a real, pre-existing (older) transaction log file
// with PUB records that predate PUBCATEGORY still real-loads, defaulting
// the missing field to an empty string rather than failing the whole
// parse.
void testTransactionLogLoadsPrePublishCategoryFileWithHonestDefault() {
    const char* path = "test_pre_publish_category.transactions";
    {
        std::ofstream out(path, std::ios::trunc);
        out << "TRANSACTIONLOG 1\n";
        out << "PUB 1699999000\n";
        out << "PUBITEMID old_item\n";
        out << "PUBITEMNAME Old Item\n";
        out << "PUBCREATOR creator_1\n";
        out << "PUBSTATUS Approved\n";
        out << "END\n";
    }
    engine::marketplace::TransactionLog loaded;
    check(loaded.loadFromFile(path), "a real, pre-PUBCATEGORY transaction log file still loads");
    check(loaded.publishRecords().size() == 1, "the real, pre-existing publish record itself still loads");
    check(loaded.publishRecords()[0].category.empty(),
          "a missing PUBCATEGORY line real-defaults to an empty string, not a parse failure");
    std::remove(path);
}

// --- MathExpression ----------------------------------------------------------

void testEvaluateMathExpressionPlainNumber() {
    float result = 0.0f;
    check(engine::core::evaluateMathExpression("42", 0.0f, result), "evaluateMathExpression() real-parses a plain integer literal");
    check(nearlyEqual(result, 42.0f), "the real result is exactly 42");
}

void testEvaluateMathExpressionNegativeLiteralIsAbsolute() {
    float result = 0.0f;
    check(engine::core::evaluateMathExpression("-5", 100.0f, result), "evaluateMathExpression() real-parses a leading-minus literal");
    check(nearlyEqual(result, -5.0f), "a leading '-' is real-treated as a literal negative number (set to -5), not 'subtract 5 from current'");
}

void testEvaluateMathExpressionSubtractionExpression() {
    float result = 0.0f;
    check(engine::core::evaluateMathExpression("180 - 45", 0.0f, result), "evaluateMathExpression() real-parses \"180 - 45\"");
    check(nearlyEqual(result, 135.0f), "\"180 - 45\" real-evaluates to 135, the exact sprint-quoted example");
}

void testEvaluateMathExpressionRelativeAdd() {
    float result = 0.0f;
    check(engine::core::evaluateMathExpression("+10", 5.0f, result), "evaluateMathExpression() real-parses the relative-add convention \"+10\"");
    check(nearlyEqual(result, 15.0f), "\"+10\" against a real currentValue of 5 real-evaluates to 15 (5+10)");
}

void testEvaluateMathExpressionRelativeMultiply() {
    float result = 0.0f;
    check(engine::core::evaluateMathExpression("*2", 5.0f, result), "evaluateMathExpression() real-parses the relative-multiply convention \"*2\"");
    check(nearlyEqual(result, 10.0f), "\"*2\" against a real currentValue of 5 real-evaluates to 10 (5*2)");
}

void testEvaluateMathExpressionRelativeDivide() {
    float result = 0.0f;
    check(engine::core::evaluateMathExpression("/3", 9.0f, result), "evaluateMathExpression() real-parses the relative-divide convention \"/3\"");
    check(nearlyEqual(result, 3.0f), "\"/3\" against a real currentValue of 9 real-evaluates to 3 (9/3)");
}

void testEvaluateMathExpressionParenthesesAndPrecedence() {
    float result = 0.0f;
    check(engine::core::evaluateMathExpression("2 + 3 * 4", 0.0f, result), "evaluateMathExpression() real-respects operator precedence");
    check(nearlyEqual(result, 14.0f), "\"2 + 3 * 4\" real-evaluates to 14, not 20");

    check(engine::core::evaluateMathExpression("(2 + 3) * 4", 0.0f, result), "evaluateMathExpression() real-respects real parentheses");
    check(nearlyEqual(result, 20.0f), "\"(2 + 3) * 4\" real-evaluates to 20");
}

void testEvaluateMathExpressionUnaryMinusInsideExpression() {
    float result = 0.0f;
    check(engine::core::evaluateMathExpression("10 + -3", 0.0f, result), "evaluateMathExpression() real-handles a real unary minus mid-expression");
    check(nearlyEqual(result, 7.0f), "\"10 + -3\" real-evaluates to 7");
}

void testEvaluateMathExpressionRejectsDivisionByZero() {
    float result = 0.0f;
    check(!engine::core::evaluateMathExpression("5 / 0", 0.0f, result), "evaluateMathExpression() real-rejects division by zero rather than producing inf/nan");
    check(!engine::core::evaluateMathExpression("/0", 5.0f, result), "the relative-divide convention real-rejects a zero divisor too");
}

void testEvaluateMathExpressionRejectsMalformedInput() {
    float result = 0.0f;
    check(!engine::core::evaluateMathExpression("", 0.0f, result), "evaluateMathExpression() real-rejects an empty string");
    check(!engine::core::evaluateMathExpression("   ", 0.0f, result), "evaluateMathExpression() real-rejects a whitespace-only string");
    check(!engine::core::evaluateMathExpression("5 +", 0.0f, result), "evaluateMathExpression() real-rejects a dangling operator");
    check(!engine::core::evaluateMathExpression("(5 + 3", 0.0f, result), "evaluateMathExpression() real-rejects unbalanced parentheses");
    check(!engine::core::evaluateMathExpression("5 3", 0.0f, result), "evaluateMathExpression() real-rejects trailing garbage after a valid expression");
    check(!engine::core::evaluateMathExpression("hello", 0.0f, result), "evaluateMathExpression() real-rejects non-numeric garbage");
}

void testSceneFileRoundTripsScriptComponent() {
    engine::core::SceneFile file;
    engine::core::SceneEntityRecord record;
    record.name = "Scripted";
    record.hasScript = true;
    // Real, deliberately awkward source -- embedded newlines, quotes,
    // and a trailing space, exactly the content a naive space-delimited
    // line format would corrupt; base64 is what makes this survive.
    record.scriptSource = "local x = \"hi\"\nprint(x)\n-- trailing space \n";
    record.scriptAutoRun = false;
    file.entities.push_back(record);

    const char* path = "test_scene_file_script_roundtrip.scene";
    check(file.saveToFile(path), "SceneFile::saveToFile() real-succeeds with a scripted entity");

    engine::core::SceneFile reloaded;
    check(reloaded.loadFromFile(path), "SceneFile::loadFromFile() real-succeeds reading it back");
    check(reloaded.entities.size() == 1, "Sanity: one real entity round-tripped");
    check(reloaded.entities[0].hasScript, "hasScript real-round-trips true");
    check(reloaded.entities[0].scriptSource == record.scriptSource,
          "the real script source -- newlines, quotes, and all -- round-trips byte-for-byte via base64");
    check(!reloaded.entities[0].scriptAutoRun, "scriptAutoRun real-round-trips false");

    std::remove(path);
}

void testSceneManagerCaptureAndLoadRoundTripScriptComponent() {
    engine::core::ECS ecs;
    engine::core::EntityId entity = ecs.createEntity("Scripted");
    auto& script = ecs.addComponent<engine::core::Script>(entity);
    script.source = "return 42\n";
    script.autoRun = true;
    script.scriptId = 7; // live-VM bookkeeping -- must NOT survive the round trip, see SceneEntityRecord's comment
    script.loadedSource = "return 42\n";

    engine::core::Camera camera;
    engine::core::SceneManager sceneManager;
    const char* path = "test_scene_manager_script_roundtrip.scene";
    check(sceneManager.saveScene(path, ecs, camera), "SceneManager::saveScene() real-succeeds with a live Script component");

    engine::core::SceneFile reread;
    check(reread.loadFromFile(path) && reread.entities.size() == 1 && reread.entities[0].hasScript &&
              reread.entities[0].scriptSource == "return 42\n",
          "the real saved file genuinely contains the live script's source");

    std::remove(path);
    std::remove(engine::core::SceneManager::recoveryPathFor(path).c_str());
}

void testSceneManagerCapture() {
    engine::core::ECS ecs;
    engine::core::EntityId box = ecs.createEntity("Box");
    if (auto* t = ecs.tryGetComponent<engine::core::Transform>(box)) t->position = {3.0f, 1.0f, -2.0f};
    auto& renderable = ecs.addComponent<engine::core::Renderable>(box);
    renderable.baseColor = {0.2f, 0.4f, 0.6f, 1.0f};
    renderable.metallic = 0.8f;
    auto& meshSource = ecs.addComponent<engine::core::MeshSource>(box);
    meshSource.kind = engine::core::MeshSourceKind::Box;
    meshSource.params = {0.5f, 0.5f, 0.5f};

    engine::core::EntityId unnamed = ecs.createEntity(); // no Name -- must be excluded from a save
    ecs.addComponent<engine::core::Renderable>(unnamed);

    engine::core::EntityId emitterEntity = ecs.createEntity("Emitter");
    auto& emitter = ecs.addComponent<engine::core::ParticleEmitter>(emitterEntity);
    emitter.settings.emissionRate = 15.0f;

    engine::core::EntityId lightEntity = ecs.createEntity("KeyLight");
    auto& light = ecs.addComponent<engine::core::Light>(lightEntity);
    light.color = {1.0f, 0.9f, 0.8f};
    light.intensity = 2.5f;
    light.radius = 8.0f;

    engine::core::Camera camera;
    camera.position = {5.0f, 6.0f, 7.0f};
    camera.yawDegrees = 120.0f;

    engine::core::SceneManager sceneManager;
    const char* path = "test_scene_manager.scene";
    check(sceneManager.saveScene(path, ecs, camera), "SceneManager::saveScene writes a real file");
    check(sceneManager.currentScenePath() == path, "saveScene() records the path as current");
    check(!sceneManager.isDirty(), "a fresh save clears the dirty flag");

    engine::core::SceneFile reread;
    check(reread.loadFromFile(path), "the file SceneManager wrote is a valid SceneFile");
    check(reread.entities.size() == 3,
          "only named entities (Box, Emitter, KeyLight) were captured -- the unnamed one was skipped");
    check(nearlyEqual(reread.cameraPosition.x, 5.0f) && nearlyEqual(reread.cameraYawDegrees, 120.0f),
          "the live camera's pose was captured");

    bool foundBox = false;
    bool foundEmitter = false;
    bool foundLight = false;
    for (const auto& e : reread.entities) {
        if (e.name == "Box") {
            foundBox = true;
            check(e.hasRenderable && e.hasMeshSource && e.meshSource.kind == engine::core::MeshSourceKind::Box,
                  "Box's Renderable+MeshSource were captured");
            check(nearlyEqual(e.position.x, 3.0f), "Box's live Transform position was captured");
        } else if (e.name == "Emitter") {
            foundEmitter = true;
            check(e.hasParticleEmitter && nearlyEqual(e.emitter.emissionRate, 15.0f),
                  "Emitter's ParticleEmitter settings were captured");
        } else if (e.name == "KeyLight") {
            foundLight = true;
            check(e.hasLight && nearlyEqual(e.light.intensity, 2.5f) && nearlyEqual(e.light.radius, 8.0f),
                  "KeyLight's real Light component was captured");
        }
    }
    check(foundBox && foundEmitter && foundLight, "all three named entities appear in the captured scene");

    // markDirty() + tickAutosave(): a big-enough dt should write a
    // recovery file once the interval elapses, without touching the real
    // save file.
    sceneManager.markDirty();
    check(!engine::core::SceneManager::hasRecoveryFile(path), "no recovery file exists before any autosave has run");
    sceneManager.tickAutosave(engine::core::SceneManager::kAutosaveIntervalSeconds + 1.0f, ecs, camera);
    check(engine::core::SceneManager::hasRecoveryFile(path), "tickAutosave() past the interval writes a recovery file");
    check(sceneManager.isDirty(), "autosave does not clear the dirty flag (only a real Save does)");
    check(!engine::core::SceneHistory::listSnapshots(path).empty(),
          "a real periodic tickAutosave() also feeds a real SceneHistory snapshot");

    check(sceneManager.saveScene(path, ecs, camera), "re-saving the scene succeeds");
    check(!engine::core::SceneManager::hasRecoveryFile(path),
          "a deliberate save consumes/clears the pending recovery file");

    std::remove(path);
    std::remove(engine::core::SceneManager::recoveryPathFor(path).c_str());
    std::filesystem::remove_all(engine::core::SceneHistory::historyDirectoryFor(path));
}

