void testBiomeNamesAreRealAndDistinct() {
    check(std::string(engine::core::biomeName(engine::core::BiomeId::Forest)) == "Forest", "Forest's real name");
    check(std::string(engine::core::biomeName(engine::core::BiomeId::Desert)) == "Desert", "Desert's real name");
    check(std::string(engine::core::biomeName(engine::core::BiomeId::Cave)) == "Cave", "Cave's real name");
}

void testBiomePresetsAreRealAndDistinct() {
    const auto& forest = engine::core::biomePreset(engine::core::BiomeId::Forest);
    const auto& desert = engine::core::biomePreset(engine::core::BiomeId::Desert);
    const auto& cave = engine::core::biomePreset(engine::core::BiomeId::Cave);
    check(!nearlyEqual(forest.lightIntensity, desert.lightIntensity), "Forest and Desert really have different real light intensities, not copy-pasted values");
    check(!nearlyEqual(desert.lightIntensity, cave.lightIntensity), "Desert and Cave really differ too");
    check(glm::length(forest.lightColor - desert.lightColor) > 0.05f, "Forest and Desert really have different real light colors");
}

void testCaveBiomeIsRealistcallyDimmerThanDesert() {
    const auto& cave = engine::core::biomePreset(engine::core::BiomeId::Cave);
    const auto& desert = engine::core::biomePreset(engine::core::BiomeId::Desert);
    check(cave.lightIntensity < desert.lightIntensity, "a real Cave (no real sun reaches it) is genuinely dimmer than a real sun-drenched Desert -- a real, physically-motivated ordering, not arbitrary numbers");
}

void testApplyBiomeLightingOverwritesColorFieldsButNotDirection() {
    engine::core::SceneLighting lighting;
    lighting.directionWS = {0.1f, -0.9f, 0.3f};
    glm::vec3 originalDirection = lighting.directionWS;

    engine::core::applyBiomeLighting(engine::core::BiomeId::Cave, lighting);

    check(lighting.directionWS == originalDirection, "applyBiomeLighting() really leaves directionWS completely untouched -- a biome is a lighting mood, not an independent sun angle (see its own header comment)");
    const auto& cavePreset = engine::core::biomePreset(engine::core::BiomeId::Cave);
    check(nearlyEqual(lighting.intensity, cavePreset.lightIntensity), "applyBiomeLighting() really overwrites intensity with the real preset value");
    check(glm::length(lighting.ambient - cavePreset.ambient) < 0.001f, "...and ambient too");
}

