void testToggleLampFlipsStateAndReturnsCorrectIntensity() {
    engine::core::LampState lamp;
    lamp.on = true;
    lamp.litIntensity = 3.5f;

    float afterFirst = engine::core::toggleLamp(lamp);
    check(!lamp.on, "the first real toggle turns a lit lamp off");
    check(nearlyEqual(afterFirst, 0.0f), "toggling off returns exactly 0 intensity");

    float afterSecond = engine::core::toggleLamp(lamp);
    check(lamp.on, "the second real toggle turns it back on");
    check(nearlyEqual(afterSecond, 3.5f), "toggling back on returns exactly the real, configured litIntensity, not a placeholder");
}

