void testSoftBoundaryCorrectionNoOpInsideRadius() {
    engine::core::WorldBoundary boundary{{0.0f, 0.0f, 0.0f}, 40.0f, 50.0f};
    glm::vec3 inside{10.0f, 3.0f, 10.0f};
    glm::vec3 corrected = engine::core::softBoundaryCorrection(inside, boundary, 1.0f);
    check(corrected == inside, "well inside the soft radius, softBoundaryCorrection() is a real, exact no-op");
}

void testSoftBoundaryCorrectionZeroStrengthIsRealNoOp() {
    engine::core::WorldBoundary boundary{{0.0f, 0.0f, 0.0f}, 10.0f, 50.0f};
    glm::vec3 farOutside{100.0f, 2.0f, 0.0f};
    glm::vec3 corrected = engine::core::softBoundaryCorrection(farOutside, boundary, 0.0f);
    check(corrected == farOutside, "correctionStrength=0 is a real, honest no-op even far outside the soft radius");
}

void testSoftBoundaryCorrectionPullsBackOutsideRadius() {
    engine::core::WorldBoundary boundary{{0.0f, 0.0f, 0.0f}, 40.0f, 50.0f};
    glm::vec3 outside{60.0f, 3.0f, 0.0f}; // 60 from center, 20 past the soft radius
    glm::vec3 corrected = engine::core::softBoundaryCorrection(outside, boundary, 0.5f);
    float correctedDistance = glm::length(glm::vec2(corrected.x, corrected.z));
    check(correctedDistance < 60.0f, "a real, positive correctionStrength really pulls the position back closer to the boundary");
    check(correctedDistance > 40.0f, "...but a partial (0.5) strength doesn't fully clamp it to the soft radius in one call -- a real, gradual nudge, not a teleport");
}

void testSoftBoundaryCorrectionFullStrengthClampsExactlyToSoftRadius() {
    engine::core::WorldBoundary boundary{{5.0f, 0.0f, -5.0f}, 30.0f, 50.0f};
    glm::vec3 outside{5.0f + 80.0f, 1.0f, -5.0f};
    glm::vec3 corrected = engine::core::softBoundaryCorrection(outside, boundary, 1.0f);
    float correctedDistance = glm::length(glm::vec2(corrected.x - boundary.center.x, corrected.z - boundary.center.z));
    check(nearlyEqual(correctedDistance, 30.0f, 0.01f), "correctionStrength=1.0 really clamps exactly to softRadius, a real, precise boundary");
}

void testSoftBoundaryCorrectionPreservesVerticalPosition() {
    engine::core::WorldBoundary boundary{{0.0f, 0.0f, 0.0f}, 10.0f, 50.0f};
    glm::vec3 outside{100.0f, 42.5f, 0.0f};
    glm::vec3 corrected = engine::core::softBoundaryCorrection(outside, boundary, 1.0f);
    check(nearlyEqual(corrected.y, 42.5f), "a horizontal world boundary never touches Y -- jumping/falling is completely unaffected");
}

void testCreateWorldBoundaryWallsSpawnsRealStaticColliders() {
    engine::core::Physics physics;
    check(physics.initialize(), "physics initializes for the world-boundary-walls test");
    engine::core::ECS ecs;

    engine::core::WorldBoundary boundary{{0.0f, 0.0f, 0.0f}, 20.0f, 25.0f};
    size_t entitiesBefore = ecs.entityCount();
    engine::core::createWorldBoundaryWalls(ecs, physics, boundary);
    size_t entitiesAfter = ecs.entityCount();
    check(entitiesAfter - entitiesBefore == 4, "createWorldBoundaryWalls() really spawns exactly 4 real wall entities (a real square boundary)");

    physics.shutdown();
}

void testWorldBoundaryWallsReallyBlockMovement() {
    engine::core::Physics physics;
    check(physics.initialize(), "physics initializes for the real wall-collision test");
    engine::core::ECS ecs;
    physics.createGroundPlane(ecs, 100.0f, 100.0f);

    engine::core::WorldBoundary boundary{{0.0f, 0.0f, 0.0f}, 15.0f, 20.0f};
    engine::core::createWorldBoundaryWalls(ecs, physics, boundary, 6.0f, 1.0f);

    // A real dynamic ball, launched hard toward the +X wall from well
    // inside the boundary -- if the wall is a real, live collider, the
    // ball must stop well short of where it would land with no wall at
    // all (it would travel far past x=20 unobstructed in 2 real seconds
    // at this speed).
    engine::core::EntityId ball = physics.createSphereBody(ecs, {0.0f, 1.0f, 0.0f}, 0.5f, 1.0f);
    physics.applyImpulse(ball, ecs, {40.0f, 0.0f, 0.0f});
    for (int i = 0; i < 120; ++i) physics.step(1.0f / 60.0f, ecs);

    float finalX = ecs.tryGetComponent<engine::core::Transform>(ball)->position.x;
    check(finalX < 22.0f, "a real launched ball is really stopped by the real hard boundary wall, not passing straight through to x=40+");

    physics.shutdown();
}

void testFindLinkedTeleportPadFindsRealMatchAndIgnoresSelfAndUnlinked() {
    engine::core::ECS ecs;
    auto padA = ecs.createEntity("PadA");
    ecs.addComponent<engine::core::TeleportPad>(padA, engine::core::TeleportPad{{0.0f, 0.0f, 0.0f}, "route1"});
    auto padB = ecs.createEntity("PadB");
    ecs.addComponent<engine::core::TeleportPad>(padB, engine::core::TeleportPad{{10.0f, 0.0f, 0.0f}, "route1"});
    auto padC = ecs.createEntity("PadC"); // a real, different, unlinked route
    ecs.addComponent<engine::core::TeleportPad>(padC, engine::core::TeleportPad{{20.0f, 0.0f, 0.0f}, "route2"});
    auto padNoTag = ecs.createEntity("PadNoTag");
    ecs.addComponent<engine::core::TeleportPad>(padNoTag, engine::core::TeleportPad{{30.0f, 0.0f, 0.0f}, ""});

    check(engine::core::findLinkedTeleportPad(ecs, padA) == padB, "padA correctly finds its real linked partner padB (matching linkTag)");
    check(engine::core::findLinkedTeleportPad(ecs, padB) == padA, "the link really works both directions");
    check(engine::core::findLinkedTeleportPad(ecs, padC) == engine::core::kNullEntity, "a pad on a different real route finds no match");
    check(engine::core::findLinkedTeleportPad(ecs, padNoTag) == engine::core::kNullEntity, "a pad with an empty linkTag honestly finds nothing, not a false match");
}

