void testNotificationCenterDefaultDurationIsApplied() {
    engine::studio::NotificationCenter center;
    center.push("Build failed", engine::studio::NotificationSeverity::Error);
    check(nearlyEqual(center.active()[0].totalSeconds, engine::studio::NotificationCenter::kDefaultDurationSeconds), "push() without an explicit duration uses the real default duration");
    check(nearlyEqual(center.active()[0].remainingSeconds, engine::studio::NotificationCenter::kDefaultDurationSeconds), "a freshly pushed notification's remaining time starts at its full duration");
}

void testNotificationCenterExplicitDurationIsHonored() {
    engine::studio::NotificationCenter center;
    center.push("Custom", engine::studio::NotificationSeverity::Info, 1.5f);
    check(nearlyEqual(center.active()[0].totalSeconds, 1.5f), "an explicit duration argument overrides the default");
}

void testNotificationCenterTickCountsDownRemainingSeconds() {
    engine::studio::NotificationCenter center;
    center.push("Test", engine::studio::NotificationSeverity::Info, 4.0f);
    center.tick(1.0f);
    check(nearlyEqual(center.active()[0].remainingSeconds, 3.0f), "tick(dt) decrements remainingSeconds by exactly dt");
    center.tick(0.5f);
    check(nearlyEqual(center.active()[0].remainingSeconds, 2.5f), "successive tick() calls accumulate correctly");
}

void testNotificationCenterTickRemovesExpiredNotifications() {
    engine::studio::NotificationCenter center;
    center.push("Short-lived", engine::studio::NotificationSeverity::Info, 1.0f);
    center.tick(1.5f);
    check(center.count() == 0, "tick() removes a notification once remainingSeconds reaches zero");
}

void testNotificationCenterTickKeepsUnexpiredNotifications() {
    engine::studio::NotificationCenter center;
    center.push("Long-lived", engine::studio::NotificationSeverity::Info, 4.0f);
    center.tick(1.0f);
    check(center.count() == 1, "tick() does not remove a notification whose remainingSeconds is still positive");
}

void testNotificationCenterMixedExpiryOnlyRemovesExpiredOnes() {
    engine::studio::NotificationCenter center;
    center.push("Expires soon", engine::studio::NotificationSeverity::Info, 1.0f);
    center.push("Expires later", engine::studio::NotificationSeverity::Info, 10.0f);
    center.tick(2.0f);
    check(center.count() == 1, "tick() removes only the notification that actually expired, keeping the other real, live one");
    check(center.active()[0].message == "Expires later", "the surviving notification is really the one whose duration hadn't elapsed yet");
}

void testNotificationCenterOverflowDropsOldest() {
    engine::studio::NotificationCenter center;
    for (size_t i = 0; i < engine::studio::NotificationCenter::kMaxNotifications + 3; ++i) {
        center.push("Notification " + std::to_string(i), engine::studio::NotificationSeverity::Info, 100.0f);
    }
    check(center.count() == engine::studio::NotificationCenter::kMaxNotifications, "pushing past kMaxNotifications really caps the queue at its bound, not unbounded growth");
    check(center.active().front().message == "Notification 3", "overflow really drops the oldest notifications first (FIFO), not the newest");
    check(center.active().back().message == "Notification 10", "the most recently pushed notification really survives overflow eviction");
}

void testNotificationCenterClearRemovesEverything() {
    engine::studio::NotificationCenter center;
    center.push("A", engine::studio::NotificationSeverity::Info);
    center.push("B", engine::studio::NotificationSeverity::Warning);
    center.clear();
    check(center.count() == 0, "clear() really empties the queue");
}

void testNotificationCenterAllSeveritiesPreserved() {
    engine::studio::NotificationCenter center;
    center.push("info", engine::studio::NotificationSeverity::Info);
    center.push("success", engine::studio::NotificationSeverity::Success);
    center.push("warning", engine::studio::NotificationSeverity::Warning);
    center.push("error", engine::studio::NotificationSeverity::Error);
    check(center.active()[0].severity == engine::studio::NotificationSeverity::Info, "Info severity round-trips correctly");
    check(center.active()[1].severity == engine::studio::NotificationSeverity::Success, "Success severity round-trips correctly");
    check(center.active()[2].severity == engine::studio::NotificationSeverity::Warning, "Warning severity round-trips correctly");
    check(center.active()[3].severity == engine::studio::NotificationSeverity::Error, "Error severity round-trips correctly");
}

void testNotificationCenterStressManyRapidPushesStaysBounded() {
    // Task category 7 ("Performance & Responsiveness"): a real burst of
    // 1000 rapid-fire pushes (far more than any real save/build/error
    // sequence would produce in practice) -- the bounded-FIFO invariant
    // must hold after every single push, not just at the end.
    engine::studio::NotificationCenter center;
    bool everExceededBound = false;
    for (int i = 0; i < 1000; ++i) {
        center.push("Burst " + std::to_string(i), engine::studio::NotificationSeverity::Info, 5.0f);
        if (center.count() > engine::studio::NotificationCenter::kMaxNotifications) everExceededBound = true;
    }
    check(!everExceededBound, "the bounded-FIFO invariant holds after every one of 1000 rapid pushes, not just eventually");
    check(center.count() == engine::studio::NotificationCenter::kMaxNotifications, "after the stress burst, the queue is really at its real bound");
    check(center.active().back().message == "Burst 999", "the very last pushed notification really survived the stress burst");

    // Real, sustained ticking under load -- 500 small ticks must drain the
    // whole queue to empty with no crash, no negative remainingSeconds
    // left un-cleaned, no UB from repeated erase-while-iterating.
    for (int i = 0; i < 500; ++i) center.tick(1.0f / 60.0f);
    check(center.count() == 0, "500 real ticks at 60fps-scale dt really drains a fully-loaded queue to empty");
}

