void testIconForCategoryMapsToRealDistinctIcons() {
    check(engine::studio::iconForCategory(engine::studio::EntityCategory::Terrain) == engine::studio::Icon::Terrain, "Terrain category maps to the real Terrain icon");
    check(engine::studio::iconForCategory(engine::studio::EntityCategory::Prop) == engine::studio::Icon::Prop, "Prop category maps to the real Prop icon");
    check(engine::studio::iconForCategory(engine::studio::EntityCategory::Physics) == engine::studio::Icon::Physics, "Physics category maps to the real Physics icon");
    check(engine::studio::iconForCategory(engine::studio::EntityCategory::Economy) == engine::studio::Icon::Material, "Economy category maps to the real Material icon (rarity-colored ore swatch reasoning)");
    check(engine::studio::iconForCategory(engine::studio::EntityCategory::Navigation) == engine::studio::Icon::WorldSpace, "Navigation category maps to the real WorldSpace (globe) icon");
    check(engine::studio::iconForCategory(engine::studio::EntityCategory::Other) == engine::studio::Icon::Folder, "Other category maps to the real Folder icon");

    // Every category with a *dedicated* icon (excluding Other's honest
    // Folder reuse) must really be pairwise distinct -- the same "not six
    // recolors of the same glyph" discipline this session's other icon
    // work already established.
    engine::studio::Icon dedicated[] = {engine::studio::Icon::Terrain, engine::studio::Icon::Prop, engine::studio::Icon::Physics,
                                          engine::studio::Icon::Material, engine::studio::Icon::WorldSpace};
    bool allDistinct = true;
    for (size_t i = 0; i < 5; ++i)
        for (size_t j = i + 1; j < 5; ++j)
            if (dedicated[i] == dedicated[j]) allDistinct = false;
    check(allDistinct, "every category's dedicated icon is really a distinct glyph, not a hidden duplicate");
}

