void testNotificationCenterZeroDurationExpiresOnFirstTick() {
    engine::studio::NotificationCenter center;
    center.push("Instant", engine::studio::NotificationSeverity::Info, 0.0f);
    check(center.count() == 1, "a zero-duration notification is still really added to the queue");
    center.tick(0.001f);
    check(center.count() == 0, "a zero-duration notification honestly expires on the very next tick, however small dt is");
}

void testNotificationCenterPushPreservesFIFOOrder() {
    engine::studio::NotificationCenter center;
    center.push("First", engine::studio::NotificationSeverity::Info, 10.0f);
    center.push("Second", engine::studio::NotificationSeverity::Info, 10.0f);
    center.push("Third", engine::studio::NotificationSeverity::Info, 10.0f);
    check(center.active()[0].message == "First", "the real FIFO order keeps the first-pushed notification at index 0");
    check(center.active()[1].message == "Second", "...the second-pushed notification really stays at index 1...");
    check(center.active()[2].message == "Third", "...and the third-pushed notification really stays at index 2");
}

void testNotificationCenterTickWithZeroDtChangesNothing() {
    engine::studio::NotificationCenter center;
    center.push("Steady", engine::studio::NotificationSeverity::Info, 4.0f);
    center.tick(0.0f);
    check(nearlyEqual(center.active()[0].remainingSeconds, 4.0f), "tick(0.0f) really leaves remainingSeconds completely unchanged");
    check(center.count() == 1, "tick(0.0f) never spuriously expires a notification with real time left");
}

void testNotificationCenterCountAlwaysMatchesActiveSize() {
    engine::studio::NotificationCenter center;
    check(center.count() == center.active().size(), "count() really matches active().size() when empty");
    center.push("A", engine::studio::NotificationSeverity::Info, 2.0f);
    center.push("B", engine::studio::NotificationSeverity::Info, 5.0f);
    check(center.count() == center.active().size(), "count() really matches active().size() after pushes");
    center.tick(3.0f);
    check(center.count() == center.active().size(), "count() really matches active().size() after a tick that expires one of them");
}

