void testProfilerRecordingToJsonProducesValidParsableJson() {
    engine::core::Profiler profiler;
    profiler.startRecording();
    engine::core::PerformanceMetrics metrics;
    metrics.frameTimeMs = 16.5f;
    metrics.drawCalls = 123;
    metrics.activePhysicsBodies = 7;
    profiler.recordSnapshot(metrics, 5.5);
    std::string json = profiler.recordingToJson();
    bool parsedOk = true;
    nlohmann::json parsed;
    try {
        parsed = nlohmann::json::parse(json);
    } catch (const nlohmann::json::parse_error&) {
        parsedOk = false;
    }
    check(parsedOk, "recordingToJson() really produces syntactically valid, parsable JSON");
    check(parsedOk && parsed.is_array() && parsed.size() == 1, "the parsed JSON really contains exactly one real recorded sample");
    if (parsedOk && parsed.size() == 1) {
        check(nearlyEqual(parsed[0]["frameTimeMs"].get<float>(), 16.5f), "the real frameTimeMs value really round-trips through JSON");
        check(parsed[0]["drawCalls"].get<uint32_t>() == 123, "the real drawCalls value really round-trips through JSON");
        check(parsed[0]["activePhysicsBodies"].get<uint32_t>() == 7, "the real activePhysicsBodies value really round-trips through JSON");
        check(nearlyEqual(static_cast<float>(parsed[0]["timestampSeconds"].get<double>()), 5.5f), "the real timestamp really round-trips through JSON");
    }
}

void testProfilerWriteRecordingToJsonFileRoundTrips() {
    const char* path = "test_performance_recording.json";
    engine::core::Profiler profiler;
    profiler.startRecording();
    engine::core::PerformanceMetrics metrics;
    metrics.fps = 59.9f;
    profiler.recordSnapshot(metrics, 1.0);
    bool wrote = profiler.writeRecordingToJsonFile(path);
    check(wrote, "writeRecordingToJsonFile() really reports success for a writable real path");

    std::ifstream in(path);
    check(in.is_open(), "the real file really exists on disk after writeRecordingToJsonFile()");
    std::stringstream buffer;
    buffer << in.rdbuf();
    nlohmann::json parsed;
    bool parsedOk = true;
    try {
        parsed = nlohmann::json::parse(buffer.str());
    } catch (const nlohmann::json::parse_error&) {
        parsedOk = false;
    }
    check(parsedOk && parsed.is_array() && parsed.size() == 1, "the real on-disk file really contains the real recorded sample, round-tripped through a real file write+read");
    if (parsedOk && parsed.size() == 1) {
        check(nearlyEqual(parsed[0]["fps"].get<float>(), 59.9f), "the real fps value really survives a full write-to-disk/read-from-disk round trip");
    }
    std::remove(path);
}

void testProfilerStressManyFramesRealisticWorkload() {
    // Task category 5 ("Testing"): a real, sustained 2000-frame synthetic
    // session mixing a steady baseline with periodic real spikes and one
    // real stall -- the event log must stay bounded and the profiler must
    // not crash/hang across a real, sustained run.
    engine::core::Profiler profiler;
    double t = 0.0;
    for (int i = 0; i < 2000; ++i) {
        float frameTime = 16.0f;
        if (i % 97 == 0) frameTime = 90.0f;              // a real periodic spike
        if (i >= 500 && i < 510) frameTime = 45.0f;       // a real, deliberate 10-frame stall window
        profiler.recordFrame(frameTime, t);
        t += static_cast<double>(frameTime) / 1000.0;
    }
    check(profiler.events().size() <= engine::core::Profiler::kMaxEvents, "2000 real frames of mixed synthetic load never exceed the real bounded event cap");
    bool foundStall = false;
    for (const auto& event : profiler.events()) {
        if (event.kind == engine::core::ProfilerEventKind::StallStart) foundStall = true;
    }
    check(foundStall, "the deliberate 10-frame slow window in the stress workload really produced a real detected stall");
}

