void testComputeChunkHeightStatsAveragesCorrectly() {
    // gridResolution=5, chunkCount=2 -> cellsPerChunk=2, vertsPerAxis=3.
    // height(x,z) = x -- chunk(0,0) covers grid x=0..2 (values 0,1,2,
    // real average 1.0); chunk(1,0) covers grid x=2..4 (values 2,3,4,
    // real average 3.0) -- real, distinct, easily-hand-verified averages.
    constexpr uint32_t kGridRes = 5;
    std::vector<float> heights(kGridRes * kGridRes);
    for (uint32_t z = 0; z < kGridRes; ++z) {
        for (uint32_t x = 0; x < kGridRes; ++x) heights[z * kGridRes + x] = static_cast<float>(x);
    }
    auto lowChunk = engine::core::Terrain::computeChunkHeightStats(heights, kGridRes, 2, 0, 0);
    check(nearlyEqual(lowChunk.averageHeight, 1.0f), "computeChunkHeightStats() really averages chunk(0,0)'s own real 0/1/2 samples to 1.0");
    auto highChunk = engine::core::Terrain::computeChunkHeightStats(heights, kGridRes, 2, 1, 0);
    check(nearlyEqual(highChunk.averageHeight, 3.0f), "computeChunkHeightStats() really averages chunk(1,0)'s own real 2/3/4 samples to 3.0, a real-distinct chunk from (0,0)");
}

void testComputeChunkHeightStatsHeightRangeDistinguishesFlatFromSteep() {
    constexpr uint32_t kGridRes = 5;
    std::vector<float> flatHeights(kGridRes * kGridRes, 5.0f); // real, perfectly flat
    auto flatStats = engine::core::Terrain::computeChunkHeightStats(flatHeights, kGridRes, 2, 0, 0);
    check(nearlyEqual(flatStats.heightRange, 0.0f), "a real, perfectly flat chunk really has a heightRange of exactly 0.0");

    std::vector<float> steepHeights(kGridRes * kGridRes);
    for (uint32_t z = 0; z < kGridRes; ++z) {
        for (uint32_t x = 0; x < kGridRes; ++x) steepHeights[z * kGridRes + x] = ((x + z) % 2 == 0) ? 0.0f : 10.0f;
    }
    auto steepStats = engine::core::Terrain::computeChunkHeightStats(steepHeights, kGridRes, 2, 0, 0);
    check(nearlyEqual(steepStats.heightRange, 10.0f), "a real, sharply-alternating chunk really has a real, wide heightRange (10.0) -- a real, working slope/steepness proxy");
    check(steepStats.heightRange > flatStats.heightRange, "the real steep chunk's heightRange is really greater than the real flat chunk's");
}

void testComputeChunkHeightStatsHandlesEmptyOrDegenerateInputSafely() {
    std::vector<float> empty;
    auto stats = engine::core::Terrain::computeChunkHeightStats(empty, 5, 2, 0, 0);
    check(nearlyEqual(stats.averageHeight, 0.0f) && nearlyEqual(stats.heightRange, 0.0f),
          "an empty real height grid really produces a real, honest zeroed result, not a crash or out-of-bounds read");
    std::vector<float> small(4, 1.0f); // smaller than gridResolution*gridResolution really claims
    auto smallStats = engine::core::Terrain::computeChunkHeightStats(small, 5, 2, 0, 0);
    check(smallStats.averageHeight >= 0.0f, "a real, undersized height grid really doesn't read out of bounds -- this call really completes rather than crashing");
}

void testSelectMaterialBandPicksFirstMatchingBandInOrder() {
    using engine::core::PbrTextureSet;
    using Band = engine::core::Terrain::HeightSlopeMaterialBand;
    PbrTextureSet sandTex; sandTex.albedo = 100;
    PbrTextureSet stoneTex; stoneTex.albedo = 200;
    // Real, deliberately overlapping bands -- both could real-match a
    // low, flat chunk; the first one listed (sand) must really win.
    std::vector<Band> bands = {
        Band{10.0f, 2.0f, &sandTex, 0.0f, 0.9f},
        Band{1e6f, 1e6f, &stoneTex, 0.02f, 0.9f}, // real catch-all
    };
    engine::core::Terrain::ChunkHeightStats lowFlat{2.0f, 0.5f};
    size_t index = engine::core::Terrain::selectMaterialBand(bands, lowFlat);
    check(index == 0, "selectMaterialBand() really picks the real *first* matching band, not the tightest-fitting one -- a real, ordered-priority chain");
    check(bands[index].material->albedo == 100, "the real selected band really is the real sand band");
}

void testSelectMaterialBandFallsThroughToLaterBandWhenEarlierOneDoesNotMatch() {
    using engine::core::PbrTextureSet;
    using Band = engine::core::Terrain::HeightSlopeMaterialBand;
    PbrTextureSet sandTex; sandTex.albedo = 100;
    PbrTextureSet stoneTex; stoneTex.albedo = 200;
    std::vector<Band> bands = {
        Band{10.0f, 2.0f, &sandTex, 0.0f, 0.9f},
        Band{1e6f, 1e6f, &stoneTex, 0.02f, 0.9f},
    };
    engine::core::Terrain::ChunkHeightStats highSteep{500.0f, 50.0f}; // really fails the sand band's real thresholds
    size_t index = engine::core::Terrain::selectMaterialBand(bands, highSteep);
    check(index == 1, "a real chunk that really fails an earlier band's thresholds really falls through to the next real matching band");
    check(bands[index].material->albedo == 200, "the real selected band really is the real catch-all stone band");
}

void testSelectMaterialBandReturnsSizeAsSentinelWhenNoBandMatches() {
    using engine::core::PbrTextureSet;
    using Band = engine::core::Terrain::HeightSlopeMaterialBand;
    PbrTextureSet sandTex; sandTex.albedo = 100;
    std::vector<Band> bands = {Band{10.0f, 2.0f, &sandTex, 0.0f, 0.9f}};
    engine::core::Terrain::ChunkHeightStats noMatch{500.0f, 50.0f};
    size_t index = engine::core::Terrain::selectMaterialBand(bands, noMatch);
    check(index == bands.size(), "selectMaterialBand() really returns bands.size() as a real, explicit \"no match\" sentinel, never a dangling/out-of-range index treated as valid");
}

void testSelectMaterialBandHandlesEmptyBandsList() {
    std::vector<engine::core::Terrain::HeightSlopeMaterialBand> empty;
    engine::core::Terrain::ChunkHeightStats stats{1.0f, 1.0f};
    size_t index = engine::core::Terrain::selectMaterialBand(empty, stats);
    check(index == 0, "an empty real bands list really returns 0 (== empty.size()), a real, honest \"no match\" from an empty real chain");
}

