void testScanSceneForMessagesStressManyEntitiesFindsAllRealIssues() {
    // Task category 6 ("Testing"): 150 real entities, a real, deliberate
    // mix of clean ones and ones with a planted, known issue -- the real
    // scan must find exactly the expected count of each, at a scale
    // closer to a real, populated creator scene than a one-entity check.
    engine::core::ECS ecs;
    for (int i = 0; i < 100; ++i) (void)ecs.createEntity("Clean" + std::to_string(i)); // no issues
    for (int i = 0; i < 30; ++i) {
        auto entity = ecs.createEntity("BadCollider" + std::to_string(i));
        ecs.addComponent<engine::core::ColliderShape>(entity, engine::core::ColliderShape{});
    }
    for (int i = 0; i < 20; ++i) {
        auto entity = ecs.createEntity("UnlinkedPad" + std::to_string(i));
        engine::core::TeleportPad state;
        state.linkTag = "tag_" + std::to_string(i); // each uniquely unlinked
        ecs.addComponent<engine::core::TeleportPad>(entity, state);
    }
    auto messages = engine::studio::scanSceneForMessages(ecs, true);
    int warningCount = 0;
    for (const auto& message : messages) {
        if (message.severity == engine::studio::ConsoleMessageSeverity::Warning) ++warningCount;
    }
    check(warningCount == 50, "at real scale (150 entities), the scan finds exactly the 30 planted collider-only warnings plus 20 planted unlinked-pad warnings -- 50 total, no more, no less");
}

