// Kronos (Alpha Roadmap Phase 6, "Tooling Layer" -- "Lighting editor").
void testSpawnPointLightAuthoringCreatesRealLightAndVisual() {
    engine::core::ECS ecs;
    auto entity = engine::studio::spawnPointLightAuthoring(ecs, {3.0f, 2.0f, 1.0f}, 1, kTestBoxMesh);

    auto* light = ecs.tryGetComponent<engine::core::Light>(entity);
    check(light != nullptr, "spawnPointLightAuthoring() really attaches a real core::Light");
    check(light != nullptr && light->enabled, "the real spawned Light defaults to enabled");

    auto* renderable = ecs.tryGetComponent<engine::core::Renderable>(entity);
    check(renderable != nullptr && renderable->meshHandle == kTestBoxMesh,
          "a spawned point light really has a real, visible Renderable (the requested box mesh handle) -- not an "
          "invisible marker, since a light needs to be seen to be placed by eye");
    check(renderable != nullptr && renderable->emissiveIntensity > 0.0f,
          "the real spawned visual is really emissive, reading like a light in the viewport");

    auto* transform = ecs.tryGetComponent<engine::core::Transform>(entity);
    check(transform != nullptr && nearlyEqual(transform->position.x, 3.0f) && nearlyEqual(transform->position.y, 2.0f) &&
              nearlyEqual(transform->position.z, 1.0f),
          "the spawned light's real position matches what was requested");

    auto* name = ecs.tryGetComponent<engine::core::Name>(entity);
    check(name != nullptr && name->value == "PointLight 1",
          "the spawned light's real display name includes the real spawn index, matching every other "
          "spawnXAuthoring()'s own naming convention");
}

