engine::core::AnimationTrack buildTestPropTrack() {
    engine::core::AnimationTrack track("PropAnimation");
    engine::core::Keyframe closed;
    closed.time = 0.0f;
    closed.position = {0.0f, 0.0f, 0.0f};
    track.addKeyframe(closed);
    engine::core::Keyframe open;
    open.time = 2.0f;
    open.position = {0.0f, 2.0f, 0.0f};
    track.addKeyframe(open);
    return track;
}

void testEvaluatePropAnimationReturnsRealPoseAtCurrentTime() {
    engine::core::PropAnimationHook hook;
    hook.track = buildTestPropTrack();
    hook.currentTime = 1.0f;
    engine::core::AnimatedPose pose = engine::core::evaluatePropAnimation(hook);
    check(nearlyEqual(pose.position.y, 1.0f), "evaluatePropAnimation() really evaluates the real track at the hook's current time (halfway between 0 and 2 -> y=1.0)");
}

void testTickPropAnimationHookAdvancesTowardOpenWhenPlayingForward() {
    engine::core::PropAnimationHook hook;
    hook.track = buildTestPropTrack();
    hook.playingForward = true;
    engine::core::AnimatedPose pose = engine::core::tickPropAnimationHook(hook, 0.5f);
    check(nearlyEqual(hook.currentTime, 0.5f), "tickPropAnimationHook() really advances currentTime toward the open end when playingForward");
    check(nearlyEqual(pose.position.y, 0.5f), "...and returns the real resulting pose at that new time");
}

void testTickPropAnimationHookAdvancesTowardClosedWhenNotPlayingForward() {
    engine::core::PropAnimationHook hook;
    hook.track = buildTestPropTrack();
    hook.currentTime = 2.0f;
    hook.playingForward = false;
    engine::core::tickPropAnimationHook(hook, 0.5f);
    check(nearlyEqual(hook.currentTime, 1.5f), "tickPropAnimationHook() really advances currentTime back toward closed (0) when not playingForward");
}

void testTickPropAnimationHookClampsAtOpenEnd() {
    engine::core::PropAnimationHook hook;
    hook.track = buildTestPropTrack();
    hook.currentTime = 1.8f;
    hook.playingForward = true;
    engine::core::tickPropAnimationHook(hook, 1.0f); // would overshoot past 2.0 without clamping
    check(nearlyEqual(hook.currentTime, 2.0f), "tickPropAnimationHook() really clamps at the track's real last-keyframe time, never overshooting past open");
}

void testTickPropAnimationHookClampsAtClosedEnd() {
    engine::core::PropAnimationHook hook;
    hook.track = buildTestPropTrack();
    hook.currentTime = 0.3f;
    hook.playingForward = false;
    engine::core::tickPropAnimationHook(hook, 1.0f); // would overshoot past 0 without clamping
    check(nearlyEqual(hook.currentTime, 0.0f), "tickPropAnimationHook() really clamps at exactly 0.0, never going negative");
}

void testTickPropAnimationHookNoOpWhenAlreadyAtTarget() {
    engine::core::PropAnimationHook hook;
    hook.track = buildTestPropTrack();
    hook.currentTime = 2.0f;
    hook.playingForward = true;
    engine::core::tickPropAnimationHook(hook, 0.5f);
    check(nearlyEqual(hook.currentTime, 2.0f), "a hook already exactly at its real target really doesn't drift further (no overshoot past a clamped bound)");
}

void testTogglePropAnimationFlipsIsOpenAndPlayingForward() {
    engine::core::PropAnimationHook hook;
    check(!hook.isOpen && !hook.playingForward, "sanity: a fresh hook starts closed");
    engine::core::togglePropAnimation(hook);
    check(hook.isOpen && hook.playingForward, "togglePropAnimation() really flips both isOpen and playingForward to true from a closed state");
}

