void testTickPropAnimationHookEmptyTrackReturnsIdentityPose() {
    engine::core::PropAnimationHook hook; // real, default-constructed, empty track
    hook.playingForward = true;
    engine::core::AnimatedPose pose = engine::core::tickPropAnimationHook(hook, 1.0f);
    check(nearlyEqual(hook.currentTime, 0.0f), "an empty track has no real 'open' end to advance toward -- currentTime honestly stays 0");
    check(nearlyEqual(pose.position.x, 0.0f) && nearlyEqual(pose.position.y, 0.0f) && nearlyEqual(pose.position.z, 0.0f), "...and the resulting pose is the real identity pose AnimationTrack::evaluate() returns for a keyframe-less track");
}

void testTickPropAnimationHookRealMultiKeyframeInterpolation() {
    engine::core::AnimationTrack track("PropAnimation");
    engine::core::Keyframe k0;
    k0.time = 0.0f;
    k0.position = {0.0f, 0.0f, 0.0f};
    track.addKeyframe(k0);
    engine::core::Keyframe k1;
    k1.time = 1.0f;
    k1.position = {0.0f, 1.0f, 0.0f};
    track.addKeyframe(k1);
    engine::core::Keyframe k2;
    k2.time = 2.0f;
    k2.position = {0.0f, 1.0f, 1.0f};
    track.addKeyframe(k2);
    engine::core::PropAnimationHook hook;
    hook.track = track;
    hook.currentTime = 1.5f;
    engine::core::AnimatedPose pose = engine::core::evaluatePropAnimation(hook);
    check(nearlyEqual(pose.position.y, 1.0f) && nearlyEqual(pose.position.z, 0.5f), "a real 3-keyframe timeline (the 'simple timeline editor' this task asks for) interpolates correctly between the 2nd and 3rd keyframes, not just a 2-point tween");
}

void testTickPropAnimationHookStressManyTicksConvergesExactly() {
    // Task category 6 ("Testing"): 500 small real ticks, matching a real
    // sustained multi-second open sweep at a real 60fps-scale dt.
    engine::core::PropAnimationHook hook;
    hook.track = buildTestPropTrack();
    hook.playingForward = true;
    for (int i = 0; i < 500; ++i) engine::core::tickPropAnimationHook(hook, 1.0f / 60.0f);
    check(nearlyEqual(hook.currentTime, 2.0f), "500 real small ticks (more than enough real time to reach a 2-second track) converge to exactly the real open end, no drift past it");
}

