void testEnetTransportRealHandshakeFiresCallbacks() {
    engine::net::ENetTransport server;
    check(server.hostServer(17802, 4), "Sanity: real server real-hosts for the handshake callback test");
    engine::net::ENetTransport client;
    check(client.connectToServer("127.0.0.1", 17802), "Sanity: real client real-initiates connection for the handshake callback test");

    bool serverSawConnect = false;
    bool clientSawConnect = false;
    for (int i = 0; i < 200 && !(serverSawConnect && clientSawConnect); ++i) {
        engine::net::ENetTransport::Callbacks serverCallbacks;
        serverCallbacks.onPeerConnected = [&](engine::net::ENetTransport::PeerId) { serverSawConnect = true; };
        server.poll(0, serverCallbacks);
        engine::net::ENetTransport::Callbacks clientCallbacks;
        clientCallbacks.onPeerConnected = [&](engine::net::ENetTransport::PeerId) { clientSawConnect = true; };
        client.poll(0, clientCallbacks);
        if (!(serverSawConnect && clientSawConnect)) std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }
    check(serverSawConnect, "A real server really fires onPeerConnected for a real incoming client connection");
    check(clientSawConnect, "A real client really fires onPeerConnected once its real outbound connection completes");
    check(server.connectedPeerCount() == 1, "The real server really counts exactly 1 real connected peer after the handshake");

    client.shutdown();
    server.shutdown();
}

void testEnetTransportRealSendReceivesPayload() {
    engine::net::ENetTransport server;
    check(server.hostServer(17803, 4), "Sanity: real server real-hosts for the send/receive test");
    engine::net::ENetTransport client;
    check(client.connectToServer("127.0.0.1", 17803), "Sanity: real client real-connects for the send/receive test");

    engine::net::ENetTransport::PeerId serverSidePeer = 0;
    for (int i = 0; i < 200 && serverSidePeer == 0; ++i) {
        engine::net::ENetTransport::Callbacks serverCallbacks;
        serverCallbacks.onPeerConnected = [&](engine::net::ENetTransport::PeerId peer) { serverSidePeer = peer; };
        server.poll(0, serverCallbacks);
        engine::net::ENetTransport::Callbacks clientCallbacks;
        client.poll(0, clientCallbacks);
        if (serverSidePeer == 0) std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }
    check(serverSidePeer != 0, "Sanity: real handshake completed before the send/receive test");

    std::vector<uint8_t> payload{1, 2, 3, 4, 5};
    client.send(engine::net::ENetTransport::kBroadcast, payload.data(), payload.size(), 0, true);

    std::vector<uint8_t> received;
    for (int i = 0; i < 200 && received.empty(); ++i) {
        engine::net::ENetTransport::Callbacks serverCallbacks;
        serverCallbacks.onPacketReceived = [&](engine::net::ENetTransport::PeerId, const uint8_t* data, size_t size, uint8_t) {
            received.assign(data, data + size);
        };
        server.poll(0, serverCallbacks);
        // enet_peer_send() only queues the packet -- it's actually
        // flushed onto the wire as a side effect of a real
        // enet_host_service() call on the SENDING host (real ENet
        // behavior, not a client-specific quirk), so the client must
        // keep being polled here too or its queued send never goes out.
        engine::net::ENetTransport::Callbacks clientCallbacks;
        client.poll(0, clientCallbacks);
        if (received.empty()) std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }
    check(received.size() == 5, "The real server really receives the exact real byte payload the client sent");
    check(received == payload, "The real received payload's real bytes match exactly what was really sent, byte for byte");

    client.shutdown();
    server.shutdown();
}

