void testProfanityFilterDetectsSeedWord() {
    engine::moderation::ProfanityFilter filter;
    auto result = filter.check("that was a damn good shot");
    check(result.containsProfanity, "ProfanityFilter real-detects a real seed word ('damn') in a real sentence");
}

void testProfanityFilterCensorsInPlacePreservingLength() {
    engine::moderation::ProfanityFilter filter;
    auto result = filter.check("this is shit");
    check(result.censored == "this is ****", "ProfanityFilter real-censors the matched word in place with the same real length, leaving surrounding words untouched");
}

void testProfanityFilterCleanTextUnaffected() {
    engine::moderation::ProfanityFilter filter;
    auto result = filter.check("what a lovely day for mining");
    check(!result.containsProfanity, "ProfanityFilter real-reports no profanity for a real clean sentence");
    check(result.censored == "what a lovely day for mining", "ProfanityFilter real-leaves clean text completely unchanged");
}

void testProfanityFilterCaseInsensitive() {
    engine::moderation::ProfanityFilter filter;
    auto result = filter.check("DAMN it all");
    check(result.containsProfanity, "ProfanityFilter real-matches regardless of real case (DAMN vs damn)");
}

void testProfanityFilterDetectsLeetspeakVariant() {
    engine::moderation::ProfanityFilter filter;
    auto result = filter.check("d4mn this is hard");
    check(result.containsProfanity, "ProfanityFilter real-catches a leetspeak-obfuscated word via the shared safety::normalizeChar table");
}

void testProfanityFilterMultipleWordsInOneMessage() {
    engine::moderation::ProfanityFilter filter;
    auto result = filter.check("damn this shit is hard");
    check(result.containsProfanity, "ProfanityFilter real-flags a message with multiple real profane words");
    check(result.censored == "**** this **** is hard", "ProfanityFilter real-censors every real matched word independently, not just the first");
}

void testProfanityFilterAddWordDetectsNewWord() {
    engine::moderation::ProfanityFilter filter;
    check(!filter.check("noob").containsProfanity, "Sanity: 'noob' isn't in the real default seed list");
    filter.addWord("noob");
    check(filter.check("noob").containsProfanity, "addWord() real-extends detection to a real newly-added word");
}

void testProfanityFilterRemoveWordStopsDetecting() {
    engine::moderation::ProfanityFilter filter;
    check(filter.check("damn").containsProfanity, "Sanity: 'damn' is real-detected before removal");
    filter.removeWord("damn");
    check(!filter.check("damn").containsProfanity, "removeWord() real-stops detecting a real removed word");
}

void testProfanityFilterWordCountReflectsSeedList() {
    engine::moderation::ProfanityFilter filter;
    check(filter.wordCount() == 8, "ProfanityFilter's real seed list has the real documented 8 words");
    filter.addWord("newword");
    check(filter.wordCount() == 9, "addWord() real-increments wordCount()");
}

void testProfanityFilterPreservesNonProfaneWordsUncensored() {
    engine::moderation::ProfanityFilter filter;
    auto result = filter.check("hello damn world");
    check(result.censored.substr(0, 5) == "hello" && result.censored.substr(result.censored.size() - 5) == "world",
          "ProfanityFilter real-leaves non-profane words in the same message completely untouched");
}

void testProfanityFilterEmptyTextNoProfanity() {
    engine::moderation::ProfanityFilter filter;
    auto result = filter.check("");
    check(!result.containsProfanity, "ProfanityFilter real-handles empty text safely, reporting no profanity");
    check(result.censored.empty(), "ProfanityFilter real-returns an empty censored string for empty input");
}

void testProfanityFilterSubstringOfProfaneWordNotFlagged() {
    engine::moderation::ProfanityFilter filter;
    auto result = filter.check("that was a damnation");
    check(!result.containsProfanity, "ProfanityFilter real-compares whole words, not substrings -- 'damnation' contains 'damn' but is a real, distinct word");
}

// --- MuteBlockRegistry ----------------------------------------------------------

void testMuteBlockRegistryMuteAndIsMuted() {
    engine::moderation::MuteBlockRegistry registry;
    check(!registry.isMuted(1, 2), "isMuted() is real-false before any real mute() call");
    registry.mute(1, 2);
    check(registry.isMuted(1, 2), "mute() real-registers player 1 muting player 2");
}

void testMuteBlockRegistryUnmute() {
    engine::moderation::MuteBlockRegistry registry;
    registry.mute(1, 2);
    registry.unmute(1, 2);
    check(!registry.isMuted(1, 2), "unmute() real-reverses a real mute()");
}

void testMuteBlockRegistryBlockAndIsBlocked() {
    engine::moderation::MuteBlockRegistry registry;
    check(!registry.isBlocked(1, 2), "isBlocked() is real-false before any real block() call");
    registry.block(1, 2);
    check(registry.isBlocked(1, 2), "block() real-registers player 1 blocking player 2");
}

void testMuteBlockRegistryUnblock() {
    engine::moderation::MuteBlockRegistry registry;
    registry.block(1, 2);
    registry.unblock(1, 2);
    check(!registry.isBlocked(1, 2), "unblock() real-reverses a real block()");
}

void testMuteBlockRegistryShouldDeliverTrueByDefault() {
    engine::moderation::MuteBlockRegistry registry;
    check(registry.shouldDeliver(1, 2), "shouldDeliver() is real-true by default -- neither muted nor blocked");
}

void testMuteBlockRegistryShouldDeliverFalseWhenMuted() {
    engine::moderation::MuteBlockRegistry registry;
    registry.mute(1, 2);
    check(!registry.shouldDeliver(1, 2), "shouldDeliver() real-becomes false once the recipient has muted the sender");
}

void testMuteBlockRegistryShouldDeliverFalseWhenBlocked() {
    engine::moderation::MuteBlockRegistry registry;
    registry.block(1, 2);
    check(!registry.shouldDeliver(1, 2), "shouldDeliver() real-becomes false once the recipient has blocked the sender");
}

void testMuteBlockRegistryShouldDeliverTrueForSelf() {
    engine::moderation::MuteBlockRegistry registry;
    registry.mute(1, 1); // pathological, but must not deadlock a player's own messages to themselves
    check(registry.shouldDeliver(1, 1), "shouldDeliver() is real-always true for a player's own messages to themselves, regardless of a real (pathological) self-mute");
}

void testMuteBlockRegistryMuteIsOneDirectional() {
    engine::moderation::MuteBlockRegistry registry;
    registry.mute(1, 2); // player 1 mutes player 2
    check(!registry.shouldDeliver(1, 2), "Player 1 real-stops receiving from player 2");
    check(registry.shouldDeliver(2, 1), "Player 2 real-still receives from player 1 -- mute() is a real one-directional, recipient-only choice");
}

void testMuteBlockRegistryRemovePlayerClearsAsAMuter() {
    engine::moderation::MuteBlockRegistry registry;
    registry.mute(1, 2);
    registry.removePlayer(1);
    check(!registry.isMuted(1, 2), "removePlayer() real-clears a departed player's own mute preferences");
}

void testMuteBlockRegistryRemovePlayerClearsAsATarget() {
    engine::moderation::MuteBlockRegistry registry;
    registry.mute(1, 2);
    registry.removePlayer(2);
    check(!registry.isMuted(1, 2), "removePlayer() real-clears a departed player as a target of others' real mutes");
}

void testMuteBlockRegistryMuteAndBlockAreIndependent() {
    engine::moderation::MuteBlockRegistry registry;
    registry.mute(1, 2);
    check(registry.isMuted(1, 2), "Sanity: player 1 really muted player 2");
    check(!registry.isBlocked(1, 2), "mute() real-does NOT also register as a block() -- the two are real, independent relations");
}

