    clientConfig.port = kTestPort;
    check(clientSession.initialize(clientConfig), "kick test: real client real-connects");
    engine::core::EntityId avatar = clientEcs.createEntity("KickAvatar");
    clientEcs.addComponent<engine::core::Transform>(avatar);

