// Kronos ("Active Joining UI"): real, symmetric coverage for the
// CLIENT-initiated "Leave Flow" -- a real bug found while implementing:
// shutdown() previously just destroyed the client's own transport with no
// notification at all, leaving the server to eventually notice via its
// own real disconnect-timeout detection (5-30s by default). Fixed
// alongside the server-side Disconnect broadcast.
void testNetworkSessionRealClientGracefulLeaveNotifiesServerPromptly() {
    constexpr uint16_t kTestPort = 17793;
    engine::core::ECS serverEcs, clientEcs;
    engine::net::NetworkSession serverSession, clientSession;

    engine::net::NetworkSession::Config serverConfig;
    serverConfig.mode = engine::net::NetworkMode::Server;
    serverConfig.port = kTestPort;
    check(serverSession.initialize(serverConfig), "graceful-leave test: real server real-starts");
    serverSession.setOnPlayerJoin([](engine::core::ECS& ecs, engine::net::PlayerId player) -> engine::core::EntityId {
        engine::core::EntityId entity = ecs.createEntity("GracefulLeaveTestPlayer" + std::to_string(player));
        ecs.addComponent<engine::core::Transform>(entity);
        return entity;
    });
    bool onPlayerLeaveFired = false;
    engine::net::PlayerId leftPlayerId = engine::net::kInvalidPlayer;
    std::string leftPlayerName;
    serverSession.setOnPlayerRemoving([&](engine::net::PlayerId player, const std::string& name) {
        onPlayerLeaveFired = true;
        leftPlayerId = player;
        leftPlayerName = name;
    });

    engine::net::NetworkSession::Config clientConfig;
    clientConfig.mode = engine::net::NetworkMode::Client;
    clientConfig.serverAddress = "127.0.0.1";
    clientConfig.port = kTestPort;
    check(clientSession.initialize(clientConfig), "graceful-leave test: real client real-connects");
    engine::core::EntityId avatar = clientEcs.createEntity("GracefulLeaveAvatar");
    clientEcs.addComponent<engine::core::Transform>(avatar);

    bool joined = false;
    for (int i = 0; i < 300 && !joined; ++i) {
        serverSession.tick(0.05f, serverEcs, engine::core::kNullEntity);
        clientSession.sampleLocalInput(clientEcs, avatar, glm::vec3(0.0f), false, false, 0.0f, 0.0f, 0.05f);
        clientSession.tick(0.05f, clientEcs, avatar);
        joined = clientSession.localPlayerId() != engine::net::kInvalidPlayer;
        if (!joined) std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }
    check(joined, "graceful-leave test: the real client really joins first");
    engine::net::PlayerId clientPlayerId = clientSession.localPlayerId();

    // The real "Leave Flow" action.
    clientSession.shutdown();

    for (int i = 0; i < 200 && !onPlayerLeaveFired; ++i) {
        serverSession.tick(0.05f, serverEcs, engine::core::kNullEntity);
        if (!onPlayerLeaveFired) std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }
    check(onPlayerLeaveFired, "the real server's real onPlayerRemoving_ callback really fires promptly after a "
                               "graceful client-initiated leave -- not after waiting out ENet's own multi-second "
                               "real disconnect-timeout detection");
    check(leftPlayerId == clientPlayerId, "the real onPlayerRemoving_ callback really names the real player who left");
    check(leftPlayerName == "Player", "the real callback also carries the real player's own real display name "
                                        "(defaulted to \"Player\" here since this test never called "
                                        "setLocalDisplayName())");
    check(serverSession.connectedPlayerIds().empty(),
          "the real server's own roster is really empty again immediately after the real graceful leave");

    serverSession.shutdown();
}

// Kronos ("Active Joining UI"): real coverage of the genuinely ungraceful
// case -- with the graceful client/server disconnect paths above both
// fixed, there's no way left to make a *real* NetworkSession disappear
// without sending a real notification (that's the whole point of the
// fix), so this uses a real, raw ENetTransport "server" that hand-builds
// just enough of a real JoinAccepted to get the client into a genuinely
// joined state, then really vanishes with zero notification -- the
// authentic "the host process just died" scenario. setPeerTimeout() tunes
// real ENet disconnect-timeout detection down to a real, bounded,
// test-friendly window instead of waiting out its 5-30s internet-tuned
// default.
void testNetworkSessionRealUngracefulDropSynthesizesConnectionLost() {
    constexpr uint16_t kTestPort = 17798;
    engine::core::ECS clientEcs;
    engine::net::NetworkSession clientSession;

    engine::net::ENetTransport rawServer;
    check(rawServer.hostServer(kTestPort, 4), "ungraceful-drop test: real raw server real-hosts");

    engine::net::NetworkSession::Config clientConfig;
    clientConfig.mode = engine::net::NetworkMode::Client;
    clientConfig.serverAddress = "127.0.0.1";
    clientConfig.port = kTestPort;
    check(clientSession.initialize(clientConfig), "ungraceful-drop test: real client real-connects");
    clientSession.setPeerTimeout(32, 300, 300);
    engine::core::EntityId avatar = clientEcs.createEntity("DropAvatar");
    clientEcs.addComponent<engine::core::Transform>(avatar);

    bool sentAccepted = false;
    for (int i = 0; i < 300 && !sentAccepted; ++i) {
        engine::net::ENetTransport::Callbacks serverCallbacks;
        serverCallbacks.onPacketReceived = [&](engine::net::ENetTransport::PeerId peer, const uint8_t*, size_t,
                                                 uint8_t) {
            if (sentAccepted) return;
            // A real, hand-built JoinAccepted -- just enough of the real
            // handshake for the client to consider itself genuinely
            // joined. WireMessageType::JoinAccepted = 16.
            engine::net::ByteWriter accepted;
            accepted.writeU8(16);
            accepted.writeU32(1);       // player id
            accepted.writeU32(0);       // avatarNetworkId
            accepted.writeU64(999ULL);  // sessionId
            accepted.writeString("Ungraceful Drop Test");
            accepted.writeU32(engine::net::kNetworkProtocolVersion);
            accepted.writeU8(0); // existingCount
            rawServer.send(peer, accepted.bytes().data(), accepted.size(), 0, true);
            sentAccepted = true;
        };
        rawServer.poll(0, serverCallbacks);
        clientSession.sampleLocalInput(clientEcs, avatar, glm::vec3(0.0f), false, false, 0.0f, 0.0f, 0.05f);
        clientSession.tick(0.05f, clientEcs, avatar);
        if (!sentAccepted) std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }
    check(sentAccepted, "ungraceful-drop test: the real raw server really sends a real hand-built JoinAccepted");

    bool joined = false;
    for (int i = 0; i < 300 && !joined; ++i) {
        engine::net::ENetTransport::Callbacks serverCallbacks;
        rawServer.poll(0, serverCallbacks);
        clientSession.tick(0.05f, clientEcs, avatar);
        joined = clientSession.localPlayerId() != engine::net::kInvalidPlayer;
        if (!joined) std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }
    check(joined, "ungraceful-drop test: the real client really processes the real hand-built JoinAccepted");

    bool sessionLeftFired = false;
    bool disconnectedFired = false;
    engine::net::DisconnectReason observedReason = engine::net::DisconnectReason::None;
    clientSession.setOnSessionLeft([&] { sessionLeftFired = true; });
    clientSession.setOnDisconnected([&](engine::net::DisconnectReason reason) {
        disconnectedFired = true;
        observedReason = reason;
    });

    // The real, ungraceful case: the "server" just disappears, with no
    // real Disconnect message ever sent.
    rawServer.shutdown();

    for (int i = 0; i < 400 && !disconnectedFired; ++i) {
        clientSession.tick(0.05f, clientEcs, avatar);
        if (!disconnectedFired) std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }
    check(disconnectedFired, "the real client's real onDisconnected callback really fires even with no real graceful "
                              "message ever sent -- ENet's own real disconnect-timeout detection still surfaces it");
    check(observedReason == engine::net::DisconnectReason::ConnectionLost,
          "the real, synthesized reason is really ConnectionLost, not Kicked/SessionClosed -- no real message ever "
          "said otherwise");
    check(sessionLeftFired, "the real client's real onSessionLeft callback also really fires for an ungraceful drop");
    check(clientSession.lastDisconnectReason() == engine::net::DisconnectReason::ConnectionLost,
          "lastDisconnectReason() real-reflects the same real synthesized reason");

    clientSession.shutdown();
}

// Kronos ("Active Joining UI"): real, three-peer coverage of the roster
// broadcasts -- a newly-joining client must real-learn about players who
// were ALREADY there (via JoinAccepted's own roster snapshot, a real gap
// found while implementing this), and an already-joined client must
// real-learn about players who join/leave AFTER it did (via the real
// PlayerRosterJoined/PlayerRosterLeft broadcasts).
void testNetworkSessionRealPlayerRosterBroadcastsToOtherJoinedClients() {
    constexpr uint16_t kTestPort = 17799;
    engine::core::ECS serverEcs, clientEcsA, clientEcsB;
    engine::net::NetworkSession serverSession, clientSessionA, clientSessionB;

    engine::net::NetworkSession::Config serverConfig;
    serverConfig.mode = engine::net::NetworkMode::Server;
    serverConfig.port = kTestPort;
    check(serverSession.initialize(serverConfig), "roster test: real server real-starts");
    serverSession.setOnPlayerJoin([](engine::core::ECS& ecs, engine::net::PlayerId player) -> engine::core::EntityId {
        engine::core::EntityId entity = ecs.createEntity("RosterTestPlayer" + std::to_string(player));
        ecs.addComponent<engine::core::Transform>(entity);
        return entity;
    });

    engine::net::NetworkSession::Config clientConfigA;
    clientConfigA.mode = engine::net::NetworkMode::Client;
    clientConfigA.serverAddress = "127.0.0.1";
    clientConfigA.port = kTestPort;
    clientSessionA.setLocalDisplayName("Alice");
    check(clientSessionA.initialize(clientConfigA), "roster test: real client A real-connects");
    engine::core::EntityId avatarA = clientEcsA.createEntity("AvatarA");
    clientEcsA.addComponent<engine::core::Transform>(avatarA);

    bool aJoined = false;
    for (int i = 0; i < 300 && !aJoined; ++i) {
        serverSession.tick(0.05f, serverEcs, engine::core::kNullEntity);
        clientSessionA.sampleLocalInput(clientEcsA, avatarA, glm::vec3(0.0f), false, false, 0.0f, 0.0f, 0.05f);
        clientSessionA.tick(0.05f, clientEcsA, avatarA);
        aJoined = clientSessionA.localPlayerId() != engine::net::kInvalidPlayer;
        if (!aJoined) std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }
    check(aJoined, "roster test: the real client A really joins first");

    engine::net::NetworkSession::Config clientConfigB;
    clientConfigB.mode = engine::net::NetworkMode::Client;
    clientConfigB.serverAddress = "127.0.0.1";
    clientConfigB.port = kTestPort;
    clientSessionB.setLocalDisplayName("Bob");
    check(clientSessionB.initialize(clientConfigB), "roster test: real client B real-connects");
    engine::core::EntityId avatarB = clientEcsB.createEntity("AvatarB");
    clientEcsB.addComponent<engine::core::Transform>(avatarB);

    bool bJoined = false;
    for (int i = 0; i < 300 && !bJoined; ++i) {
        serverSession.tick(0.05f, serverEcs, engine::core::kNullEntity);
        clientSessionA.tick(0.05f, clientEcsA, avatarA);
        clientSessionB.sampleLocalInput(clientEcsB, avatarB, glm::vec3(0.0f), false, false, 0.0f, 0.0f, 0.05f);
        clientSessionB.tick(0.05f, clientEcsB, avatarB);
        bJoined = clientSessionB.localPlayerId() != engine::net::kInvalidPlayer;
        if (!bJoined) std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }
    check(bJoined, "roster test: the real client B really joins second, while A is already in");

    check(clientSessionB.clientKnownPlayers().size() == 2 &&
              clientSessionB.clientKnownPlayers().count(clientSessionA.localPlayerId()) == 1 &&
              clientSessionB.clientKnownPlayers().at(clientSessionA.localPlayerId()) == "Alice",
          "the real newly-joined client B's own JoinAccepted roster snapshot really includes the real "
          "already-joined client A, by name");

    bool aLearnedAboutB = false;
    for (int i = 0; i < 300 && !aLearnedAboutB; ++i) {
        serverSession.tick(0.05f, serverEcs, engine::core::kNullEntity);
        clientSessionA.tick(0.05f, clientEcsA, avatarA);
        clientSessionB.tick(0.05f, clientEcsB, avatarB);
        aLearnedAboutB = clientSessionA.clientKnownPlayers().count(clientSessionB.localPlayerId()) == 1;
        if (!aLearnedAboutB) std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }
    check(aLearnedAboutB, "the real already-joined client A really receives a real PlayerRosterJoined broadcast "
                           "when client B joins");
    check(clientSessionA.clientKnownPlayers().at(clientSessionB.localPlayerId()) == "Bob",
          "the real broadcast carries B's real display name");

    engine::net::PlayerId bPlayerId = clientSessionB.localPlayerId();
    clientSessionB.shutdown(); // the real, graceful "Leave Flow" action

    bool aLearnedBLeft = false;
    for (int i = 0; i < 300 && !aLearnedBLeft; ++i) {
        serverSession.tick(0.05f, serverEcs, engine::core::kNullEntity);
        clientSessionA.tick(0.05f, clientEcsA, avatarA);
        aLearnedBLeft = clientSessionA.clientKnownPlayers().count(bPlayerId) == 0;
        if (!aLearnedBLeft) std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }
    check(aLearnedBLeft, "the real client A really receives a real PlayerRosterLeft broadcast when client B leaves "
                          "gracefully, and really removes B from its own clientKnownPlayers()");

    serverSession.shutdown();
    clientSessionA.shutdown();
}

// Kronos ("Active Joining UI" -- LAN discovery): pure, real serialization
// round-trip -- no sockets.
void testLanDiscoveryProtocolSerializationRoundTrips() {
    engine::net::ByteWriter writer;
    engine::net::writeLanDiscoveryHeader(writer, engine::net::LanMessageKind::Announce);
    engine::net::LanSessionAnnouncement announcement;
    announcement.protocolVersion = 42;
    announcement.sessionId = 123456789ULL;
    announcement.sessionName = "Test Session";
    announcement.hostDisplayName = "Test Host";
    announcement.gamePort = 7777;
    announcement.currentPlayerCount = 3;
    announcement.maxPlayerCount = 8;
    // Kronos ("Moderation Architecture v2", "Session Browser Game
    // Identity"): real game-identity fields round-trip too.
    announcement.gameName = "Sky Sandbox";
    announcement.gameThumbnailColor = glm::vec4(0.2f, 0.6f, 0.9f, 1.0f);
    announcement.gameSafetyStatusValue = static_cast<uint8_t>(engine::core::GameSafetyStatus::UnderReview);
    // Kronos ("Session Browser Polish v2" -- "Sorting: Newly Created"):
    // real, new field round-trips too.
    announcement.sessionStartUnixSeconds = 1700000000;
    engine::net::serializeLanAnnouncement(announcement, writer);

    engine::net::ByteReader reader(writer.bytes().data(), writer.size());
    engine::net::LanMessageKind kind = engine::net::readLanDiscoveryHeader(reader);
    check(kind == engine::net::LanMessageKind::Announce, "readLanDiscoveryHeader() real-reads back the real kind byte");

    engine::net::LanSessionAnnouncement decoded;
    check(engine::net::deserializeLanAnnouncement(reader, decoded), "the real announcement payload real-decodes");
    check(decoded.protocolVersion == 42 && decoded.sessionId == 123456789ULL && decoded.sessionName == "Test Session" &&
              decoded.hostDisplayName == "Test Host" && decoded.gamePort == 7777 && decoded.currentPlayerCount == 3 &&
              decoded.maxPlayerCount == 8,
          "every real field round-trips exactly");
    check(decoded.gameName == "Sky Sandbox", "the real gameName round-trips exactly");
    check(nearlyEqual(decoded.gameThumbnailColor.x, 0.2f) && nearlyEqual(decoded.gameThumbnailColor.w, 1.0f),
          "the real gameThumbnailColor round-trips exactly");
    check(decoded.gameSafetyStatusValue == static_cast<uint8_t>(engine::core::GameSafetyStatus::UnderReview),
          "the real gameSafetyStatusValue round-trips exactly");
    check(decoded.sessionStartUnixSeconds == 1700000000, "the real sessionStartUnixSeconds round-trips exactly");
}

// Kronos ("Session Browser Polish v2" -- "Sorting"): real, pure coverage
// over net::sortDiscoveredSessions() -- every real order, and that the
// real input vector is never mutated (sortDiscoveredSessions() takes and
// returns by value).
void testSessionBrowserSortOrdersCorrectly() {
    engine::net::DiscoveredSession zebra;
    zebra.sessionId = 1;
    zebra.sessionName = "Zebra Zone";
    zebra.currentPlayerCount = 2;
    zebra.pingMs = 50.0f;
    zebra.sessionStartUnixSeconds = 1000;

    engine::net::DiscoveredSession alpha;
    alpha.sessionId = 2;
    alpha.sessionName = "alpha camp"; // lowercase -- real case-insensitive compare must still order this first
    alpha.currentPlayerCount = 5;
    alpha.pingMs = 20.0f;
    alpha.sessionStartUnixSeconds = 3000;

    engine::net::DiscoveredSession mid;
    mid.sessionId = 3;
    mid.sessionName = "Mid Point";
    mid.currentPlayerCount = 5;
    mid.pingMs = 10.0f;
    mid.sessionStartUnixSeconds = 2000;

    std::vector<engine::net::DiscoveredSession> original = {zebra, alpha, mid};

    auto byActivity = engine::net::sortDiscoveredSessions(original, engine::net::SessionSortOrder::MostActive);
    check(byActivity.size() == 3 && byActivity[0].sessionId == 3 && byActivity[1].sessionId == 2 &&
              byActivity[2].sessionId == 1,
          "MostActive real-sorts by highest currentPlayerCount first, ties broken by real, lowest ping");

    auto byNewest = engine::net::sortDiscoveredSessions(original, engine::net::SessionSortOrder::NewlyCreated);
    check(byNewest.size() == 3 && byNewest[0].sessionId == 2 && byNewest[1].sessionId == 3 && byNewest[2].sessionId == 1,
          "NewlyCreated real-sorts by highest real sessionStartUnixSeconds first");

    auto alphabetical = engine::net::sortDiscoveredSessions(original, engine::net::SessionSortOrder::Alphabetical);
    check(alphabetical.size() == 3 && alphabetical[0].sessionId == 2 && alphabetical[1].sessionId == 3 &&
              alphabetical[2].sessionId == 1,
          "Alphabetical real-sorts case-insensitively by sessionName");

    check(original.size() == 3 && original[0].sessionId == 1 && original[1].sessionId == 2 && original[2].sessionId == 3,
          "the real, original input vector is never mutated by any real sort call");
}

// Kronos ("Session Browser Polish v2" -- "Filters: Friends' sessions"):
// real, pure coverage over net::filterDiscoveredSessionsToFriends().
void testSessionBrowserFilterToFriendsMatchesByHostDisplayName() {
    engine::net::DiscoveredSession fromFriend;
    fromFriend.sessionId = 1;
    fromFriend.hostDisplayName = "Alice";

    engine::net::DiscoveredSession fromStranger;
    fromStranger.sessionId = 2;
    fromStranger.hostDisplayName = "RandomHost";

    std::vector<engine::net::DiscoveredSession> sessions = {fromFriend, fromStranger};
    std::vector<engine::core::FriendEntry> friends = {{"creator_alice", "Alice"}};

    auto filtered = engine::net::filterDiscoveredSessionsToFriends(sessions, friends);
    check(filtered.size() == 1 && filtered[0].sessionId == 1,
          "filterDiscoveredSessionsToFriends() real-keeps only the real session whose hostDisplayName matches a real friend");

    auto filteredNoFriends = engine::net::filterDiscoveredSessionsToFriends(sessions, {});
    check(filteredNoFriends.empty(), "an empty real friends list real-yields an empty, honest filtered result");
}

void testLanDiscoveryHeaderRejectsWrongMagicOrKind() {
    engine::net::ByteWriter badMagic;
    badMagic.writeU32(0xDEADBEEF);
    badMagic.writeU8(1);
    engine::net::ByteReader badMagicReader(badMagic.bytes().data(), badMagic.size());
    check(engine::net::readLanDiscoveryHeader(badMagicReader) == engine::net::LanMessageKind::Invalid,
          "readLanDiscoveryHeader() real-rejects a real wrong magic marker");

    // Real, correct magic (0x4B524E53 -- 'KRNS', deliberately duplicated
    // here from LanDiscoveryProtocol.cpp's own anonymous-namespace
    // constant to test header validation in isolation), but a garbage
    // kind byte.
    engine::net::ByteWriter badKind;
    badKind.writeU32(0x4B524E53);
    badKind.writeU8(99);
    engine::net::ByteReader badKindReader(badKind.bytes().data(), badKind.size());
    check(engine::net::readLanDiscoveryHeader(badKindReader) == engine::net::LanMessageKind::Invalid,
          "readLanDiscoveryHeader() real-rejects a real, unrecognized kind byte even with the real correct magic");

    std::vector<uint8_t> tooShort{1, 2};
    engine::net::ByteReader tooShortReader(tooShort.data(), tooShort.size());
    check(engine::net::readLanDiscoveryHeader(tooShortReader) == engine::net::LanMessageKind::Invalid,
          "readLanDiscoveryHeader() real-rejects a real, too-short datagram rather than reading out of bounds");
}

// Kronos ("Active Joining UI" -- LAN discovery): the real, core
// end-to-end proof -- a real LanSessionAnnouncer's real broadcasts (real
// loopback UDP, matching ENetTransport's own tests' precedent of never
// touching real LAN broadcast, always 127.0.0.1) really reach a real
// LanSessionBrowser, with every real field intact, plus a real,
// measured (not fabricated) ping via the real Echo/EchoReply round trip.
void testLanSessionAnnouncerRealLoopbackReachesBrowserWithRealPing() {
    constexpr uint16_t kAnnouncePort = 45680;
    constexpr uint16_t kPingPort = 45690;
    engine::net::LanSessionAnnouncer announcer;
    check(announcer.start("127.0.0.1", kAnnouncePort, kPingPort), "loopback test: the real announcer real-starts");
    engine::net::LanSessionBrowser browser;
    check(browser.start(kAnnouncePort, kPingPort), "loopback test: the real browser real-starts");

    engine::net::LanSessionAnnouncement announcement;
    announcement.protocolVersion = engine::net::kNetworkProtocolVersion;
    announcement.sessionId = 555555ULL;
    announcement.sessionName = "Loopback Test Session";
    announcement.hostDisplayName = "Loopback Host";
    announcement.gamePort = 9999;
    announcement.currentPlayerCount = 2;
    announcement.maxPlayerCount = 6;
    announcement.gameName = "Loopback Game";
    announcement.gameThumbnailColor = glm::vec4(0.9f, 0.4f, 0.1f, 1.0f);
    announcement.gameSafetyStatusValue = static_cast<uint8_t>(engine::core::GameSafetyStatus::Unsafe);

    bool discovered = false;
    float nowSeconds = 0.0f;
    for (int i = 0; i < 300 && !discovered; ++i) {
        announcer.tick(0.05f, announcement);
        nowSeconds += 0.05f;
        browser.tick(nowSeconds);
        discovered = !browser.discoveredSessions().empty();
        if (!discovered) std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }
    check(discovered, "the real browser really discovers the real announcer's session over real loopback UDP");

    auto sessions = browser.discoveredSessions();
    check(sessions.size() == 1, "exactly one real session is real-discovered");
    check(sessions[0].sessionId == 555555ULL && sessions[0].sessionName == "Loopback Test Session" &&
              sessions[0].hostDisplayName == "Loopback Host" && sessions[0].gamePort == 9999 &&
              sessions[0].currentPlayerCount == 2 && sessions[0].maxPlayerCount == 6,
          "every real field of the real discovered session matches the real announced values");
    check(sessions[0].sourceAddress == "127.0.0.1",
          "the real discovered session's own sourceAddress is really the real loopback address it actually "
          "arrived from");
    check(sessions[0].gameName == "Loopback Game", "the real broadcast gameName really reaches the real browser");
    check(nearlyEqual(sessions[0].gameThumbnailColor.x, 0.9f) && nearlyEqual(sessions[0].gameThumbnailColor.z, 0.1f),
          "the real broadcast gameThumbnailColor really reaches the real browser");
    check(sessions[0].gameSafetyStatusValue == static_cast<uint8_t>(engine::core::GameSafetyStatus::Unsafe),
          "the real broadcast gameSafetyStatusValue really reaches the real browser");

    bool gotPing = false;
    for (int i = 0; i < 100 && !gotPing; ++i) {
        announcer.tick(0.05f, announcement);
        nowSeconds += 0.05f;
        browser.tick(nowSeconds);
        auto latest = browser.discoveredSessions();
        gotPing = !latest.empty() && latest[0].pingMs > 0.0f;
        if (!gotPing) std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }
    check(gotPing, "the real browser's own real unicast Echo/EchoReply round trip really produces a real, positive "
                    "ping measurement -- not a fabricated estimate (matches NetworkStats::averagePingMs()'s own "
                    "'0.0f is honest, not an error' convention until a real sample exists)");

    announcer.stop();
    browser.stop();
}

void testLanSessionBrowserPrunesStaleSessionAfterAnnouncerStops() {
    constexpr uint16_t kAnnouncePort = 45681;
    constexpr uint16_t kPingPort = 45691;
    engine::net::LanSessionAnnouncer announcer;
    check(announcer.start("127.0.0.1", kAnnouncePort, kPingPort), "staleness test: real announcer real-starts");
    engine::net::LanSessionBrowser browser;
    check(browser.start(kAnnouncePort, kPingPort), "staleness test: real browser real-starts");

    engine::net::LanSessionAnnouncement announcement;
    announcement.protocolVersion = engine::net::kNetworkProtocolVersion;
    announcement.sessionId = 777777ULL;
    announcement.sessionName = "Staleness Test";

    float nowSeconds = 0.0f;
    bool discovered = false;
    for (int i = 0; i < 300 && !discovered; ++i) {
        announcer.tick(0.05f, announcement);
        nowSeconds += 0.05f;
        browser.tick(nowSeconds);
        discovered = !browser.discoveredSessions().empty();
        if (!discovered) std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }
    check(discovered, "staleness test: the real session is really discovered first");

    announcer.stop(); // the real "host crashed/session closed" case -- no more real announces ever arrive

    nowSeconds += engine::net::LanSessionBrowser::kStaleTimeoutSeconds + 1.0f;
    browser.tick(nowSeconds);

    check(browser.discoveredSessions().empty(),
          "the real browser really prunes the real session once it's stopped real-refreshing for longer than "
          "kStaleTimeoutSeconds");

    browser.stop();
}

void testLanSessionBrowserDedupesRepeatedAnnouncesBySessionId() {
    constexpr uint16_t kAnnouncePort = 45682;
    constexpr uint16_t kPingPort = 45692;
    engine::net::LanSessionAnnouncer announcer;
    check(announcer.start("127.0.0.1", kAnnouncePort, kPingPort), "dedup test: real announcer real-starts");
    engine::net::LanSessionBrowser browser;
    check(browser.start(kAnnouncePort, kPingPort), "dedup test: real browser real-starts");

    engine::net::LanSessionAnnouncement announcement;
    announcement.protocolVersion = engine::net::kNetworkProtocolVersion;
    announcement.sessionId = 888888ULL;
    announcement.sessionName = "Dedup Test";

    float nowSeconds = 0.0f;
    float firstSeenAt = -1.0f;
    bool everSawMoreThanOne = false;
    for (int i = 0; i < 60; ++i) {
        announcer.tick(0.05f, announcement);
        nowSeconds += 0.05f;
        browser.tick(nowSeconds);
        auto sessions = browser.discoveredSessions();
        if (sessions.size() > 1) everSawMoreThanOne = true;
        if (!sessions.empty() && firstSeenAt < 0.0f) firstSeenAt = sessions[0].lastSeenSeconds;
        std::this_thread::sleep_for(std::chrono::milliseconds(20));
    }
    check(!everSawMoreThanOne, "dedup test: the real browser never real-lists more than one entry for the same real "
                                "sessionId, no matter how many real repeated announces arrive");
    auto finalSessions = browser.discoveredSessions();
    check(finalSessions.size() == 1, "dedup test: exactly one real entry survives after many real repeated announces");
    check(finalSessions[0].lastSeenSeconds > firstSeenAt,
          "the real entry's own lastSeenSeconds really keeps advancing with each real repeated announce, not stuck "
          "at its first real value");

    announcer.stop();
    browser.stop();
}

// Kronos ("Active Joining UI"): a real session whose own protocolVersion
// doesn't match this build's real kNetworkProtocolVersion can never
// actually be joined (NetworkSession's own real handshake would reject
// it) -- the browser real-rejects it at the discovery layer too, rather
// than listing something a real join attempt would just fail against.
// POSIX-only raw socket use below (matches this file's own stated
// real/no-mock scope for test-side socket code, see the top-of-file
// comment on why -- Windows would need winsock2's own socket()/sendto()/
// closesocket(), not attempted here for a single test).
#if !defined(_WIN32)
void testLanSessionBrowserRejectsAnnouncementWithWrongProtocolVersion() {
    constexpr uint16_t kAnnouncePort = 45683;
    constexpr uint16_t kPingPort = 45693;
    engine::net::LanSessionBrowser browser;
    check(browser.start(kAnnouncePort, kPingPort), "version-reject test: real browser real-starts");

    engine::net::ByteWriter writer;
    engine::net::writeLanDiscoveryHeader(writer, engine::net::LanMessageKind::Announce);
    engine::net::LanSessionAnnouncement announcement;
    announcement.protocolVersion = 999999; // real, deliberately wrong
    announcement.sessionId = 111ULL;
    announcement.sessionName = "Should Never Appear";
    engine::net::serializeLanAnnouncement(announcement, writer);

    int rawSocket = ::socket(AF_INET, SOCK_DGRAM, 0);
    check(rawSocket >= 0, "version-reject test: real raw UDP socket() succeeds");
    sockaddr_in destAddr{};
    destAddr.sin_family = AF_INET;
    destAddr.sin_port = htons(kAnnouncePort);
    ::inet_pton(AF_INET, "127.0.0.1", &destAddr.sin_addr);
    ::sendto(rawSocket, writer.bytes().data(), writer.size(), 0, reinterpret_cast<sockaddr*>(&destAddr),
             sizeof(destAddr));
    ::close(rawSocket);

    for (int i = 0; i < 60; ++i) {
        browser.tick(static_cast<float>(i) * 0.05f);
        std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }
    check(browser.discoveredSessions().empty(),
          "the real browser really never lists a real session whose own protocolVersion doesn't match "
          "kNetworkProtocolVersion");

    browser.stop();
}
#endif // !defined(_WIN32)

// Kronos ("request real server allocations via join tickets"): real,
// adversarial coverage over ticket enforcement in the join handshake.
//
// These run two real NetworkSessions over real loopback ENet -- a real
// server and a real client completing (or failing) a real handshake.
// The validator is injected, so no backend is needed to prove the
// enforcement logic itself; what is being tested is that the server
// really refuses a client the validator rejects, and really admits one
// it accepts.
namespace {

// Drives both sides of a real handshake until it resolves, so a test
// never depends on a fixed sleep.
void pumpSessions(engine::net::NetworkSession& server, engine::core::ECS& serverEcs,
                   engine::net::NetworkSession& client, engine::core::ECS& clientEcs, int iterations = 120) {
    for (int i = 0; i < iterations; ++i) {
        server.tick(0.016f, serverEcs, engine::core::kNullEntity);
        client.tick(0.016f, clientEcs, engine::core::kNullEntity);
        std::this_thread::sleep_for(std::chrono::milliseconds(4));
    }
}

} // namespace

void testJoinTicketServerRejectsClientWithNoTicket() {
    constexpr uint16_t kPort = 17840;
    engine::core::ECS serverEcs;
    engine::core::ECS clientEcs;
    engine::net::NetworkSession server;
    engine::net::NetworkSession client;

    engine::net::NetworkSession::Config serverConfig;
    serverConfig.mode = engine::net::NetworkMode::Server;
    serverConfig.port = kPort;
    serverConfig.advertiseOnLan = false;
    serverConfig.requireJoinTicket = true;
    int validatorCalls = 0;
    server.setJoinTicketValidator([&validatorCalls](const std::string& ticket, uint64_t& outUserId) {
        ++validatorCalls;
        // Only one exact ticket is ever accepted here.
        if (ticket != "good-ticket") return false;
        outUserId = 4242;
        return true;
    });
    server.setOnPlayerJoin([](engine::core::ECS&, engine::net::PlayerId) { return engine::core::kNullEntity; });
    check(server.initialize(serverConfig), "join-ticket test: real ticket-requiring server really starts");

    engine::net::NetworkSession::Config clientConfig;
    clientConfig.mode = engine::net::NetworkMode::Client;
    clientConfig.serverAddress = "127.0.0.1";
    clientConfig.port = kPort;
    // Deliberately no ticket -- exactly what a client that skipped the
    // real allocation step and connected straight to the address would
    // look like.
    check(client.initialize(clientConfig), "join-ticket test: real ticketless client really starts");

    pumpSessions(server, serverEcs, client, clientEcs);

    check(client.lastJoinFailureReason() == engine::net::JoinFailureReason::InvalidTicket,
          "a real client presenting NO join ticket is really rejected with InvalidTicket -- connecting straight to "
          "an allocated server's address does not get you in");

    client.shutdown();
    server.shutdown();
}

