void testExportFrameCountMatchesDurationAndFrameRate() {
    engine::cinematic::ExportSettings settings;
    settings.frameRate = engine::cinematic::SequenceFrameRate::Fps24;
    check(engine::cinematic::exportFrameCount(settings, 1.0f) == 24,
          "one real second at 24fps really produces exactly 24 real frames");

    settings.frameRate = engine::cinematic::SequenceFrameRate::Fps60;
    check(engine::cinematic::exportFrameCount(settings, 10.0f) == 600,
          "ten real seconds at 60fps really produces exactly 600 real frames");

    // Explicit range wins over sequence duration.
    settings.startSeconds = 2.0f;
    settings.endSeconds = 3.0f;
    check(engine::cinematic::exportFrameCount(settings, 100.0f) == 60,
          "a real explicit export range really overrides the real sequence duration");

    // A zero or inverted span produces nothing rather than a negative count.
    settings.startSeconds = 5.0f;
    settings.endSeconds = 5.0f;
    check(engine::cinematic::exportFrameCount(settings, 100.0f) == 0,
          "a real zero-length range really exports nothing rather than a negative count");
}

void testExportScheduleWithoutMotionBlurIsOneSamplePerFrame() {
    engine::cinematic::ExportSettings settings;
    settings.frameRate = engine::cinematic::SequenceFrameRate::Fps24;
    settings.motionBlur.enabled = false;

    std::vector<engine::cinematic::ExportFrameJob> jobs;
    engine::cinematic::buildExportSchedule(settings, 1.0f, jobs);

    check(jobs.size() == 24, "the real schedule really has one job per real output frame");
    for (size_t i = 0; i < jobs.size(); ++i) {
        check(jobs[i].sampleTimesSeconds.size() == 1,
              "without real motion blur each real frame really renders exactly once");
        const float expected = static_cast<float>(i) / 24.0f;
        check(std::fabs(jobs[i].frameStartSeconds - expected) < 1e-4f,
              "each real frame really starts at its real time on the timeline");
    }
}

void testMotionBlurSamplesAreCentredOnTheFrame() {
    engine::cinematic::ExportSettings settings;
    settings.frameRate = engine::cinematic::SequenceFrameRate::Fps24;
    settings.startSeconds = 1.0f;
    settings.endSeconds = 1.0f + 1.0f / 24.0f; // exactly one frame
    settings.motionBlur.enabled = true;
    settings.motionBlur.subFrameSamples = 8;
    settings.motionBlur.shutterAngleFraction = 0.5f;

    std::vector<engine::cinematic::ExportFrameJob> jobs;
    engine::cinematic::buildExportSchedule(settings, 10.0f, jobs);
    check(jobs.size() == 1, "the real one-frame range really produces exactly one real job");
    check(jobs[0].sampleTimesSeconds.size() == 8,
          "real motion blur really renders the real requested number of sub-frame samples");

    // The mean sample time must equal the frame time: a shutter centred
    // on the frame, not trailing behind it.
    double sum = 0.0;
    for (float t : jobs[0].sampleTimesSeconds) sum += t;
    const double mean = sum / static_cast<double>(jobs[0].sampleTimesSeconds.size());
    check(std::fabs(mean - jobs[0].frameStartSeconds) < 1e-4,
          "real motion blur samples really centre on the real frame rather than trailing behind it");

    // And they must span the shutter, not sit on top of each other.
    const float span = jobs[0].sampleTimesSeconds.back() - jobs[0].sampleTimesSeconds.front();
    const float frameDuration = 1.0f / 24.0f;
    check(span > 0.0f && span < frameDuration,
          "real samples really spread across the real shutter without exceeding the real frame");

    // Samples must be strictly increasing.
    for (size_t i = 1; i < jobs[0].sampleTimesSeconds.size(); ++i) {
        check(jobs[0].sampleTimesSeconds[i] > jobs[0].sampleTimesSeconds[i - 1],
              "real sub-frame samples really advance in time");
    }
}

void testExportValidationRefusesUnrenderableSettings() {
    engine::cinematic::ExportSettings settings;
    std::string error;
    check(engine::cinematic::validateExportSettings(settings, error), "real default export settings are really valid");

    auto expectRejected = [&](engine::cinematic::ExportSettings bad, const char* what) {
        std::string message;
        const bool valid = engine::cinematic::validateExportSettings(bad, message);
        std::string label = std::string("a real export with ") + what + " is really refused up front";
        check(!valid && !message.empty(), label.c_str());
    };

    engine::cinematic::ExportSettings noDirectory = settings;
    noDirectory.outputDirectory.clear();
    expectRejected(noDirectory, "no output directory");

    engine::cinematic::ExportSettings tooBig = settings;
    tooBig.resolution = {16000, 9000};
    expectRejected(tooBig, "a resolution beyond 8K");

    engine::cinematic::ExportSettings noChannels = settings;
    noChannels.channels.clear();
    expectRejected(noChannels, "no channels selected");

    engine::cinematic::ExportSettings badBlur = settings;
    badBlur.motionBlur.enabled = true;
    badBlur.motionBlur.subFrameSamples = 0;
    expectRejected(badBlur, "zero motion blur samples");

    engine::cinematic::ExportSettings badRange = settings;
    badRange.startSeconds = 5.0f;
    badRange.endSeconds = 2.0f;
    expectRejected(badRange, "an end time before its start");

    // 8K exactly must be ACCEPTED -- it is the documented maximum.
    engine::cinematic::ExportSettings eightK = settings;
    eightK.resolution = engine::cinematic::resolution_presets::k8K;
    std::string message;
    check(engine::cinematic::validateExportSettings(eightK, message),
          "a real 8K export is really accepted -- it is the real documented maximum");
}

void testExportFilenamesSortLexicallyInRenderOrder() {
    engine::cinematic::ExportSettings settings;
    settings.filePrefix = "shot";
    settings.colorFormat = engine::cinematic::ExportImageFormat::Png;

    const std::string first = engine::cinematic::exportFrameFilename(settings, 7, engine::cinematic::ExportChannel::Color);
    const std::string later = engine::cinematic::exportFrameFilename(settings, 1234, engine::cinematic::ExportChannel::Color);
    check(first == "shot_color_000007.png", "the real colour filename really matches the real expected pattern");
    check(first < later, "real zero padding really makes a directory listing sort in real render order");

    // Depth and motion vectors must be EXR whatever the colour setting --
    // 8-bit would quantise away the precision a compositor came for.
    const std::string depth = engine::cinematic::exportFrameFilename(settings, 7, engine::cinematic::ExportChannel::Depth);
    const std::string motion = engine::cinematic::exportFrameFilename(settings, 7, engine::cinematic::ExportChannel::MotionVectors);
    check(depth == "shot_depth_000007.exr", "the real depth channel is really forced to float EXR");
    check(motion == "shot_motion_000007.exr", "the real motion vector channel is really forced to float EXR");
}

void testExportSizeEstimateScalesWithResolutionAndChannels() {
    engine::cinematic::ExportSettings settings;
    settings.resolution = engine::cinematic::resolution_presets::k1080p;
    settings.channels = {engine::cinematic::ExportChannel::Color};
    const uint64_t hd = engine::cinematic::estimatedBytesPerFrame(settings);

    settings.resolution = engine::cinematic::resolution_presets::k8K;
    const uint64_t eightK = engine::cinematic::estimatedBytesPerFrame(settings);
    check(eightK > hd * 10,
          "a real 8K frame really estimates far larger than a real 1080p one -- worth warning about before a render");

    settings.channels = {engine::cinematic::ExportChannel::Color, engine::cinematic::ExportChannel::Depth,
                         engine::cinematic::ExportChannel::MotionVectors};
    check(engine::cinematic::estimatedBytesPerFrame(settings) > eightK,
          "adding real channels really increases the real estimate");
}

void testExportScheduleBuildingIsBoundedForALongRender() {
    // A 60-second 60fps render with 32-sample blur: 3600 frames, 115200
    // sub-frame renders. Building the schedule must stay proportional
    // rather than doing something quadratic.
    engine::cinematic::ExportSettings settings;
    settings.frameRate = engine::cinematic::SequenceFrameRate::Fps60;
    settings.motionBlur.enabled = true;
    settings.motionBlur.subFrameSamples = 32;

    std::vector<engine::cinematic::ExportFrameJob> jobs;
    engine::cinematic::buildExportSchedule(settings, 60.0f, jobs);
    check(jobs.size() == 3600, "a real long render really schedules exactly the real expected frame count");

    size_t totalSamples = 0;
    for (const auto& job : jobs) totalSamples += job.sampleTimesSeconds.size();
    check(totalSamples == 3600 * 32, "and really schedules the real expected number of sub-frame renders");
}

void testTimecodeFormattingMatchesTheFrameRate() {
    using engine::cinematic::SequenceFrameRate;
    check(engine::cinematic::formatTimecode(0.0f, SequenceFrameRate::Fps24) == "00:00:00:00",
          "a real zero time really formats as a real zero timecode");
    check(engine::cinematic::formatTimecode(1.0f, SequenceFrameRate::Fps24) == "00:00:01:00",
          "one real second really formats as one real second at 24fps");
    // 1.5s at 24fps = 36 frames = 1 second + 12 frames.
    check(engine::cinematic::formatTimecode(1.5f, SequenceFrameRate::Fps24) == "00:00:01:12",
          "a real half second really formats as the real frame remainder at 24fps");
    check(engine::cinematic::formatTimecode(1.5f, SequenceFrameRate::Fps60) == "00:00:01:30",
          "and the same real time really formats differently at a different real frame rate");
    check(engine::cinematic::formatTimecode(3661.0f, SequenceFrameRate::Fps30) == "01:01:01:00",
          "real hours and minutes really roll over correctly");
    // Negative must not produce a stray sign mid-string.
    check(engine::cinematic::formatTimecode(-5.0f, SequenceFrameRate::Fps24) == "00:00:00:00",
          "a real negative time really clamps rather than formatting a malformed timecode");
}

void testFrameSnappingLandsOnWholeFrames() {
    using engine::cinematic::SequenceFrameRate;
    const float frame24 = 1.0f / 24.0f;
    // Scrubbing must land on frames or exported footage will not match
    // what was previewed.
    check(std::fabs(engine::cinematic::snapToFrame(frame24 * 3.4f, SequenceFrameRate::Fps24) - frame24 * 3.0f) < 1e-5f,
          "a real time just past a frame really snaps back to that real frame");
    check(std::fabs(engine::cinematic::snapToFrame(frame24 * 3.6f, SequenceFrameRate::Fps24) - frame24 * 4.0f) < 1e-5f,
          "and a real time near the next frame really snaps forward");
}

void testSequenceTracksAndChannelsRoundTrip() {
    engine::cinematic::Sequence sequence;
    engine::cinematic::SequencerTrack& light =
        sequence.addTrack("KeyLight", engine::cinematic::TrackKind::LightIntensity);
    engine::cinematic::insertKeyframe(light.channel("intensity").keys,
                                      {0.0f, 0.0f, engine::cinematic::InterpolationMode::Linear, {}, {}});
    engine::cinematic::insertKeyframe(light.channel("intensity").keys,
                                      {2.0f, 100.0f, engine::cinematic::InterpolationMode::Linear, {}, {}});

    check(sequence.tracks().size() == 1, "a real track really got added");
    check(std::fabs(sequence.sampleChannel("KeyLight", "intensity", 1.0f) - 50.0f) < 0.01f,
          "the real channel really samples through the real sequence");

    // A missing track or channel must return the caller's fallback, not
    // 0 -- a missing light track should leave the light alone, not black
    // it out.
    check(std::fabs(sequence.sampleChannel("NoSuchTrack", "intensity", 1.0f, 42.0f) - 42.0f) < 0.01f,
          "a real missing track really returns the real fallback rather than zero");
    check(std::fabs(sequence.sampleChannel("KeyLight", "nosuchchannel", 1.0f, 42.0f) - 42.0f) < 0.01f,
          "a real missing channel really returns the real fallback rather than zero");

    // Muting reads as absent for the same reason.
    sequence.mutableTracks()[0].muted = true;
    check(std::fabs(sequence.sampleChannel("KeyLight", "intensity", 1.0f, 7.0f) - 7.0f) < 0.01f,
          "a real muted track really reads as absent rather than driving the value to zero");
}

void testSequenceDurationCoversKeysAndEvents() {
    engine::cinematic::Sequence sequence;
    engine::cinematic::SequencerTrack& transform =
        sequence.addTrack("Hero", engine::cinematic::TrackKind::Transform);
    engine::cinematic::insertKeyframe(transform.channel("x").keys,
                                      {3.0f, 1.0f, engine::cinematic::InterpolationMode::Linear, {}, {}});

    engine::cinematic::SequencerTrack& triggers =
        sequence.addTrack("Cues", engine::cinematic::TrackKind::ScriptTrigger);
    triggers.events.push_back({7.5f, "explode"});

    check(std::fabs(sequence.durationSeconds() - 7.5f) < 0.01f,
          "the real duration really covers real events, not just real keyframes");
}

void testTransportStepsWholeFramesAndReportsTimecode() {
    engine::cinematic::Sequence sequence;
    sequence.setFrameRate(engine::cinematic::SequenceFrameRate::Fps30);

    sequence.setPlayhead(0.0f);
    sequence.stepFrames(45);
    check(sequence.timecode() == "00:00:01:15",
          "real frame stepping really lands on the real expected timecode");

    sequence.stepFrames(-15);
    check(sequence.timecode() == "00:00:01:00", "real backward stepping really works too");

    // Stepping below zero must clamp, not go negative.
    sequence.stepFrames(-1000);
    check(sequence.playheadSeconds() >= 0.0f, "the real playhead really never goes negative");
}

void testScriptTriggersFireExactlyOnceWhenCrossed() {
    engine::cinematic::Sequence sequence;
    engine::cinematic::SequencerTrack& triggers =
        sequence.addTrack("Cues", engine::cinematic::TrackKind::ScriptTrigger);
    triggers.events.push_back({1.0f, "spawn"});
    triggers.events.push_back({2.0f, "explode"});

    sequence.setPlayhead(0.0f);
    sequence.play();

    std::vector<engine::cinematic::TrackEvent> fired;
    int spawnCount = 0;
    int explodeCount = 0;
    // Advance past both triggers in many small steps.
    for (int i = 0; i < 150; ++i) {
        sequence.advance(1.0f / 60.0f, fired);
        for (const auto& event : fired) {
            if (event.payload == "spawn") ++spawnCount;
            if (event.payload == "explode") ++explodeCount;
        }
    }
    check(spawnCount == 1, "a real script trigger really fires exactly ONCE when the playhead crosses it");
    check(explodeCount == 1, "and the real second trigger really fires exactly once too");
}

void testMutedEventTracksDoNotFire() {
    engine::cinematic::Sequence sequence;
    engine::cinematic::SequencerTrack& triggers =
        sequence.addTrack("Cues", engine::cinematic::TrackKind::ScriptTrigger);
    triggers.events.push_back({0.5f, "boom"});
    sequence.mutableTracks()[0].muted = true;

    sequence.setPlayhead(0.0f);
    sequence.play();
    std::vector<engine::cinematic::TrackEvent> fired;
    int count = 0;
    for (int i = 0; i < 60; ++i) {
        sequence.advance(1.0f / 60.0f, fired);
        count += static_cast<int>(fired.size());
    }
    check(count == 0, "a real muted event track really fires nothing");
}

void testLoopRegionWrapsAndStillFiresEventsNearTheEnd() {
    engine::cinematic::Sequence sequence;
    engine::cinematic::SequencerTrack& triggers =
        sequence.addTrack("Cues", engine::cinematic::TrackKind::ScriptTrigger);
    // Deliberately very close to the loop end -- the frame that wraps
    // must not silently skip it.
    triggers.events.push_back({0.98f, "nearEnd"});

    sequence.setLoopRegion(0.0f, 1.0f);
    check(sequence.loopEnabled(), "a real loop region really enables looping");
    sequence.setPlayhead(0.0f);
    sequence.play();

    std::vector<engine::cinematic::TrackEvent> fired;
    int nearEndCount = 0;
    // Three full loops at 60fps.
    for (int i = 0; i < 180; ++i) {
        sequence.advance(1.0f / 60.0f, fired);
        for (const auto& event : fired) {
            if (event.payload == "nearEnd") ++nearEndCount;
        }
        check(sequence.playheadSeconds() <= 1.0f + 0.001f,
              "the real playhead really stays inside the real loop region");
    }
    check(nearEndCount >= 2,
          "a real event near the real loop end really fires on EVERY pass -- the wrapping frame does not skip it");
}

void testPausedSequenceDoesNotAdvance() {
    engine::cinematic::Sequence sequence;
    sequence.setPlayhead(0.5f);
    sequence.pause();
    std::vector<engine::cinematic::TrackEvent> fired;
    const float before = sequence.playheadSeconds();
    for (int i = 0; i < 60; ++i) sequence.advance(1.0f / 60.0f, fired);
    check(std::fabs(sequence.playheadSeconds() - before) < 1e-6f,
          "a real paused sequence really does not advance");
}

void testRemoveTrackIsSafeOnABadIndex() {
    engine::cinematic::Sequence sequence;
    (void)sequence.addTrack("A", engine::cinematic::TrackKind::Transform);
    sequence.removeTrack(99); // must not be UB
    check(sequence.tracks().size() == 1, "removing a real out-of-range track index is really a safe no-op");
    sequence.removeTrack(0);
    check(sequence.tracks().empty(), "removing a real valid index really removes the real track");
}

void testSequenceAdvanceIsZeroHeapWithAReusedBuffer() {
    engine::cinematic::Sequence sequence;
    engine::cinematic::SequencerTrack& transform =
        sequence.addTrack("Hero", engine::cinematic::TrackKind::Transform);
    for (int i = 0; i < 32; ++i) {
        engine::cinematic::insertKeyframe(transform.channel("x").keys,
                                          {static_cast<float>(i) * 0.25f, static_cast<float>(i),
                                           engine::cinematic::InterpolationMode::Cubic, {}, {}});
    }
    sequence.setPlayhead(0.0f);
    sequence.play();

    // The caller owns the output buffer precisely so a per-frame advance
    // can reuse it instead of allocating every tick.
    std::vector<engine::cinematic::TrackEvent> fired;
    fired.reserve(16);
    sequence.advance(1.0f / 60.0f, fired); // warm up

    engine::core::AllocationScope scope;
    for (int i = 0; i < 240; ++i) {
        sequence.advance(1.0f / 60.0f, fired);
        volatile float value = sequence.sampleChannel("Hero", "x", sequence.playheadSeconds());
        (void)value;
    }
    check(scope.allocationsSinceStart() == 0,
          "real sequence playback really performs ZERO heap allocations across 240 real frames with a reused buffer");
}

void testCurveSamplingHitsEveryKeyframeExactly() {
    std::vector<engine::cinematic::Keyframe> keys;
    for (int i = 0; i < 5; ++i) {
        engine::cinematic::Keyframe key;
        key.timeSeconds = static_cast<float>(i);
        key.value = static_cast<float>(i * i); // deliberately non-linear
        key.mode = engine::cinematic::InterpolationMode::Cubic;
        engine::cinematic::insertKeyframe(keys, key);
    }

    for (const engine::cinematic::Keyframe& key : keys) {
        const float sampled = engine::cinematic::sampleCurve(keys, key.timeSeconds);
        std::string message = "the real curve really passes exactly through its real key at t=" +
                              std::to_string(key.timeSeconds);
        check(std::fabs(sampled - key.value) < 0.001f, message.c_str());
    }
}

void testCurveClampsRatherThanExtrapolating() {
    std::vector<engine::cinematic::Keyframe> keys;
    engine::cinematic::insertKeyframe(keys, {1.0f, 10.0f, engine::cinematic::InterpolationMode::Cubic, {}, {}});
    engine::cinematic::insertKeyframe(keys, {2.0f, 20.0f, engine::cinematic::InterpolationMode::Cubic, {}, {}});

    check(std::fabs(engine::cinematic::sampleCurve(keys, -100.0f) - 10.0f) < 0.001f,
          "sampling before the real first key really clamps rather than extrapolating wildly");
    check(std::fabs(engine::cinematic::sampleCurve(keys, 100.0f) - 20.0f) < 0.001f,
          "sampling past the real last key really clamps rather than extrapolating wildly");
}

void testSteppedAndLinearModesBehaveDistinctly() {
    std::vector<engine::cinematic::Keyframe> stepped;
    engine::cinematic::insertKeyframe(stepped, {0.0f, 0.0f, engine::cinematic::InterpolationMode::Stepped, {}, {}});
    engine::cinematic::insertKeyframe(stepped, {1.0f, 100.0f, engine::cinematic::InterpolationMode::Stepped, {}, {}});

    check(engine::cinematic::sampleCurve(stepped, 0.5f) == 0.0f,
          "a real Stepped key really holds its value until the next key -- no blending");
    check(std::fabs(engine::cinematic::sampleCurve(stepped, 1.0f) - 100.0f) < 0.001f,
          "and really jumps exactly at the next real key");

    std::vector<engine::cinematic::Keyframe> linear;
    engine::cinematic::insertKeyframe(linear, {0.0f, 0.0f, engine::cinematic::InterpolationMode::Linear, {}, {}});
    engine::cinematic::insertKeyframe(linear, {1.0f, 100.0f, engine::cinematic::InterpolationMode::Linear, {}, {}});
    check(std::fabs(engine::cinematic::sampleCurve(linear, 0.5f) - 50.0f) < 0.001f,
          "a real Linear segment really reaches its real midpoint value halfway through");
}

void testCurveIsContinuousWithNoSuddenJumps() {
    std::vector<engine::cinematic::Keyframe> keys;
    const float values[] = {0.0f, 40.0f, -20.0f, 65.0f, 10.0f};
    for (int i = 0; i < 5; ++i) {
        engine::cinematic::insertKeyframe(
            keys, {static_cast<float>(i), values[i], engine::cinematic::InterpolationMode::Cubic, {}, {}});
    }

    // A discontinuity in an animation curve is a visible snap on screen.
    float previous = engine::cinematic::sampleCurve(keys, 0.0f);
    float largestJump = 0.0f;
    for (int step = 1; step <= 4000; ++step) {
        const float time = static_cast<float>(step) * 0.001f;
        const float current = engine::cinematic::sampleCurve(keys, time);
        largestJump = std::max(largestJump, std::fabs(current - previous));
        previous = current;
    }
    check(largestJump < 1.0f,
          "the real cubic curve really has no discontinuity -- a jump here is a visible snap in the shot");
}

void testBezierHandlesShapeEasingWithoutMovingTheKeys() {
    // Two identical keys, differing only in handles: an ease-out curve
    // must sit ABOVE a linear one early on, and still hit both keys.
    engine::cinematic::Keyframe from;
    from.timeSeconds = 0.0f;
    from.value = 0.0f;
    from.mode = engine::cinematic::InterpolationMode::Bezier;
    from.outHandle = glm::vec2(0.5f, 80.0f); // shoots up fast, then eases

    engine::cinematic::Keyframe to;
    to.timeSeconds = 1.0f;
    to.value = 100.0f;
    to.mode = engine::cinematic::InterpolationMode::Bezier;
    to.inHandle = glm::vec2(-0.1f, 0.0f);

    std::vector<engine::cinematic::Keyframe> keys;
    engine::cinematic::insertKeyframe(keys, from);
    engine::cinematic::insertKeyframe(keys, to);

    check(std::fabs(engine::cinematic::sampleCurve(keys, 0.0f) - 0.0f) < 0.01f,
          "a real Bezier segment really still starts exactly on its real first key");
    check(std::fabs(engine::cinematic::sampleCurve(keys, 1.0f) - 100.0f) < 0.01f,
          "a real Bezier segment really still ends exactly on its real last key");

    const float quarter = engine::cinematic::sampleCurve(keys, 0.25f);
    check(quarter > 25.0f,
          "real out-handles really shape the real easing -- a fast-out curve leads a linear one");
    check(quarter <= 100.0f, "and really never overshoots past the real destination key");
}

void testInsertKeyframeKeepsTrackSortedAndDeduplicated() {
    std::vector<engine::cinematic::Keyframe> keys;
    for (float t : {3.0f, 1.0f, 2.0f, 0.0f}) {
        engine::cinematic::insertKeyframe(keys, {t, t * 10.0f, engine::cinematic::InterpolationMode::Linear, {}, {}});
    }
    check(keys.size() == 4, "every real distinct key really inserted");
    for (size_t i = 1; i < keys.size(); ++i) {
        check(keys[i - 1].timeSeconds < keys[i].timeSeconds,
              "the real track really stays sorted by time regardless of insertion order");
    }

    // Same time again must REPLACE, not duplicate -- two keys at one time
    // would make sampling ambiguous.
    engine::cinematic::insertKeyframe(keys, {2.0f, 999.0f, engine::cinematic::InterpolationMode::Linear, {}, {}});
    check(keys.size() == 4, "a real key at an existing time really replaces rather than duplicating");
    check(std::fabs(engine::cinematic::sampleCurve(keys, 2.0f) - 999.0f) < 0.001f,
          "and the real replacement really takes effect");
}

