        camera.focusDistanceMeters = 1.0f + static_cast<float>(i) * 0.01f;
        volatile float fov = engine::core::verticalFovDegrees(camera);
        volatile auto dof = engine::core::toRendererDofParams(camera, 1080.0f);
        (void)fov;
