void testShellStateTransitionsIgnoreInapplicableEvents() {
    using engine::runtime::ShellEvent;
    using engine::runtime::ShellState;
    // Kronos ("Active Joining UI"): a real, deliberate design choice --
    // an event that doesn't apply to the current state is a real, honest
    // no-op (the state stays unchanged), not an assertion/crash. A stray
    // double-click (e.g. two real "Join" clicks landing in the same real
    // frame) must never corrupt shell state.
    check(engine::runtime::computeNextState(ShellState::Home, ShellEvent::JoinSucceeded) == ShellState::Home,
          "an inapplicable event on Home is really ignored, state stays Home");
    check(engine::runtime::computeNextState(ShellState::InGame, ShellEvent::OpenSessionBrowser) == ShellState::InGame,
          "an inapplicable event on InGame is really ignored, state stays InGame");
    check(engine::runtime::computeNextState(ShellState::Error, ShellEvent::JoinRequested) == ShellState::Error,
          "an inapplicable event on Error is really ignored, state stays Error");
    check(engine::runtime::computeNextState(ShellState::SessionBrowser, ShellEvent::GameSelected) == ShellState::SessionBrowser,
          "an inapplicable event on SessionBrowser is really ignored, state stays SessionBrowser");
    check(engine::runtime::computeNextState(ShellState::Home, ShellEvent::GameSelected) == ShellState::Home,
          "GameSelected without first real-opening the Game Catalogue is really ignored, state stays Home");
}

void testNetworkSessionAndScriptingRealSessionAndPlayerEventsFireOnBothSides() {
    constexpr uint16_t kTestPort = 17801;
    engine::core::ECS serverEcs, clientAEcs, clientBEcs;
    engine::net::NetworkSession serverSession, clientASession, clientBSession;
    engine::core::Scripting serverScripting, clientAScripting;

    // Server-side wiring -- the exact real pattern core::Application::
    // startNetworking() uses, registered before initialize() since
    // Server-mode initialize() fires onSessionJoined_ synchronously.
    check(serverScripting.initialize(), "session/player events integration: real server Scripting real-initializes");
    std::vector<std::string> serverOutput;
    serverScripting.setOutputCallback([&](const std::string& line) { serverOutput.push_back(line); });
    serverSession.setOnSessionJoined([&] { serverScripting.fireSessionJoin(); });
    serverSession.setOnSessionLeft([&] { serverScripting.fireSessionLeave(); });
    serverSession.setOnPlayerAdded(
        [&](engine::net::PlayerId id, const std::string& name) { serverScripting.firePlayerJoin(id, name); });
    serverSession.setOnPlayerRemoving(
        [&](engine::net::PlayerId id, const std::string& name) { serverScripting.firePlayerLeave(id, name); });

    engine::core::ScriptId serverScriptId = serverScripting.loadAndRun(
        "ServerEvents", "events.onSessionJoin(function() print(\"server session joined\") end)\n"
                         "events.onPlayerJoin(function(id, name) print(\"server saw player join \" .. name) end)\n"
                         "events.onPlayerLeave(function(id, name) print(\"server saw player leave \" .. name) end)\n");
    check(serverScriptId != engine::core::kInvalidScript,
          "session/player events integration: real server script real-loads");

    engine::net::NetworkSession::Config serverConfig;
    serverConfig.mode = engine::net::NetworkMode::Server;
    serverConfig.port = kTestPort;
    check(serverSession.initialize(serverConfig), "session/player events integration: real server real-starts");
    serverSession.setOnPlayerJoin([](engine::core::ECS& ecs, engine::net::PlayerId player) -> engine::core::EntityId {
        engine::core::EntityId entity = ecs.createEntity("IntegrationPlayer" + std::to_string(player));
        ecs.addComponent<engine::core::Transform>(entity);
        return entity;
    });

    bool sawServerSessionJoined = false;
    for (const auto& line : serverOutput)
        if (line == "server session joined") sawServerSessionJoined = true;
    check(sawServerSessionJoined, "the real server-side events.onSessionJoin() handler really fires right when "
                                    "hosting starts, via the exact real setOnSessionJoined() wiring "
                                    "core::Application uses");

    // Client A wiring.
    check(clientAScripting.initialize(),
          "session/player events integration: real client A Scripting real-initializes");
    std::vector<std::string> clientAOutput;
    clientAScripting.setOutputCallback([&](const std::string& line) { clientAOutput.push_back(line); });
    clientASession.setOnSessionJoined([&] { clientAScripting.fireSessionJoin(); });
    clientASession.setOnSessionLeft([&] { clientAScripting.fireSessionLeave(); });
    clientASession.setOnPlayerAdded(
        [&](engine::net::PlayerId id, const std::string& name) { clientAScripting.firePlayerJoin(id, name); });
    clientASession.setOnPlayerRemoving(
        [&](engine::net::PlayerId id, const std::string& name) { clientAScripting.firePlayerLeave(id, name); });

    engine::core::ScriptId clientAScriptId = clientAScripting.loadAndRun(
        "ClientAEvents", "events.onSessionJoin(function() print(\"clientA session joined\") end)\n"
                          "events.onPlayerJoin(function(id, name) print(\"clientA saw player join \" .. name) end)\n"
                          "events.onPlayerLeave(function(id, name) print(\"clientA saw player leave \" .. name) end)\n");
    check(clientAScriptId != engine::core::kInvalidScript,
          "session/player events integration: real client A script real-loads");

    engine::net::NetworkSession::Config clientAConfig;
    clientAConfig.mode = engine::net::NetworkMode::Client;
    clientAConfig.serverAddress = "127.0.0.1";
    clientAConfig.port = kTestPort;
    clientASession.setLocalDisplayName("Alice");
    check(clientASession.initialize(clientAConfig), "session/player events integration: real client A real-connects");
    engine::core::EntityId avatarA = clientAEcs.createEntity("AvatarA");
    clientAEcs.addComponent<engine::core::Transform>(avatarA);

    bool aJoined = false;
    for (int i = 0; i < 300 && !aJoined; ++i) {
        serverSession.tick(0.05f, serverEcs, engine::core::kNullEntity);
        serverScripting.tick(0.05f);
        clientASession.sampleLocalInput(clientAEcs, avatarA, glm::vec3(0.0f), false, false, 0.0f, 0.0f, 0.05f);
        clientASession.tick(0.05f, clientAEcs, avatarA);
        clientAScripting.tick(0.05f);
        aJoined = clientASession.localPlayerId() != engine::net::kInvalidPlayer;
        if (!aJoined) std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }
    check(aJoined, "session/player events integration: the real client A really joins");

    bool sawClientASessionJoined = false, sawServerSawAliceJoin = false;
    for (const auto& line : clientAOutput)
        if (line == "clientA session joined") sawClientASessionJoined = true;
    for (const auto& line : serverOutput)
        if (line == "server saw player join Alice") sawServerSawAliceJoin = true;
    check(sawClientASessionJoined,
          "the real client A's own events.onSessionJoin() handler really fires once its real join completes");
    check(sawServerSawAliceJoin, "the real server-side events.onPlayerJoin() handler really fires with the real "
                                   "joining client's real display name, via the real join handshake");

    // Client B joins second -- client A should real-learn about it via
    // events.onPlayerJoin (the real client-side roster-broadcast path,
    // not the server-side join-handshake path Alice's own join used).
    engine::net::NetworkSession::Config clientBConfig;
    clientBConfig.mode = engine::net::NetworkMode::Client;
    clientBConfig.serverAddress = "127.0.0.1";
    clientBConfig.port = kTestPort;
    clientBSession.setLocalDisplayName("Bob");
    check(clientBSession.initialize(clientBConfig), "session/player events integration: real client B real-connects");
    engine::core::EntityId avatarB = clientBEcs.createEntity("AvatarB");
    clientBEcs.addComponent<engine::core::Transform>(avatarB);

    bool clientASawBobJoin = false;
    for (int i = 0; i < 300 && !clientASawBobJoin; ++i) {
        serverSession.tick(0.05f, serverEcs, engine::core::kNullEntity);
        serverScripting.tick(0.05f);
        clientASession.tick(0.05f, clientAEcs, avatarA);
        clientAScripting.tick(0.05f);
        clientBSession.sampleLocalInput(clientBEcs, avatarB, glm::vec3(0.0f), false, false, 0.0f, 0.0f, 0.05f);
        clientBSession.tick(0.05f, clientBEcs, avatarB);
        for (const auto& line : clientAOutput)
            if (line == "clientA saw player join Bob") clientASawBobJoin = true;
        if (!clientASawBobJoin) std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }
    check(clientASawBobJoin, "the real, already-joined client A's own events.onPlayerJoin() handler really fires "
                              "when client B joins after it, via the real client-side PlayerRosterJoined path");

    // Client B leaves gracefully -- both the server and client A should
    // real-learn via events.onPlayerLeave.
    clientBSession.shutdown();

    bool serverSawBobLeave = false, clientASawBobLeave = false;
    for (int i = 0; i < 300 && !(serverSawBobLeave && clientASawBobLeave); ++i) {
        serverSession.tick(0.05f, serverEcs, engine::core::kNullEntity);
        serverScripting.tick(0.05f);
        clientASession.tick(0.05f, clientAEcs, avatarA);
        clientAScripting.tick(0.05f);
        for (const auto& line : serverOutput)
            if (line == "server saw player leave Bob") serverSawBobLeave = true;
        for (const auto& line : clientAOutput)
            if (line == "clientA saw player leave Bob") clientASawBobLeave = true;
        if (!(serverSawBobLeave && clientASawBobLeave)) std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }
    check(serverSawBobLeave,
          "the real server-side events.onPlayerLeave() handler really fires when a real client gracefully leaves");
    check(clientASawBobLeave, "the real client A's own events.onPlayerLeave() handler really fires too, via the "
                                "real client-side PlayerRosterLeft path");

    serverSession.shutdown();
    clientASession.shutdown();
    serverScripting.shutdown();
    clientAScripting.shutdown();
}

// Kronos (Alpha Roadmap Phase 4, "Networking Upgrade") -- the real,
// end-to-end proof that the Luau binding itself works, not just the C++
// API it sits on: a real Luau script on the client calls
// network.fireServer(), received by a real Luau script's
// network.onServerEvent() handler on the server, which mutates a real
// server-side ECS entity -- exercising the full real stack (Luau ->
// ScriptNetworkApi -> NetworkSession -> real ENet wire -> NetworkSession
// -> ScriptNetworkApi -> Luau -> world.setPosition), matching
// ScriptedPlugin's own real (not mocked) Luau-against-real-ECS test
// discipline.
void testScriptNetworkApiRealFireServerReachesLuauHandler() {
    constexpr uint16_t kTestPort = 17785;
    engine::core::ECS serverEcs, clientEcs;
    engine::net::NetworkSession serverSession, clientSession;

    engine::net::NetworkSession::Config serverConfig;
    serverConfig.mode = engine::net::NetworkMode::Server;
    serverConfig.port = kTestPort;
    check(serverSession.initialize(serverConfig), "ScriptNetworkApi test: real server real-starts");
    serverSession.setOnPlayerJoin([](engine::core::ECS& ecs, engine::net::PlayerId player) -> engine::core::EntityId {
        engine::core::EntityId entity = ecs.createEntity("ScriptRpcPlayer" + std::to_string(player));
        ecs.addComponent<engine::core::Transform>(entity);
        return entity;
    });

    engine::core::EntityId target = serverEcs.createEntity("Target");
    serverEcs.addComponent<engine::core::Transform>(target);

    engine::core::Scripting serverScripting;
    check(serverScripting.initialize(), "ScriptNetworkApi test: real server Scripting real-initializes");
    engine::core::ScriptNetworkApi serverNetworkApi(serverSession, serverScripting);
    serverScripting.setBindingsHook([&](lua_State* L) {
        engine::studio::registerStudioEcsBindings(L, serverEcs);
        serverNetworkApi.registerInto(L);
    });

    // The real server-side handler script: registers a real
    // network.onServerEvent handler that moves the real "Target" entity
    // to the position named in the fired payload.
    engine::core::ScriptId serverScriptId = serverScripting.loadAndRun(
        "ServerHandler", "network.onServerEvent(\"MoveTarget\", function(player, payload)\n"
                          "  local id = world.findByName(\"Target\")\n"
                          "  if id then world.setPosition(id, payload.x, payload.y, payload.z) end\n"
                          "end)\n");
    check(serverScriptId != engine::core::kInvalidScript, "ScriptNetworkApi test: the real server handler script real-loads");

    engine::net::NetworkSession::Config clientConfig;
    clientConfig.mode = engine::net::NetworkMode::Client;
    clientConfig.serverAddress = "127.0.0.1";
    clientConfig.port = kTestPort;
    check(clientSession.initialize(clientConfig), "ScriptNetworkApi test: real client real-connects");

    engine::core::EntityId clientAvatar = clientEcs.createEntity("LocalScriptRpc");
    clientEcs.addComponent<engine::core::Transform>(clientAvatar);

    bool handshook = false;
    for (int i = 0; i < 300 && !handshook; ++i) {
        serverSession.tick(0.05f, serverEcs, engine::core::kNullEntity);
        clientSession.sampleLocalInput(clientEcs, clientAvatar, glm::vec3(0.0f), false, false, 0.0f, 0.0f, 0.05f);
        clientSession.tick(0.05f, clientEcs, clientAvatar);
        handshook = clientSession.localPlayerId() != engine::net::kInvalidPlayer;
        if (!handshook) std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }
    check(handshook, "ScriptNetworkApi test: the real client really completes its real handshake");

    engine::core::Scripting clientScripting;
    check(clientScripting.initialize(), "ScriptNetworkApi test: real client Scripting real-initializes");
    engine::core::ScriptNetworkApi clientNetworkApi(clientSession, clientScripting);
    clientScripting.setBindingsHook([&](lua_State* L) {
        engine::studio::registerStudioEcsBindings(L, clientEcs);
        clientNetworkApi.registerInto(L);
    });

    engine::core::ScriptId clientScriptId =
        clientScripting.loadAndRun("ClientFire", "network.fireServer(\"MoveTarget\", {x = 11, y = 22, z = 33})\n");
    check(clientScriptId != engine::core::kInvalidScript,
          "ScriptNetworkApi test: the real client fire-script real-loads and real-runs");

    auto* transform = serverEcs.tryGetComponent<engine::core::Transform>(target);
    bool moved = false;
    for (int i = 0; i < 200 && !moved; ++i) {
        serverSession.tick(0.05f, serverEcs, engine::core::kNullEntity);
        clientSession.tick(0.05f, clientEcs, clientAvatar);
        moved = transform != nullptr && nearlyEqual(transform->position.x, 11.0f);
        if (!moved) std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }
    check(moved, "a real Luau script's network.fireServer() call, received by another real Luau script's real "
                 "network.onServerEvent() handler, really mutates the real server-side ECS entity -- the full real "
                 "stack works end-to-end");
    check(nearlyEqual(transform->position.y, 22.0f) && nearlyEqual(transform->position.z, 33.0f),
          "all three real payload fields (x, y, z) survive the full real round-trip, not just the first checked");

    // Kronos (Alpha Completion Checklist, "Engine Validation Pass" --
    // "Validate all Lua bindings"): the reverse direction --
    // network.fireAllClients()/network.onClientEvent() -- had zero real
    // Luau-level test coverage (only the underlying C++
    // NetworkSession::fireAllClientsEvent() API was tested, in
    // testNetworkSessionRealRemoteEventFireServerReachesRegisteredHandler
    // -- not the actual Luau binding a creator script would really call).
    engine::core::EntityId announceReceiver = clientEcs.createEntity("AnnounceReceiver");
    clientEcs.addComponent<engine::core::Transform>(announceReceiver);
    engine::core::ScriptId clientListenerId = clientScripting.loadAndRun(
        "ClientListener", "network.onClientEvent(\"Announcement\", function(payload)\n"
                           "  local id = world.findByName(\"AnnounceReceiver\")\n"
                           "  if id then world.setPosition(id, payload.value, 0, 0) end\n"
                           "end)\n");
    check(clientListenerId != engine::core::kInvalidScript,
          "network.onClientEvent() real-registers a real handler with no error");

    engine::core::ScriptId serverBroadcastId =
        serverScripting.loadAndRun("ServerBroadcast", "network.fireAllClients(\"Announcement\", {value = 77})\n");
    check(serverBroadcastId != engine::core::kInvalidScript, "network.fireAllClients() real-runs with no error");

    auto* announceTransform = clientEcs.tryGetComponent<engine::core::Transform>(announceReceiver);
    bool announced = false;
    for (int i = 0; i < 200 && !announced; ++i) {
        serverSession.tick(0.05f, serverEcs, engine::core::kNullEntity);
        clientSession.tick(0.05f, clientEcs, clientAvatar);
        announced = announceTransform != nullptr && nearlyEqual(announceTransform->position.x, 77.0f);
        if (!announced) std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }
    check(announced, "a real Luau script's network.fireAllClients() call, received by another real Luau script's real "
                      "network.onClientEvent() handler, really mutates the real client-side ECS entity -- the full "
                      "real broadcast stack works end-to-end too, not just the fire-to-server direction");

    serverScripting.shutdown();
    clientScripting.shutdown();
    serverSession.shutdown();
    clientSession.shutdown();
}

void testNetworkSessionRealChatRespectsWorldSafetyChatDisabled() {
    constexpr uint16_t kTestPort = 17771;
    engine::core::ECS serverEcs, clientEcs;
    engine::net::NetworkSession serverSession, clientSession;

    engine::net::NetworkSession::Config serverConfig;
    serverConfig.mode = engine::net::NetworkMode::Server;
    serverConfig.port = kTestPort;
    check(serverSession.initialize(serverConfig), "Chat-disabled test: real server real-starts");
    serverSession.setOnPlayerJoin([](engine::core::ECS& ecs, engine::net::PlayerId) -> engine::core::EntityId {
        engine::core::EntityId entity = ecs.createEntity("Player");
        ecs.addComponent<engine::core::Transform>(entity);
        return entity;
    });
    serverSession.worldSafetySettings().chatEnabled = false;

    engine::net::NetworkSession::Config clientConfig;
    clientConfig.mode = engine::net::NetworkMode::Client;
    clientConfig.serverAddress = "127.0.0.1";
    clientConfig.port = kTestPort;
    check(clientSession.initialize(clientConfig), "Chat-disabled test: real client real-connects");

    engine::core::EntityId clientAvatar = clientEcs.createEntity("Local");
    clientEcs.addComponent<engine::core::Transform>(clientAvatar);

    bool handshakeComplete = false;
    for (int i = 0; i < 200 && !handshakeComplete; ++i) {
        serverSession.tick(0.05f, serverEcs, engine::core::kNullEntity);
        clientSession.sampleLocalInput(clientEcs, clientAvatar, glm::vec3(0.0f), false, false, 0.0f, 0.0f, 0.05f);
        clientSession.tick(0.05f, clientEcs, clientAvatar);
        handshakeComplete = clientSession.localPlayerId() != engine::net::kInvalidPlayer;
        if (!handshakeComplete) std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }
    check(handshakeComplete, "Chat-disabled test: real handshake really completes");

    clientSession.sendChatMessage("can anyone hear me");
    for (int i = 0; i < 60; ++i) {
        serverSession.tick(0.05f, serverEcs, engine::core::kNullEntity);
        clientSession.tick(0.05f, clientEcs, clientAvatar);
        std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }
    check(serverSession.chatLog().size() == 0, "A real chat message sent while worldSafetySettings().chatEnabled is false is real-dropped server-side, never logged");

    serverSession.shutdown();
    clientSession.shutdown();
}

void testNetworkSessionRealChatRateLimitDropsExcessMessages() {
    constexpr uint16_t kTestPort = 17772;
    engine::core::ECS serverEcs, clientEcs;
    engine::net::NetworkSession serverSession, clientSession;

    engine::net::NetworkSession::Config serverConfig;
    serverConfig.mode = engine::net::NetworkMode::Server;
    serverConfig.port = kTestPort;
    check(serverSession.initialize(serverConfig), "Rate-limit test: real server real-starts");
    serverSession.setOnPlayerJoin([](engine::core::ECS& ecs, engine::net::PlayerId) -> engine::core::EntityId {
        engine::core::EntityId entity = ecs.createEntity("Player");
        ecs.addComponent<engine::core::Transform>(entity);
        return entity;
    });
    serverSession.worldSafetySettings().maxChatMessagesPerSecond = 2.0f; // real, low real cap for this test

    engine::net::NetworkSession::Config clientConfig;
    clientConfig.mode = engine::net::NetworkMode::Client;
    clientConfig.serverAddress = "127.0.0.1";
    clientConfig.port = kTestPort;
    check(clientSession.initialize(clientConfig), "Rate-limit test: real client real-connects");

    engine::core::EntityId clientAvatar = clientEcs.createEntity("Local");
    clientEcs.addComponent<engine::core::Transform>(clientAvatar);

    bool handshakeComplete = false;
    for (int i = 0; i < 200 && !handshakeComplete; ++i) {
        serverSession.tick(0.05f, serverEcs, engine::core::kNullEntity);
        clientSession.sampleLocalInput(clientEcs, clientAvatar, glm::vec3(0.0f), false, false, 0.0f, 0.0f, 0.05f);
        clientSession.tick(0.05f, clientEcs, clientAvatar);
        handshakeComplete = clientSession.localPlayerId() != engine::net::kInvalidPlayer;
        if (!handshakeComplete) std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }
    check(handshakeComplete, "Rate-limit test: real handshake really completes");

    for (int i = 0; i < 10; ++i) clientSession.sendChatMessage("spam " + std::to_string(i));
    for (int i = 0; i < 40; ++i) {
        serverSession.tick(0.02f, serverEcs, engine::core::kNullEntity);
        clientSession.tick(0.02f, clientEcs, clientAvatar);
        std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }
    check(serverSession.chatLog().size() < 10, "Real rate limiting really drops most of 10 near-simultaneous real messages against a real 2/sec cap -- not all 10 are logged");
    check(serverSession.chatLog().size() >= 1, "Real rate limiting still real-allows at least the real initial burst through, not zero");

    serverSession.shutdown();
    clientSession.shutdown();
}

void testNetworkSessionRealChatProfanityFilterCensorsBroadcast() {
    constexpr uint16_t kTestPort = 17773;
    engine::core::ECS serverEcs, clientAEcs, clientBEcs;
    engine::net::NetworkSession serverSession, clientASession, clientBSession;

    engine::net::NetworkSession::Config serverConfig;
    serverConfig.mode = engine::net::NetworkMode::Server;
    serverConfig.port = kTestPort;
    serverConfig.maxClients = 4;
    check(serverSession.initialize(serverConfig), "Profanity broadcast test: real server real-starts");
    serverSession.setOnPlayerJoin([](engine::core::ECS& ecs, engine::net::PlayerId player) -> engine::core::EntityId {
        engine::core::EntityId entity = ecs.createEntity("Player" + std::to_string(player));
        ecs.addComponent<engine::core::Transform>(entity);
        return entity;
    });

    engine::net::NetworkSession::Config clientConfig;
    clientConfig.mode = engine::net::NetworkMode::Client;
    clientConfig.serverAddress = "127.0.0.1";
    clientConfig.port = kTestPort;
    check(clientASession.initialize(clientConfig), "Profanity broadcast test: real client A real-connects");
    check(clientBSession.initialize(clientConfig), "Profanity broadcast test: real client B real-connects");

    engine::core::EntityId clientAAvatar = clientAEcs.createEntity("LocalA");
    clientAEcs.addComponent<engine::core::Transform>(clientAAvatar);
    engine::core::EntityId clientBAvatar = clientBEcs.createEntity("LocalB");
    clientBEcs.addComponent<engine::core::Transform>(clientBAvatar);

    std::string receivedText;
    clientBSession.setOnChatMessageReceived([&](engine::net::PlayerId, const std::string& text) { receivedText = text; });

    bool bothHandshook = false;
    for (int i = 0; i < 300 && !bothHandshook; ++i) {
        serverSession.tick(0.05f, serverEcs, engine::core::kNullEntity);
        clientASession.sampleLocalInput(clientAEcs, clientAAvatar, glm::vec3(0.0f), false, false, 0.0f, 0.0f, 0.05f);
        clientASession.tick(0.05f, clientAEcs, clientAAvatar);
        clientBSession.sampleLocalInput(clientBEcs, clientBAvatar, glm::vec3(0.0f), false, false, 0.0f, 0.0f, 0.05f);
        clientBSession.tick(0.05f, clientBEcs, clientBAvatar);
        bothHandshook = clientASession.localPlayerId() != engine::net::kInvalidPlayer &&
                         clientBSession.localPlayerId() != engine::net::kInvalidPlayer;
        if (!bothHandshook) std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }
    check(bothHandshook, "Profanity broadcast test: both real clients really complete real handshakes");

    clientASession.sendChatMessage("this is shit");
    for (int i = 0; i < 200 && receivedText.empty(); ++i) {
        serverSession.tick(0.05f, serverEcs, engine::core::kNullEntity);
        clientASession.tick(0.05f, clientAEcs, clientAAvatar);
        clientBSession.tick(0.05f, clientBEcs, clientBAvatar);
        if (receivedText.empty()) std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }
    check(receivedText == "this is ****", "Client B really receives the real, server-censored version of a profane message, not the raw text");
    check(serverSession.chatLog().entries().front().text == "this is shit",
          "The real server-side chat log keeps the real, ORIGINAL uncensored text for moderation review -- a censored-only log would be useless as evidence");
    check(serverSession.chatLog().entries().front().containedProfanity, "The real server-side log entry correctly records that this real message contained profanity");

    serverSession.shutdown();
    clientASession.shutdown();
    clientBSession.shutdown();
}

// Kronos ("Moderation Architecture v1", Phase 1): real, end-to-end proof
// that safety::PolicyEngine's hard-block categories genuinely stop
// delivery over a real loopback ENet connection -- not just a flag that
// nothing reads. Mirrors testNetworkSessionRealChatProfanityFilterCensorsBroadcast()'s
// exact real 2-client handshake pattern.
void testNetworkSessionRealHardBlockCategoryNeverDeliveredToRecipient() {
    constexpr uint16_t kTestPort = 17797;
    engine::core::ECS serverEcs, clientAEcs, clientBEcs;
    engine::net::NetworkSession serverSession, clientASession, clientBSession;

    engine::net::NetworkSession::Config serverConfig;
    serverConfig.mode = engine::net::NetworkMode::Server;
    serverConfig.port = kTestPort;
    serverConfig.maxClients = 4;
    check(serverSession.initialize(serverConfig), "Hard-block test: real server real-starts");
    serverSession.setOnPlayerJoin([](engine::core::ECS& ecs, engine::net::PlayerId player) -> engine::core::EntityId {
        engine::core::EntityId entity = ecs.createEntity("Player" + std::to_string(player));
        ecs.addComponent<engine::core::Transform>(entity);
        return entity;
    });

    engine::net::NetworkSession::Config clientConfig;
    clientConfig.mode = engine::net::NetworkMode::Client;
    clientConfig.serverAddress = "127.0.0.1";
    clientConfig.port = kTestPort;
    check(clientASession.initialize(clientConfig), "Hard-block test: real client A real-connects");
    check(clientBSession.initialize(clientConfig), "Hard-block test: real client B real-connects");

    engine::core::EntityId clientAAvatar = clientAEcs.createEntity("LocalA");
    clientAEcs.addComponent<engine::core::Transform>(clientAAvatar);
    engine::core::EntityId clientBAvatar = clientBEcs.createEntity("LocalB");
    clientBEcs.addComponent<engine::core::Transform>(clientBAvatar);

    bool clientBReceivedAnything = false;
    clientBSession.setOnChatMessageReceived(
        [&](engine::net::PlayerId, const std::string&) { clientBReceivedAnything = true; });

    bool bothHandshook = false;
    for (int i = 0; i < 300 && !bothHandshook; ++i) {
        serverSession.tick(0.05f, serverEcs, engine::core::kNullEntity);
        clientASession.sampleLocalInput(clientAEcs, clientAAvatar, glm::vec3(0.0f), false, false, 0.0f, 0.0f, 0.05f);
        clientASession.tick(0.05f, clientAEcs, clientAAvatar);
        clientBSession.sampleLocalInput(clientBEcs, clientBAvatar, glm::vec3(0.0f), false, false, 0.0f, 0.0f, 0.05f);
        clientBSession.tick(0.05f, clientBEcs, clientBAvatar);
        bothHandshook = clientASession.localPlayerId() != engine::net::kInvalidPlayer &&
                         clientBSession.localPlayerId() != engine::net::kInvalidPlayer;
        if (!bothHandshook) std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }
    check(bothHandshook, "Hard-block test: both real clients really complete real handshakes");

    // A real Hate-category hard-block marker (TextClassifierStub's own
    // heuristic) -- safety::PolicyEngine::decide() must return Block for
    // this, and NetworkSession's real chat broadcast path must honor it.
    clientASession.sendChatMessage("go back to your country");
    for (int i = 0; i < 100; ++i) {
        serverSession.tick(0.05f, serverEcs, engine::core::kNullEntity);
        clientASession.tick(0.05f, clientAEcs, clientAAvatar);
        clientBSession.tick(0.05f, clientBEcs, clientBAvatar);
        std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }

    check(!clientBReceivedAnything,
          "A real hard-block-category message (Hate) is genuinely never delivered to the recipient over a real "
          "loopback connection -- not merely flagged-after-delivery");
    check(serverSession.chatLog().size() == 1 && serverSession.chatLog().entries().front().text == "go back to your country",
          "The real blocked message is still recorded to the real server-side chat log -- real evidence for a "
          "moderator, not silently discarded just because it wasn't delivered");
    check(serverSession.chatLog().entries().front().flaggedByClassifier,
          "The real logged entry correctly records that the real classifier flagged this message");

    serverSession.shutdown();
    clientASession.shutdown();
    clientBSession.shutdown();
}

// Kronos ("Moderation Architecture v2", "Account System v1"): real,
// end-to-end proof that a persistent, profileId-keyed ban genuinely
// rejects a real join attempt over a real loopback ENet connection.
void testNetworkSessionRealPersistentBanRejectsJoin() {
    constexpr uint16_t kTestPort = 17798;
    constexpr uint64_t kBannedProfileId = 424242;
    engine::core::ECS serverEcs, clientEcs;
    engine::net::NetworkSession serverSession, clientSession;

    engine::net::NetworkSession::Config serverConfig;
    serverConfig.mode = engine::net::NetworkMode::Server;
    serverConfig.port = kTestPort;
    check(serverSession.initialize(serverConfig), "Persistent ban test: real server real-starts");
    serverSession.accountModerationRegistry().ban(kBannedProfileId, "real, pre-existing ban for this test");
    serverSession.setOnPlayerJoin([](engine::core::ECS& ecs, engine::net::PlayerId) -> engine::core::EntityId {
        return ecs.createEntity("ShouldNeverJoin");
    });

    engine::net::NetworkSession::Config clientConfig;
    clientConfig.mode = engine::net::NetworkMode::Client;
    clientConfig.serverAddress = "127.0.0.1";
    clientConfig.port = kTestPort;
    clientSession.setLocalIdentity(kBannedProfileId, engine::core::AgeGroup::Adult);
    check(clientSession.initialize(clientConfig), "Persistent ban test: real client real-attempts real connect");

    bool sawBanRejection = false;
    for (int i = 0; i < 200 && !sawBanRejection; ++i) {
        serverSession.tick(0.05f, serverEcs, engine::core::kNullEntity);
        clientSession.tick(0.05f, clientEcs, engine::core::kNullEntity);
        sawBanRejection = clientSession.lastJoinFailureReason() == engine::net::JoinFailureReason::Banned;
        if (!sawBanRejection) std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }
    check(sawBanRejection, "a real, persistently-banned profileId real-receives a real JoinFailureReason::Banned "
                            "rejection, not a real, silent generic failure");
    check(clientSession.localPlayerId() == engine::net::kInvalidPlayer,
          "the real banned client real-never actually joins");

    serverSession.shutdown();
    clientSession.shutdown();
}

// Kronos ("Moderation Architecture v2", "DM System v1"): real, end-to-
// end proof over a real loopback ENet connection -- two real, self-
// declared Adults can DM each other (real, targeted delivery, not a
// broadcast: a real third client never sees it), and Minor Mode's real
// "DM restrictions" genuinely block a DM touching a real (or possibly)
// minor.
void testNetworkSessionRealDirectMessageDeliveryAndMinorModeRestriction() {
    constexpr uint16_t kTestPort = 17799;
    engine::core::ECS serverEcs, clientAEcs, clientBEcs, clientCEcs;
    engine::net::NetworkSession serverSession, clientASession, clientBSession, clientCSession;

    engine::net::NetworkSession::Config serverConfig;
    serverConfig.mode = engine::net::NetworkMode::Server;
    serverConfig.port = kTestPort;
    serverConfig.maxClients = 6;
    check(serverSession.initialize(serverConfig), "DM test: real server real-starts");
    serverSession.setOnPlayerJoin([](engine::core::ECS& ecs, engine::net::PlayerId player) -> engine::core::EntityId {
        engine::core::EntityId entity = ecs.createEntity("Player" + std::to_string(player));
        ecs.addComponent<engine::core::Transform>(entity);
        return entity;
    });

    engine::net::NetworkSession::Config clientConfig;
    clientConfig.mode = engine::net::NetworkMode::Client;
    clientConfig.serverAddress = "127.0.0.1";
    clientConfig.port = kTestPort;
    // A (Adult) DMs B (Adult) -- must be delivered. C (Minor) is a real,
    // uninvolved bystander proving DM delivery is genuinely targeted,
    // not a broadcast.
    clientASession.setLocalIdentity(101, engine::core::AgeGroup::Adult);
    clientBSession.setLocalIdentity(102, engine::core::AgeGroup::Adult);
    clientCSession.setLocalIdentity(103, engine::core::AgeGroup::Minor);
    check(clientASession.initialize(clientConfig), "DM test: real client A real-connects");
    check(clientBSession.initialize(clientConfig), "DM test: real client B real-connects");
    check(clientCSession.initialize(clientConfig), "DM test: real client C real-connects");

    engine::core::EntityId a = clientAEcs.createEntity("A");
    clientAEcs.addComponent<engine::core::Transform>(a);
    engine::core::EntityId b = clientBEcs.createEntity("B");
    clientBEcs.addComponent<engine::core::Transform>(b);
    engine::core::EntityId c = clientCEcs.createEntity("C");
    clientCEcs.addComponent<engine::core::Transform>(c);

    std::string bReceivedText;
    bool cReceivedAnything = false;
    clientBSession.setOnDirectMessageReceived([&](engine::net::PlayerId, const std::string& text) { bReceivedText = text; });
    clientCSession.setOnDirectMessageReceived([&](engine::net::PlayerId, const std::string&) { cReceivedAnything = true; });

    bool allHandshook = false;
    for (int i = 0; i < 300 && !allHandshook; ++i) {
        serverSession.tick(0.05f, serverEcs, engine::core::kNullEntity);
        clientASession.sampleLocalInput(clientAEcs, a, glm::vec3(0.0f), false, false, 0.0f, 0.0f, 0.05f);
        clientASession.tick(0.05f, clientAEcs, a);
        clientBSession.sampleLocalInput(clientBEcs, b, glm::vec3(0.0f), false, false, 0.0f, 0.0f, 0.05f);
        clientBSession.tick(0.05f, clientBEcs, b);
        clientCSession.sampleLocalInput(clientCEcs, c, glm::vec3(0.0f), false, false, 0.0f, 0.0f, 0.05f);
        clientCSession.tick(0.05f, clientCEcs, c);
        allHandshook = clientASession.localPlayerId() != engine::net::kInvalidPlayer &&
                        clientBSession.localPlayerId() != engine::net::kInvalidPlayer &&
                        clientCSession.localPlayerId() != engine::net::kInvalidPlayer;
        if (!allHandshook) std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }
    check(allHandshook, "DM test: all three real clients really complete real handshakes");

    clientASession.sendDirectMessage(clientBSession.localPlayerId(), "a real, adult-to-adult DM");
    for (int i = 0; i < 150 && bReceivedText.empty(); ++i) {
        serverSession.tick(0.05f, serverEcs, engine::core::kNullEntity);
        clientASession.tick(0.05f, clientAEcs, a);
        clientBSession.tick(0.05f, clientBEcs, b);
        clientCSession.tick(0.05f, clientCEcs, c);
        if (bReceivedText.empty()) std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }
    check(bReceivedText == "a real, adult-to-adult DM",
          "a real DM between two real, self-declared Adults is genuinely delivered to the real intended recipient");
    check(!cReceivedAnything, "a real, uninvolved third client genuinely never receives a DM meant for someone else "
                               "-- real, targeted delivery, not a broadcast");

    // Now A (Adult) DMs C (Minor) -- Minor Mode's real "DM restrictions"
    // must block this entirely.
    bool bStillOnlyHasFirstMessage = true;
    cReceivedAnything = false;
    clientASession.sendDirectMessage(clientCSession.localPlayerId(), "should never arrive");
    for (int i = 0; i < 100; ++i) {
        serverSession.tick(0.05f, serverEcs, engine::core::kNullEntity);
        clientASession.tick(0.05f, clientAEcs, a);
        clientCSession.tick(0.05f, clientCEcs, c);
        std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }
    check(!cReceivedAnything, "Minor Mode's real DM restriction genuinely blocks a DM touching a real (or possibly) "
                               "minor recipient -- never delivered");
    check(bStillOnlyHasFirstMessage, "sanity: the unrelated real delivery to B from earlier is untouched by this second attempt");
    check(serverSession.directMessageLog().size() == 2,
          "both real DM attempts (delivered and Minor-Mode-blocked) are real-recorded to the real server-side DM "
          "log for moderator review");
    check(serverSession.directMessageLog().entries()[1].blocked,
          "the real second, Minor-Mode-blocked DM is real-recorded with blocked=true");

    serverSession.shutdown();
    clientASession.shutdown();
    clientBSession.shutdown();
    clientCSession.shutdown();
}

// Kronos ("Moderation Architecture v2", item B "Behavioral Model
// (Heuristic v1)"): real, end-to-end proof a real burst of real DMs
// through the real NetworkSession send path genuinely escalates the real
// sender's real server-side risk tier -- not a hand-built sample vector
// the way the pure BehavioralPatternAnalyzer/TrustSafetyService tests
// above are, the actual wire-protocol path.
void testNetworkSessionRealRapidDmBurstEscalatesSenderRiskTier() {
    constexpr uint16_t kTestPort = 17814;
    engine::core::ECS serverEcs, clientAEcs, clientBEcs;
    engine::net::NetworkSession serverSession, clientASession, clientBSession;

    engine::net::NetworkSession::Config serverConfig;
    serverConfig.mode = engine::net::NetworkMode::Server;
    serverConfig.port = kTestPort;
    serverConfig.maxClients = 4;
    check(serverSession.initialize(serverConfig), "rapid-DM test: real server real-starts");
    serverSession.setOnPlayerJoin([](engine::core::ECS& ecs, engine::net::PlayerId player) -> engine::core::EntityId {
        engine::core::EntityId entity = ecs.createEntity("Player" + std::to_string(player));
        ecs.addComponent<engine::core::Transform>(entity);
        return entity;
    });

    engine::net::NetworkSession::Config clientConfig;
    clientConfig.mode = engine::net::NetworkMode::Client;
    clientConfig.serverAddress = "127.0.0.1";
    clientConfig.port = kTestPort;
    clientASession.setLocalIdentity(201, engine::core::AgeGroup::Adult);
    clientBSession.setLocalIdentity(202, engine::core::AgeGroup::Adult);
    check(clientASession.initialize(clientConfig), "rapid-DM test: real client A real-connects");
    check(clientBSession.initialize(clientConfig), "rapid-DM test: real client B real-connects");

    engine::core::EntityId a = clientAEcs.createEntity("A");
    clientAEcs.addComponent<engine::core::Transform>(a);
    engine::core::EntityId b = clientBEcs.createEntity("B");
    clientBEcs.addComponent<engine::core::Transform>(b);

    bool allHandshook = false;
    for (int i = 0; i < 300 && !allHandshook; ++i) {
        serverSession.tick(0.05f, serverEcs, engine::core::kNullEntity);
        clientASession.sampleLocalInput(clientAEcs, a, glm::vec3(0.0f), false, false, 0.0f, 0.0f, 0.05f);
        clientASession.tick(0.05f, clientAEcs, a);
        clientBSession.sampleLocalInput(clientBEcs, b, glm::vec3(0.0f), false, false, 0.0f, 0.0f, 0.05f);
        clientBSession.tick(0.05f, clientBEcs, b);
        allHandshook = clientASession.localPlayerId() != engine::net::kInvalidPlayer &&
                        clientBSession.localPlayerId() != engine::net::kInvalidPlayer;
        if (!allHandshook) std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }
    check(allHandshook, "rapid-DM test: both real clients really complete real handshakes");

    engine::net::PlayerId realSenderId = clientASession.localPlayerId();
    check(serverSession.trustSafetyService().currentTier(realSenderId) == engine::safety::EscalationTier::Log,
          "rapid-DM test: the real sender starts at the real baseline tier server-side");

    // 10 real, ordinary DMs -- kRapidMessageCountThreshold's real value --
    // sent in a real burst, each one real-ticked through to real server
    // receipt before the next is sent.
    for (int i = 0; i < 10; ++i) {
        clientASession.sendDirectMessage(clientBSession.localPlayerId(), "hi");
        for (int tick = 0; tick < 20; ++tick) {
            serverSession.tick(0.05f, serverEcs, engine::core::kNullEntity);
            clientASession.tick(0.05f, clientAEcs, a);
            clientBSession.tick(0.05f, clientBEcs, b);
            std::this_thread::sleep_for(std::chrono::milliseconds(5));
        }
    }

    check(serverSession.directMessageLog().size() == 10, "rapid-DM test: all 10 real DMs are real-recorded server-side");
    check(serverSession.trustSafetyService().currentTier(realSenderId) != engine::safety::EscalationTier::Log,
          "a real burst of 10 real, ordinary DMs within the real recent window genuinely escalates the real "
          "sender's real risk tier past baseline -- proving BehavioralPatternAnalyzer is real-wired into the "
          "actual DM send path, not just unit-testable in isolation");

    serverSession.shutdown();
    clientASession.shutdown();
    clientBSession.shutdown();
}

