void testNetworkSessionRealMultipleReportCategoriesRoundTrip() {
    constexpr uint16_t kTestPort = 17783;
    engine::core::ECS serverEcs, clientEcs;
    engine::net::NetworkSession serverSession, clientSession;

    engine::net::NetworkSession::Config serverConfig;
    serverConfig.mode = engine::net::NetworkMode::Server;
    serverConfig.port = kTestPort;
    check(serverSession.initialize(serverConfig), "Multi-category report test: real server real-starts");
    serverSession.setOnPlayerJoin([](engine::core::ECS& ecs, engine::net::PlayerId player) -> engine::core::EntityId {
        engine::core::EntityId entity = ecs.createEntity("Player" + std::to_string(player));
        ecs.addComponent<engine::core::Transform>(entity);
        return entity;
    });

    engine::net::NetworkSession::Config clientConfig;
    clientConfig.mode = engine::net::NetworkMode::Client;
    clientConfig.serverAddress = "127.0.0.1";
    clientConfig.port = kTestPort;
    check(clientSession.initialize(clientConfig), "Multi-category report test: real client real-connects");

    engine::core::EntityId clientAvatar = clientEcs.createEntity("Local");
    clientEcs.addComponent<engine::core::Transform>(clientAvatar);

    bool handshakeComplete = false;
    for (int i = 0; i < 200 && !handshakeComplete; ++i) {
        serverSession.tick(0.05f, serverEcs, engine::core::kNullEntity);
        clientSession.sampleLocalInput(clientEcs, clientAvatar, glm::vec3(0.0f), false, false, 0.0f, 0.0f, 0.05f);
        clientSession.tick(0.05f, clientEcs, clientAvatar);
        handshakeComplete = clientSession.localPlayerId() != engine::net::kInvalidPlayer;
        if (!handshakeComplete) std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }
    check(handshakeComplete, "Multi-category report test: real handshake really completes");

    clientSession.reportPlayer(111, engine::moderation::ReportCategory::Abuse, "harassment in chat");
    clientSession.reportPlayer(222, engine::moderation::ReportCategory::InappropriateContent, "bad build");

    for (int i = 0; i < 200 && serverSession.reportLog().size() < 2; ++i) {
        serverSession.tick(0.05f, serverEcs, engine::core::kNullEntity);
        clientSession.tick(0.05f, clientEcs, clientAvatar);
        std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }
    check(serverSession.reportLog().size() == 2, "Both real, distinct report submissions really reach the real server's report log");

    bool foundAbuse = false, foundInappropriate = false;
    for (const auto& report : serverSession.reportLog().reports()) {
        if (report.category == engine::moderation::ReportCategory::Abuse && report.reported == 111) foundAbuse = true;
        if (report.category == engine::moderation::ReportCategory::InappropriateContent && report.reported == 222) foundInappropriate = true;
    }
    check(foundAbuse, "The real Abuse-category report real-round-trips with its real correct reported player id");
    check(foundInappropriate, "The real InappropriateContent-category report real-round-trips with its real correct reported player id");

    serverSession.shutdown();
    clientSession.shutdown();
}

