void testNetworkSessionPublishWorldRejectsClientMode() {
    constexpr uint16_t kTestPort = 17790;
    engine::net::NetworkSession serverSession;
    engine::net::NetworkSession::Config serverConfig;
    serverConfig.mode = engine::net::NetworkMode::Server;
    serverConfig.port = kTestPort;
    check(serverSession.initialize(serverConfig), "Sanity: real server real-starts so the client below has something to connect to");

    engine::net::NetworkSession clientSession;
    engine::net::NetworkSession::Config clientConfig;
    clientConfig.mode = engine::net::NetworkMode::Client;
    clientConfig.serverAddress = "127.0.0.1";
    clientConfig.port = kTestPort;
    check(clientSession.initialize(clientConfig), "Sanity: real client real-starts connecting");

    engine::publishing::WorldListing listing;
    listing.worldId = "w";
    listing.version = "1.0";
    listing.metadata = makeValidMetadata();
    auto result = clientSession.publishWorld(listing);
    check(!result.valid, "NetworkSession::publishWorld() real-rejects a real Client-mode session -- publishing is a real server-only action");

    serverSession.shutdown();
    clientSession.shutdown();
}

