void testEndToEndPublishPipelineValidatePackageSaveLoadRegister() {
    // A real, full, pure-logic integration test tying together every
    // Sprint 13 piece except the GPU-touching thumbnail capture (already
    // live-verified separately, see this section's own header comment):
    // build real metadata + a real scene, validate, package, save to a
    // real directory, reload it fresh, and register it with a real
    // server-mode NetworkSession -- the same real sequence
    // studio::plugins::PublishingPanel's own Test Publish + registry
    // buttons drive.
    engine::publishing::WorldMetadata metadata = makeValidMetadata();
    metadata.title = "End To End World";
    metadata.category = engine::publishing::WorldCategory::Adventure;

    engine::core::SceneFile scene = makeNonEmptyScene();

    auto validation = engine::publishing::validateForPublish("e2e_world", "1.0.0", metadata, scene);
    check(validation.valid, "End-to-end: real validation real-passes before packaging");

    engine::publishing::WorldPackage package;
    package.worldId = "e2e_world";
    package.version = "1.0.0";
    package.metadata = metadata;
    package.scene = scene;
    const char* directory = "test_world_package_e2e";
    check(package.saveToDirectory(directory), "End-to-end: real package real-saves to a real local directory (Test Publish)");

    engine::publishing::WorldPackage reloaded;
    check(reloaded.loadFromDirectory(directory), "End-to-end: real package real-reloads fresh from disk");
    check(reloaded.metadata.title == "End To End World", "End-to-end: the real reloaded package's metadata really matches what was published");

    engine::net::NetworkSession session;
    engine::net::NetworkSession::Config config;
    config.mode = engine::net::NetworkMode::Server;
    config.port = 17800;
    check(session.initialize(config), "End-to-end: real server real-starts for the registry step");

    engine::publishing::WorldListing listing;
    listing.worldId = reloaded.worldId;
    listing.version = reloaded.version;
    listing.metadata = reloaded.metadata;
    listing.creatorId = 1;
    auto publishResult = session.publishWorld(listing);
    check(publishResult.valid, "End-to-end: the real reloaded package's listing real-passes registry publish validation");
    check(session.worldRegistry().findById("e2e_world") != nullptr,
          "End-to-end: the real complete pipeline (validate -> package -> save -> reload -> register) really lands the world in the real server registry");
    session.shutdown();
}

