void testWorldRegistryUpsertPreservesUnrelatedEntries() {
    engine::publishing::WorldRegistry registry;
    engine::publishing::WorldListing a, b, c;
    a.worldId = "keep_a";
    a.version = "1.0";
    b.worldId = "update_b";
    b.version = "1.0";
    c.worldId = "keep_c";
    c.version = "1.0";
    registry.upsert(a);
    registry.upsert(b);
    registry.upsert(c);

    engine::publishing::WorldListing updatedB;
    updatedB.worldId = "update_b";
    updatedB.version = "9.9";
    registry.upsert(updatedB);

    check(registry.size() == 3, "Updating one real entry real-leaves the real total count unchanged");
    check(registry.findById("keep_a")->version == "1.0", "Updating one real entry real-leaves an unrelated real entry completely untouched");
    check(registry.findById("keep_c")->version == "1.0", "Updating one real entry real-leaves a second unrelated real entry completely untouched");
    check(registry.findById("update_b")->version == "9.9", "The real targeted entry really was updated");
}

