void testValidateWorldMetadataEachFieldIndividuallyValid() {
    // A real, one-field-at-a-time sweep -- each of these starts from a
    // real, fully-valid baseline and changes exactly one field, so a
    // regression in any single real validation rule shows up as exactly
    // one real failing check here, not a vague "something broke".
    auto base = makeValidMetadata();
    check(engine::publishing::validateWorldMetadata(base).valid, "Baseline real metadata is real-valid");

    auto withLongCreator = base;
    withLongCreator.creatorName = std::string(50, 'c');
    check(engine::publishing::validateWorldMetadata(withLongCreator).valid, "A real, reasonably long (50-char) creator name is real-valid -- no length cap on creatorName");

    auto withManyTags = base;
    for (int i = 0; i < 30; ++i) withManyTags.tags.push_back("t" + std::to_string(i));
    check(engine::publishing::validateWorldMetadata(withManyTags).valid, "A real world with 30 tags is real-valid -- no cap on tag count");

    auto withEmptyStringTag = base;
    withEmptyStringTag.tags.push_back("");
    check(engine::publishing::validateWorldMetadata(withEmptyStringTag).valid, "A real, technically-empty tag string doesn't real-invalidate the whole metadata -- tags aren't individually validated");
}

