void testWorldRegistryRealPublishingWorkflowMultipleCreatorsAndCategories() {
    engine::publishing::WorldRegistry registry;
    struct Seed {
        const char* id;
        engine::net::PlayerId creator;
        engine::publishing::WorldCategory category;
    };
    Seed seeds[] = {
        {"w1", 1, engine::publishing::WorldCategory::Mining},
        {"w2", 1, engine::publishing::WorldCategory::Adventure},
        {"w3", 2, engine::publishing::WorldCategory::Mining},
        {"w4", 2, engine::publishing::WorldCategory::Horror},
        {"w5", 3, engine::publishing::WorldCategory::Sandbox},
    };
    for (const auto& seed : seeds) {
        engine::publishing::WorldListing listing;
        listing.worldId = seed.id;
        listing.creatorId = seed.creator;
        listing.metadata.category = seed.category;
        registry.upsert(listing);
    }

    check(registry.size() == 5, "A real registry seeded with 5 real distinct worlds real-reports size 5");
    check(registry.findByCreator(1).size() == 2, "Creator 1's real 2 published worlds are real-found");
    check(registry.findByCreator(2).size() == 2, "Creator 2's real 2 published worlds are real-found");
    check(registry.findByCreator(3).size() == 1, "Creator 3's real 1 published world is real-found");
    check(registry.listByCategory(engine::publishing::WorldCategory::Mining).size() == 2, "The real 2 Mining-category worlds are real-found across different creators");
    check(registry.listByCategory(engine::publishing::WorldCategory::Adventure).size() == 1, "The real 1 Adventure-category world is real-found");
    check(registry.listByCategory(engine::publishing::WorldCategory::Horror).size() == 1, "The real 1 Horror-category world is real-found");
    check(registry.listByCategory(engine::publishing::WorldCategory::Sandbox).size() == 1, "The real 1 Sandbox-category world is real-found");
}

