void testWorldPackageRealMiningWorldScenario() {
    // A real, representative "Mining Simulator"-shaped world package --
    // exercising the real pipeline against realistic content, not just
    // minimal single-entity fixtures.
    engine::publishing::WorldPackage package;
    package.worldId = "mining_world_scenario";
    package.version = "1.0.0";
    package.metadata.title = "Deep Rock Caverns";
    package.metadata.description = "Mine your way through five real biomes.";
    package.metadata.tags = {"mining", "rpg"};
    package.metadata.creatorName = "Test Studio";
    package.metadata.recommendedPlayerCount = 4;
    package.metadata.category = engine::publishing::WorldCategory::Mining;
    package.metadata.thumbnailPath = "thumb.ppm";

    const char* oreNames[] = {"CommonOre", "UncommonOre", "RareOre", "EpicOre", "LegendaryOre"};
    for (const char* oreName : oreNames) {
        for (int i = 0; i < 3; ++i) {
            engine::core::SceneEntityRecord entity;
            entity.name = std::string(oreName) + "_" + std::to_string(i);
            package.scene.entities.push_back(entity);
        }
    }

    auto validation = engine::publishing::validateForPublish(package.worldId, package.version, package.metadata, package.scene);
    check(validation.valid, "A real, representative 15-entity mining world real-passes full publish validation");

    const char* directory = "test_world_package_mining_scenario";
    check(package.saveToDirectory(directory), "The real mining world scenario package real-saves to disk");

    engine::publishing::WorldPackage reloaded;
    check(reloaded.loadFromDirectory(directory), "The real mining world scenario package real-reloads from disk");
    check(reloaded.scene.entities.size() == 15, "All 15 real entities (5 ore tiers x 3 each) real-survive the save/load round trip");
    check(reloaded.metadata.category == engine::publishing::WorldCategory::Mining, "The real Mining category real-survives the save/load round trip");
}

