void testPlayerClassNameAllFiveClassesReturnDistinctRealNames() {
    engine::tntwars::PlayerClassType classes[] = {
        engine::tntwars::PlayerClassType::Striker, engine::tntwars::PlayerClassType::Deflector,
        engine::tntwars::PlayerClassType::Engineer, engine::tntwars::PlayerClassType::Interceptor,
        engine::tntwars::PlayerClassType::Saboteur};
    std::vector<std::string> names;
    for (auto c : classes) names.emplace_back(engine::tntwars::playerClassName(c));
    for (size_t i = 0; i < names.size(); ++i) {
        for (size_t j = i + 1; j < names.size(); ++j) {
            check(names[i] != names[j], "Every real PlayerClassType name is real-distinct from every other");
        }
    }
    check(names[0] == "Striker", "Striker's real name is exactly \"Striker\"");
    check(names[4] == "Saboteur", "Saboteur's real name is exactly \"Saboteur\"");
}

