// --- CinematicSequence ---------------------------------------------------

void testCinematicSequenceEmptyWhenNoKeyframes() {
    engine::tntwars::CinematicSequence seq;
    check(seq.empty(), "A fresh real CinematicSequence with no real keyframes real-reports empty()");
}

void testCinematicSequenceNotEmptyAfterAddKeyframe() {
    engine::tntwars::CinematicSequence seq;
    seq.addKeyframe(0.0f, glm::vec3(0.0f));
    check(!seq.empty(), "Adding one real keyframe real-makes empty() false");
}

void testCinematicSequenceDurationSecondsMatchesLastKeyframeTime() {
    engine::tntwars::CinematicSequence seq;
    seq.addKeyframe(0.0f, glm::vec3(0.0f));
    seq.addKeyframe(2.5f, glm::vec3(1.0f, 0.0f, 0.0f));
    seq.addKeyframe(4.0f, glm::vec3(2.0f, 0.0f, 0.0f));
    check(nearlyEqual(seq.durationSeconds(), 4.0f), "durationSeconds() real-matches the real last keyframe's time");
}

void testCinematicSequenceSampleAtStartReturnsFirstKeyframePosition() {
    engine::tntwars::CinematicSequence seq;
    glm::vec3 start(5.0f, 2.0f, -3.0f);
    seq.addKeyframe(0.0f, start);
    seq.addKeyframe(4.0f, glm::vec3(0.0f));
    auto sample = seq.sample(0.0f, glm::vec3(0.0f, 0.0f, -100.0f));
    check(nearlyEqual(glm::length(sample.cameraPosition - start), 0.0f), "sample() at t=0 real-returns real the first keyframe's exact position");
}

void testCinematicSequenceSampleInterpolatesBetweenKeyframes() {
    engine::tntwars::CinematicSequence seq;
    seq.addKeyframe(0.0f, glm::vec3(0.0f, 0.0f, 0.0f), engine::core::EasingMode::Linear);
    seq.addKeyframe(2.0f, glm::vec3(10.0f, 0.0f, 0.0f), engine::core::EasingMode::Linear);
    auto sample = seq.sample(1.0f, glm::vec3(0.0f, 0.0f, -50.0f));
    check(nearlyEqual(sample.cameraPosition.x, 5.0f, 0.05f), "A real linear-eased sample at the real midpoint time real-lands at the real midpoint position");
}

void testCinematicSequenceSampleYawPitchFacesLookAtTarget() {
    // Real inversion check against core::Camera::forward()'s own real
    // convention (see CinematicSequence.cpp): pitch = degrees(asin(dir.y)),
    // yaw = degrees(atan2(dir.z, dir.x)).
    engine::tntwars::CinematicSequence seq;
    glm::vec3 cameraPos(0.0f, 0.0f, 0.0f);
    seq.addKeyframe(0.0f, cameraPos);
    seq.addKeyframe(1.0f, cameraPos);
    glm::vec3 target(10.0f, 5.0f, 0.0f);
    auto sample = seq.sample(0.0f, target);
    glm::vec3 direction = glm::normalize(target - cameraPos);
    float expectedPitch = glm::degrees(std::asin(std::clamp(direction.y, -1.0f, 1.0f)));
    float expectedYaw = glm::degrees(std::atan2(direction.z, direction.x));
    check(nearlyEqual(sample.pitchDegrees, expectedPitch, 0.1f), "sample()'s real pitch real-matches the documented look-at inversion formula");
    check(nearlyEqual(sample.yawDegrees, expectedYaw, 0.1f), "sample()'s real yaw real-matches the documented look-at inversion formula");
}

void testBuildUltimateCinematicAllFiveTypesAreNonEmptyWithRealDuration() {
    engine::tntwars::UltimateType types[] = {
        engine::tntwars::UltimateType::FinalPush, engine::tntwars::UltimateType::BarrierBreak,
        engine::tntwars::UltimateType::Overclock, engine::tntwars::UltimateType::HyperScan,
        engine::tntwars::UltimateType::ShadowDive};
    for (auto t : types) {
        engine::tntwars::CinematicSequence seq = engine::tntwars::buildUltimateCinematic(t, glm::vec3(0.0f, 1.0f, 0.0f));
        check(!seq.empty(), "Every real ultimate type real-produces a non-empty real CinematicSequence");
        check(nearlyEqual(seq.durationSeconds(), engine::tntwars::kUltimateCinematicDurationSeconds, 0.01f),
              "Every real ultimate cinematic real-runs for exactly kUltimateCinematicDurationSeconds");
    }
}

void testBuildUltimateCinematicProducesDistinctPathsPerType() {
    using namespace engine::tntwars;
    glm::vec3 origin(0.0f, 1.0f, 0.0f);
    CinematicSequence finalPush = buildUltimateCinematic(UltimateType::FinalPush, origin);
    CinematicSequence barrierBreak = buildUltimateCinematic(UltimateType::BarrierBreak, origin);
    auto a = finalPush.sample(1.0f, origin);
    auto b = barrierBreak.sample(1.0f, origin);
    check(glm::length(a.cameraPosition - b.cameraPosition) > 0.5f,
          "FinalPush's real camera path real-differs meaningfully from BarrierBreak's at the same real sample time -- distinct real choreography, not a shared placeholder");
}

