// --- ThrusterHp --------------------------------------------------------

void testApplyThrusterHitIncrementsHitsTaken() {
    engine::tntwars::ThrusterPlatformState state;
    engine::tntwars::applyThrusterHit(state);
    check(state.hitsTaken == 1, "One real hit real-increments hitsTaken to 1");
}

void testApplyThrusterHitTiltRampsLinearly() {
    engine::tntwars::ThrusterPlatformState state;
    for (int i = 1; i <= 5; ++i) {
        engine::tntwars::applyThrusterHit(state);
        float expectedTilt = (static_cast<float>(i) / 5.0f) * engine::tntwars::ThrusterPlatformState::kMaxTiltDegrees;
        check(nearlyEqual(state.tiltDegrees, expectedTilt, 0.01f), "Real tilt after each real hit real-matches the real linear ramp formula");
    }
}

void testApplyThrusterHitCollapsesAtMaxHits() {
    engine::tntwars::ThrusterPlatformState state;
    for (int i = 0; i < engine::tntwars::ThrusterPlatformState::kMaxHits; ++i) engine::tntwars::applyThrusterHit(state);
    check(state.collapsed, "Exactly kMaxHits real hits real-collapses the real platform");
    check(nearlyEqual(state.tiltDegrees, engine::tntwars::ThrusterPlatformState::kMaxTiltDegrees), "A real collapsed platform sits at real kMaxTiltDegrees exactly");
}

void testApplyThrusterHitIdempotentOnceCollapsed() {
    engine::tntwars::ThrusterPlatformState state;
    for (int i = 0; i < engine::tntwars::ThrusterPlatformState::kMaxHits; ++i) engine::tntwars::applyThrusterHit(state);
    engine::tntwars::applyThrusterHit(state);
    check(state.hitsTaken == engine::tntwars::ThrusterPlatformState::kMaxHits, "A real hit against an real already-collapsed platform real-does not further increment hitsTaken");
}

void testIsThrusterDestabilizingFalseAtZeroHits() {
    engine::tntwars::ThrusterPlatformState state;
    check(!engine::tntwars::isThrusterDestabilizing(state), "A real untouched platform real-is not destabilizing");
}

void testIsThrusterDestabilizingTrueAfterOneHitBeforeCollapse() {
    engine::tntwars::ThrusterPlatformState state;
    engine::tntwars::applyThrusterHit(state);
    check(engine::tntwars::isThrusterDestabilizing(state), "A real platform with 1 real hit (not yet collapsed) real-is destabilizing");
}

void testIsThrusterDestabilizingFalseOnceCollapsed() {
    engine::tntwars::ThrusterPlatformState state;
    for (int i = 0; i < engine::tntwars::ThrusterPlatformState::kMaxHits; ++i) engine::tntwars::applyThrusterHit(state);
    check(!engine::tntwars::isThrusterDestabilizing(state), "A real fully-collapsed platform real-is no longer \"destabilizing\" -- it's already down");
}

// --- LavaEruption --------------------------------------------------------

void testLavaEruptionStateAtTimeZeroIsErupting() {
    engine::tntwars::LavaEruptionState state;
    check(state.isErupting(), "A real fresh LavaEruptionState at cycleTimer=0 real-starts erupting immediately");
}

void testTickLavaEruptionStopsEruptingAfterDuration() {
    engine::tntwars::LavaEruptionState state;
    engine::tntwars::tickLavaEruption(state, engine::tntwars::LavaEruptionState::kEruptionDurationSeconds + 0.5f);
    check(!state.isErupting(), "After real kEruptionDurationSeconds elapses, the real hazard real-stops erupting");
}

void testTickLavaEruptionReEruptsAfterFullInterval() {
    engine::tntwars::LavaEruptionState state;
    engine::tntwars::tickLavaEruption(state, engine::tntwars::LavaEruptionState::kEruptionIntervalSeconds + 0.5f);
    check(state.isErupting(), "Real wraparound past a full real kEruptionIntervalSeconds real-re-enters the real erupting phase");
}

void testTickLavaEruptionPreservesOvershootViaFmod() {
    engine::tntwars::LavaEruptionState state;
    engine::tntwars::tickLavaEruption(state, engine::tntwars::LavaEruptionState::kEruptionIntervalSeconds + 1.0f);
    check(nearlyEqual(state.cycleTimer, 1.0f, 0.01f), "Real overshoot past the real interval real-wraps via fmod, not a hard reset to 0 -- 1.0s of real overshoot survives");
}

void testTickLavaEruptionNoOpOnNonPositiveDt() {
    engine::tntwars::LavaEruptionState state;
    state.cycleTimer = 5.0f;
    engine::tntwars::tickLavaEruption(state, 0.0f);
    check(nearlyEqual(state.cycleTimer, 5.0f), "A real non-positive dt real-does not advance the real cycle timer");
}

void testIsWithinEruptionDamageRadiusTrueAtCenter() {
    check(engine::tntwars::isWithinEruptionDamageRadius(glm::vec3(0.0f), glm::vec3(0.0f), 5.0f),
          "Standing real-exactly at the real eruption center is real-within the real damage radius");
}

void testIsWithinEruptionDamageRadiusTrueAtExactBoundary() {
    check(engine::tntwars::isWithinEruptionDamageRadius(glm::vec3(5.0f, 0.0f, 0.0f), glm::vec3(0.0f), 5.0f),
          "Real-exactly at the real radius boundary real-counts as within it (inclusive real <=)");
}

void testIsWithinEruptionDamageRadiusFalseOutsideRadius() {
    check(!engine::tntwars::isWithinEruptionDamageRadius(glm::vec3(50.0f, 0.0f, 0.0f), glm::vec3(0.0f), 5.0f),
          "Real far outside the real damage radius real-registers no damage");
}

// --- TorpedoStealth --------------------------------------------------------

void testIsDetectedBySonarFalseWithNoSources() {
    check(!engine::tntwars::isDetectedBySonar(glm::vec3(0.0f), {}, engine::tntwars::kDefaultSonarDetectionRadius),
          "With real zero sonar sources, a real torpedo is real-never detected");
}

void testIsDetectedBySonarTrueWithinRadius() {
    std::vector<glm::vec3> sources = {glm::vec3(0.0f, 0.0f, 0.0f)};
    check(engine::tntwars::isDetectedBySonar(glm::vec3(2.0f, 0.0f, 0.0f), sources, 12.0f),
          "A real torpedo real-within a real sonar source's detection radius real-is detected");
}

void testIsDetectedBySonarFalseOutsideRadius() {
    std::vector<glm::vec3> sources = {glm::vec3(0.0f, 0.0f, 0.0f)};
    check(!engine::tntwars::isDetectedBySonar(glm::vec3(200.0f, 0.0f, 0.0f), sources, 12.0f),
          "A real torpedo real-far outside every real sonar source's radius real-is not detected");
}

void testIsDetectedBySonarTrueIfAnyOfMultipleSourcesInRange() {
    std::vector<glm::vec3> sources = {glm::vec3(1000.0f, 0.0f, 0.0f), glm::vec3(0.0f, 0.0f, 0.0f)};
    check(engine::tntwars::isDetectedBySonar(glm::vec3(1.0f, 0.0f, 0.0f), sources, 12.0f),
          "Real detection real-succeeds if ANY real sonar source (not necessarily the first) is real-in range");
}

void testIsDetectedBySonarTrueAtExactBoundary() {
    std::vector<glm::vec3> sources = {glm::vec3(0.0f, 0.0f, 0.0f)};
    check(engine::tntwars::isDetectedBySonar(glm::vec3(12.0f, 0.0f, 0.0f), sources, 12.0f),
          "Real-exactly at the real detection radius boundary real-counts as detected (inclusive real <=)");
}

// --- RadarIntercept --------------------------------------------------------

void testTryInterceptBlipSucceedsWithinWindow() {
    engine::tntwars::RadarBlip blip;
    blip.spawnTimeSeconds = 10.0f;
    check(engine::tntwars::tryInterceptBlip(blip, 10.5f), "A real intercept attempt real-within the real timing window real-succeeds");
    check(blip.intercepted, "A real successful intercept real-sets intercepted=true");
}

void testTryInterceptBlipFailsBeforeSpawnTime() {
    engine::tntwars::RadarBlip blip;
    blip.spawnTimeSeconds = 10.0f;
    check(!engine::tntwars::tryInterceptBlip(blip, 9.0f), "An real attempt real-before the real blip even spawned real-fails");
}

void testTryInterceptBlipFailsAfterWindowExpires() {
    engine::tntwars::RadarBlip blip;
    blip.spawnTimeSeconds = 0.0f;
    check(!engine::tntwars::tryInterceptBlip(blip, engine::tntwars::RadarBlip::kInterceptWindowSeconds + 1.0f),
          "An real attempt real-after the real interceptWindowSeconds has elapsed real-fails");
}

void testTryInterceptBlipFailsIfAlreadyIntercepted() {
    engine::tntwars::RadarBlip blip;
    blip.spawnTimeSeconds = 0.0f;
    check(engine::tntwars::tryInterceptBlip(blip, 0.5f), "Sanity: the real first attempt real-succeeds");
    check(!engine::tntwars::tryInterceptBlip(blip, 0.6f), "A real second attempt against an real already-intercepted blip real-fails -- one-shot, not repeatable");
}

void testTryInterceptBlipFailsIfAlreadyExpired() {
    engine::tntwars::RadarBlip blip;
    blip.spawnTimeSeconds = 0.0f;
    blip.expired = true;
    check(!engine::tntwars::tryInterceptBlip(blip, 0.5f), "A real attempt against an real already-expired blip real-fails");
}

void testTryInterceptBlipSucceedsAtExactWindowBoundary() {
    engine::tntwars::RadarBlip blip;
    blip.spawnTimeSeconds = 0.0f;
    check(engine::tntwars::tryInterceptBlip(blip, engine::tntwars::RadarBlip::kInterceptWindowSeconds),
          "A real attempt real-exactly at the real window boundary real-still succeeds (inclusive real <=)");
}

void testTickRadarBlipExpirySetsExpiredAfterWindow() {
    engine::tntwars::RadarBlip blip;
    blip.spawnTimeSeconds = 0.0f;
    engine::tntwars::tickRadarBlipExpiry(blip, engine::tntwars::RadarBlip::kInterceptWindowSeconds + 0.1f);
    check(blip.expired, "A real un-intercepted blip past its real window real-gets marked expired by a real tick");
}

void testTickRadarBlipExpiryDoesNotExpireWithinWindow() {
    engine::tntwars::RadarBlip blip;
    blip.spawnTimeSeconds = 0.0f;
    engine::tntwars::tickRadarBlipExpiry(blip, 0.5f);
    check(!blip.expired, "A real blip still real-within its window real-does not get marked expired");
}

void testTickRadarBlipExpiryNoOpIfAlreadyIntercepted() {
    engine::tntwars::RadarBlip blip;
    blip.spawnTimeSeconds = 0.0f;
    blip.intercepted = true;
    engine::tntwars::tickRadarBlipExpiry(blip, 100.0f);
    check(!blip.expired, "A real already-intercepted blip real-never gets marked expired, no matter how late the real tick runs");
}

// --- MapDefinition --------------------------------------------------------

void testMapNameAllFiveMapsReturnDistinctRealNames() {
    engine::tntwars::MapId maps[] = {engine::tntwars::MapId::Trenches, engine::tntwars::MapId::Mantle,
                                      engine::tntwars::MapId::SkyPlatforms, engine::tntwars::MapId::IslandSea,
                                      engine::tntwars::MapId::Space};
    std::vector<std::string> names;
    for (auto m : maps) names.emplace_back(engine::tntwars::mapName(m));
    for (size_t i = 0; i < names.size(); ++i)
        for (size_t j = i + 1; j < names.size(); ++j) check(names[i] != names[j], "Every real MapId name is real-distinct");
}

void testMapModifiersForTrenchesIsBaselineNoHazards() {
    auto modifiers = engine::tntwars::mapModifiersFor(engine::tntwars::MapId::Trenches);
    check(!modifiers.hasLavaHazard && !modifiers.hasThrusterPlatforms && !modifiers.hasTorpedoStealth && !modifiers.hasSonarIntercept,
          "Trenches -- the real classic-artillery baseline -- real-has no active real hazard systems");
}

void testMapModifiersForMantleHasLavaHazard() {
    check(engine::tntwars::mapModifiersFor(engine::tntwars::MapId::Mantle).hasLavaHazard, "Mantle real-has the real lava hazard flag set");
    check(engine::tntwars::mapModifiersFor(engine::tntwars::MapId::Mantle).heatDamagePerSecond > 0.0f, "Mantle real-has real-positive heat damage per second");
}

void testMapModifiersForSkyPlatformsHasThrusterPlatforms() {
    check(engine::tntwars::mapModifiersFor(engine::tntwars::MapId::SkyPlatforms).hasThrusterPlatforms,
          "Sky Platforms real-has the real thruster-platform flag set");
}

void testMapModifiersForIslandSeaHasTorpedoStealthAndSonar() {
    auto modifiers = engine::tntwars::mapModifiersFor(engine::tntwars::MapId::IslandSea);
    check(modifiers.hasTorpedoStealth, "Island Sea real-has the real torpedo-stealth flag set");
    check(modifiers.hasSonarIntercept, "Island Sea real-has the real sonar-intercept flag set");
    check(modifiers.pressureFactor < 1.0f, "Island Sea's real underwater pressure real-reduces the real movement-speed factor below 1.0");
}

void testMapTuningTableDefaultsMatchMapModifiersFor() {
    using namespace engine::tntwars;
    MapTuningTable table;
    MapId maps[] = {MapId::Trenches, MapId::Mantle, MapId::SkyPlatforms, MapId::IslandSea, MapId::Space};
    for (auto m : maps) {
        MapModifiers expected = mapModifiersFor(m);
        MapModifiers actual = table.modifiersFor(m);
        check(actual.hasLavaHazard == expected.hasLavaHazard && nearlyEqual(actual.fogDensity, expected.fogDensity),
              "A fresh real MapTuningTable real-seeds every map from mapModifiersFor()'s real default");
    }
}

void testMapTuningTableSetModifiersForOverridesAndPersists() {
    using namespace engine::tntwars;
    MapTuningTable table;
    MapModifiers edited = table.modifiersFor(MapId::Trenches);
    edited.fogDensity = 0.75f;
    table.setModifiersFor(MapId::Trenches, edited);
    check(nearlyEqual(table.modifiersFor(MapId::Trenches).fogDensity, 0.75f), "A real setModifiersFor() edit real-persists across a subsequent real read");
}

void testMapTuningTableSetModifiersForOneMapDoesNotAffectOthers() {
    using namespace engine::tntwars;
    MapTuningTable table;
    MapModifiers edited = table.modifiersFor(MapId::Trenches);
    edited.fogDensity = 0.75f;
    table.setModifiersFor(MapId::Trenches, edited);
    check(!nearlyEqual(table.modifiersFor(MapId::Mantle).fogDensity, 0.75f), "Editing one real map's modifiers real-does not bleed into another real map's modifiers");
}

void testMapTuningTableResetToDefaultsRestoresOriginalValues() {
    using namespace engine::tntwars;
    MapTuningTable table;
    MapModifiers edited = table.modifiersFor(MapId::Mantle);
    edited.hasLavaHazard = false;
    table.setModifiersFor(MapId::Mantle, edited);
    table.resetToDefaults();
    check(table.modifiersFor(MapId::Mantle).hasLavaHazard == mapModifiersFor(MapId::Mantle).hasLavaHazard,
          "resetToDefaults() real-restores every real map back to mapModifiersFor()'s real default");
}

// --- MapLayout --------------------------------------------------------

bool layoutHasPieceNamed(const std::vector<engine::tntwars::MapLayoutPiece>& pieces, const std::string& name) {
    for (const auto& piece : pieces) {
        if (piece.name == name) return true;
    }
    return false;
}

void testBuildMapLayoutTrenchesHasGroundAndTwoBases() {
    auto pieces = engine::tntwars::buildMapLayout(engine::tntwars::MapId::Trenches);
    check(layoutHasPieceNamed(pieces, "Ground"), "Trenches' real layout real-includes a real Ground piece");
    check(layoutHasPieceNamed(pieces, "TeamA_Base"), "Trenches' real layout real-includes a real TeamA_Base piece");
    check(layoutHasPieceNamed(pieces, "TeamB_Base"), "Trenches' real layout real-includes a real TeamB_Base piece");
}

void testBuildMapLayoutMantleIncludesLavaPoolPiece() {
    auto pieces = engine::tntwars::buildMapLayout(engine::tntwars::MapId::Mantle);
    check(layoutHasPieceNamed(pieces, "LavaPool"), "Mantle's real layout real-includes a real LavaPool piece, matching its real hasLavaHazard modifier");
}

void testBuildMapLayoutSkyPlatformsHasNoSingleGroundPlane() {
    auto pieces = engine::tntwars::buildMapLayout(engine::tntwars::MapId::SkyPlatforms);
    check(!layoutHasPieceNamed(pieces, "Ground"), "Sky Platforms' real layout real-has no single \"Ground\" piece -- it's real floating platforms instead");
    check(layoutHasPieceNamed(pieces, "TeamA_SkyPlatform") && layoutHasPieceNamed(pieces, "TeamB_SkyPlatform"),
          "Sky Platforms' real layout real-includes a real sky platform for each team");
}

void testBuildMapLayoutIslandSeaIncludesWaterPiece() {
    auto pieces = engine::tntwars::buildMapLayout(engine::tntwars::MapId::IslandSea);
    check(layoutHasPieceNamed(pieces, "Water"), "Island Sea's real layout real-includes a real Water piece");
}

void testBuildMapLayoutAllMapsIncludeBothTeamBases() {
    engine::tntwars::MapId maps[] = {engine::tntwars::MapId::Trenches, engine::tntwars::MapId::Mantle,
                                      engine::tntwars::MapId::SkyPlatforms, engine::tntwars::MapId::IslandSea,
                                      engine::tntwars::MapId::Space};
    for (auto m : maps) {
        auto pieces = engine::tntwars::buildMapLayout(m);
        check(layoutHasPieceNamed(pieces, "TeamA_Base"), "Every real map's real layout real-includes a real TeamA_Base");
        check(layoutHasPieceNamed(pieces, "TeamB_Base"), "Every real map's real layout real-includes a real TeamB_Base");
    }
}

void testBuildMapLayoutTeamBasesAreSymmetricAroundOrigin() {
    engine::tntwars::MapId maps[] = {engine::tntwars::MapId::Trenches, engine::tntwars::MapId::Mantle,
                                      engine::tntwars::MapId::SkyPlatforms, engine::tntwars::MapId::IslandSea,
                                      engine::tntwars::MapId::Space};
    for (auto m : maps) {
        auto pieces = engine::tntwars::buildMapLayout(m);
        const engine::tntwars::MapLayoutPiece* teamA = nullptr;
        const engine::tntwars::MapLayoutPiece* teamB = nullptr;
        for (const auto& piece : pieces) {
            if (piece.name == "TeamA_Base") teamA = &piece;
            if (piece.name == "TeamB_Base") teamB = &piece;
        }
        check(teamA != nullptr && teamB != nullptr, "Sanity: both real team bases real-exist in this real map's layout");
        if (teamA && teamB) {
            check(nearlyEqual(teamA->position.z, -teamB->position.z, 0.01f), "Real TeamA_Base and TeamB_Base sit real-symmetrically opposite each other on the Z axis");
            check(nearlyEqual(teamA->position.x, teamB->position.x, 0.01f), "Real team bases real-share the same real X position (centered lane)");
        }
    }
}

void testBuildMapLayoutPieceNamesAreUniquePerMap() {
    engine::tntwars::MapId maps[] = {engine::tntwars::MapId::Trenches, engine::tntwars::MapId::Mantle,
                                      engine::tntwars::MapId::SkyPlatforms, engine::tntwars::MapId::IslandSea,
                                      engine::tntwars::MapId::Space};
    for (auto m : maps) {
        auto pieces = engine::tntwars::buildMapLayout(m);
        for (size_t i = 0; i < pieces.size(); ++i) {
            for (size_t j = i + 1; j < pieces.size(); ++j) {
                check(pieces[i].name != pieces[j].name, "Every real piece name within a single real map's layout is real-unique");
            }
        }
    }
}

void testBuildMapLayoutHazardPiecesConsistentWithMapModifiers() {
    auto mantleModifiers = engine::tntwars::mapModifiersFor(engine::tntwars::MapId::Mantle);
    auto mantlePieces = engine::tntwars::buildMapLayout(engine::tntwars::MapId::Mantle);
    check(mantleModifiers.hasLavaHazard == layoutHasPieceNamed(mantlePieces, "LavaPool"),
          "Mantle's real LavaPool piece presence real-matches its real hasLavaHazard modifier exactly");

    auto islandModifiers = engine::tntwars::mapModifiersFor(engine::tntwars::MapId::IslandSea);
    auto islandPieces = engine::tntwars::buildMapLayout(engine::tntwars::MapId::IslandSea);
    check(islandModifiers.hasTorpedoStealth == layoutHasPieceNamed(islandPieces, "Water"),
          "Island Sea's real Water piece presence real-lines up with its real underwater hazard modifiers being active");
}

void testBuildMapLayoutEveryPieceHasPositiveHalfExtents() {
    engine::tntwars::MapId maps[] = {engine::tntwars::MapId::Trenches, engine::tntwars::MapId::Mantle,
                                      engine::tntwars::MapId::SkyPlatforms, engine::tntwars::MapId::IslandSea,
                                      engine::tntwars::MapId::Space};
    for (auto m : maps) {
        for (const auto& piece : engine::tntwars::buildMapLayout(m)) {
            check(piece.halfExtents.x > 0.0f && piece.halfExtents.z > 0.0f, "Every real map-layout piece real-has real-positive real half-extents on X/Z");
        }
    }
}

