        for (const auto& piece : pieces) {
            if (piece.name == "TeamB_Base") base = &piece;
        }
        check(base != nullptr, "Sanity: every real map real-has a TeamB_Base piece");
        if (base) {
            glm::vec3 expected = base->position + glm::vec3(0.0f, base->halfExtents.y + 1.8f, 0.0f);
            glm::vec3 actual = engine::tntwars::teamSpawnPosition(m, engine::tntwars::TeamId::B);
            check(nearlyEqual(actual.x, expected.x, 0.01f) && nearlyEqual(actual.y, expected.y, 0.01f) &&
                      nearlyEqual(actual.z, expected.z, 0.01f),
                  "teamSpawnPosition(map, B) real-sits real-exactly halfExtents.y + 1.8 above the real TeamB_Base piece's own position");
        }
