// --- MatchFlow --------------------------------------------------------

void testMatchPhaseNameAllFiveReturnDistinctRealNames() {
    engine::tntwars::MatchPhase phases[] = {engine::tntwars::MatchPhase::Lobby, engine::tntwars::MatchPhase::ClassSelect,
                                             engine::tntwars::MatchPhase::InProgress, engine::tntwars::MatchPhase::CinematicFinale,
                                             engine::tntwars::MatchPhase::Results};
    std::vector<std::string> names;
    for (auto p : phases) names.emplace_back(engine::tntwars::matchPhaseName(p));
    for (size_t i = 0; i < names.size(); ++i)
        for (size_t j = i + 1; j < names.size(); ++j) check(names[i] != names[j], "Every real MatchPhase name is real-distinct");
}

void testMatchFlowControllerStartsInLobby() {
    engine::tntwars::MatchFlowController flow;
    check(flow.phase() == engine::tntwars::MatchPhase::Lobby, "A real fresh MatchFlowController real-starts in Lobby");
    check(nearlyEqual(flow.phaseElapsedSeconds(), 0.0f), "A real fresh MatchFlowController's real phase timer real-starts at 0");
}

void testMatchFlowControllerAdvanceToFullRealChain() {
    using namespace engine::tntwars;
    MatchFlowController flow;
    MatchPhase chain[] = {MatchPhase::ClassSelect, MatchPhase::InProgress, MatchPhase::CinematicFinale,
                           MatchPhase::Results, MatchPhase::Lobby};
    for (auto next : chain) {
        bool ok = flow.advanceTo(next);
        check(ok, "Each real legal next step in the real match-flow chain real-succeeds");
        check(flow.phase() == next, "advanceTo() real-actually applies the real requested phase on success");
    }
}

void testMatchFlowControllerAdvanceToSkippedPhaseFails() {
    engine::tntwars::MatchFlowController flow;
    check(!flow.advanceTo(engine::tntwars::MatchPhase::InProgress), "Skipping real from Lobby real-straight to InProgress real-fails -- no phase is skippable");
    check(flow.phase() == engine::tntwars::MatchPhase::Lobby, "A real rejected advanceTo() real-leaves the real phase unchanged");
}

void testMatchFlowControllerAdvanceToBackwardPhaseFails() {
    engine::tntwars::MatchFlowController flow;
    check(flow.advanceTo(engine::tntwars::MatchPhase::ClassSelect), "Sanity: real Lobby -> ClassSelect real-succeeds");
    check(!flow.advanceTo(engine::tntwars::MatchPhase::Lobby), "Real ClassSelect -> Lobby (backward) real-fails -- no backward transition exists");
}

void testMatchFlowControllerAdvanceToResetsPhaseTimer() {
    engine::tntwars::MatchFlowController flow;
    flow.tick(5.0f);
    flow.advanceTo(engine::tntwars::MatchPhase::ClassSelect);
    check(nearlyEqual(flow.phaseElapsedSeconds(), 0.0f), "A real successful advanceTo() real-resets the real phase timer back to 0");
}

void testMatchFlowControllerTickAccumulatesPhaseTimer() {
    engine::tntwars::MatchFlowController flow;
    flow.tick(1.5f);
    flow.tick(2.0f);
    check(nearlyEqual(flow.phaseElapsedSeconds(), 3.5f), "Real tick() calls real-accumulate additively onto the real phase timer");
}

void testMatchFlowControllerTickNoOpOnNonPositiveDt() {
    engine::tntwars::MatchFlowController flow;
    flow.tick(2.0f);
    flow.tick(-1.0f);
    check(nearlyEqual(flow.phaseElapsedSeconds(), 2.0f), "A real non-positive dt real-does not advance the real phase timer");
}

void testIsValidTransitionExhaustiveMatrix() {
    using namespace engine::tntwars;
    MatchPhase phases[] = {MatchPhase::Lobby, MatchPhase::ClassSelect, MatchPhase::InProgress,
                            MatchPhase::CinematicFinale, MatchPhase::Results};
    int trueCount = 0;
    for (auto from : phases) {
        for (auto to : phases) {
            if (MatchFlowController::isValidTransition(from, to)) ++trueCount;
        }
    }
    check(trueCount == 5, "Across the real full 5x5 real transition matrix, exactly 5 real transitions (the real linear chain) are real-valid");
    check(!MatchFlowController::isValidTransition(MatchPhase::Lobby, MatchPhase::Lobby), "A real same-phase transition is real-never valid");
}

