    engine::tntwars::TntWarsMatch match;
    match.applyDamageToCore(engine::tntwars::TeamId::A, 150.0f);
    check(nearlyEqual(match.coreHealth(engine::tntwars::TeamId::A), engine::tntwars::TntWarsMatch::kCoreMaxHealth - 150.0f),
          "applyDamageToCore() real-reduces the real targeted team's real Core health by real-exactly the real damage amount");
    check(nearlyEqual(match.coreHealth(engine::tntwars::TeamId::B), engine::tntwars::TntWarsMatch::kCoreMaxHealth),
          "Damaging TeamA's real Core real-leaves TeamB's own real Core real-untouched");
