// --- Kronos ("TNT Wars Foundational Playability" Phase 2):
// DestructibleGeometryVisual -- real, live end-to-end coverage. Unlike
// spawnDestructibleWallVisual() (needs a real Vulkan device for its own
// Mesh/GPU upload, the same honest ceiling every GPU-touching spawn
// function in this codebase already has), tickDestructibleWallVisual()
// itself only touches core::ECS/core::Physics -- both real, headless, and
// already proven GPU-free by the Physics Core tests above -- so this
// builds its own real entity+physics body by hand (bypassing the mesh
// step entirely) and drives the real destroy/rebuild state machine
// against a real, live Jolt body. -------------------------------------

engine::core::EntityId spawnTestDestructibleEntity(engine::core::ECS& ecs, engine::core::Physics& physics,
                                                    glm::vec3 halfExtents) {
    engine::core::EntityId entity = ecs.createEntity("TestDestructibleSegment");
    ecs.addComponent<engine::core::Renderable>(entity);
    engine::core::ColliderShape shape;
    shape.kind = engine::core::ColliderShapeKind::Box;
    shape.params = halfExtents;
    bool attached =
        physics.attachBodyToEntity(entity, ecs, shape, engine::core::PhysicsMaterial{}, engine::core::RigidBodyMotionType::Static);
    check(attached, "the real test entity's own initial physics body really attaches successfully");
    return entity;
}

void testTickDestructibleWallVisualHidesAndDetachesOnDestruction() {
    engine::core::Physics physics;
    check(physics.initialize(), "a real Jolt PhysicsSystem initializes headlessly for this real destructible test too");
    engine::core::ECS ecs;

    engine::tntwars::DestructibleSegment segment;
    segment.health = 0.0f; // already destroyed as of this tick's own damage math
    segment.maxHealth = 100.0f;
    segment.halfExtents = glm::vec3(1.0f, 1.0f, 0.5f);
    std::vector<engine::tntwars::DestructibleSegment> segments{segment};

    engine::tntwars::DestructibleSegmentVisual visual;
    visual.entity = spawnTestDestructibleEntity(ecs, physics, segment.halfExtents);
    std::vector<engine::tntwars::DestructibleSegmentVisual> visuals{visual};

    auto* rigidBodyBefore = ecs.tryGetComponent<engine::core::RigidBody>(visual.entity);
    check(rigidBodyBefore != nullptr && rigidBodyBefore->joltBodyId != engine::core::RigidBody::kInvalidBodyId,
          "the real test entity really has a live Jolt body before the first tick");

    engine::tntwars::tickDestructibleWallVisual(segments, visuals, ecs, physics, 0.1f);

    check(visuals[0].destroyed, "a segment at 0 health really gets marked destroyed on its very next real tick");
    auto* renderable = ecs.tryGetComponent<engine::core::Renderable>(visual.entity);
    check(renderable != nullptr && !renderable->visible, "a destroyed segment's real mesh really becomes invisible");
    auto* rigidBodyAfter = ecs.tryGetComponent<engine::core::RigidBody>(visual.entity);
    check(rigidBodyAfter != nullptr && rigidBodyAfter->joltBodyId == engine::core::RigidBody::kInvalidBodyId,
          "a destroyed segment's real physics body is really detached -- nothing collides with it anymore");
    check(visuals[0].rebuildTimer > 0.0f, "destruction really starts a real, positive rebuild countdown, not an already-elapsed one");
}

void testTickDestructibleWallVisualDoesNotRebuildBeforeTimerElapses() {
    engine::core::Physics physics;
    check(physics.initialize(), "a real Jolt PhysicsSystem initializes for this real test");
    engine::core::ECS ecs;

    engine::tntwars::DestructibleSegment segment;
    segment.health = 0.0f;
    segment.maxHealth = 100.0f;
    std::vector<engine::tntwars::DestructibleSegment> segments{segment};

    engine::tntwars::DestructibleSegmentVisual visual;
    visual.entity = spawnTestDestructibleEntity(ecs, physics, glm::vec3(1.0f));
    visual.destroyed = true;
    visual.rebuildTimer = 5.0f;
    std::vector<engine::tntwars::DestructibleSegmentVisual> visuals{visual};

    engine::tntwars::tickDestructibleWallVisual(segments, visuals, ecs, physics, 1.0f);

    check(visuals[0].destroyed, "a real segment stays destroyed while real time remains on its own rebuild timer");
    check(nearlyEqual(visuals[0].rebuildTimer, 4.0f), "the real rebuild timer really counts down by real-exactly dt each tick");
    check(nearlyEqual(segments[0].health, 0.0f), "health stays real-zero until the real rebuild actually completes");
}

void testTickDestructibleWallVisualFullyRebuildsWhenTimerElapses() {
    engine::core::Physics physics;
    check(physics.initialize(), "a real Jolt PhysicsSystem initializes for this real test");
    engine::core::ECS ecs;

    engine::tntwars::DestructibleSegment segment;
    segment.health = 0.0f;
    segment.maxHealth = 250.0f;
    segment.halfExtents = glm::vec3(1.0f);
    std::vector<engine::tntwars::DestructibleSegment> segments{segment};

    engine::tntwars::DestructibleSegmentVisual visual;
    visual.entity = spawnTestDestructibleEntity(ecs, physics, segment.halfExtents);
    physics.detachBody(visual.entity, ecs); // matches the real state a just-destroyed segment would already be in
    if (auto* renderable = ecs.tryGetComponent<engine::core::Renderable>(visual.entity)) renderable->visible = false;
    visual.destroyed = true;
    visual.rebuildTimer = 0.5f;
    std::vector<engine::tntwars::DestructibleSegmentVisual> visuals{visual};

    engine::tntwars::tickDestructibleWallVisual(segments, visuals, ecs, physics, 1.0f); // dt exceeds the remaining timer

    check(!visuals[0].destroyed, "a real segment whose rebuild timer really elapsed is no longer marked destroyed");
    check(nearlyEqual(segments[0].health, 250.0f), "a real rebuild really restores health to real-exactly maxHealth, not a partial value");
    auto* renderable = ecs.tryGetComponent<engine::core::Renderable>(visual.entity);
    check(renderable != nullptr && renderable->visible, "a real rebuild really makes the mesh visible again");
    auto* rigidBody = ecs.tryGetComponent<engine::core::RigidBody>(visual.entity);
    check(rigidBody != nullptr && rigidBody->joltBodyId != engine::core::RigidBody::kInvalidBodyId,
          "a real rebuild really reattaches a live Jolt body -- players collide with it again");
}

void testTickDestructibleWallVisualIgnoresAlreadyAliveSegments() {
    engine::core::Physics physics;
    check(physics.initialize(), "a real Jolt PhysicsSystem initializes for this real test");
    engine::core::ECS ecs;

    engine::tntwars::DestructibleSegment segment;
    segment.health = 80.0f; // real-alive, nothing this tick should touch it
    segment.maxHealth = 100.0f;
    std::vector<engine::tntwars::DestructibleSegment> segments{segment};

    engine::tntwars::DestructibleSegmentVisual visual;
    visual.entity = spawnTestDestructibleEntity(ecs, physics, glm::vec3(1.0f));
    std::vector<engine::tntwars::DestructibleSegmentVisual> visuals{visual};

    engine::tntwars::tickDestructibleWallVisual(segments, visuals, ecs, physics, 1.0f);

    check(!visuals[0].destroyed, "a real, still-alive segment is real-never marked destroyed");
    auto* renderable = ecs.tryGetComponent<engine::core::Renderable>(visual.entity);
    check(renderable != nullptr && renderable->visible, "a real, still-alive segment's mesh stays real-visible");
}

void testTickDestructibleWallVisualHandlesMismatchedVectorSizesSafely() {
    // A real, deliberately-mismatched pair (3 segments, 1 visual) -- this
    // must be a real, honest no-op past the shorter vector's length, not
    // an out-of-bounds access. Regression coverage for exactly the "two
    // parallel vectors could silently drift apart" risk this whole
    // design otherwise avoids by construction.
    engine::core::Physics physics;
    check(physics.initialize(), "a real Jolt PhysicsSystem initializes for this real test");
    engine::core::ECS ecs;

    std::vector<engine::tntwars::DestructibleSegment> segments(3);
    segments[0].health = 0.0f;
    segments[1].health = 0.0f;
    segments[2].health = 0.0f;

    engine::tntwars::DestructibleSegmentVisual visual;
    visual.entity = spawnTestDestructibleEntity(ecs, physics, glm::vec3(1.0f));
    std::vector<engine::tntwars::DestructibleSegmentVisual> visuals{visual}; // only 1, real-shorter than segments

    engine::tntwars::tickDestructibleWallVisual(segments, visuals, ecs, physics, 0.1f);
    check(visuals[0].destroyed, "the one real, shared index still processes normally despite the real size mismatch");
    check(visuals.size() == 1, "a real size mismatch never grows/shrinks the caller's own visuals vector");
}

