void testPlaceTntChargeCapturesOwnerPositionAndFuse() {
    auto charge = engine::tntwars::placeTntCharge(7, glm::vec3(1.0f, 2.0f, 3.0f), 5.0f);
    check(charge.owner == 7, "placeTntCharge() real-records the real placing player as owner");
    check(nearlyEqual(charge.position.x, 1.0f) && nearlyEqual(charge.position.y, 2.0f) && nearlyEqual(charge.position.z, 3.0f),
          "placeTntCharge() real-records the real requested world position");
    check(nearlyEqual(charge.fuseSecondsRemaining, 5.0f), "placeTntCharge() real-starts the real fuse at the real requested duration");
    check(!charge.detonated, "A real freshly-placed charge real-has not detonated yet");
}

void testPlaceTntChargeDefaultsToKDefaultFuseSeconds() {
    auto charge = engine::tntwars::placeTntCharge(1, glm::vec3(0.0f));
    check(nearlyEqual(charge.fuseSecondsRemaining, engine::tntwars::kDefaultFuseSeconds), "placeTntCharge() real-defaults its real fuse to kDefaultFuseSeconds when none is real-given");
}

void testTickTntChargeCountsDownFuseWithoutDetonatingEarly() {
    auto charge = engine::tntwars::placeTntCharge(1, glm::vec3(0.0f), 5.0f);
    engine::tntwars::tickTntCharge(charge, 2.0f);
    check(nearlyEqual(charge.fuseSecondsRemaining, 3.0f), "tickTntCharge() real-counts the real fuse down by real-exactly dt");
    check(!charge.detonated, "The real charge real-has not detonated while real fuse time remains");
}

void testTickTntChargeDetonatesExactlyWhenFuseReachesZero() {
    auto charge = engine::tntwars::placeTntCharge(1, glm::vec3(0.0f), 2.0f);
    engine::tntwars::tickTntCharge(charge, 2.0f);
    check(charge.detonated, "tickTntCharge() real-detonates the real charge the real moment its fuse real-reaches 0");
    check(nearlyEqual(charge.fuseSecondsRemaining, 0.0f), "A real detonated charge's real fuse real-reads exactly 0, never negative");
}

void testTickTntChargeIsNoOpOnceDetonated() {
    auto charge = engine::tntwars::placeTntCharge(1, glm::vec3(0.0f), 1.0f);
    engine::tntwars::tickTntCharge(charge, 5.0f);
    check(charge.detonated, "Sanity: the real charge real-detonated from an real-overshooting tick");
    engine::tntwars::tickTntCharge(charge, 5.0f);
    check(nearlyEqual(charge.fuseSecondsRemaining, 0.0f), "tickTntCharge() real-is a real no-op on an real-already-detonated charge -- fuse real-stays at 0, not real-negative");
}

void testComputeExplosionDamageIsMaxAtCenterAndZeroAtRadius() {
    float atCenter = engine::tntwars::computeExplosionDamage(glm::vec3(0.0f), glm::vec3(0.0f), 10.0f, 100.0f);
    check(nearlyEqual(atCenter, 100.0f), "computeExplosionDamage() real-deals real-full maxDamage at real-zero distance");
    float atRadius = engine::tntwars::computeExplosionDamage(glm::vec3(0.0f), glm::vec3(10.0f, 0.0f, 0.0f), 10.0f, 100.0f);
    check(nearlyEqual(atRadius, 0.0f), "computeExplosionDamage() real-deals real-zero damage real-exactly at the blast radius");
}

void testComputeExplosionDamageFallsOffLinearlyWithDistance() {
    float atHalfRadius = engine::tntwars::computeExplosionDamage(glm::vec3(0.0f), glm::vec3(5.0f, 0.0f, 0.0f), 10.0f, 100.0f);
    check(nearlyEqual(atHalfRadius, 50.0f, 0.01f), "computeExplosionDamage() real-falls off real-linearly -- half the real radius real-deals half the real maxDamage");
}

void testComputeExplosionDamageZeroBeyondRadius() {
    float beyond = engine::tntwars::computeExplosionDamage(glm::vec3(0.0f), glm::vec3(50.0f, 0.0f, 0.0f), 10.0f, 100.0f);
    check(nearlyEqual(beyond, 0.0f), "computeExplosionDamage() real-deals real-zero damage to a real target real-outside the blast radius");
}

void testComputeExplosionImpulseDirectionRadiatesOutwardFromCenter() {
    auto impulse = engine::tntwars::computeExplosionImpulse(glm::vec3(0.0f), glm::vec3(4.0f, 0.0f, 0.0f), 10.0f, 20.0f);
    check(nearlyEqual(impulse.direction.x, 1.0f, 0.01f) && nearlyEqual(impulse.direction.y, 0.0f, 0.01f) && nearlyEqual(impulse.direction.z, 0.0f, 0.01f),
          "computeExplosionImpulse() real-points real-directly away from the real explosion center toward the real target");
}

void testComputeExplosionImpulseFallsBackToUpVectorAtZeroDistance() {
    auto impulse = engine::tntwars::computeExplosionImpulse(glm::vec3(2.0f, 3.0f, 1.0f), glm::vec3(2.0f, 3.0f, 1.0f), 10.0f, 20.0f);
    check(nearlyEqual(impulse.direction.x, 0.0f) && nearlyEqual(impulse.direction.y, 1.0f) && nearlyEqual(impulse.direction.z, 0.0f),
          "computeExplosionImpulse() real-falls back to a real fixed up-vector when the real target sits real-exactly at the explosion center, avoiding a real NaN normalize");
}

void testComputeExplosionImpulseMagnitudeFallsOffWithDistance() {
    auto atCenter = engine::tntwars::computeExplosionImpulse(glm::vec3(0.0f), glm::vec3(0.001f, 0.0f, 0.0f), 10.0f, 20.0f);
    auto atEdge = engine::tntwars::computeExplosionImpulse(glm::vec3(0.0f), glm::vec3(10.0f, 0.0f, 0.0f), 10.0f, 20.0f);
    check(atCenter.magnitude > atEdge.magnitude, "computeExplosionImpulse() real-magnitude real-falls off with distance, real-near-center is real-stronger than real-at-the-edge");
    check(nearlyEqual(atEdge.magnitude, 0.0f), "computeExplosionImpulse() real-magnitude real-reaches 0 real-exactly at the blast radius");
}

void testApplyExplosionToSegmentsDamagesNearSegmentsMoreThanFarSegments() {
    std::vector<engine::tntwars::DestructibleSegment> segments(2);
    segments[0].position = glm::vec3(1.0f, 0.0f, 0.0f);
    segments[0].health = segments[0].maxHealth = 100.0f;
    segments[1].position = glm::vec3(9.0f, 0.0f, 0.0f);
    segments[1].health = segments[1].maxHealth = 100.0f;
    engine::tntwars::applyExplosionToSegments(segments, glm::vec3(0.0f), 10.0f, 100.0f);
    check(segments[0].health < segments[1].health, "applyExplosionToSegments() real-deals real-more damage to the real segment real-closer to the explosion center");
    check(segments[0].health < 100.0f, "The real near segment real-actually took real damage");
}

