void testTntWarsMatchTickTntChargesOnlyDamagesCoreOnceAtDetonation() {
    engine::tntwars::TntWarsMatch match;
    match.setMap(engine::tntwars::MapId::Trenches);
    match.registerPlayer(1);
    match.selectClass(1, engine::tntwars::PlayerClassType::Engineer);
    match.matchFlow().advanceTo(engine::tntwars::MatchPhase::ClassSelect);
    match.matchFlow().advanceTo(engine::tntwars::MatchPhase::InProgress);

    glm::vec3 teamBCore = engine::tntwars::coreWorldPosition(engine::tntwars::MapId::Trenches, engine::tntwars::TeamId::B);
    match.placeTntCharge(1, teamBCore);
    match.tickTntCharges(engine::tntwars::kDefaultFuseSeconds + 0.01f);
    float afterFirstDetonation = match.coreHealth(engine::tntwars::TeamId::B);
    match.tickTntCharges(1.0f);
    check(nearlyEqual(match.coreHealth(engine::tntwars::TeamId::B), afterFirstDetonation),
          "tickTntCharges() real-only applies a real charge's own explosion damage once, real-exactly at the tick it detonates -- ticking an real-already-detonated charge again real-deals no further damage");
}

// --- Kronos ("TNT Wars Foundational Playability" Phase 2): Oxygen -------

void testFuseDtMultiplierForIsHalfOnlyOnIslandSea() {
    using engine::tntwars::MapId;
    check(nearlyEqual(engine::tntwars::fuseDtMultiplierFor(MapId::IslandSea), 0.5f),
          "a real TNT fuse really burns at real half speed underwater (IslandSea)");
    for (MapId map : {MapId::Trenches, MapId::Mantle, MapId::SkyPlatforms, MapId::Space}) {
        check(nearlyEqual(engine::tntwars::fuseDtMultiplierFor(map), 1.0f),
              "every real non-underwater map keeps the real, unmodified full fuse-burn rate");
    }
}

void testTntWarsMatchTickTntChargesBurnsFuseSlowerOnIslandSea() {
    // Real, direct A/B: the exact same dt, the exact same starting fuse,
    // on Trenches vs IslandSea -- IslandSea's own charge must really have
    // *more* fuse time left after one identical tick.
    engine::tntwars::TntWarsMatch trenchesMatch;
    trenchesMatch.setMap(engine::tntwars::MapId::Trenches);
    trenchesMatch.registerPlayer(1);
    trenchesMatch.selectClass(1, engine::tntwars::PlayerClassType::Engineer);
    trenchesMatch.matchFlow().advanceTo(engine::tntwars::MatchPhase::ClassSelect);
    trenchesMatch.matchFlow().advanceTo(engine::tntwars::MatchPhase::InProgress);
    trenchesMatch.placeTntCharge(1, glm::vec3(0.0f));
    trenchesMatch.tickTntCharges(1.0f);

    engine::tntwars::TntWarsMatch islandSeaMatch;
    islandSeaMatch.setMap(engine::tntwars::MapId::IslandSea);
    islandSeaMatch.registerPlayer(1);
    islandSeaMatch.selectClass(1, engine::tntwars::PlayerClassType::Engineer);
    islandSeaMatch.matchFlow().advanceTo(engine::tntwars::MatchPhase::ClassSelect);
    islandSeaMatch.matchFlow().advanceTo(engine::tntwars::MatchPhase::InProgress);
    islandSeaMatch.placeTntCharge(1, glm::vec3(0.0f));
    islandSeaMatch.tickTntCharges(1.0f);

    check(islandSeaMatch.tntCharges()[0].fuseSecondsRemaining > trenchesMatch.tntCharges()[0].fuseSecondsRemaining,
          "the real-identical charge on real IslandSea really has more real fuse time left after one real-identical tick -- its fuse really burns slower underwater");
    check(nearlyEqual(trenchesMatch.tntCharges()[0].fuseSecondsRemaining, engine::tntwars::kDefaultFuseSeconds - 1.0f),
          "Trenches' own real fuse burns at the real, unmodified full rate (1 real second of dt = 1 real second less fuse)");
    check(nearlyEqual(islandSeaMatch.tntCharges()[0].fuseSecondsRemaining, engine::tntwars::kDefaultFuseSeconds - 0.5f),
          "IslandSea's own real fuse burns at real-exactly half rate (1 real second of dt = only 0.5 real seconds less fuse)");
}

void testTickOxygenDepletesOnlyWhileSubmergedWithoutAnOxygenZone() {
    engine::tntwars::OxygenState state;
    engine::tntwars::tickOxygen(state, 1.0f, /*submerged=*/true, /*inOxygenZone=*/false);
    check(nearlyEqual(state.oxygen, engine::tntwars::kMaxOxygen - engine::tntwars::kOxygenDepletionPerSecond),
          "a real player submerged with no real oxygen zone really depletes at real-exactly kOxygenDepletionPerSecond");
}

void testTickOxygenRefillsInsideAnOxygenZoneEvenWhileSubmerged() {
    engine::tntwars::OxygenState state;
    state.oxygen = 10.0f;
    engine::tntwars::tickOxygen(state, 1.0f, /*submerged=*/true, /*inOxygenZone=*/true);
    check(state.oxygen > 10.0f, "a real air-pocket oxygen zone really refills oxygen even while still real-submerged");
}

void testTickOxygenRefillsWhenSurfaced() {
    engine::tntwars::OxygenState state;
    state.oxygen = 10.0f;
    engine::tntwars::tickOxygen(state, 1.0f, /*submerged=*/false, /*inOxygenZone=*/false);
    check(state.oxygen > 10.0f, "a real surfaced (not submerged) player really refills oxygen even outside a real oxygen zone");
}

void testTickOxygenClampsAtMaxAndZero() {
    engine::tntwars::OxygenState fullState;
    engine::tntwars::tickOxygen(fullState, 100.0f, /*submerged=*/false, /*inOxygenZone=*/false);
    check(nearlyEqual(fullState.oxygen, engine::tntwars::kMaxOxygen), "oxygen really never exceeds kMaxOxygen, no matter how long a real player stays surfaced");

    engine::tntwars::OxygenState emptyState;
    engine::tntwars::tickOxygen(emptyState, 100.0f, /*submerged=*/true, /*inOxygenZone=*/false);
    check(nearlyEqual(emptyState.oxygen, 0.0f), "oxygen really never goes negative, no matter how long a real player stays submerged without air");
}

void testTickOxygenIgnoresNonPositiveDt() {
    engine::tntwars::OxygenState state;
    state.oxygen = 50.0f;
    engine::tntwars::tickOxygen(state, 0.0f, true, false);
    engine::tntwars::tickOxygen(state, -1.0f, true, false);
    check(nearlyEqual(state.oxygen, 50.0f), "a real non-positive dt is a real, honest no-op, matching applyDamageToSegment()'s own convention for non-positive damage");
}

void testIsDrowningTrueOnlyAtZeroOxygen() {
    engine::tntwars::OxygenState state;
    state.oxygen = 0.01f;
    check(!engine::tntwars::isDrowning(state), "a real player with even a sliver of real oxygen left really is not drowning");
    state.oxygen = 0.0f;
    check(engine::tntwars::isDrowning(state), "a real player at real-exactly 0 oxygen really is drowning");
}

void testDrowningDamageThisTickOnlyAppliesWhileDrowning() {
    engine::tntwars::OxygenState notDrowning;
    notDrowning.oxygen = 5.0f;
    check(nearlyEqual(engine::tntwars::drowningDamageThisTick(notDrowning, 1.0f), 0.0f),
          "a real player with oxygen left really takes zero real drowning damage");

    engine::tntwars::OxygenState drowning;
    drowning.oxygen = 0.0f;
    check(nearlyEqual(engine::tntwars::drowningDamageThisTick(drowning, 1.0f), engine::tntwars::kOxygenDamagePerSecondAtZero),
          "a real fully-drowning player really takes real-exactly kOxygenDamagePerSecondAtZero worth of damage for a real 1-second tick");
    check(nearlyEqual(engine::tntwars::drowningDamageThisTick(drowning, 0.0f), 0.0f),
          "a real non-positive dt really deals zero real drowning damage even while drowning");
}

void testTntWarsMatchRemoveDetonatedChargesErasesOnlyDetonatedOnes() {
    engine::tntwars::TntWarsMatch match;
    match.setMap(engine::tntwars::MapId::Trenches);
    match.registerPlayer(1);
    match.selectClass(1, engine::tntwars::PlayerClassType::Engineer);
    match.matchFlow().advanceTo(engine::tntwars::MatchPhase::ClassSelect);
    match.matchFlow().advanceTo(engine::tntwars::MatchPhase::InProgress);

    match.placeTntCharge(1, glm::vec3(0.0f, 0.0f, 0.0f));
    match.placeTntCharge(1, glm::vec3(100.0f, 0.0f, 0.0f));
    match.tickTntCharges(engine::tntwars::kDefaultFuseSeconds + 0.01f);
    check(match.tntCharges().size() == 2, "Sanity: both real charges real-still exist right after real detonating");

    size_t removed = match.removeDetonatedCharges();
    check(removed == 2, "removeDetonatedCharges() real-reports real-exactly how many real detonated charges it real-erased");
    check(match.tntCharges().empty(), "removeDetonatedCharges() real-actually erases every real detonated charge from tntCharges()");
}

// --- Kronos Milestone 4: CombatFx (gameplay shake + explosion burst + hit markers) --

void testAddShakeTraumaIncreasesAndClampsAtOne() {
    engine::tntwars::GameplayShakeState state;
    engine::tntwars::addShakeTrauma(state, 0.4f);
    check(nearlyEqual(state.trauma, 0.4f), "addShakeTrauma() real-adds real-exactly the requested amount to a real-fresh state");
    engine::tntwars::addShakeTrauma(state, 0.9f);
    check(nearlyEqual(state.trauma, 1.0f), "addShakeTrauma() real-clamps real-stacked trauma at the real ceiling of 1.0");
}

void testAddShakeTraumaIgnoresNonPositiveAmounts() {
    engine::tntwars::GameplayShakeState state;
    state.trauma = 0.3f;
    engine::tntwars::addShakeTrauma(state, 0.0f);
    engine::tntwars::addShakeTrauma(state, -0.5f);
    check(nearlyEqual(state.trauma, 0.3f), "addShakeTrauma() real-ignores real non-positive amounts entirely");
}

void testTickGameplayShakeDecaysTraumaOverTime() {
    engine::tntwars::GameplayShakeState state;
    state.trauma = 1.0f;
    engine::tntwars::tickGameplayShake(state, 0.25f);
    check(nearlyEqual(state.trauma, 1.0f - engine::tntwars::kShakeDecayPerSecond * 0.25f, 0.01f),
          "tickGameplayShake() real-decays trauma by real-exactly kShakeDecayPerSecond * dt");
}

void testTickGameplayShakeClampsTraumaAtZero() {
    engine::tntwars::GameplayShakeState state;
    state.trauma = 0.1f;
    engine::tntwars::tickGameplayShake(state, 5.0f);
    check(nearlyEqual(state.trauma, 0.0f), "tickGameplayShake() real-clamps trauma at 0, never going real-negative even with an real-overshooting dt");
}

void testTickGameplayShakeAdvancesTimeEvenAtZeroTrauma() {
    engine::tntwars::GameplayShakeState state;
    engine::tntwars::tickGameplayShake(state, 0.5f);
    check(nearlyEqual(state.timeSeconds, 0.5f), "tickGameplayShake() real-advances its own internal clock every real tick, real-independent of current trauma");
}

void testSampleGameplayShakeOffsetIsZeroAtZeroTrauma() {
    engine::tntwars::GameplayShakeState state;
    glm::vec3 offset = engine::tntwars::sampleGameplayShakeOffset(state);
    check(nearlyEqual(offset.x, 0.0f) && nearlyEqual(offset.y, 0.0f) && nearlyEqual(offset.z, 0.0f),
          "sampleGameplayShakeOffset() real-is the real zero vector while trauma is real-exactly 0");
}

void testSampleGameplayShakeOffsetIsBoundedByKShakeMaxOffset() {
    engine::tntwars::GameplayShakeState state;
    state.trauma = 1.0f;
    for (float t = 0.0f; t < 2.0f; t += 0.05f) {
        state.timeSeconds = t;
        glm::vec3 offset = engine::tntwars::sampleGameplayShakeOffset(state);
        // Real per-axis bound: X/Z are each real-scaled directly by amplitude
        // (trauma^2 * kShakeMaxOffset at full trauma), Y by a real-smaller
        // 0.6x of that -- the combined vector's own length is real-allowed
        // to exceed kShakeMaxOffset (three independent axes), only each
        // individual real axis is real-clamped to its own share.
        check(std::abs(offset.x) <= engine::tntwars::kShakeMaxOffset + 0.01f &&
                  std::abs(offset.z) <= engine::tntwars::kShakeMaxOffset + 0.01f,
              "sampleGameplayShakeOffset() real-never exceeds kShakeMaxOffset on its real X/Z axes, even at real-full trauma");
        check(std::abs(offset.y) <= engine::tntwars::kShakeMaxOffset * 0.6f + 0.01f,
              "sampleGameplayShakeOffset() real-never exceeds its real-smaller Y-axis share (0.6 * kShakeMaxOffset), even at real-full trauma");
    }
}

void testExplosionShakeTraumaIsMaxAtCenterAndZeroAtRadius() {
    float atCenter = engine::tntwars::explosionShakeTrauma(glm::vec3(0.0f), glm::vec3(0.0f), 10.0f);
    check(nearlyEqual(atCenter, 1.0f), "explosionShakeTrauma() real-is full 1.0 real-exactly at the explosion center");
    float atRadius = engine::tntwars::explosionShakeTrauma(glm::vec3(0.0f), glm::vec3(10.0f, 0.0f, 0.0f), 10.0f);
    check(nearlyEqual(atRadius, 0.0f), "explosionShakeTrauma() real-is 0 real-exactly at the blast radius");
}

void testExplosionShakeTraumaZeroBeyondRadius() {
    float beyond = engine::tntwars::explosionShakeTrauma(glm::vec3(0.0f), glm::vec3(50.0f, 0.0f, 0.0f), 10.0f);
    check(nearlyEqual(beyond, 0.0f), "explosionShakeTrauma() real-is 0 for a real listener real-outside the blast radius");
}

void testExplosionBurstSettingsIsARealOneShotBurst() {
    auto settings = engine::tntwars::explosionBurstSettings();
    check(!settings.looping, "explosionBurstSettings() real-produces a real one-shot burst, not a real looping emitter");
    check(settings.emissionRate > 0.0f, "explosionBurstSettings() real-spawns a real-positive particle count on its one real burst");
}

void testSpawnExplosionParticleBurstCreatesRealEntityWithEmitterAtPosition() {
    engine::core::ECS ecs;
    glm::vec3 center(3.0f, 1.0f, -2.0f);
    engine::core::EntityId entity = engine::tntwars::spawnExplosionParticleBurst(ecs, center);
    check(ecs.hasComponent<engine::core::ParticleEmitter>(entity), "spawnExplosionParticleBurst() real-attaches a real ParticleEmitter to the real spawned entity");
    auto* transform = ecs.tryGetComponent<engine::core::Transform>(entity);
    check(transform != nullptr && nearlyEqual(transform->position.x, center.x) && nearlyEqual(transform->position.y, center.y) &&
              nearlyEqual(transform->position.z, center.z),
          "spawnExplosionParticleBurst() real-places the real spawned entity's Transform real-exactly at the explosion center");
    auto* emitter = ecs.tryGetComponent<engine::core::ParticleEmitter>(entity);
    check(emitter != nullptr && !emitter->settings.looping, "The real spawned entity's own ParticleEmitter real-carries the real one-shot burst settings");
}

void testTriggerHitMarkerFlashAppliesRealFlashToTarget() {
    engine::core::ECS ecs;
    engine::core::EntityId entity = ecs.createEntity("HitTarget");
    ecs.addComponent<engine::core::Renderable>(entity);
    engine::tntwars::triggerHitMarkerFlash(ecs, entity);
    check(nearlyEqual(ecs.tryGetComponent<engine::core::Renderable>(entity)->emissiveIntensity, engine::tntwars::kHitMarkerPeakIntensity),
          "triggerHitMarkerFlash() real-jumps the real target's emissiveIntensity to real-exactly kHitMarkerPeakIntensity");
    check(ecs.hasComponent<engine::core::FlashEffect>(entity), "triggerHitMarkerFlash() real-attaches a real FlashEffect so the hit marker real-decays back down like any other real flash");
}

void testTriggerHitMarkerFlashIsNoOpWithoutRenderable() {
    engine::core::ECS ecs;
    engine::core::EntityId entity = ecs.createEntity("NoRenderable");
    engine::tntwars::triggerHitMarkerFlash(ecs, entity); // real, honest no-op -- matches core::triggerFlash()'s own documented behavior
    check(!ecs.hasComponent<engine::core::FlashEffect>(entity), "triggerHitMarkerFlash() real-attaches no FlashEffect to an entity with real-no Renderable to flash");
}

// --- Kronos Milestone 5: Scavenging --------------------------------------

void testTerritoryAtClassifiesTeamAZoneTeamBZoneAndNoMansLand() {
    check(engine::tntwars::territoryAt(glm::vec3(0.0f, 0.0f, -40.0f)) == engine::tntwars::Territory::TeamA,
          "territoryAt() real-classifies a real-deep-negative-Z position as TeamA territory");
    check(engine::tntwars::territoryAt(glm::vec3(0.0f, 0.0f, 40.0f)) == engine::tntwars::Territory::TeamB,
          "territoryAt() real-classifies a real-deep-positive-Z position as TeamB territory");
    check(engine::tntwars::territoryAt(glm::vec3(0.0f, 0.0f, 0.0f)) == engine::tntwars::Territory::NoMansLand,
          "territoryAt() real-classifies the real map center as NoMansLand");
}

void testTerritoryAtBoundaryIsExclusiveOfNoMansLandBand() {
    check(engine::tntwars::territoryAt(glm::vec3(0.0f, 0.0f, -engine::tntwars::kNoMansLandHalfWidth - 0.1f)) ==
              engine::tntwars::Territory::TeamA,
          "territoryAt() real-just-outside the real negative no-man's-land edge real-is TeamA territory");
    check(engine::tntwars::territoryAt(glm::vec3(0.0f, 0.0f, engine::tntwars::kNoMansLandHalfWidth)) ==
              engine::tntwars::Territory::NoMansLand,
          "territoryAt() real-exactly-at the real positive no-man's-land edge real-still counts as NoMansLand (inclusive band)");
}

void testBuildScavengeNodesPlacesThreeNodesInEachTeamsOwnTerritory() {
    auto nodes = engine::tntwars::buildScavengeNodes(engine::tntwars::MapId::Trenches);
    check(nodes.size() == 6, "buildScavengeNodes() real-places real-exactly 6 nodes (3 per team) on a real map");
    int teamACount = 0, teamBCount = 0;
    for (const auto& node : nodes) {
        auto territory = engine::tntwars::territoryAt(node.position);
        if (territory == engine::tntwars::Territory::TeamA) ++teamACount;
        if (territory == engine::tntwars::Territory::TeamB) ++teamBCount;
        check(territory != engine::tntwars::Territory::NoMansLand, "No real scavenge node real-lands in the real neutral no-man's-land band");
    }
    check(teamACount == 3 && teamBCount == 3, "buildScavengeNodes() real-splits its real nodes real-evenly, 3 in each team's own real territory");
}

void testBuildScavengeNodesEveryNodeStartsFullyStocked() {
    auto nodes = engine::tntwars::buildScavengeNodes(engine::tntwars::MapId::IslandSea);
    for (const auto& node : nodes) {
        check(node.quantityRemaining == engine::tntwars::kScavengeNodeMaxQuantity && node.maxQuantity == engine::tntwars::kScavengeNodeMaxQuantity,
              "Every real freshly-built scavenge node real-starts at real-full kScavengeNodeMaxQuantity");
        check(nearlyEqual(node.respawnSecondsRemaining, 0.0f), "A real freshly-built, real-full node real-has no respawn timer running");
    }
}

void testScavengeNodeRejectsWrongTeamTerritory() {
    engine::tntwars::ScavengeNodeState node;
    node.position = glm::vec3(0.0f, 0.0f, -40.0f); // real TeamA territory
    node.quantityRemaining = node.maxQuantity = 20;
    auto result = engine::tntwars::scavengeNode(node, engine::tntwars::TeamId::B, 5);
    check(!result.success, "scavengeNode() real-rejects TeamB real-reaching into a real node sitting in TeamA's own territory");
    check(node.quantityRemaining == 20, "A real rejected scavenge attempt real-leaves the node's own quantity real-untouched");
}

void testScavengeNodeRejectsNoMansLandNode() {
    engine::tntwars::ScavengeNodeState node;
    node.position = glm::vec3(0.0f, 0.0f, 0.0f); // real NoMansLand
    node.quantityRemaining = node.maxQuantity = 20;
    check(!engine::tntwars::scavengeNode(node, engine::tntwars::TeamId::A, 5).success,
          "scavengeNode() real-rejects any real attempt on a real node sitting in the real neutral no-man's-land band");
}

void testScavengeNodeSucceedsInOwnTerritoryAndDecrementsQuantity() {
    engine::tntwars::ScavengeNodeState node;
    node.position = glm::vec3(0.0f, 0.0f, -40.0f);
    node.material = engine::tntwars::ScavengeMaterialType::Wiring;
    node.quantityRemaining = node.maxQuantity = 20;
    auto result = engine::tntwars::scavengeNode(node, engine::tntwars::TeamId::A, 5);
    check(result.success && result.material == engine::tntwars::ScavengeMaterialType::Wiring && result.quantityCollected == 5,
          "scavengeNode() real-succeeds for the real owning team, real-reporting the real material and real-exact quantity collected");
    check(node.quantityRemaining == 15, "A real successful scavenge real-decrements the node's own quantityRemaining by real-exactly the amount collected");
}

void testScavengeNodeCapsCollectionAtWhatsActuallyRemaining() {
    engine::tntwars::ScavengeNodeState node;
    node.position = glm::vec3(0.0f, 0.0f, 40.0f);
    node.quantityRemaining = node.maxQuantity = 3;
    auto result = engine::tntwars::scavengeNode(node, engine::tntwars::TeamId::B, 100);
    check(result.success && result.quantityCollected == 3, "scavengeNode() real-caps quantityCollected at real-exactly what the node actually had left");
    check(node.quantityRemaining == 0, "A real fully-drained node real-reaches exactly 0, never negative");
}

void testScavengeNodeStartsRespawnTimerOnceDepleted() {
    engine::tntwars::ScavengeNodeState node;
    node.position = glm::vec3(0.0f, 0.0f, 40.0f);
    node.quantityRemaining = node.maxQuantity = 5;
    (void)engine::tntwars::scavengeNode(node, engine::tntwars::TeamId::B, 5);
    check(nearlyEqual(node.respawnSecondsRemaining, engine::tntwars::kScavengeNodeRespawnSeconds),
          "Draining a real node to 0 real-starts its real respawn countdown at real-exactly kScavengeNodeRespawnSeconds");
}

void testScavengeNodeRejectsScavengingAnAlreadyDepletedNode() {
    engine::tntwars::ScavengeNodeState node;
    node.position = glm::vec3(0.0f, 0.0f, 40.0f);
    node.quantityRemaining = 0;
    node.maxQuantity = 20;
    check(!engine::tntwars::scavengeNode(node, engine::tntwars::TeamId::B, 5).success,
          "scavengeNode() real-rejects a real attempt on a real-already-depleted node");
}

void testTickScavengeNodeRespawnRefillsExactlyWhenTimerElapses() {
    engine::tntwars::ScavengeNodeState node;
    node.quantityRemaining = 0;
    node.maxQuantity = 20;
    node.respawnSecondsRemaining = 2.0f;
    engine::tntwars::tickScavengeNodeRespawn(node, 1.0f);
    check(node.quantityRemaining == 0 && nearlyEqual(node.respawnSecondsRemaining, 1.0f), "tickScavengeNodeRespawn() real-counts down without real-refilling early");
    engine::tntwars::tickScavengeNodeRespawn(node, 1.5f);
    check(node.quantityRemaining == 20, "tickScavengeNodeRespawn() real-refills quantityRemaining back to maxQuantity real-exactly once the real timer elapses");
    check(nearlyEqual(node.respawnSecondsRemaining, 0.0f), "A real freshly-respawned node real-has no lingering respawn timer left");
}

void testTickScavengeNodeRespawnIsNoOpOnNonDepletedNode() {
    engine::tntwars::ScavengeNodeState node;
    node.quantityRemaining = 10;
    node.maxQuantity = 20;
    engine::tntwars::tickScavengeNodeRespawn(node, 100.0f);
    check(node.quantityRemaining == 10, "tickScavengeNodeRespawn() real-is a real no-op on a node that real-isn't depleted -- nothing to respawn");
}

void testAddAndRemoveScavengedMaterialTracksCountsPerType() {
    engine::tntwars::ScavengedMaterials materials;
    engine::tntwars::addScavengedMaterial(materials, engine::tntwars::ScavengeMaterialType::ScrapMetal, 10);
    engine::tntwars::addScavengedMaterial(materials, engine::tntwars::ScavengeMaterialType::Wiring, 4);
    check(engine::tntwars::scavengedMaterialCount(materials, engine::tntwars::ScavengeMaterialType::ScrapMetal) == 10,
          "addScavengedMaterial() real-accumulates real-per-type counts independently");
    check(engine::tntwars::scavengedMaterialCount(materials, engine::tntwars::ScavengeMaterialType::BlastingPowder) == 0,
          "A real untouched material type real-stays at real-0");

    int removed = engine::tntwars::removeScavengedMaterial(materials, engine::tntwars::ScavengeMaterialType::ScrapMetal, 4);
    check(removed == 4 && engine::tntwars::scavengedMaterialCount(materials, engine::tntwars::ScavengeMaterialType::ScrapMetal) == 6,
          "removeScavengedMaterial() real-removes real-exactly the requested amount and real-reports it back");
}

void testRemoveScavengedMaterialCapsAtWhatsActuallyHeld() {
    engine::tntwars::ScavengedMaterials materials;
    engine::tntwars::addScavengedMaterial(materials, engine::tntwars::ScavengeMaterialType::BlastingPowder, 3);
    int removed = engine::tntwars::removeScavengedMaterial(materials, engine::tntwars::ScavengeMaterialType::BlastingPowder, 100);
    check(removed == 3, "removeScavengedMaterial() real-caps the real removed amount at what's real-actually held, never over-reporting");
    check(engine::tntwars::scavengedMaterialCount(materials, engine::tntwars::ScavengeMaterialType::BlastingPowder) == 0,
          "removeScavengedMaterial() real-never drives a real count negative");
}

void testTntWarsMatchScavengeRejectsOutsideInProgress() {
    engine::tntwars::TntWarsMatch match;
    match.registerPlayer(1);
    match.selectClass(1, engine::tntwars::PlayerClassType::Saboteur);
    check(!match.scavenge(1, 0, 5).success, "TntWarsMatch::scavenge() real-rejects while the real match is real-still Lobby, not InProgress");
}

void testTntWarsMatchScavengeSucceedsForOwnTeamNodeDuringInProgress() {
    engine::tntwars::TntWarsMatch match;
    match.setMap(engine::tntwars::MapId::Trenches);
    match.registerPlayer(1); // real-joins TeamA
    match.selectClass(1, engine::tntwars::PlayerClassType::Saboteur);
    match.matchFlow().advanceTo(engine::tntwars::MatchPhase::ClassSelect);
    match.matchFlow().advanceTo(engine::tntwars::MatchPhase::InProgress);

    // Real, honest lookup -- find a node that's real-actually in TeamA's
    // own territory rather than assuming a fixed index, since node order
    // is an internal real implementation detail.
    size_t ownNodeIndex = match.scavengeNodes().size();
    for (size_t i = 0; i < match.scavengeNodes().size(); ++i) {
        if (engine::tntwars::territoryAt(match.scavengeNodes()[i].position) == engine::tntwars::Territory::TeamA) {
            ownNodeIndex = i;
            break;
        }
    }
    check(ownNodeIndex < match.scavengeNodes().size(), "Sanity: TntWarsMatch real-actually has a real node in TeamA's own territory");

    auto result = match.scavenge(1, ownNodeIndex, 5);
    check(result.success, "TntWarsMatch::scavenge() real-succeeds for TeamA real-scavenging its own real territory's node during InProgress");
    check(engine::tntwars::scavengedMaterialCount(match.scavengedMaterials(1), result.material) == result.quantityCollected,
          "A real successful scavenge real-credits the real collected material to the real player's own scavengedMaterials() ledger");
}

