void testExplosiveRecipeInfoStandardChargeIsStrictlyWeakerThanMegaCharge() {
    const auto& standard = engine::tntwars::explosiveRecipeInfo(engine::tntwars::ExplosiveRecipeType::StandardCharge);
    const auto& mega = engine::tntwars::explosiveRecipeInfo(engine::tntwars::ExplosiveRecipeType::MegaCharge);
    check(mega.explosionRadius > standard.explosionRadius, "MegaCharge real-has a real-bigger blast radius than StandardCharge");
    check(mega.explosionMaxDamage > standard.explosionMaxDamage, "MegaCharge real-deals real-more max damage than StandardCharge");
    check(mega.explosionMaxImpulse > standard.explosionMaxImpulse, "MegaCharge real-has a real-stronger explosion impulse than StandardCharge");
}

void testExplosiveRecipeInfoEachRecipeIsStrictlyStrongerThanTheBasicCharge() {
    const auto& standard = engine::tntwars::explosiveRecipeInfo(engine::tntwars::ExplosiveRecipeType::StandardCharge);
    check(standard.explosionRadius > engine::tntwars::kExplosionRadius, "A real crafted StandardCharge real-out-ranges the always-available basic charge");
    check(standard.explosionMaxDamage > engine::tntwars::kExplosionMaxDamage, "A real crafted StandardCharge real-out-damages the always-available basic charge");
}

