void testTntWarsMatchCraftFailsWithoutMaterialsThenSucceedsAfterScavenging() {
    engine::tntwars::TntWarsMatch match;
    match.setMap(engine::tntwars::MapId::Trenches);
    match.registerPlayer(1); // real-joins TeamA
    match.selectClass(1, engine::tntwars::PlayerClassType::Engineer);
    match.matchFlow().advanceTo(engine::tntwars::MatchPhase::ClassSelect);
    match.matchFlow().advanceTo(engine::tntwars::MatchPhase::InProgress);

    check(!match.craft(1, engine::tntwars::ExplosiveRecipeType::StandardCharge), "TntWarsMatch::craft() real-fails for a real player carrying real-no scavenged materials yet");

    // Real-scavenge every real TeamA node until there's real-enough of
    // both ingredients (each node holds 20 units of one real material).
    for (size_t i = 0; i < match.scavengeNodes().size(); ++i) {
        if (engine::tntwars::territoryAt(match.scavengeNodes()[i].position) == engine::tntwars::Territory::TeamA) {
            match.scavenge(1, i, engine::tntwars::kScavengeNodeMaxQuantity);
        }
    }
    check(match.craft(1, engine::tntwars::ExplosiveRecipeType::StandardCharge),
          "TntWarsMatch::craft() real-succeeds once the real player has real-actually scavenged enough materials");
    check(match.craftedExplosives(1).counts[static_cast<size_t>(engine::tntwars::ExplosiveRecipeType::StandardCharge)] == 1,
          "A real successful craft() real-credits the real player's own craftedExplosives() ledger");
}

