void testTntWarsMatchRemoveResolvedMissilesErasesOnlyResolvedOnes() {
    engine::tntwars::TntWarsMatch match;
    match.registerPlayer(1); // TeamA
    match.registerPlayer(2); // TeamB
    match.selectClass(1, engine::tntwars::PlayerClassType::Striker);
    match.selectClass(2, engine::tntwars::PlayerClassType::Interceptor);
    match.matchFlow().advanceTo(engine::tntwars::MatchPhase::ClassSelect);
    match.matchFlow().advanceTo(engine::tntwars::MatchPhase::InProgress);

    match.launchMissileAt(1, engine::tntwars::TeamId::B);
    match.launchMissileAt(1, engine::tntwars::TeamId::B);
    check(match.interceptMissile(2, 0), "Sanity: real-intercepting missile 0 real-succeeds");
    match.tickMissiles(engine::tntwars::kMissileFlightSeconds + 0.1f); // real-impacts missile 1
    check(match.missiles().size() == 2, "Sanity: both real missiles real-still exist right after real-resolving");

    size_t removed = match.removeResolvedMissiles();
    check(removed == 2, "removeResolvedMissiles() real-reports real-exactly how many real resolved missiles it real-erased");
    check(match.missiles().empty(), "removeResolvedMissiles() real-actually erases every real resolved missile from missiles()");
}

