void testBuildJumpPadsPlacesTwoSymmetricRealPads() {
    auto pads = engine::tntwars::buildJumpPads(engine::tntwars::MapId::Trenches);
    check(pads.size() == 2, "buildJumpPads() real-places real-exactly 2 pads");
    check(nearlyEqual(pads[0].position.x, -pads[1].position.x, 0.01f), "The real two pads real-sit symmetrically opposite each other on the X axis");
}

void testIsWithinJumpPadRadiusTrueInsideFalseOutside() {
    engine::tntwars::JumpPadState pad;
    pad.position = glm::vec3(0.0f);
    pad.triggerRadius = 3.0f;
    check(engine::tntwars::isWithinJumpPadRadius(glm::vec3(1.0f, 0.0f, 0.0f), pad), "isWithinJumpPadRadius() real-is true real-inside the trigger radius");
    check(!engine::tntwars::isWithinJumpPadRadius(glm::vec3(10.0f, 0.0f, 0.0f), pad), "isWithinJumpPadRadius() real-is false real-outside the trigger radius");
}

void testTriggerJumpPadSucceedsInsideRadiusAndReturnsUpwardOffset() {
    engine::tntwars::JumpPadState pad;
    pad.position = glm::vec3(0.0f);
    pad.triggerRadius = 3.0f;
    pad.launchStrength = 14.0f;
    auto offset = engine::tntwars::triggerJumpPad(pad, glm::vec3(1.0f, 0.0f, 0.0f));
    check(offset.has_value(), "triggerJumpPad() real-succeeds for a real player standing real-inside the pad's radius");
    check(nearlyEqual(offset->y, 14.0f) && nearlyEqual(offset->x, 0.0f) && nearlyEqual(offset->z, 0.0f),
          "triggerJumpPad() real-returns a real, purely-vertical launch offset real-matching launchStrength");
}

void testTriggerJumpPadFailsOutsideRadius() {
    engine::tntwars::JumpPadState pad;
    pad.position = glm::vec3(0.0f);
    pad.triggerRadius = 3.0f;
    check(!engine::tntwars::triggerJumpPad(pad, glm::vec3(50.0f, 0.0f, 0.0f)).has_value(),
          "triggerJumpPad() real-fails for a real player real-outside the pad's radius");
}

void testTriggerJumpPadStartsCooldownAndRejectsRepeatedTrigger() {
    engine::tntwars::JumpPadState pad;
    pad.position = glm::vec3(0.0f);
    pad.triggerRadius = 3.0f;
    check(engine::tntwars::triggerJumpPad(pad, glm::vec3(0.0f)).has_value(), "Sanity: the real first trigger real-succeeds");
    check(nearlyEqual(pad.cooldownSecondsRemaining, engine::tntwars::kJumpPadCooldownSeconds), "A real successful trigger real-starts the pad's own real cooldown");
    check(!engine::tntwars::triggerJumpPad(pad, glm::vec3(0.0f)).has_value(),
          "A real second real-immediate trigger real-fails while the pad is real-still on cooldown");
}

void testTickJumpPadCountsDownCooldownThenAllowsRetrigger() {
    engine::tntwars::JumpPadState pad;
    pad.position = glm::vec3(0.0f);
    pad.triggerRadius = 3.0f;
    pad.cooldownSecondsRemaining = engine::tntwars::kJumpPadCooldownSeconds;
    engine::tntwars::tickJumpPad(pad, engine::tntwars::kJumpPadCooldownSeconds + 0.1f);
    check(nearlyEqual(pad.cooldownSecondsRemaining, 0.0f), "tickJumpPad() real-counts the cooldown real-down to exactly 0, never negative");
    check(engine::tntwars::triggerJumpPad(pad, glm::vec3(0.0f)).has_value(), "Once the real cooldown real-elapses, the real pad real-triggers again");
}

// --- Kronos ("Sky Map Full Engine Specification"): real zip-lines ------

void testDistanceToZipLineSegmentIsZeroOnTheLineItself() {
    glm::vec3 start(0.0f, 0.0f, 0.0f);
    glm::vec3 end(10.0f, 0.0f, 0.0f);
    float d = engine::tntwars::distanceToZipLineSegment(glm::vec3(5.0f, 0.0f, 0.0f), start, end);
    check(nearlyEqual(d, 0.0f), "distanceToZipLineSegment() is really 0 for a point really sitting on the segment");
}

void testDistanceToZipLineSegmentClampsToNearestEndpoint() {
    glm::vec3 start(0.0f, 0.0f, 0.0f);
    glm::vec3 end(10.0f, 0.0f, 0.0f);
    // A real point "behind" the segment's own start should really
    // measure distance to `start`, not project past it onto the
    // infinite line.
    float d = engine::tntwars::distanceToZipLineSegment(glm::vec3(-3.0f, 0.0f, 0.0f), start, end);
    check(nearlyEqual(d, 3.0f), "distanceToZipLineSegment() really clamps to the nearest real endpoint, not the infinite line");
}

void testDistanceToZipLineSegmentPerpendicularDistance() {
    glm::vec3 start(0.0f, 0.0f, 0.0f);
    glm::vec3 end(10.0f, 0.0f, 0.0f);
    float d = engine::tntwars::distanceToZipLineSegment(glm::vec3(5.0f, 0.0f, 4.0f), start, end);
    check(nearlyEqual(d, 4.0f), "distanceToZipLineSegment() really measures the real perpendicular distance to a point abreast of the segment's own middle");
}

void testComputeZipLineVelocityNulloptOutsideRadius() {
    engine::tntwars::ZipLineState zip;
    zip.start = glm::vec3(0.0f, 0.0f, 0.0f);
    zip.end = glm::vec3(20.0f, 0.0f, 0.0f);
    zip.controlPoint = (zip.start + zip.end) * 0.5f; // real straight-line-equivalent curve
    zip.triggerRadius = 3.0f;
    check(!engine::tntwars::computeZipLineVelocity(zip, glm::vec3(5.0f, 0.0f, 10.0f)).has_value(),
          "computeZipLineVelocity() really returns nullopt for a real player far outside the zip-line's own trigger radius");
}

void testComputeZipLineVelocityPointsFromStartToEndAtTravelSpeed() {
    engine::tntwars::ZipLineState zip;
    zip.start = glm::vec3(0.0f, 0.0f, 0.0f);
    zip.end = glm::vec3(20.0f, 0.0f, 0.0f);
    zip.controlPoint = (zip.start + zip.end) * 0.5f;
    zip.triggerRadius = 3.0f;
    zip.travelSpeed = 22.0f;
    // Real, near-start probe -- bidirectional riding (see this
    // function's own header comment) means direction depends on which
    // real endpoint is closer, so this test real-picks a point closer to
    // `start` to exercise the real "ride toward end" direction.
    auto velocity = engine::tntwars::computeZipLineVelocity(zip, glm::vec3(5.0f, 0.0f, 1.0f));
    check(velocity.has_value(), "computeZipLineVelocity() really returns a real velocity for a real player within the trigger radius");
    check(nearlyEqual(velocity->x, 22.0f, 0.05f) && nearlyEqual(velocity->y, 0.0f, 0.05f) && nearlyEqual(velocity->z, 0.0f, 0.05f),
          "computeZipLineVelocity() really points real-exactly from start toward end, magnitude real-equal to travelSpeed, when ridden from the start side");
}

void testComputeZipLineVelocityIsBidirectional() {
    // Kronos ("Sky Map Full Engine Specification" Section 5,
    // "bidirectional zip-lines"): a real player near `end` really rides
    // back toward `start` -- the exact real opposite direction of the
    // "ridden from start" case above, using the real *same* ZipLineState.
    engine::tntwars::ZipLineState zip;
    zip.start = glm::vec3(0.0f, 0.0f, 0.0f);
    zip.end = glm::vec3(20.0f, 0.0f, 0.0f);
    zip.controlPoint = (zip.start + zip.end) * 0.5f;
    zip.triggerRadius = 3.0f;
    zip.travelSpeed = 22.0f;
    auto velocity = engine::tntwars::computeZipLineVelocity(zip, glm::vec3(15.0f, 0.0f, 1.0f));
    check(velocity.has_value(), "computeZipLineVelocity() really returns a real velocity for a real player near the end side");
    check(velocity->x < 0.0f, "computeZipLineVelocity() really rides back toward start (real-negative X) for a real player closer to end");
    check(nearlyEqual(glm::length(*velocity), 22.0f, 0.05f), "The real return-ride velocity's own magnitude still real-equals travelSpeed");
}

void testSampleZipLineCurveEndpointsMatchStartAndEnd() {
    engine::tntwars::ZipLineState zip;
    zip.start = glm::vec3(0.0f, 0.0f, 0.0f);
    zip.end = glm::vec3(20.0f, 0.0f, 0.0f);
    zip.controlPoint = glm::vec3(10.0f, 8.0f, 0.0f); // real, raised control point -- an arc over an obstacle
    check(nearlyEqual(glm::length(engine::tntwars::sampleZipLineCurve(zip, 0.0f) - zip.start), 0.0f),
          "sampleZipLineCurve() at t=0 is really exactly the curve's own start point");
    check(nearlyEqual(glm::length(engine::tntwars::sampleZipLineCurve(zip, 1.0f) - zip.end), 0.0f),
          "sampleZipLineCurve() at t=1 is really exactly the curve's own end point");
}

void testSampleZipLineCurveArcsAboveTheStraightChordAtItsMidpoint() {
    // Real, direct proof the real curve arcs *above* obstacle geometry
    // between start/end rather than clipping straight through it -- the
    // real midpoint of a raised-control-point curve sits real-higher
    // than the straight-line chord's own midpoint.
    engine::tntwars::ZipLineState zip;
    zip.start = glm::vec3(0.0f, 0.0f, 0.0f);
    zip.end = glm::vec3(20.0f, 0.0f, 0.0f);
    zip.controlPoint = glm::vec3(10.0f, 8.0f, 0.0f);
    glm::vec3 curveMid = engine::tntwars::sampleZipLineCurve(zip, 0.5f);
    float straightChordMidY = (zip.start.y + zip.end.y) * 0.5f;
    check(curveMid.y > straightChordMidY, "sampleZipLineCurve() at t=0.5 really sits above the real straight chord when controlPoint is raised -- the real obstacle-avoidance arc");
}

void testDistanceToZipLineCurveIsZeroOnTheCurveItself() {
    engine::tntwars::ZipLineState zip;
    zip.start = glm::vec3(0.0f, 0.0f, 0.0f);
    zip.end = glm::vec3(20.0f, 0.0f, 0.0f);
    zip.controlPoint = glm::vec3(10.0f, 5.0f, 0.0f);
    glm::vec3 pointOnCurve = engine::tntwars::sampleZipLineCurve(zip, 0.5f);
    float d = engine::tntwars::distanceToZipLineCurve(zip, pointOnCurve);
    check(d < 0.01f, "distanceToZipLineCurve() is really (near-)0 for a point really sampled from the curve itself");
}

void testComputeZipLineVelocityNulloptForZeroLengthLine() {
    engine::tntwars::ZipLineState zip;
    zip.start = glm::vec3(5.0f, 0.0f, 5.0f);
    zip.end = glm::vec3(5.0f, 0.0f, 5.0f);
    zip.controlPoint = glm::vec3(5.0f, 0.0f, 5.0f);
    zip.triggerRadius = 3.0f;
    check(!engine::tntwars::computeZipLineVelocity(zip, glm::vec3(5.0f, 0.0f, 5.0f)).has_value(),
          "computeZipLineVelocity() really returns nullopt (an honest no-op) for a real, degenerate zero-length line");
}

// --- Kronos (zip-line arc-length traversal fix) -------------------------

void testBuildZipLineArcLengthTableStraightLineMatchesChordLength() {
    engine::tntwars::ZipLineState zip;
    zip.start = glm::vec3(0.0f, 0.0f, 0.0f);
    zip.end = glm::vec3(20.0f, 0.0f, 0.0f);
    zip.controlPoint = (zip.start + zip.end) * 0.5f; // real, exact straight line -- see ZipLineState's own header comment
    auto table = engine::tntwars::buildZipLineArcLengthTable(zip);
    check(nearlyEqual(table.totalLength, 20.0f),
          "buildZipLineArcLengthTable() really measures a real straight zip-line's own total length as real-exactly the chord length");
}

void testBuildZipLineArcLengthTableCurvedLineIsLongerThanChord() {
    engine::tntwars::ZipLineState zip;
    zip.start = glm::vec3(0.0f, 0.0f, 0.0f);
    zip.end = glm::vec3(20.0f, 0.0f, 0.0f);
    zip.controlPoint = glm::vec3(10.0f, 8.0f, 0.0f); // real, raised arc
    auto table = engine::tntwars::buildZipLineArcLengthTable(zip);
    check(table.totalLength > 20.0f,
          "buildZipLineArcLengthTable() really measures a real curved zip-line's own total length as real-longer than the straight chord");
}

void testZipLineDistanceToTBoundaries() {
    engine::tntwars::ZipLineState zip;
    zip.start = glm::vec3(0.0f, 0.0f, 0.0f);
    zip.end = glm::vec3(20.0f, 0.0f, 0.0f);
    zip.controlPoint = glm::vec3(10.0f, 6.0f, 0.0f);
    auto table = engine::tntwars::buildZipLineArcLengthTable(zip);
    check(nearlyEqual(engine::tntwars::zipLineDistanceToT(table, 0.0f), 0.0f),
          "zipLineDistanceToT() really returns t=0 real-exactly at distance=0");
    check(nearlyEqual(engine::tntwars::zipLineDistanceToT(table, table.totalLength), 1.0f),
          "zipLineDistanceToT() really returns t=1 real-exactly at distance=totalLength");
    check(nearlyEqual(engine::tntwars::zipLineDistanceToT(table, table.totalLength + 50.0f), 1.0f),
          "zipLineDistanceToT() really clamps a real distance beyond totalLength to t=1, not undefined behavior");
}

void testZipLineTToDistanceIsApproxInverseOfDistanceToT() {
    engine::tntwars::ZipLineState zip;
    zip.start = glm::vec3(0.0f, 0.0f, 0.0f);
    zip.end = glm::vec3(20.0f, 0.0f, 0.0f);
    zip.controlPoint = glm::vec3(10.0f, 6.0f, 0.0f);
    auto table = engine::tntwars::buildZipLineArcLengthTable(zip);
    float distance = table.totalLength * 0.35f;
    float t = engine::tntwars::zipLineDistanceToT(table, distance);
    float roundTrip = engine::tntwars::zipLineTToDistance(table, t);
    check(std::abs(roundTrip - distance) < 0.05f,
          "zipLineTToDistance(zipLineDistanceToT(d)) really round-trips back to real-approximately the original distance");
}

void testAdvanceZipLineRiderFollowsTheRealCurveNotTheChord() {
    // Real, live-reported bug this test directly guards against: a rider
    // advancing via straight chord interpolation would sit real-exactly
    // on the line between start and end -- a rider advancing via the
    // real fix (arc-length parameterization along the actual Bezier)
    // should sit real-above that chord partway through the ride, matching
    // the curve's own real raised controlPoint.
    engine::tntwars::ZipLineState zip;
    zip.start = glm::vec3(0.0f, 0.0f, 0.0f);
    zip.end = glm::vec3(20.0f, 0.0f, 0.0f);
    zip.controlPoint = glm::vec3(10.0f, 8.0f, 0.0f);
    zip.travelSpeed = 10.0f;
    auto table = engine::tntwars::buildZipLineArcLengthTable(zip);
    engine::tntwars::ZipLineRiderState rider;
    rider.direction = 1.0f;

    // Advance roughly to the curve's own real midpoint.
    float halfwayDt = (table.totalLength * 0.5f) / zip.travelSpeed;
    auto position = engine::tntwars::advanceZipLineRider(zip, table, rider, halfwayDt);
    check(position.has_value(), "advanceZipLineRider() really returns a real position for a real, non-degenerate curve");

    float chordMidY = 0.0f; // real straight-chord Y at the midpoint (start.y == end.y == 0 here)
    check(position->y - engine::tntwars::kZipLineVerticalClearance > chordMidY + 1.0f,
          "advanceZipLineRider() really rides real-above the straight chord partway through -- following the actual curve, not the chord");
}

void testAdvanceZipLineRiderReachesTheEndAfterFullDuration() {
    engine::tntwars::ZipLineState zip;
    zip.start = glm::vec3(0.0f, 0.0f, 0.0f);
    zip.end = glm::vec3(20.0f, 0.0f, 0.0f);
    zip.controlPoint = glm::vec3(10.0f, 4.0f, 0.0f);
    zip.travelSpeed = 10.0f;
    auto table = engine::tntwars::buildZipLineArcLengthTable(zip);
    engine::tntwars::ZipLineRiderState rider;
    rider.direction = 1.0f;

    float fullDt = (table.totalLength / zip.travelSpeed) + 1.0f; // real, deliberately overshoots -- must real-clamp, not overshoot the table
    auto position = engine::tntwars::advanceZipLineRider(zip, table, rider, fullDt);
    check(position.has_value(), "advanceZipLineRider() really returns a real position even when the tick overshoots the ride's own end");
    check(nearlyEqual(rider.distanceTraveled, table.totalLength),
          "advanceZipLineRider() really clamps distanceTraveled to real-exactly totalLength rather than overshooting past the real end");
    glm::vec3 expectedEnd = zip.end + glm::vec3(0.0f, engine::tntwars::kZipLineVerticalClearance, 0.0f);
    check(glm::length(*position - expectedEnd) < 0.01f,
          "advanceZipLineRider() really places the rider real-exactly at the curve's own end (+ vertical clearance) once the ride completes");
}

void testAdvanceZipLineRiderBackwardDirectionRidesTowardStart() {
    engine::tntwars::ZipLineState zip;
    zip.start = glm::vec3(0.0f, 0.0f, 0.0f);
    zip.end = glm::vec3(20.0f, 0.0f, 0.0f);
    zip.controlPoint = glm::vec3(10.0f, 4.0f, 0.0f);
    zip.travelSpeed = 10.0f;
    auto table = engine::tntwars::buildZipLineArcLengthTable(zip);
    engine::tntwars::ZipLineRiderState rider;
    rider.distanceTraveled = table.totalLength; // real, starts at the far end
    rider.direction = -1.0f;                    // real, riding back toward start

    auto position = engine::tntwars::advanceZipLineRider(zip, table, rider, 0.5f);
    check(position.has_value(), "advanceZipLineRider() really returns a real position when riding real-backward");
    check(rider.distanceTraveled < table.totalLength,
          "advanceZipLineRider() really decreases distanceTraveled for a real, negative-direction rider");
}

void testAdvanceZipLineRiderNulloptForDegenerateZeroLengthCurve() {
    engine::tntwars::ZipLineState zip;
    zip.start = glm::vec3(5.0f, 0.0f, 5.0f);
    zip.end = glm::vec3(5.0f, 0.0f, 5.0f);
    zip.controlPoint = glm::vec3(5.0f, 0.0f, 5.0f);
    zip.travelSpeed = 10.0f;
    auto table = engine::tntwars::buildZipLineArcLengthTable(zip);
    engine::tntwars::ZipLineRiderState rider;
    check(!engine::tntwars::advanceZipLineRider(zip, table, rider, 0.5f).has_value(),
          "advanceZipLineRider() really returns nullopt (an honest no-op) for a real, degenerate zero-length curve");
}

// Kronos ("Gameplay Loop" world-building): real TraversalChallenge tests.
void testTickChallengeCheckpointNoChangeOutsideRadius() {
    auto challenge = engine::tntwars::buildZipLineRaceChallenge(
        "Test Race", {glm::vec3(0.0f), glm::vec3(10.0f, 0.0f, 0.0f)});
    auto result = engine::tntwars::tickChallengeCheckpoint(challenge, glm::vec3(50.0f, 0.0f, 0.0f));
    check(result == engine::tntwars::ChallengeTickResult::NoChange,
          "tickChallengeCheckpoint() really no-ops when the player is nowhere near the next checkpoint");
    check(!challenge.running, "tickChallengeCheckpoint() really leaves a challenge un-started when far from checkpoint 0");
}

void testTickChallengeCheckpointStartsOnFirstCheckpoint() {
    auto challenge = engine::tntwars::buildZipLineRaceChallenge(
        "Test Race", {glm::vec3(0.0f), glm::vec3(10.0f, 0.0f, 0.0f)});
    auto result = engine::tntwars::tickChallengeCheckpoint(challenge, glm::vec3(0.0f));
    check(result == engine::tntwars::ChallengeTickResult::Started,
          "tickChallengeCheckpoint() really returns Started when the player first reaches checkpoint 0");
    check(challenge.running, "tickChallengeCheckpoint() really marks the challenge running once started");
    check(challenge.nextCheckpointIndex == 1, "tickChallengeCheckpoint() really advances to checkpoint 1 immediately after starting");
    check(nearlyEqual(challenge.elapsedSeconds, 0.0f), "tickChallengeCheckpoint() really resets elapsedSeconds to 0 on start");
}

void testTickChallengeCheckpointOutOfOrderIsNoChange() {
    auto challenge = engine::tntwars::buildZipLineRaceChallenge(
        "Test Race", {glm::vec3(0.0f), glm::vec3(10.0f, 0.0f, 0.0f), glm::vec3(20.0f, 0.0f, 0.0f)});
    (void)engine::tntwars::tickChallengeCheckpoint(challenge, glm::vec3(0.0f)); // real start
    auto result = engine::tntwars::tickChallengeCheckpoint(challenge, glm::vec3(20.0f, 0.0f, 0.0f)); // real, skips checkpoint 1
    check(result == engine::tntwars::ChallengeTickResult::NoChange,
          "tickChallengeCheckpoint() really refuses to skip ahead to a later checkpoint out of order");
    check(challenge.nextCheckpointIndex == 1, "tickChallengeCheckpoint() really leaves nextCheckpointIndex unchanged after a rejected out-of-order reach");
}

void testTickChallengeCheckpointCompletesAndRecordsBestTime() {
    auto challenge = engine::tntwars::buildZipLineRaceChallenge(
        "Test Race", {glm::vec3(0.0f), glm::vec3(10.0f, 0.0f, 0.0f)});
    (void)engine::tntwars::tickChallengeCheckpoint(challenge, glm::vec3(0.0f));
    engine::tntwars::tickChallengeClock(challenge, 12.5f);
    auto result = engine::tntwars::tickChallengeCheckpoint(challenge, glm::vec3(10.0f, 0.0f, 0.0f));
    check(result == engine::tntwars::ChallengeTickResult::Completed,
          "tickChallengeCheckpoint() really returns Completed when the final checkpoint is reached");
    check(!challenge.running, "tickChallengeCheckpoint() really stops the clock on completion");
    check(nearlyEqual(challenge.bestTimeSeconds, 12.5f), "tickChallengeCheckpoint() really records the real elapsed time as the best time");
    check(challenge.nextCheckpointIndex == 0, "tickChallengeCheckpoint() really resets to checkpoint 0 so the course can be re-run");
}

void testTickChallengeCheckpointKeepsFasterBestTime() {
    auto challenge = engine::tntwars::buildZipLineRaceChallenge(
        "Test Race", {glm::vec3(0.0f), glm::vec3(10.0f, 0.0f, 0.0f)});
    challenge.bestTimeSeconds = 5.0f; // real, pre-existing fast time
    (void)engine::tntwars::tickChallengeCheckpoint(challenge, glm::vec3(0.0f));
    engine::tntwars::tickChallengeClock(challenge, 20.0f); // real, deliberately slower run
    (void)engine::tntwars::tickChallengeCheckpoint(challenge, glm::vec3(10.0f, 0.0f, 0.0f));
    check(nearlyEqual(challenge.bestTimeSeconds, 5.0f),
          "tickChallengeCheckpoint() really keeps the real pre-existing faster best time over a real slower run");
}

void testTickChallengeClockIsNoOpWhileNotRunning() {
    auto challenge = engine::tntwars::buildJumpPadRouteChallenge("Test Route", {glm::vec3(0.0f), glm::vec3(5.0f, 0.0f, 0.0f)});
    engine::tntwars::tickChallengeClock(challenge, 3.0f);
    check(nearlyEqual(challenge.elapsedSeconds, 0.0f),
          "tickChallengeClock() really leaves elapsedSeconds untouched while the challenge isn't running");
}

// Kronos ("Gameplay Loop" world-building, "Progression"): real
// TntWarsUpgrades tests.
void testPurchaseUpgradeRejectsWhenUnaffordable() {
    engine::tntwars::PlayerUpgrades upgrades;
    engine::tntwars::ScavengedMaterials materials; // real, empty -- can afford nothing
    auto result = engine::tntwars::purchaseUpgrade(upgrades, materials, engine::tntwars::UpgradeCategory::Traversal);
    check(!result.success, "purchaseUpgrade() really rejects a purchase the player can't afford");
    check(upgrades.traversalTier == 0, "purchaseUpgrade() really leaves the tier unchanged on a rejected purchase");
}

void testPurchaseUpgradeDeductsExactCostAndAdvancesTier() {
    engine::tntwars::PlayerUpgrades upgrades;
    engine::tntwars::ScavengedMaterials materials;
    auto cost = engine::tntwars::upgradeCost(engine::tntwars::UpgradeCategory::Suit, 0);
    for (size_t i = 0; i < engine::tntwars::kScavengeMaterialTypeCount; ++i) materials.counts[i] = cost.counts[i];

    auto result = engine::tntwars::purchaseUpgrade(upgrades, materials, engine::tntwars::UpgradeCategory::Suit);
    check(result.success, "purchaseUpgrade() really succeeds when the player can exactly afford the next tier");
    check(result.newTier == 1, "purchaseUpgrade() really reports the real new tier (1) on success");
    check(upgrades.suitTier == 1, "purchaseUpgrade() really advances the real suitTier field");
    for (size_t i = 0; i < engine::tntwars::kScavengeMaterialTypeCount; ++i) {
        check(materials.counts[i] == 0, "purchaseUpgrade() really deducts the real exact cost, leaving zero remainder");
    }
}

void testPurchaseUpgradeNoPartialSpendOnRejectedPurchase() {
    engine::tntwars::PlayerUpgrades upgrades;
    engine::tntwars::ScavengedMaterials materials;
    auto cost = engine::tntwars::upgradeCost(engine::tntwars::UpgradeCategory::Traversal, 0);
    materials.counts[0] = cost.counts[0]; // real, affords only the first of 3 real currencies

    auto result = engine::tntwars::purchaseUpgrade(upgrades, materials, engine::tntwars::UpgradeCategory::Traversal);
    check(!result.success, "purchaseUpgrade() really rejects when even one real required currency is short");
    check(materials.counts[0] == cost.counts[0],
          "purchaseUpgrade() really spends nothing at all on a rejected purchase, not even the affordable currencies");
}

void testPurchaseUpgradeRejectsPastMaxTier() {
    engine::tntwars::PlayerUpgrades upgrades;
    upgrades.suitTier = engine::tntwars::kMaxUpgradeTier;
    engine::tntwars::ScavengedMaterials materials{{9999, 9999, 9999}}; // real, can obviously afford anything
    auto result = engine::tntwars::purchaseUpgrade(upgrades, materials, engine::tntwars::UpgradeCategory::Suit);
    check(!result.success, "purchaseUpgrade() really rejects once a category is already at kMaxUpgradeTier, no matter how affordable");
}

void testMultipliersAreOneAtTierZero() {
    check(nearlyEqual(engine::tntwars::traversalSpeedMultiplier(0), 1.0f),
          "traversalSpeedMultiplier() really returns real-exactly 1.0 at tier 0 (the map's own untouched tuning)");
    check(nearlyEqual(engine::tntwars::suitMoveSpeedMultiplier(0), 1.0f),
          "suitMoveSpeedMultiplier() really returns real-exactly 1.0 at tier 0");
}

void testMultipliersIncreaseWithTier() {
    check(engine::tntwars::traversalSpeedMultiplier(3) > engine::tntwars::traversalSpeedMultiplier(1),
          "traversalSpeedMultiplier() really increases at a real higher tier");
    check(engine::tntwars::suitMoveSpeedMultiplier(3) > engine::tntwars::suitMoveSpeedMultiplier(1),
          "suitMoveSpeedMultiplier() really increases at a real higher tier");
}

// Kronos ("Lighting Polish" world-building): real AtmosphereZones tests.
void testSampleAtmosphereZonesReturnsDefaultWhenEmpty() {
    engine::tntwars::AtmosphereSample defaultSample;
    defaultSample.fogColor = glm::vec3(0.1f, 0.2f, 0.3f);
    defaultSample.fogDensity = 0.005f;
    defaultSample.exposure = 1.0f;
    auto sample = engine::tntwars::sampleAtmosphereZones({}, glm::vec3(0.0f), defaultSample);
    check(sample.fogColor == defaultSample.fogColor,
          "sampleAtmosphereZones() really returns the real, unchanged default fogColor with no zones at all");
    check(nearlyEqual(sample.exposure, defaultSample.exposure),
          "sampleAtmosphereZones() really returns the real, unchanged default exposure with no zones at all");
}

void testSampleAtmosphereZonesFullyInsideZoneUsesZoneValues() {
    engine::tntwars::AtmosphereZone zone;
    zone.position = glm::vec3(10.0f, 0.0f, 0.0f);
    zone.radius = 20.0f;
    zone.fogColor = glm::vec3(0.9f, 0.5f, 0.2f);
    zone.exposure = 1.3f;
    engine::tntwars::AtmosphereSample defaultSample;
    defaultSample.fogColor = glm::vec3(0.0f);
    defaultSample.exposure = 1.0f;

    // real, well inside the zone's own real inner core (radius*0.7)
    auto sample = engine::tntwars::sampleAtmosphereZones({zone}, zone.position, defaultSample);
    check(glm::length(sample.fogColor - zone.fogColor) < 0.001f,
          "sampleAtmosphereZones() really returns real-exactly the zone's own fogColor at its own center");
    check(nearlyEqual(sample.exposure, zone.exposure),
          "sampleAtmosphereZones() really returns real-exactly the zone's own exposure at its own center");
}

void testSampleAtmosphereZonesOutsideRadiusIsUnaffected() {
    engine::tntwars::AtmosphereZone zone;
    zone.position = glm::vec3(0.0f);
    zone.radius = 10.0f;
    zone.exposure = 2.0f;
    engine::tntwars::AtmosphereSample defaultSample;
    defaultSample.exposure = 1.0f;

    auto sample = engine::tntwars::sampleAtmosphereZones({zone}, glm::vec3(100.0f, 0.0f, 0.0f), defaultSample);
    check(nearlyEqual(sample.exposure, defaultSample.exposure),
          "sampleAtmosphereZones() really leaves the default fully unaffected well outside every zone's own radius");
}

void testSampleAtmosphereZonesSoftEdgeIsPartialBlend() {
    engine::tntwars::AtmosphereZone zone;
    zone.position = glm::vec3(0.0f);
    zone.radius = 10.0f;
    zone.exposure = 2.0f;
    engine::tntwars::AtmosphereSample defaultSample;
    defaultSample.exposure = 1.0f;

    // real, halfway across the real soft-edge band (inner=7, outer=10)
    auto sample = engine::tntwars::sampleAtmosphereZones({zone}, glm::vec3(8.5f, 0.0f, 0.0f), defaultSample);
    check(sample.exposure > defaultSample.exposure && sample.exposure < zone.exposure,
          "sampleAtmosphereZones() really produces a real, honest partial blend inside the soft-edge band, not a hard on/off snap");
}

void testSampleAtmosphereZonesStrongestZoneWinsOverlap() {
    engine::tntwars::AtmosphereZone weak;
    weak.position = glm::vec3(0.0f);
    weak.radius = 31.0f; // real -- distance 30 sits in this zone's own real outer soft-edge band, a real low weight
    weak.exposure = 1.5f;
    engine::tntwars::AtmosphereZone strong;
    strong.position = glm::vec3(30.0f, 0.0f, 0.0f);
    strong.radius = 10.0f;
    strong.exposure = 3.0f;
    engine::tntwars::AtmosphereSample defaultSample;
    defaultSample.exposure = 1.0f;

    // real, dead-center of `strong`, real-well inside `weak`'s own radius too
    auto sample = engine::tntwars::sampleAtmosphereZones({weak, strong}, strong.position, defaultSample);
    check(nearlyEqual(sample.exposure, strong.exposure),
          "sampleAtmosphereZones() really lets the real highest-weight zone win outright over a real, weaker overlapping zone");
}

// Kronos ("Lighting Polish" world-building, "station flicker panels"):
// real FlickerLight tests.
void testFlickerIntensityFactorIsDeterministic() {
    float a = engine::tntwars::flickerIntensityFactor(3.5f, 12.25f);
    float b = engine::tntwars::flickerIntensityFactor(3.5f, 12.25f);
    check(nearlyEqual(a, b), "flickerIntensityFactor() really returns the real, identical value for identical inputs (no hidden clock/state)");
}

void testFlickerIntensityFactorStaysInPlausibleRange() {
    bool allInRange = true;
    for (float t = 0.0f; t < 40.0f; t += 0.37f) {
        float factor = engine::tntwars::flickerIntensityFactor(1.7f, t);
        if (factor < 0.0f || factor > 1.2f) allInRange = false;
    }
    check(allInRange, "flickerIntensityFactor() really stays within a real, plausible 0..1.2 range across many real sampled times");
}

void testFlickerIntensityFactorDiffersAcrossPhase() {
    float a = engine::tntwars::flickerIntensityFactor(0.0f, 5.0f);
    float b = engine::tntwars::flickerIntensityFactor(9.0f, 5.0f);
    check(!nearlyEqual(a, b), "flickerIntensityFactor() really produces a real, different value for a real different phase at the same time (panels don't sync)");
}

// Kronos ("Space Map Bible" v1.0, Section III "Traversal Systems"): real
// SpaceTraversal tests.
void testTriggerBoosterPadNulloptOutsideRadius() {
    engine::tntwars::BoosterPadState pad;
    pad.position = glm::vec3(0.0f);
    pad.triggerRadius = 3.0f;
    auto launch = engine::tntwars::triggerBoosterPad(pad, glm::vec3(50.0f, 0.0f, 0.0f));
    check(!launch.has_value(), "triggerBoosterPad() really returns nullopt when the player is outside the trigger radius");
}

void testTriggerBoosterPadLaunchesAlongItsRealDirection() {
    engine::tntwars::BoosterPadState pad;
    pad.position = glm::vec3(0.0f);
    pad.direction = glm::vec3(1.0f, 0.0f, 0.0f);
    pad.triggerRadius = 3.0f;
    pad.launchStrength = 10.0f;
    auto launch = engine::tntwars::triggerBoosterPad(pad, glm::vec3(1.0f, 0.0f, 0.0f));
    check(launch.has_value(), "triggerBoosterPad() really succeeds when the player is inside the trigger radius");
    check(nearlyEqual(launch->x, 10.0f) && nearlyEqual(launch->y, 0.0f) && nearlyEqual(launch->z, 0.0f),
          "triggerBoosterPad() really returns direction*launchStrength as the real launch vector");
    check(pad.cooldownSecondsRemaining > 0.0f, "triggerBoosterPad() really starts the real cooldown on success");
}

void testTriggerBoosterPadRejectsWhileOnCooldown() {
    engine::tntwars::BoosterPadState pad;
    pad.position = glm::vec3(0.0f);
    pad.triggerRadius = 3.0f;
    pad.cooldownSecondsRemaining = 1.0f;
    auto launch = engine::tntwars::triggerBoosterPad(pad, glm::vec3(0.0f));
    check(!launch.has_value(), "triggerBoosterPad() really rejects a real, still-cooling-down pad even at point-blank range");
}

void testZeroGravityCompensationIsZeroOutsideZone() {
    engine::tntwars::ZeroGravityZone zone;
    zone.position = glm::vec3(0.0f);
    zone.radius = 10.0f;
    glm::vec3 comp = engine::tntwars::zeroGravityCompensation(zone, glm::vec3(100.0f, 0.0f, 0.0f),
                                                                 glm::vec3(0.0f, -9.8f, 0.0f), 0.1f);
    check(nearlyEqual(glm::length(comp), 0.0f), "zeroGravityCompensation() really returns a real zero vector outside the zone");
}

void testZeroGravityCompensationCountersGravityInsideZone() {
    engine::tntwars::ZeroGravityZone zone;
    zone.position = glm::vec3(0.0f);
    zone.radius = 10.0f;
    zone.gravityCancelFraction = 1.0f;
    glm::vec3 gravity(0.0f, -9.8f, 0.0f);
    glm::vec3 comp = engine::tntwars::zeroGravityCompensation(zone, zone.position, gravity, 0.1f);
    check(comp.y > 0.0f, "zeroGravityCompensation() really points real-upward (opposite gravity) inside the zone");
    check(nearlyEqual(comp.y, 0.98f), "zeroGravityCompensation() really scales real-exactly by cancelFraction*dt at fraction=1.0");
}

void testGravityWellPullIsZeroOutsideRadius() {
    engine::tntwars::GravityWellState well;
    well.position = glm::vec3(0.0f);
    well.radius = 10.0f;
    well.maxAccel = 5.0f;
    glm::vec3 pull = engine::tntwars::gravityWellPull(well, glm::vec3(50.0f, 0.0f, 0.0f), 0.1f);
    check(nearlyEqual(glm::length(pull), 0.0f), "gravityWellPull() really returns a real zero vector outside the well's own radius");
}

void testGravityWellPullPointsTowardCenter() {
    engine::tntwars::GravityWellState well;
    well.position = glm::vec3(0.0f);
    well.radius = 10.0f;
    well.maxAccel = 5.0f;
    glm::vec3 pull = engine::tntwars::gravityWellPull(well, glm::vec3(5.0f, 0.0f, 0.0f), 0.1f);
    check(pull.x < 0.0f, "gravityWellPull() really pulls real-toward the well's own center, not away from it");
}

void testGravityWellPullFallsOffWithDistance() {
    engine::tntwars::GravityWellState well;
    well.position = glm::vec3(0.0f);
    well.radius = 10.0f;
    well.maxAccel = 5.0f;
    glm::vec3 pullNear = engine::tntwars::gravityWellPull(well, glm::vec3(1.0f, 0.0f, 0.0f), 0.1f);
    glm::vec3 pullFar = engine::tntwars::gravityWellPull(well, glm::vec3(9.0f, 0.0f, 0.0f), 0.1f);
    check(glm::length(pullNear) > glm::length(pullFar),
          "gravityWellPull() really produces a real, stronger pull closer to the well's own center than near its outer edge");
}

// Kronos ("Space Map Bible" v1.0 Section VI, "PvP Orbital Conflict"):
// real PvPNode tests.
void testTickPvPNodeCaptureContestedMakesNoProgress() {
    engine::tntwars::PvPNodeState node;
    engine::tntwars::tickPvPNodeCapture(node, true, true, 5.0f);
    check(nearlyEqual(node.captureProgress, 0.0f), "tickPvPNodeCapture() really makes no progress while both teams are present (contested)");
    check(!node.controllingTeam.has_value(), "tickPvPNodeCapture() really leaves a contested node real-uncontrolled");
}

void testTickPvPNodeCaptureAccruesForSoleTeam() {
    engine::tntwars::PvPNodeState node;
    engine::tntwars::tickPvPNodeCapture(node, true, false, 3.0f);
    check(node.captureProgress > 0.0f, "tickPvPNodeCapture() really accrues progress for the one real team present alone");
    check(node.capturingTeam.has_value() && *node.capturingTeam == engine::tntwars::TeamId::A,
          "tickPvPNodeCapture() really sets capturingTeam to the real, sole present team");
}

void testTickPvPNodeCaptureFlipsControlAtFullProgress() {
    engine::tntwars::PvPNodeState node;
    engine::tntwars::tickPvPNodeCapture(node, true, false, engine::tntwars::kPvPNodeCaptureSeconds + 1.0f);
    check(node.controllingTeam.has_value() && *node.controllingTeam == engine::tntwars::TeamId::A,
          "tickPvPNodeCapture() really flips real control to TeamA once capture progress reaches its own real full duration");
    check(node.captureProgress <= 1.0f, "tickPvPNodeCapture() really caps captureProgress at real 1.0, never overshooting");
}

void testTickPvPNodeCaptureSwitchingTeamsRestartsProgress() {
    engine::tntwars::PvPNodeState node;
    engine::tntwars::tickPvPNodeCapture(node, true, false, 6.0f); // real, halfway through TeamA's own capture
    float halfwayProgress = node.captureProgress;
    check(halfwayProgress > 0.0f, "test setup sanity: TeamA really made real progress first");
    engine::tntwars::tickPvPNodeCapture(node, false, true, 0.5f); // real, TeamB now walks on alone
    check(node.capturingTeam.has_value() && *node.capturingTeam == engine::tntwars::TeamId::B,
          "tickPvPNodeCapture() really switches capturingTeam when a different real team takes sole presence");
    check(node.captureProgress < halfwayProgress,
          "tickPvPNodeCapture() really restarts progress from a real 0 rather than continuing the previous team's own progress");
}

void testTickPvPNodeCaptureUncontestedEmptyHoldsProgress() {
    engine::tntwars::PvPNodeState node;
    engine::tntwars::tickPvPNodeCapture(node, true, false, 3.0f);
    float progressBefore = node.captureProgress;
    engine::tntwars::tickPvPNodeCapture(node, false, false, 5.0f);
    check(nearlyEqual(node.captureProgress, progressBefore),
          "tickPvPNodeCapture() really holds progress unchanged (no decay) while neither team is present");
}

// Kronos ("Explosives System" world-building): real Grenade/
// ExplosiveBarrel tests.
void testThrowGrenadeNormalizesDirectionAndSetsFuse() {
    auto grenade = engine::tntwars::throwGrenade(1, glm::vec3(0.0f), glm::vec3(2.0f, 0.0f, 0.0f), 10.0f, 3.0f);
    check(nearlyEqual(glm::length(grenade.velocity), 10.0f),
          "throwGrenade() really normalizes the real throw direction before scaling by throwSpeed");
    check(nearlyEqual(grenade.fuseSecondsRemaining, 3.0f), "throwGrenade() really sets the real requested fuse duration");
    check(!grenade.detonated, "throwGrenade() really starts un-detonated");
}

void testThrowGrenadeFallsBackToUpwardForZeroDirection() {
    auto grenade = engine::tntwars::throwGrenade(1, glm::vec3(0.0f), glm::vec3(0.0f), 5.0f);
    check(grenade.velocity.y > 0.0f, "throwGrenade() really falls back to a real upward toss for a real zero-length direction");
}

void testTickGrenadeTrajectoryAppliesGravity() {
    engine::tntwars::GrenadeState grenade;
    grenade.position = glm::vec3(0.0f);
    grenade.velocity = glm::vec3(5.0f, 5.0f, 0.0f);
    engine::tntwars::tickGrenadeTrajectory(grenade, glm::vec3(0.0f, -9.8f, 0.0f), 0.5f);
    check(nearlyEqual(grenade.velocity.y, 5.0f - 4.9f), "tickGrenadeTrajectory() really integrates real gravity into vertical velocity");
    check(grenade.position.x > 0.0f && grenade.position.y > 0.0f, "tickGrenadeTrajectory() really advances real position from real velocity");
}

void testTickGrenadeTrajectoryNoOpAfterDetonation() {
    engine::tntwars::GrenadeState grenade;
    grenade.detonated = true;
    glm::vec3 posBefore = grenade.position = glm::vec3(3.0f, 4.0f, 5.0f);
    engine::tntwars::tickGrenadeTrajectory(grenade, glm::vec3(0.0f, -9.8f, 0.0f), 0.5f);
    check(grenade.position == posBefore, "tickGrenadeTrajectory() really no-ops once a grenade has already detonated");
}

void testTickGrenadeFuseDetonatesExactlyAtZero() {
    engine::tntwars::GrenadeState grenade;
    grenade.fuseSecondsRemaining = 1.0f;
    engine::tntwars::tickGrenadeFuse(grenade, 0.6f);
    check(!grenade.detonated, "tickGrenadeFuse() really hasn't detonated yet with real fuse time still remaining");
    engine::tntwars::tickGrenadeFuse(grenade, 0.6f);
    check(grenade.detonated, "tickGrenadeFuse() really detonates the exact real tick fuseSecondsRemaining reaches 0");
    check(nearlyEqual(grenade.fuseSecondsRemaining, 0.0f), "tickGrenadeFuse() really clamps fuseSecondsRemaining at real 0, not negative");
}

void testTickExplosiveBarrelDetonationFalseWhileAlive() {
    auto barrel = engine::tntwars::buildExplosiveBarrel(glm::vec3(0.0f));
    check(!engine::tntwars::tickExplosiveBarrelDetonation(barrel),
          "tickExplosiveBarrelDetonation() really returns false while the real barrel's own segment is still alive");
}

void testTickExplosiveBarrelDetonationTrueExactlyOnceOnDestruction() {
    auto barrel = engine::tntwars::buildExplosiveBarrel(glm::vec3(0.0f));
    engine::tntwars::applyDamageToSegment(barrel.segment, barrel.segment.maxHealth * 2.0f);
    check(engine::tntwars::tickExplosiveBarrelDetonation(barrel),
          "tickExplosiveBarrelDetonation() really returns true the real first tick its segment reaches 0 health");
    check(!engine::tntwars::tickExplosiveBarrelDetonation(barrel),
          "tickExplosiveBarrelDetonation() really returns false on every real subsequent tick (fires exactly once)");
}

