void testTntWarsMatchEffectiveMoveSpeedForReflectsActiveBoost() {
    engine::tntwars::TntWarsMatch match;
    match.registerPlayer(1);
    match.selectClass(1, engine::tntwars::PlayerClassType::Striker);
    match.matchFlow().advanceTo(engine::tntwars::MatchPhase::ClassSelect);
    match.matchFlow().advanceTo(engine::tntwars::MatchPhase::InProgress);

    float baseSpeed = match.classTuning().statsFor(engine::tntwars::PlayerClassType::Striker).moveSpeed;
    check(nearlyEqual(match.effectiveMoveSpeedFor(1), baseSpeed), "Without an real-active boost, effectiveMoveSpeedFor() real-equals the real player's own base class moveSpeed");

    check(match.applySpeedBoostTo(1, 2.0f, 5.0f), "applySpeedBoostTo() real-succeeds during real InProgress for a real class-selected, alive player");
    check(nearlyEqual(match.effectiveMoveSpeedFor(1), baseSpeed * 2.0f), "With a real 2x boost active, effectiveMoveSpeedFor() real-doubles the real base moveSpeed");

    match.tickSpeedBoosts(5.1f);
    check(nearlyEqual(match.effectiveMoveSpeedFor(1), baseSpeed), "Once the real boost real-expires via tickSpeedBoosts(), effectiveMoveSpeedFor() real-returns to the real base moveSpeed");
}

