void testStandingThrusterCountStartsAtSixAndDecreasesPerCollapse() {
    engine::tntwars::SkyPlatformState state;
    check(engine::tntwars::standingThrusterCount(state) == 6, "A real freshly-built SkyPlatformState real-starts with all 6 thrusters standing");
    for (int i = 0; i < engine::tntwars::ThrusterPlatformState::kMaxHits; ++i) {
        engine::tntwars::applyThrusterHit(state.thrusters[0]);
    }
    check(state.thrusters[0].collapsed, "Sanity: 5 real hits real-collapses one real thruster (see ThrusterHp.hpp)");
    check(engine::tntwars::standingThrusterCount(state) == 5, "standingThrusterCount() real-drops by real-exactly one once a real thruster collapses");
}

void testIsSkyPlatformCollapsedOnlyOnceAllSixThrustersCollapse() {
    engine::tntwars::SkyPlatformState state;
    for (size_t t = 0; t < engine::tntwars::kThrustersPerTeam - 1; ++t) {
        for (int i = 0; i < engine::tntwars::ThrusterPlatformState::kMaxHits; ++i) engine::tntwars::applyThrusterHit(state.thrusters[t]);
    }
    check(!engine::tntwars::isSkyPlatformCollapsed(state), "isSkyPlatformCollapsed() real-is false while even one real thruster real-still stands");
    for (int i = 0; i < engine::tntwars::ThrusterPlatformState::kMaxHits; ++i) {
        engine::tntwars::applyThrusterHit(state.thrusters[engine::tntwars::kThrustersPerTeam - 1]);
    }
    check(engine::tntwars::isSkyPlatformCollapsed(state), "isSkyPlatformCollapsed() real-is true real-exactly once all 6 real thrusters real-collapse");
}

