void testBuildSpaceIsMuchLargerScaleThanTrenches() {
    auto spacePieces = engine::tntwars::buildMapLayout(engine::tntwars::MapId::Space);
    auto trenchesPieces = engine::tntwars::buildMapLayout(engine::tntwars::MapId::Trenches);
    const engine::tntwars::MapLayoutPiece* spaceBaseA = nullptr;
    const engine::tntwars::MapLayoutPiece* trenchesBaseA = nullptr;
    for (const auto& p : spacePieces) if (p.name == "TeamA_Base") spaceBaseA = &p;
    for (const auto& p : trenchesPieces) if (p.name == "TeamA_Base") trenchesBaseA = &p;
    check(spaceBaseA != nullptr && trenchesBaseA != nullptr, "Sanity: both real maps real-have a TeamA_Base");
    if (spaceBaseA && trenchesBaseA) {
        check(std::abs(spaceBaseA->position.z) > std::abs(trenchesBaseA->position.z),
              "Space's real team bases real-sit much farther apart than Trenches' own, matching the brief's real \"much larger map\"");
    }
}

