void testCraftExplosiveAdvancedChargeRequiresMoreOfEveryMaterialThanMegaCharge() {
    engine::tntwars::ScavengedMaterials materials;
    // Real-exactly enough for MegaCharge, but real-not enough for AdvancedCharge.
    engine::tntwars::addScavengedMaterial(materials, engine::tntwars::ScavengeMaterialType::ScrapMetal, 6);
    engine::tntwars::addScavengedMaterial(materials, engine::tntwars::ScavengeMaterialType::BlastingPowder, 4);
    engine::tntwars::addScavengedMaterial(materials, engine::tntwars::ScavengeMaterialType::Wiring, 3);
    check(engine::tntwars::canAffordRecipe(materials, engine::tntwars::ExplosiveRecipeType::MegaCharge),
          "Sanity: this real material stockpile real-affords MegaCharge");
    check(!engine::tntwars::canAffordRecipe(materials, engine::tntwars::ExplosiveRecipeType::AdvancedCharge),
          "The real same stockpile real-does NOT afford AdvancedCharge -- it real-costs strictly more of every real material");
}

void testTntWarsMatchTriggerJumpPadAmplifiesLaunchUnderZeroGravity() {
    engine::tntwars::TntWarsMatch matchSpace;
    matchSpace.setMap(engine::tntwars::MapId::Space);
    matchSpace.registerPlayer(1);
    matchSpace.selectClass(1, engine::tntwars::PlayerClassType::Striker);
    matchSpace.matchFlow().advanceTo(engine::tntwars::MatchPhase::ClassSelect);
    matchSpace.matchFlow().advanceTo(engine::tntwars::MatchPhase::InProgress);

    engine::tntwars::TntWarsMatch matchTrenches;
    matchTrenches.registerPlayer(1);
    matchTrenches.selectClass(1, engine::tntwars::PlayerClassType::Striker);
    matchTrenches.matchFlow().advanceTo(engine::tntwars::MatchPhase::ClassSelect);
    matchTrenches.matchFlow().advanceTo(engine::tntwars::MatchPhase::InProgress);

    glm::vec3 spacePad = matchSpace.jumpPads()[0].position;
    glm::vec3 trenchesPad = matchTrenches.jumpPads()[0].position;
    auto spaceOffset = matchSpace.triggerJumpPad(1, spacePad, 0);
    auto trenchesOffset = matchTrenches.triggerJumpPad(1, trenchesPad, 0);
    check(spaceOffset.has_value() && trenchesOffset.has_value(), "Sanity: both real jump pads real-trigger successfully");
    if (spaceOffset.has_value() && trenchesOffset.has_value()) {
        check(nearlyEqual(spaceOffset->y, trenchesOffset->y * engine::tntwars::TntWarsMatch::kZeroGravityJumpMultiplier),
              "triggerJumpPad() real-amplifies the real launch offset by real-exactly kZeroGravityJumpMultiplier under Space's own real zero gravity");
    }
}

