// --- WorldPackage TNT-Wars scenario --------------------------------------

void testWorldPackageRealTntWarsMapScenario() {
    // Mirrors testWorldPackageRealMiningWorldScenario()'s exact real
    // shape, using real tntwars::buildMapLayout() piece data (position
    // names only -- no live GPU mesh needed for a real WorldPackage
    // round trip) so this exercises the real, unmodified Sprint 13
    // publish pipeline against real TNT-Wars content, not a synthetic
    // fixture.
    engine::publishing::WorldPackage package;
    package.worldId = "tntwars_trenches_scenario";
    package.version = "1.0.0";
    package.metadata.title = "TNT-Wars: Trenches";
    package.metadata.description = "Classic two-base artillery destruction.";
    package.metadata.tags = {"tntwars", "pvp", "artillery"};
    package.metadata.creatorName = "Test Studio";
    package.metadata.recommendedPlayerCount = 10;
    package.metadata.category = engine::publishing::WorldCategory::Adventure;
    package.metadata.thumbnailPath = "thumb.ppm";

    auto layout = engine::tntwars::buildMapLayout(engine::tntwars::MapId::Trenches);
    for (const auto& piece : layout) {
        engine::core::SceneEntityRecord entity;
        entity.name = piece.name;
        package.scene.entities.push_back(entity);
    }

    auto validation = engine::publishing::validateForPublish(package.worldId, package.version, package.metadata, package.scene);
    check(validation.valid, "A real TNT-Wars Trenches map package real-passes full publish validation, same pipeline as any other real world");

    const char* directory = "test_world_package_tntwars_scenario";
    check(package.saveToDirectory(directory), "The real TNT-Wars map package real-saves to disk through the real, unmodified Sprint 13 pipeline");

    engine::publishing::WorldPackage reloaded;
    check(reloaded.loadFromDirectory(directory), "The real TNT-Wars map package real-reloads from disk");
    check(reloaded.scene.entities.size() == layout.size(), "Every real map-layout piece real-survives the save/load round trip as a real scene entity");
    check(reloaded.metadata.tags.size() == 3, "The real TNT-Wars-specific tags real-survive the round trip");
}

