void testBuildTntWarsTrailerBeatsHasTwentyNineBeats() {
    auto beats = engine::trailer::buildTntWarsTrailerBeats();
    // Kronos ("Four RTX Maps" Phase 6): 29, not 28 -- MapHighlight_Mantle
    // (the real Volcano Map highlight) joined the roster.
    check(beats.size() == 29,
          "The real Kronos trailer real-has exactly 29 real beats (2 Intro + 6 MiningSim + 1 Opening + 5 Showcase + "
          "5 MapHighlight + 5 Ultimate + 2 Forge + 1 FinalClash + 1 LogoReveal + 1 TitleCard)");
}

void testBuildTntWarsTrailerBeatsSceneOrderMatchesKronosBrief() {
    auto beats = engine::trailer::buildTntWarsTrailerBeats();
    // Kronos Mega Prompt Section 3's own real flow: 1) cinematic intro
    // (Heavenly<->Void) 2) Mining Sim RTX showcase 3) TNT Wars showcase
    // 4) PvP highlights 5) explosions/mining/forging/combat 6) Kronos
    // logo reveal 7) final cinematic outro.
    check(beats.front().action == engine::trailer::BeatAction::ShowMiningSimZone,
          "Scene 1 (cinematic intro) real-opens on a real Mining Sim zone beat, not a TNT-Wars one");
    check(beats[0].zoneType == engine::miningsim::ZoneType::Heavenly && beats[1].zoneType == engine::miningsim::ZoneType::Void,
          "Scene 1 real-contrasts Heavenly then Void, matching the brief's own exact framing");
    check(beats[6].action == engine::trailer::BeatAction::ShowDungeon && beats[7].action == engine::trailer::BeatAction::ShowBoss,
          "Scene 2 (Mining Sim RTX showcase) real-closes on a real dungeon beat then a real boss beat");
    check(beats[8].action == engine::trailer::BeatAction::Opening, "Scene 3 (TNT Wars showcase) real-opens with the real Sprint 15 Opening beat");
    check(beats[9].action == engine::trailer::BeatAction::ClassShowcase, "Scene 3 real-continues into real Class Showcase beats");
    check(beats[14].action == engine::trailer::BeatAction::ShowMap, "Scene 3 real-continues into real Map Highlight beats");
    // Kronos ("Four RTX Maps" Phase 6): indices 19+ (not 18+) -- the real
    // MapHighlight_Mantle beat inserted at index 16 shifts everything
    // after it by +1.
    check(beats[19].action == engine::trailer::BeatAction::TriggerUltimate, "Scene 4 (PvP highlights) real-is the real Ultimate Montage");
    check(beats[24].action == engine::trailer::BeatAction::ShowForge, "Scene 5 (forging/combat) real-opens with real Forge beats");
    check(beats[26].action == engine::trailer::BeatAction::FinalClash, "Scene 5 real-closes with the real Final Clash beat");
    check(beats[27].action == engine::trailer::BeatAction::LogoReveal, "Scene 6 is the real Kronos logo reveal beat");
    check(beats.back().action == engine::trailer::BeatAction::TitleCard, "Scene 7 (final outro) is the real closing Title Card beat");
}

