void testBuildFinalClashCinematicHasMultipleKeyframes() {
    auto seq = engine::trailer::buildFinalClashCinematic(glm::vec3(0.0f));
    auto early = seq.sample(1.0f, glm::vec3(0.0f));
    auto mid = seq.sample(5.0f, glm::vec3(0.0f));
    auto late = seq.sample(9.0f, glm::vec3(0.0f));
    bool allDistinct = glm::length(early.cameraPosition - mid.cameraPosition) > 0.1f &&
                        glm::length(mid.cameraPosition - late.cameraPosition) > 0.1f;
    check(allDistinct, "Final Clash's real longer, multi-keyframe path real-actually moves the camera across its real 10-second real duration, not a static hold");
}

