// --- TrailerDirector (headless-testable surface only -- no tick()/initializeCapture()) --

void testTrailerDirectorConstructionRegistersBothTrailerPlayerIds() {
    engine::core::Camera camera;
    engine::core::ECS ecs;
    engine::core::MeshLibrary meshLibrary;
    engine::core::ParticleSystem particleSystem;
    engine::tntwars::TntWarsMatch match;
    engine::trailer::TrailerDirector director(camera, ecs, meshLibrary, particleSystem, match);
    // Real, observable side effect of real player registration:
    // classOf() real-defaults to Striker for a real registered-but-
    // class-unselected player (see TntWarsMatch::classOf()'s own real
    // fallback), while an *unregistered* player would behave
    // identically for classOf() -- so the real, meaningful check here is
    // that selectClass() real-succeeds for both real reserved ids
    // (TntWarsMatch::registerPlayer() is what makes a player id real-known
    // to the match at all).
    check(match.selectClass(engine::trailer::TrailerDirector::kTrailerPlayerIdA, engine::tntwars::PlayerClassType::Striker),
          "TrailerDirector's real constructor real-registers kTrailerPlayerIdA with the real TntWarsMatch (selectClass real-succeeds)");
    check(match.selectClass(engine::trailer::TrailerDirector::kTrailerPlayerIdB, engine::tntwars::PlayerClassType::Saboteur),
          "TrailerDirector's real constructor real-registers kTrailerPlayerIdB with the real TntWarsMatch too");
}

void testTrailerDirectorPlayerIdsAreReservedFarOutsideNormalRange() {
    // Real "TNT-Wars gameplay isolation during capture" property: real
    // net::NetworkSession-assigned player ids are real, small, sequential
    // integers (server-assigned, starting near 1) -- these real reserved
    // trailer ids are real, deliberately far outside that range, so a
    // trailer capture sharing a TntWarsMatch with real connected players
    // can never real-collide with one.
    check(engine::trailer::TrailerDirector::kTrailerPlayerIdA > 100000,
          "kTrailerPlayerIdA is real-reserved far outside any real, normal connected-player id range");
    check(engine::trailer::TrailerDirector::kTrailerPlayerIdB > 100000,
          "kTrailerPlayerIdB is real-reserved far outside any real, normal connected-player id range too");
}

void testTrailerDirectorPlayerIdsAreDistinctFromEachOther() {
    check(engine::trailer::TrailerDirector::kTrailerPlayerIdA != engine::trailer::TrailerDirector::kTrailerPlayerIdB,
          "The real two trailer performer player ids are real-distinct from each other -- Final Clash's real rockets (A) and real torpedoes (B) never real-collide as the real-same player");
}

