void testTrailerDirectorSeekToBeatMatchesTimelineCumulativeDuration() {
    engine::core::Camera camera;
    engine::core::ECS ecs;
    engine::core::MeshLibrary meshLibrary;
    engine::core::ParticleSystem particleSystem;
    engine::tntwars::TntWarsMatch match;
    engine::trailer::TrailerDirector director(camera, ecs, meshLibrary, particleSystem, match);

    float expected = 0.0f;
    for (int i = 0; i < 5; ++i) expected += director.beats()[static_cast<size_t>(i)].durationSeconds;
    director.seekToBeat(5);
    check(nearlyEqual(director.elapsedSeconds(), expected, 0.01f),
          "seekToBeat(5) real-jumps elapsedSeconds() to real-exactly the real cumulative duration of beats 0..4 -- the real start of beat 5");
}

