// Real integration checks against tntwars::buildMapLayout()'s own real,
// live piece names -- not just hand-picked strings.

void testClassifyMapPieceMaterialCoversEveryTrenchesPieceName() {
    auto pieces = engine::tntwars::buildMapLayout(engine::tntwars::MapId::Trenches);
    for (const auto& piece : pieces) {
        auto kind = engine::tntwars::classifyMapPieceMaterial(piece.name);
        if (piece.name.find("Ground") != std::string::npos) {
            check(kind == engine::tntwars::MapPieceMaterialKind::Ground, "Every real Trenches Ground piece real-classifies as Ground");
        } else if (piece.name.find("Cover") != std::string::npos) {
            check(kind == engine::tntwars::MapPieceMaterialKind::Metal, "Every real Trenches Cover piece real-classifies as Metal");
        }
    }
}

void testClassifyMapPieceMaterialCoversEveryMantlePieceName() {
    auto pieces = engine::tntwars::buildMapLayout(engine::tntwars::MapId::Mantle);
    bool sawLava = false;
    bool sawStone = false;
    for (const auto& piece : pieces) {
        auto kind = engine::tntwars::classifyMapPieceMaterial(piece.name);
        if (piece.name == "LavaPool") {
            check(kind == engine::tntwars::MapPieceMaterialKind::Lava, "Mantle's real LavaPool piece real-classifies as Lava");
            sawLava = true;
        }
        if (piece.name.find("RockPillar") != std::string::npos) {
            check(kind == engine::tntwars::MapPieceMaterialKind::Stone, "Every real Mantle RockPillar piece real-classifies as Stone");
            sawStone = true;
        }
    }
    check(sawLava, "Mantle's real layout real-still contains its own LavaPool piece (this test real-exercised a real branch, not a no-op)");
    check(sawStone, "Mantle's real layout real-still contains at least one real RockPillar piece");
}

void testClassifyMapPieceMaterialCoversEverySkyPlatformsPieceName() {
    auto pieces = engine::tntwars::buildMapLayout(engine::tntwars::MapId::SkyPlatforms);
    bool sawPlatform = false;
    for (const auto& piece : pieces) {
        if (piece.name.find("Platform") != std::string::npos) {
            check(engine::tntwars::classifyMapPieceMaterial(piece.name) == engine::tntwars::MapPieceMaterialKind::Metal,
                  "Every real Sky Platforms Platform piece real-classifies as Metal");
            sawPlatform = true;
        }
    }
    check(sawPlatform, "Sky Platforms' real layout real-still contains at least one real Platform piece");
}

void testClassifyMapPieceMaterialCoversEveryIslandSeaPieceName() {
    auto pieces = engine::tntwars::buildMapLayout(engine::tntwars::MapId::IslandSea);
    bool sawIsland = false;
    bool sawWater = false;
    for (const auto& piece : pieces) {
        auto kind = engine::tntwars::classifyMapPieceMaterial(piece.name);
        if (piece.name.find("Island") != std::string::npos) {
            check(kind == engine::tntwars::MapPieceMaterialKind::Stone, "Every real Island Sea Island piece real-classifies as Stone");
            sawIsland = true;
        }
        if (piece.name == "Water") {
            check(kind == engine::tntwars::MapPieceMaterialKind::None, "Island Sea's real Water piece real-classifies as None");
            sawWater = true;
        }
    }
    check(sawIsland, "Island Sea's real layout real-still contains at least one real Island piece");
    check(sawWater, "Island Sea's real layout real-still contains its own real Water piece");
}

void testClassifyMapPieceMaterialNeverCrashesAcrossEveryRealMapPiece() {
    engine::tntwars::MapId maps[] = {engine::tntwars::MapId::Trenches, engine::tntwars::MapId::Mantle,
                                       engine::tntwars::MapId::SkyPlatforms, engine::tntwars::MapId::IslandSea,
                                      engine::tntwars::MapId::Space};
    int totalPiecesChecked = 0;
    for (auto map : maps) {
        for (const auto& piece : engine::tntwars::buildMapLayout(map)) {
            (void)engine::tntwars::classifyMapPieceMaterial(piece.name); // real, honest "does this crash/throw" check
            ++totalPiecesChecked;
        }
    }
    check(totalPiecesChecked > 0, "The real combined loop over every real map's real pieces real-actually iterated real content, not an empty no-op");
}

// --- core::ProceduralMaterialLibrary::applyTo() -----------------------------
// A fake, non-GPU-backed library (real, distinct handle values, never
// generate()'d) so applyTo()'s real dispatch logic is testable without a
// real Vulkan device -- see this section's own header comment.

engine::core::ProceduralMaterialLibrary makeFakeMaterialLibraryForTests() {
    engine::core::ProceduralMaterialLibrary lib;
    lib.stone = {100, 101, 102, 103, 104};
    lib.metal = {200, 201, 202, 203, 204};
    lib.lava = {300, 301, 302, 303, 304};
    lib.ground = {400, 401, 402, 403, 404};
    lib.crystal = {500, 501, 502, 503, 504};
    return lib;
}

void testProceduralMaterialLibraryApplyToStoneSetsStoneTextures() {
    auto lib = makeFakeMaterialLibraryForTests();
    engine::core::Renderable renderable;
    lib.applyTo(renderable, engine::tntwars::MapPieceMaterialKind::Stone);
    check(renderable.albedoTexture == 100, "applyTo(Stone) real-copies stone's real albedo handle");
    check(renderable.normalTexture == 101, "applyTo(Stone) real-copies stone's real normal handle");
    check(renderable.metallicTexture == 102, "applyTo(Stone) real-copies stone's real metallic handle");
    check(renderable.roughnessTexture == 103, "applyTo(Stone) real-copies stone's real roughness handle");
    check(renderable.aoTexture == 104, "applyTo(Stone) real-copies stone's real AO handle");
    check(nearlyEqual(renderable.metallic, 0.02f), "applyTo(Stone) real-sets a real low, non-zero metallic value");
    check(nearlyEqual(renderable.roughness, 0.9f), "applyTo(Stone) real-sets a real high roughness value");
}

