void testCinematicSequenceFovDegreesThreeKeyframesInterpolatesWithinEachSegment() {
    engine::tntwars::CinematicSequence seq;
    seq.addKeyframe(0.0f, glm::vec3(0.0f));
    seq.addKeyframe(12.0f, glm::vec3(1.0f, 0.0f, 0.0f));
    seq.addFovKeyframe(0.0f, 30.0f);
    seq.addFovKeyframe(4.0f, 70.0f);
    seq.addFovKeyframe(12.0f, 70.0f);
    auto midFirstSegment = seq.sample(2.0f, glm::vec3(0.0f, 0.0f, -100.0f));
    check(nearlyEqual(midFirstSegment.fovDegrees, 50.0f, 0.1f),
          "A real three-FOV-keyframe midpoint within the real first segment real-interpolates correctly");
    auto secondSegment = seq.sample(8.0f, glm::vec3(0.0f, 0.0f, -100.0f));
    check(nearlyEqual(secondSegment.fovDegrees, 70.0f, 0.1f), "A real flat second FOV segment real-holds its own constant value");
}

void testCinematicSequenceFovKeyframeReKeysWithinOneMillisecond() {
    engine::tntwars::CinematicSequence seq;
    seq.addKeyframe(0.0f, glm::vec3(0.0f));
    seq.addKeyframe(2.0f, glm::vec3(1.0f, 0.0f, 0.0f));
    seq.addFovKeyframe(1.0f, 40.0f);
    seq.addFovKeyframe(1.0f, 90.0f); // real re-key at the exact same time -- should replace, not duplicate
    auto sample = seq.sample(1.0f, glm::vec3(0.0f, 0.0f, -100.0f));
    check(nearlyEqual(sample.fovDegrees, 90.0f, 0.01f),
          "Re-keying a real FOV keyframe at the same real time real-replaces it, matching addKeyframe()'s own convention");
}

void testCinematicSequenceDurationSecondsUsesMaxOfBezierAndFovKeyframes() {
    engine::tntwars::CinematicSequence seq;
    engine::tntwars::BezierSegment segment;
    segment.startTime = 0.0f;
    segment.endTime = 3.0f;
    seq.addBezierSegment(segment);
    seq.addFovKeyframe(0.0f, 60.0f);
    seq.addFovKeyframe(7.0f, 90.0f); // real, deliberately past the real Bezier segment's own endTime
    check(nearlyEqual(seq.durationSeconds(), 7.0f),
          "durationSeconds() real-takes the real max of every real position/FOV source, not just one");
}

