// --- core::Renderer -- Cinematic Mode / Performance Mode real mutual
// exclusion (Sprint 16 Phase 1) -- a fresh, never-initialize()'d Renderer is
// real and safe to construct/destruct here: every setter tested is a plain
// member write (no Vulkan calls), and Renderer::shutdown() (called from its
// own destructor) real-null-checks device_ before touching any Vulkan handle.

void testRendererCinematicModeAndPerformanceModeAreMutuallyExclusive() {
    engine::core::Renderer renderer;
    check(!renderer.isCinematicModeEnabled(), "A fresh, real, uninitialized Renderer real-defaults Cinematic Mode to off");
    check(!renderer.isPerformanceModeEnabled(), "A fresh, real, uninitialized Renderer real-defaults Performance Mode to off");

    renderer.setPerformanceMode(true);
    check(renderer.isPerformanceModeEnabled(), "setPerformanceMode(true) real-enables Performance Mode");

    renderer.setCinematicMode(true);
    check(renderer.isCinematicModeEnabled(), "setCinematicMode(true) real-enables Cinematic Mode");
    check(!renderer.isPerformanceModeEnabled(),
          "Enabling Cinematic Mode real-force-disables Performance Mode -- the two real, opposite-direction "
          "GPU-cost modes real-stay mutually exclusive");

    renderer.setPerformanceMode(true);
    check(renderer.isPerformanceModeEnabled(), "Re-enabling Performance Mode real-works again");
    check(!renderer.isCinematicModeEnabled(),
          "Enabling Performance Mode real-force-disables Cinematic Mode, the real reverse direction of the same "
          "mutual exclusion");
}

void testRendererCinematicModeOffDoesNotAffectPerformanceMode() {
    engine::core::Renderer renderer;
    renderer.setPerformanceMode(true);
    renderer.setCinematicMode(false);
    check(renderer.isPerformanceModeEnabled(),
          "Explicitly turning Cinematic Mode *off* real-leaves Performance Mode's own real state alone -- the real "
          "exclusion only fires on the real *enabling* transition");
}

void testRendererPerformanceModeOffDoesNotAffectCinematicMode() {
    engine::core::Renderer renderer;
    renderer.setCinematicMode(true);
    renderer.setPerformanceMode(false);
    check(renderer.isCinematicModeEnabled(), "Explicitly turning Performance Mode *off* real-leaves Cinematic Mode's own real state alone");
}

