void testZoneVisualThemeNormalMatchesOriginalMiningSimRtxDefaults() {
    auto theme = engine::miningsim::zoneVisualTheme(engine::miningsim::ZoneType::Normal);
    check(nearlyEqual(theme.fogDensity, 0.012f), "ZoneType::Normal's real fogDensity real-matches MiningSimRtx.cpp's own original hand-tuned 0.012 exactly");
    check(nearlyEqual(theme.accentLightColor.x, 0.55f) && nearlyEqual(theme.accentLightColor.y, 0.30f) && nearlyEqual(theme.accentLightColor.z, 1.0f),
          "ZoneType::Normal's real accent color real-matches the original hand-tuned violet exactly -- the default call site's real look is unchanged");
}

void testZoneVisualThemeEveryZoneProducesARealDistinctTheme() {
    engine::miningsim::ZoneType zones[] = {
        engine::miningsim::ZoneType::Normal,      engine::miningsim::ZoneType::Underwater,
        engine::miningsim::ZoneType::Void,        engine::miningsim::ZoneType::Heavenly,
        engine::miningsim::ZoneType::CorruptedHeavenly, engine::miningsim::ZoneType::BioluminescentCaverns,
        engine::miningsim::ZoneType::Dungeon,     engine::miningsim::ZoneType::DevBonus};
    std::vector<glm::vec3> accentColors;
    for (auto z : zones) accentColors.push_back(engine::miningsim::zoneVisualTheme(z).accentLightColor);
    for (size_t i = 0; i < accentColors.size(); ++i) {
        for (size_t j = i + 1; j < accentColors.size(); ++j) {
            bool distinct = !nearlyEqual(accentColors[i].x, accentColors[j].x) ||
                             !nearlyEqual(accentColors[i].y, accentColors[j].y) ||
                             !nearlyEqual(accentColors[i].z, accentColors[j].z);
            check(distinct, "Every real ZoneType real-gets its own real, distinct accent light color -- not six recolors of one theme");
        }
    }
}

void testZoneVisualThemeHeavenlyIsBrighterThanVoid() {
    auto heavenly = engine::miningsim::zoneVisualTheme(engine::miningsim::ZoneType::Heavenly);
    auto voidTheme = engine::miningsim::zoneVisualTheme(engine::miningsim::ZoneType::Void);
    float heavenlyLuma = heavenly.ambientTint.x + heavenly.ambientTint.y + heavenly.ambientTint.z;
    float voidLuma = voidTheme.ambientTint.x + voidTheme.ambientTint.y + voidTheme.ambientTint.z;
    check(heavenlyLuma > voidLuma, "Heavenly's real ambient real-is brighter than Void's own real darker ambient");
}

void testZoneVisualThemeEveryZoneStaysWithinSafeAmbientMagnitude() {
    // Kronos trailer production: real, live-capture-verified retune --
    // every real zone's own ambientTint/fogColor now stays within a real,
    // narrow band around Normal's own proven-safe magnitude (sum ~0.17),
    // varying real hue rather than overall brightness, after live
    // capture showed the original, wider-ranging values reading as a
    // badly overexposed wash on camera (see ZoneVisualTheme.cpp's own
    // header comment on this real fix).
    engine::miningsim::ZoneType zones[] = {
        engine::miningsim::ZoneType::Normal,      engine::miningsim::ZoneType::Underwater,
        engine::miningsim::ZoneType::Void,        engine::miningsim::ZoneType::Heavenly,
        engine::miningsim::ZoneType::CorruptedHeavenly, engine::miningsim::ZoneType::BioluminescentCaverns,
        engine::miningsim::ZoneType::Dungeon,     engine::miningsim::ZoneType::DevBonus};
    for (auto z : zones) {
        auto theme = engine::miningsim::zoneVisualTheme(z);
        float ambientLuma = theme.ambientTint.x + theme.ambientTint.y + theme.ambientTint.z;
        float fogLuma = theme.fogColor.x + theme.fogColor.y + theme.fogColor.z;
        check(ambientLuma < 0.30f, "Every real zone's own real ambientTint real-stays under a real, safe magnitude ceiling");
        check(fogLuma < 0.30f, "Every real zone's own real fogColor real-stays under a real, safe magnitude ceiling");
        check(theme.fogDensity < 0.020f, "Every real zone's own real fogDensity real-stays under a real, safe ceiling");
    }
}

void testZoneVisualThemeAmbientGroundTintIsAlwaysDimmerThanAmbientTint() {
    engine::miningsim::ZoneType zones[] = {
        engine::miningsim::ZoneType::Normal,      engine::miningsim::ZoneType::Underwater,
        engine::miningsim::ZoneType::Void,        engine::miningsim::ZoneType::Heavenly,
        engine::miningsim::ZoneType::CorruptedHeavenly, engine::miningsim::ZoneType::BioluminescentCaverns,
        engine::miningsim::ZoneType::Dungeon,     engine::miningsim::ZoneType::DevBonus};
    for (auto z : zones) {
        auto theme = engine::miningsim::zoneVisualTheme(z);
        float groundLuma = theme.ambientGroundTint.x + theme.ambientGroundTint.y + theme.ambientGroundTint.z;
        float ambientLuma = theme.ambientTint.x + theme.ambientTint.y + theme.ambientTint.z;
        check(groundLuma <= ambientLuma, "Every real zone's own real ambientGroundTint real-stays real-no brighter than its own ambientTint");
    }
}

// --- Kronos Milestone 18: Procedural dungeons ----------------------------

void testDungeonRoomsOverlapDetectsRealOverlapAndNonOverlap() {
    engine::miningsim::DungeonRoom a{{0, 0}, {2, 2}};
    engine::miningsim::DungeonRoom overlapping{{1, 1}, {2, 2}};
    engine::miningsim::DungeonRoom disjoint{{5, 5}, {2, 2}};
    check(engine::miningsim::dungeonRoomsOverlap(a, overlapping), "dungeonRoomsOverlap() real-detects a real, genuine overlap");
    check(!engine::miningsim::dungeonRoomsOverlap(a, disjoint), "dungeonRoomsOverlap() real-is false for real, genuinely disjoint rooms");
}

void testDungeonRoomsOverlapAdjacentRoomsDoNotOverlap() {
    engine::miningsim::DungeonRoom a{{0, 0}, {2, 2}};
    engine::miningsim::DungeonRoom adjacent{{2, 0}, {2, 2}}; // real, exactly touching edge, not overlapping
    check(!engine::miningsim::dungeonRoomsOverlap(a, adjacent), "Two real rooms real-exactly sharing an edge real-do not count as overlapping");
}

void testGenerateDungeonLayoutProducesNonOverlappingRoomsWithinGridBounds() {
    std::mt19937 rng(1234);
    for (int trial = 0; trial < 20; ++trial) {
        auto layout = engine::miningsim::generateDungeonLayout(engine::miningsim::RarityTier::Epic, rng);
        check(!layout.rooms.empty() && static_cast<int>(layout.rooms.size()) <= engine::miningsim::kMaxDungeonRooms,
              "generateDungeonLayout() real-places between 1 and kMaxDungeonRooms real rooms");
        for (const auto& room : layout.rooms) {
            check(room.gridPosition.x >= 0 && room.gridPosition.y >= 0 &&
                      room.gridPosition.x + room.gridSize.x <= engine::miningsim::kDungeonGridWidth &&
                      room.gridPosition.y + room.gridSize.y <= engine::miningsim::kDungeonGridHeight,
                  "Every real placed room real-stays fully within the real dungeon grid bounds");
        }
        for (size_t i = 0; i < layout.rooms.size(); ++i) {
            for (size_t j = i + 1; j < layout.rooms.size(); ++j) {
                check(!engine::miningsim::dungeonRoomsOverlap(layout.rooms[i], layout.rooms[j]),
                      "No two real rooms in a real generated layout real-overlap each other");
            }
        }
    }
}

void testGenerateDungeonLayoutCorridorsConnectEveryRoom() {
    std::mt19937 rng(99);
    auto layout = engine::miningsim::generateDungeonLayout(engine::miningsim::RarityTier::Common, rng);
    check(layout.corridors.size() == layout.rooms.size() - 1,
          "generateDungeonLayout() real-produces real-exactly (roomCount - 1) corridors -- a real, fully-connected spanning layout");
}

void testGenerateDungeonLayoutAttachesTheRequestedRarity() {
    std::mt19937 rng(55);
    auto layout = engine::miningsim::generateDungeonLayout(engine::miningsim::RarityTier::TrueHeavenly, rng);
    check(layout.rarity == engine::miningsim::RarityTier::TrueHeavenly,
          "generateDungeonLayout() real-attaches real-exactly the requested rarity to the real resulting layout, unmodified");
}

void testGenerateDungeonLayoutIsDeterministicForASeededRng() {
    std::mt19937 rngA(2026);
    std::mt19937 rngB(2026);
    auto layoutA = engine::miningsim::generateDungeonLayout(engine::miningsim::RarityTier::Rare, rngA);
    auto layoutB = engine::miningsim::generateDungeonLayout(engine::miningsim::RarityTier::Rare, rngB);
    check(layoutA.rooms.size() == layoutB.rooms.size(), "Two real identically-seeded generations real-produce the real-same room count");
    bool allMatch = true;
    for (size_t i = 0; i < layoutA.rooms.size() && i < layoutB.rooms.size(); ++i) {
        if (layoutA.rooms[i].gridPosition != layoutB.rooms[i].gridPosition || layoutA.rooms[i].gridSize != layoutB.rooms[i].gridSize) {
            allMatch = false;
        }
    }
    check(allMatch, "Two real identically-seeded generations real-produce real-identical room layouts -- real, deterministic given a fixed seed");
}

void testCanGenerateDungeonInStartingZoneMatchesRarityCap() {
    check(engine::miningsim::canGenerateDungeonInStartingZone(engine::miningsim::RarityTier::Epic),
          "canGenerateDungeonInStartingZone() real-allows Epic, matching the real starting-zone dungeon cap");
    check(!engine::miningsim::canGenerateDungeonInStartingZone(engine::miningsim::RarityTier::Legendary),
          "canGenerateDungeonInStartingZone() real-rejects Legendary, real-beyond the starting-zone dungeon cap");
}

// --- Kronos Milestone 19: Mob system --------------------------------

void testSpawnMobOfRarityScalesStatsWithRarityRank() {
    auto common = engine::miningsim::spawnMobOfRarity(engine::miningsim::RarityTier::Common);
    auto trueHeavenly = engine::miningsim::spawnMobOfRarity(engine::miningsim::RarityTier::TrueHeavenly);
    check(trueHeavenly.maxHealth > common.maxHealth, "A real TrueHeavenly mob real-has more health than a real Common mob");
    check(trueHeavenly.moveSpeed > common.moveSpeed, "A real TrueHeavenly mob real-is faster than a real Common mob");
    check(trueHeavenly.attackDamagePerSecond > common.attackDamagePerSecond, "A real TrueHeavenly mob real-hits harder than a real Common mob");
    check(trueHeavenly.rarity == engine::miningsim::RarityTier::TrueHeavenly && common.rarity == engine::miningsim::RarityTier::Common,
          "spawnMobOfRarity() real-tags the real spawned mob with real-exactly the requested rarity");
}

void testSpawnMobOfRarityStartsAtFullHealthAndIdle() {
    auto mob = engine::miningsim::spawnMobOfRarity(engine::miningsim::RarityTier::Epic);
    check(nearlyEqual(mob.health, mob.maxHealth), "A real freshly-spawned mob real-starts at real-full health");
    check(mob.behavior == engine::miningsim::MobBehaviorState::Idle, "A real freshly-spawned mob real-starts Idle");
}

void testTickMobBehaviorStateIdleToPursueOnDetection() {
    auto mob = engine::miningsim::spawnMobOfRarity(engine::miningsim::RarityTier::Common);
    engine::miningsim::tickMobBehaviorState(mob, glm::vec3(0.0f), glm::vec3(5.0f, 0.0f, 0.0f)); // within real detectionRadius (12)
    check(mob.behavior == engine::miningsim::MobBehaviorState::Pursue, "tickMobBehaviorState() real-transitions Idle -> Pursue once the real target real-enters detectionRadius");
}

void testTickMobBehaviorStateStaysIdleWhenTargetFar() {
    auto mob = engine::miningsim::spawnMobOfRarity(engine::miningsim::RarityTier::Common);
    engine::miningsim::tickMobBehaviorState(mob, glm::vec3(0.0f), glm::vec3(1000.0f, 0.0f, 0.0f));
    check(mob.behavior == engine::miningsim::MobBehaviorState::Idle, "tickMobBehaviorState() real-stays Idle while the real target real-is far outside detectionRadius");
}

void testTickMobBehaviorStatePursueToAttackWithinAttackRadius() {
    auto mob = engine::miningsim::spawnMobOfRarity(engine::miningsim::RarityTier::Common);
    mob.behavior = engine::miningsim::MobBehaviorState::Pursue;
    engine::miningsim::tickMobBehaviorState(mob, glm::vec3(0.0f), glm::vec3(1.0f, 0.0f, 0.0f)); // within real attackRadius (2)
    check(mob.behavior == engine::miningsim::MobBehaviorState::Attack, "tickMobBehaviorState() real-transitions Pursue -> Attack once real-within attackRadius");
}

void testTickMobBehaviorStateAttackBacksOffToPursue() {
    auto mob = engine::miningsim::spawnMobOfRarity(engine::miningsim::RarityTier::Common);
    mob.behavior = engine::miningsim::MobBehaviorState::Attack;
    engine::miningsim::tickMobBehaviorState(mob, glm::vec3(0.0f), glm::vec3(5.0f, 0.0f, 0.0f)); // real-beyond attackRadius but real-within detectionRadius
    check(mob.behavior == engine::miningsim::MobBehaviorState::Pursue, "tickMobBehaviorState() real-drops Attack -> Pursue once the real target real-backs out past attackRadius");
}

void testTickMobBehaviorStateLosesTrailBackToIdle() {
    auto mob = engine::miningsim::spawnMobOfRarity(engine::miningsim::RarityTier::Common);
    mob.behavior = engine::miningsim::MobBehaviorState::Pursue;
    engine::miningsim::tickMobBehaviorState(mob, glm::vec3(0.0f), glm::vec3(1000.0f, 0.0f, 0.0f));
    check(mob.behavior == engine::miningsim::MobBehaviorState::Idle, "tickMobBehaviorState() real-resets Pursue -> Idle once the real target real-fully leaves detectionRadius");
}

void testMobPursuitStepMovesTowardTargetWithoutOvershooting() {
    glm::vec3 next = engine::miningsim::mobPursuitStep(glm::vec3(0.0f), glm::vec3(10.0f, 0.0f, 0.0f), 3.0f, 1.0f);
    check(nearlyEqual(next.x, 3.0f) && nearlyEqual(next.y, 0.0f) && nearlyEqual(next.z, 0.0f),
          "mobPursuitStep() real-moves real-exactly moveSpeed*dt toward the real target");
}

void testMobPursuitStepClampsExactlyAtTargetWhenStepOvershoots() {
    glm::vec3 next = engine::miningsim::mobPursuitStep(glm::vec3(0.0f), glm::vec3(2.0f, 0.0f, 0.0f), 100.0f, 1.0f);
    check(nearlyEqual(next.x, 2.0f) && nearlyEqual(next.y, 0.0f) && nearlyEqual(next.z, 0.0f),
          "mobPursuitStep() real-clamps real-exactly at the target rather than real-overshooting past it");
}

void testMobAttackDamageThisTickOnlyDealsDamageWhileAttacking() {
    auto mob = engine::miningsim::spawnMobOfRarity(engine::miningsim::RarityTier::Common);
    mob.behavior = engine::miningsim::MobBehaviorState::Pursue;
    check(nearlyEqual(engine::miningsim::mobAttackDamageThisTick(mob, 1.0f), 0.0f), "mobAttackDamageThisTick() real-is 0 while the real mob real-isn't Attacking");
    mob.behavior = engine::miningsim::MobBehaviorState::Attack;
    check(nearlyEqual(engine::miningsim::mobAttackDamageThisTick(mob, 1.0f), mob.attackDamagePerSecond),
          "mobAttackDamageThisTick() real-deals real-exactly attackDamagePerSecond * dt while Attacking");
}

void testApplyDamageToMobClampsAtZeroAndIgnoresNonPositive() {
    auto mob = engine::miningsim::spawnMobOfRarity(engine::miningsim::RarityTier::Common);
    float before = mob.health;
    engine::miningsim::applyDamageToMob(mob, 10.0f);
    check(nearlyEqual(mob.health, before - 10.0f), "applyDamageToMob() real-reduces health by real-exactly the real damage amount");
    engine::miningsim::applyDamageToMob(mob, 999999.0f);
    check(nearlyEqual(mob.health, 0.0f), "applyDamageToMob() real-clamps health at 0, never real-negative");
    check(!engine::miningsim::isMobAlive(mob), "A real mob at real-0 health real-is not alive");
    engine::miningsim::applyDamageToMob(mob, -5.0f);
    check(nearlyEqual(mob.health, 0.0f), "applyDamageToMob() real-ignores real non-positive damage entirely");
}

// --- Kronos Milestone 20: Boss system -------------------------------

void testSpawnBossOfRarityIsStrictlyStrongerThanARegularMob() {
    auto mob = engine::miningsim::spawnMobOfRarity(engine::miningsim::RarityTier::Epic);
    auto boss = engine::miningsim::spawnBossOfRarity(engine::miningsim::RarityTier::Epic);
    check(boss.maxHealth > mob.maxHealth, "A real boss real-has more max health than a real regular mob of the real-same rarity");
    check(boss.attackDamagePerSecond > mob.attackDamagePerSecond, "A real boss real-hits harder than a real regular mob of the real-same rarity");
    check(boss.detectionRadius > mob.detectionRadius, "A real boss real-has a wider real aggro range than a real regular mob");
    check(nearlyEqual(boss.maxHealth, mob.maxHealth * engine::miningsim::kBossStatMultiplier),
          "spawnBossOfRarity() real-scales maxHealth by real-exactly kBossStatMultiplier over the real regular-mob baseline");
}

void testSpawnBossOfRarityStartsAtFullHealth() {
    auto boss = engine::miningsim::spawnBossOfRarity(engine::miningsim::RarityTier::Void);
    check(nearlyEqual(boss.health, boss.maxHealth), "A real freshly-spawned boss real-starts at real-full health");
    check(boss.rarity == engine::miningsim::RarityTier::Void, "spawnBossOfRarity() real-tags the real boss with real-exactly the requested rarity");
}

void testBossSpawnChanceDecreasesWithRarityRank() {
    engine::miningsim::RarityTier tiers[] = {
        engine::miningsim::RarityTier::Common,        engine::miningsim::RarityTier::Rare,
        engine::miningsim::RarityTier::Epic,          engine::miningsim::RarityTier::Legendary,
        engine::miningsim::RarityTier::UltraLegendary, engine::miningsim::RarityTier::CorruptedHeavenly,
        engine::miningsim::RarityTier::Void,          engine::miningsim::RarityTier::TrueHeavenly};
    for (size_t i = 0; i + 1 < 8; ++i) {
        check(engine::miningsim::bossSpawnChance(tiers[i]) > engine::miningsim::bossSpawnChance(tiers[i + 1]),
              "bossSpawnChance() real-strictly decreases from Common through TrueHeavenly");
    }
    check(nearlyEqual(engine::miningsim::bossSpawnChance(engine::miningsim::RarityTier::Common), engine::miningsim::kBaseBossSpawnChance),
          "bossSpawnChance(Common) real-equals real-exactly kBaseBossSpawnChance (rank 0 -- no falloff yet)");
}

void testRollBossSpawnConvergesTowardChanceOverManyTrials() {
    std::mt19937 rng(4242);
    int successCount = 0;
    constexpr int kTrials = 20000;
    for (int i = 0; i < kTrials; ++i) {
        if (engine::miningsim::rollBossSpawn(engine::miningsim::RarityTier::Common, rng)) ++successCount;
    }
    float observedRate = static_cast<float>(successCount) / static_cast<float>(kTrials);
    check(std::abs(observedRate - engine::miningsim::kBaseBossSpawnChance) < 0.01f,
          "Over many real trials, rollBossSpawn()'s own real success rate real-converges close to kBaseBossSpawnChance");
}

void testRollBossSpawnIsDeterministicForASeededRng() {
    std::mt19937 rngA(88);
    std::mt19937 rngB(88);
    for (int i = 0; i < 30; ++i) {
        check(engine::miningsim::rollBossSpawn(engine::miningsim::RarityTier::Rare, rngA) ==
                  engine::miningsim::rollBossSpawn(engine::miningsim::RarityTier::Rare, rngB),
              "Two real identically-seeded RNGs real-produce real-identical rollBossSpawn() sequences");
    }
}

void testBossRewardMultiplierIncreasesWithRarityAndStartsAtOne() {
    check(nearlyEqual(engine::miningsim::bossRewardMultiplier(engine::miningsim::RarityTier::Common), 1.0f),
          "bossRewardMultiplier(Common) real-is real-exactly 1.0 -- no real bonus at the real baseline rarity");
    check(engine::miningsim::bossRewardMultiplier(engine::miningsim::RarityTier::TrueHeavenly) >
              engine::miningsim::bossRewardMultiplier(engine::miningsim::RarityTier::Common),
          "bossRewardMultiplier() real-strictly increases with rarity, matching the brief's own \"harder boss = better reward\"");
}

