// Real, welded quad -- 4 shared vertices, 2 triangles sharing the
// diagonal edge (1,2) -- unlike EditableMesh::createBox() (flat-shaded,
// no vertex sharing at all across faces, see that function's own
// comment), this is what bevelEdge() needs a real interior edge to test
// against.
engine::core::EditableMesh makeWeldedQuad() {
    std::vector<engine::core::Vertex> vertices = {
        {{-1.0f, 0.0f, -1.0f}, {0, 1, 0}, {0, 0}},
        {{1.0f, 0.0f, -1.0f}, {0, 1, 0}, {1, 0}},
        {{1.0f, 0.0f, 1.0f}, {0, 1, 0}, {1, 1}},
        {{-1.0f, 0.0f, 1.0f}, {0, 1, 0}, {0, 1}},
    };
    std::vector<uint32_t> indices = {0, 1, 2, 0, 2, 3};
    return engine::core::EditableMesh::fromVertexData(std::move(vertices), std::move(indices));
}

void testEditableMeshCreateBoxHasRealBoxTopology() {
    auto box = engine::core::EditableMesh::createBox({0.5f, 0.5f, 0.5f});
    check(box.vertexCount() == 24, "box has 24 vertices (4 per face x 6 faces, flat-shaded)");
    check(box.faceCount() == 12, "box has 12 triangles (2 per face x 6 faces)");
}

void testEditableMeshExtrudeFaceAddsSixFacesAndMovesTheCap() {
    auto box = engine::core::EditableMesh::createBox({0.5f, 0.5f, 0.5f});
    size_t facesBefore = box.faceCount();
    size_t vertsBefore = box.vertexCount();
    glm::vec3 normalBefore = box.faceNormal(0);
    glm::vec3 centroidBefore = box.faceCentroid(0);

    check(box.extrudeFace(0, 1.0f), "extrudeFace succeeds on a real, in-range face");
    check(box.faceCount() == facesBefore + 6, "extrude adds exactly 6 faces (moved cap + 3 wall quads x 2 tris)");
    check(box.vertexCount() == vertsBefore + 3, "extrude adds exactly 3 new (offset) vertices");

    glm::vec3 centroidAfter = box.faceCentroid(0);
    float movedDistance = glm::distance(centroidBefore + normalBefore * 1.0f, centroidAfter);
    check(movedDistance < 1e-3f, "the cap's new centroid is offset by exactly the extrude distance along the face normal");

    check(!box.extrudeFace(999, 1.0f), "extrudeFace on an out-of-range face is a real, honest no-op");
}

void testEditableMeshSubdivideFaceSplitsOneTriangleIntoFour() {
    auto box = engine::core::EditableMesh::createBox({0.5f, 0.5f, 0.5f});
    size_t facesBefore = box.faceCount();
    size_t vertsBefore = box.vertexCount();

    check(box.subdivideFace(0), "subdivideFace succeeds on a real, in-range face");
    check(box.faceCount() == facesBefore + 3, "subdivide turns 1 triangle into 4 (net +3)");
    check(box.vertexCount() == vertsBefore + 3, "subdivide adds exactly 3 new (edge midpoint) vertices");
}

void testEditableMeshMergeVerticesWeldsCloseVerticesAndDropsDegenerateFaces() {
    // Two unit triangles sharing an edge in *position* only (not index --
    // constructed the way a naive .obj import or a hand-placed pair of
    // Block Builder triangles might leave things), one vertex apart by
    // less than the weld threshold.
    std::vector<engine::core::Vertex> vertices = {
        {{0.0f, 0.0f, 0.0f}, {0, 1, 0}, {0, 0}}, {{1.0f, 0.0f, 0.0f}, {0, 1, 0}, {1, 0}},
        {{0.0f, 0.0f, 1.0f}, {0, 1, 0}, {0, 1}}, {{0.001f, 0.0f, 0.0f}, {0, 1, 0}, {0, 0}},
        {{1.0f, 0.0f, 0.0f}, {0, 1, 0}, {1, 0}}, {{1.0f, 0.0f, 1.0f}, {0, 1, 0}, {1, 1}},
    };
    std::vector<uint32_t> indices = {0, 1, 2, 3, 4, 5};
    auto mesh = engine::core::EditableMesh::fromVertexData(std::move(vertices), std::move(indices));
    check(mesh.vertexCount() == 6, "starts with 6 real, distinct vertex entries");

    size_t mergedCount = mesh.mergeVertices(0.01f);
    check(mergedCount > 0, "mergeVertices reports a real, non-zero number of welded vertices");
    check(mesh.vertexCount() < 6, "vertex count actually drops after welding close vertices");
    check(mesh.faceCount() == 2, "both real (non-degenerate) triangles survive the weld");
}

void testEditableMeshBevelEdgeReplacesASharedInteriorEdge() {
    auto quad = makeWeldedQuad();
    // indices {0,1,2} and {0,2,3} -- the real shared edge (in both
    // triangles) is (0,2), the quad's own diagonal, not (1,2) (only in
    // the first triangle).
    size_t facesBefore = quad.faceCount();
    size_t vertsBefore = quad.vertexCount();

    check(quad.bevelEdge(0, 2, 0.25f), "bevelEdge succeeds on the quad's real, shared interior edge (0,2)");
    check(quad.faceCount() == facesBefore + 2, "bevel adds exactly 2 new triangles (1 new connecting quad)");
    check(quad.vertexCount() == vertsBefore + 4, "bevel adds exactly 4 new (offset) vertices, 2 per adjacent face");
}

void testEditableMeshBevelEdgeIsHonestNoOpOnANonSharedEdge() {
    auto box = engine::core::EditableMesh::createBox({0.5f, 0.5f, 0.5f});
    // Box faces share no vertex indices at all (flat-shaded, see
    // createBox()'s own comment) -- any edge here has 0 or 1 adjacent
    // faces by construction, never the 2 a real interior-edge bevel
    // needs.
    check(!box.bevelEdge(0, 1, 0.25f), "bevelEdge on a box (no real shared edges) is a real, honest no-op");
}

void testEditableMeshInsetFaceShrinksTowardCentroidAndAddsSixFaces() {
    auto box = engine::core::EditableMesh::createBox({0.5f, 0.5f, 0.5f});
    size_t facesBefore = box.faceCount();
    size_t vertsBefore = box.vertexCount();
    glm::vec3 centroidBefore = box.faceCentroid(0);

    check(box.insetFace(0, 0.5f), "insetFace succeeds on a real, in-range face");
    check(box.faceCount() == facesBefore + 6, "inset adds exactly 6 faces (shrunk cap + 3 wall quads x 2 tris)");
    check(box.vertexCount() == vertsBefore + 3, "inset adds exactly 3 new (shrunk) vertices");

    glm::vec3 centroidAfter = box.faceCentroid(0);
    check(nearlyEqual(glm::distance(centroidBefore, centroidAfter), 0.0f, 1e-3f),
          "an inset face's centroid stays put (shrinks symmetrically around the same center)");
}

void testUvToolsPlanarProjectionMapsToNormalizedZeroOneRange() {
    auto box = engine::core::EditableMesh::createBox({1.0f, 1.0f, 1.0f});
    engine::core::applyPlanarProjection(box, engine::core::ProjectionAxis::Y);
    for (const auto& v : box.vertices()) {
        check(v.uv.x >= -1e-4f && v.uv.x <= 1.0f + 1e-4f, "planar-projected U stays within [0,1]");
        check(v.uv.y >= -1e-4f && v.uv.y <= 1.0f + 1e-4f, "planar-projected V stays within [0,1]");
    }
    // A 2x2x2 box's real corner at (+1,+1,+1) projects (Y-axis away) to
    // the real UV corner (1,1) -- the top-right of the bounding box in
    // the XZ plane.
    bool foundTopRightCorner = false;
    for (const auto& v : box.vertices()) {
        if (nearlyEqual(v.position.x, 1.0f) && nearlyEqual(v.position.z, 1.0f)) {
            if (nearlyEqual(v.uv.x, 1.0f, 1e-3f) && nearlyEqual(v.uv.y, 1.0f, 1e-3f)) foundTopRightCorner = true;
        }
    }
    check(foundTopRightCorner, "the box's real (+1,*,+1) corner lands at real UV (1,1) under Y-axis planar projection");
}

void testUvToolsCubeProjectionPicksPerFaceDominantAxis() {
    auto box = engine::core::EditableMesh::createBox({1.0f, 1.0f, 1.0f});
    engine::core::applyCubeProjection(box);
    // Every vertex gets a real UV in [0,1] regardless of which face's
    // dominant axis produced it.
    bool anyOutOfRange = false;
    for (const auto& v : box.vertices()) {
        if (v.uv.x < -1e-4f || v.uv.x > 1.0f + 1e-4f || v.uv.y < -1e-4f || v.uv.y > 1.0f + 1e-4f) anyOutOfRange = true;
    }
    check(!anyOutOfRange, "cube projection keeps every real UV within [0,1] regardless of per-face axis choice");
}

void testUvToolsAutoUnwrapPreservesRealTriangleEdgeLengthRatios() {
    auto original = engine::core::EditableMesh::createBox({0.5f, 1.5f, 0.5f}); // real, non-cubic proportions
    auto box = engine::core::applyAutoUnwrap(original);

    auto indices = box.faceVertexIndices(0);
    const auto& vertices = box.vertices();
    glm::vec3 pa = vertices[indices[0]].position, pb = vertices[indices[1]].position, pc = vertices[indices[2]].position;
    glm::vec2 ua = vertices[indices[0]].uv, ub = vertices[indices[1]].uv, uc = vertices[indices[2]].uv;

    float real3dAb = glm::length(pb - pa), real3dAc = glm::length(pc - pa);
    float uvAb = glm::length(ub - ua), uvAc = glm::length(uc - ua);
    check(real3dAb > 1e-6f && uvAb > 1e-6f, "auto-unwrap produces a real, non-degenerate UV edge");
    // The real 3D edge-length ratio must match the real UV edge-length
    // ratio -- this is what "shape-preserving" actually means, checked
    // directly rather than assumed.
    check(nearlyEqual(real3dAb / real3dAc, uvAb / uvAc, 0.01f),
          "auto-unwrap's per-triangle UV preserves the real 3D edge-length ratio (shape-preserving, not just any layout)");
}

void testUvToolsAutoUnwrapPacksFacesIntoNonOverlappingCells() {
    auto original = engine::core::EditableMesh::createBox({0.5f, 0.5f, 0.5f});
    auto box = engine::core::applyAutoUnwrap(original);
    // Real, direct non-overlap check: every face's own UV bounding box
    // must fit inside a single, real 1/ceil(sqrt(faceCount)) grid cell --
    // if two faces' UV bounds ever overlapped, this would fail for at
    // least one of them.
    int gridSize = static_cast<int>(std::ceil(std::sqrt(static_cast<double>(box.faceCount()))));
    float cell = 1.0f / static_cast<float>(gridSize);
    bool anyCellViolation = false;
    for (size_t f = 0; f < box.faceCount(); ++f) {
        auto indices = box.faceVertexIndices(f);
        int col = static_cast<int>(f) % gridSize, row = static_cast<int>(f) / gridSize;
        float cellMinX = col * cell, cellMaxX = (col + 1) * cell;
        float cellMinY = row * cell, cellMaxY = (row + 1) * cell;
        for (uint32_t vi : indices) {
            glm::vec2 uv = box.vertices()[vi].uv;
            if (uv.x < cellMinX - 1e-4f || uv.x > cellMaxX + 1e-4f || uv.y < cellMinY - 1e-4f ||
                uv.y > cellMaxY + 1e-4f) {
                anyCellViolation = true;
            }
        }
    }
    check(!anyCellViolation, "every real face's UV stays inside its own real, non-overlapping grid cell");
}

void testSaveObjRoundTripsThroughLoadObjWithRealGeometry() {
    auto box = engine::core::EditableMesh::createBox({0.5f, 0.5f, 0.5f});
    const char* path = "test_export.obj";
    check(engine::core::saveObj(path, box.vertices(), box.indices()), "saveObj writes a real file successfully");

    auto loaded = engine::core::loadObj(path);
    check(loaded.succeeded, "loadObj reads saveObj's own output back successfully");
    check(loaded.vertices.size() == box.vertexCount(), "round-tripped vertex count matches the real original");
    check(loaded.indices.size() == box.indices().size(), "round-tripped index count matches the real original");

    // Real, direct spot check: every original vertex position must
    // appear somewhere in the reloaded set (order/indexing may differ,
    // the real geometry must not).
    bool foundOriginalCorner = false;
    for (const auto& v : loaded.vertices) {
        if (nearlyEqual(v.position.x, 0.5f) && nearlyEqual(v.position.y, 0.5f) && nearlyEqual(v.position.z, 0.5f)) {
            foundOriginalCorner = true;
        }
    }
    check(foundOriginalCorner, "a real original corner position survives the saveObj/loadObj round trip");
    std::remove(path);
}

void testKMeshSaveLoadRoundTripsExactly() {
    auto box = engine::core::EditableMesh::createBox({0.5f, 0.5f, 0.5f});
    const char* path = "test_export.kmesh";
    check(engine::core::saveKMesh(path, box.vertices(), box.indices()), "saveKMesh writes a real file successfully");

    auto loaded = engine::core::loadKMesh(path);
    check(loaded.succeeded, "loadKMesh reads saveKMesh's own output back successfully");
    check(loaded.vertices.size() == box.vertexCount(), "kmesh round trip preserves the exact real vertex count");
    check(loaded.indices.size() == box.indices().size(), "kmesh round trip preserves the exact real index count");

    // Unlike .obj (which only carries position/uv/normal, no shared-vs-
    // unshared structure), .kmesh is the one real format that
    // round-trips EVERY vertex exactly, in order -- checked directly.
    bool allExact = true;
    for (size_t i = 0; i < box.vertexCount() && i < loaded.vertices.size(); ++i) {
        if (!nearlyEqual(box.vertices()[i].position.x, loaded.vertices[i].position.x) ||
            !nearlyEqual(box.vertices()[i].position.y, loaded.vertices[i].position.y) ||
            !nearlyEqual(box.vertices()[i].position.z, loaded.vertices[i].position.z)) {
            allExact = false;
        }
    }
    check(allExact, "every real vertex position round-trips through .kmesh byte-for-byte (within float precision)");
    std::remove(path);
}

void testKMeshLoadIsHonestAboutAMalformedFile() {
    const char* path = "test_malformed.kmesh";
    {
        std::ofstream out(path);
        out << "NOT_A_REAL_KMESH_HEADER\n";
    }
    auto loaded = engine::core::loadKMesh(path);
    check(!loaded.succeeded, "loadKMesh reports real failure on a file with no real KMESH header");
    check(!loaded.error.empty(), "loadKMesh's failure includes a real, non-empty error message");
    std::remove(path);
}

void testShippedAvatarAnimationClipsLoadAndValidate() {
    // Kronos ("Avatar System" -- animation set): real regression coverage
    // for the 6 shipped clips (engine/assets/animations/*.anim) -- loads
    // each real file back from disk (not just checking it was written
    // once) and validates it against the real 18-bone skeleton, the same
    // check a real caller (AvatarController::setIdleClip() et al.) needs
    // to hold.
    //
    // Real bug found via the packaged alpha zip's own engine_tests binary
    // (package_alpha.sh copies it in specifically so a tester can verify
    // the exact shipped binaries pass the full suite): a hardcoded
    // "../assets/animations/" relative path only resolves correctly when
    // cwd is engine/build/ (this suite's own dev convention) -- from the
    // packaged flat layout (engine_tests sitting next to assets/, no
    // "build/" parent) it silently resolved to the wrong directory and
    // every check below false-failed, exactly the same real packaging
    // failure mode core/ResourcePaths.hpp's own header comment already
    // documents for engine_runtime/studio's shader/asset loading. Fixed
    // the same way: resolveResourceDir() prefers a real "assets" sitting
    // next to the running test binary (the packaged case) before falling
    // back to the compile-time source path (the dev-build case) -- one
    // real resolution, correct from both cwd conventions.
    std::string animDir =
        engine::core::resolveResourceDir(engine::core::executableDirectory(), "assets", ENGINE_ASSET_DIR) + "/animations";
    engine::core::Skeleton skeleton = engine::core::buildHumanoidSkeleton();
    struct ClipSpec {
        const char* fileName;
        bool looping;
    };
    const ClipSpec kClips[] = {
        {"idle.anim", true},       {"walk.anim", true},      {"run.anim", true},
        {"jump_start.anim", false}, {"jump_air.anim", true}, {"jump_land.anim", false},
    };
    for (const ClipSpec& spec : kClips) {
        engine::core::AnimationClip clip;
        check(clip.loadFromFile(animDir + "/" + spec.fileName), "shipped clip loads from real disk file");
        check(!clip.tracks.empty(), "shipped clip has real tracks, not an empty stub");
        check(clip.looping == spec.looping, "shipped clip's looping flag matches its real intended playback (loop vs one-shot)");

        std::string error;
        check(engine::core::validateAnimationClipAgainstSkeleton(clip, skeleton, error),
              "shipped clip validates against the real 18-bone skeleton");

        // Real "no root motion" check: every keyframe's position must
        // exactly equal that joint's own real bind-local position --
        // nothing ever translates away from bind pose, only rotates.
        bool noRootMotion = true;
        for (const auto& track : clip.tracks) {
            int jointIndex = skeleton.findJointIndex(track.targetName());
            if (jointIndex < 0) continue; // already caught by validateAnimationClipAgainstSkeleton above
            glm::vec3 bindPos = skeleton.joints[static_cast<size_t>(jointIndex)].localPosition;
            for (const auto& keyframe : track.keyframes()) {
                if (glm::distance(keyframe.position, bindPos) > 1e-4f) noRootMotion = false;
            }
        }
        check(noRootMotion, "shipped clip never animates position away from bind pose -- real, honest no-root-motion");
    }
}

void testHouseLayoutHasExactlyOneFloorAndTwoRoofWedges() {
    auto parts = engine::housedemo::computeHouseLayout();
    check(!parts.empty(), "computeHouseLayout returns a non-empty layout");

    int floorCount = 0, roofCount = 0, wallCount = 0;
    for (const auto& part : parts) {
        if (part.kind == engine::housedemo::HousePartKind::Floor) ++floorCount;
        if (part.kind == engine::housedemo::HousePartKind::RoofWedge) ++roofCount;
        if (part.kind == engine::housedemo::HousePartKind::Wall) ++wallCount;
    }
    check(floorCount == 1, "exactly one Floor part");
    check(roofCount == 2, "exactly two RoofWedge parts (front + back gable halves)");
    check(wallCount > 0, "at least one Wall part");
}

void testHouseLayoutRoofWedgesMeetAtRidge() {
    // Real, direct check of the yaw math HouseLayout.cpp's own comment
    // describes -- a yaw=0 wedge's "tall" (ridge) edge sits at
    // position.z - halfExtents.z; a yaw=180 wedge's tall edge sits at
    // position.z + halfExtents.z (the 180-degree rotation flips which
    // local end is "tall" in world space). Both must land on the exact
    // same world Z for the two roof halves to actually meet, not leave a
    // gap or overlap at the ridge line.
    auto parts = engine::housedemo::computeHouseLayout();
    std::vector<engine::housedemo::HousePart> roofParts;
    for (const auto& part : parts) {
        if (part.kind == engine::housedemo::HousePartKind::RoofWedge) roofParts.push_back(part);
    }
    check(roofParts.size() == 2, "exactly two roof wedges to check ridge alignment on");
    if (roofParts.size() != 2) return;

    float ridgeA = roofParts[0].yawDegrees == 0.0f ? roofParts[0].localPosition.z - roofParts[0].halfExtents.z
                                                     : roofParts[0].localPosition.z + roofParts[0].halfExtents.z;
    float ridgeB = roofParts[1].yawDegrees == 0.0f ? roofParts[1].localPosition.z - roofParts[1].halfExtents.z
                                                     : roofParts[1].localPosition.z + roofParts[1].halfExtents.z;
    check(nearlyEqual(ridgeA, ridgeB), "both roof wedges' tall (ridge) edges land on the same world Z");

    // Both roof pieces must also reach the same peak height (ridge apex),
    // and their eave (low) edges must sit at the same height as each
    // other (a real, symmetric gable, not a lopsided roof).
    check(nearlyEqual(roofParts[0].localPosition.y + roofParts[0].halfExtents.y,
                       roofParts[1].localPosition.y + roofParts[1].halfExtents.y),
          "both roof wedges reach the same peak (ridge apex) height");
}

void testHouseLayoutDoorGapIsOpenInFrontWall() {
    // Real, direct check that no Wall part's box actually covers the
    // real door gap (x in [-0.6, 0.6], z == -3, the front wall) -- a
    // wall segment overlapping this gap would silently block the real
    // door main.cpp/HouseDemoScene.cpp spawns there.
    auto parts = engine::housedemo::computeHouseLayout();
    bool gapBlocked = false;
    for (const auto& part : parts) {
        if (part.kind != engine::housedemo::HousePartKind::Wall) continue;
        bool touchesFrontWallZ = std::fabs(part.localPosition.z - (-3.0f)) < 0.15f;
        if (!touchesFrontWallZ) continue;
        bool overlapsDoorGapX = (part.localPosition.x - part.halfExtents.x < 0.0f) &&
                                 (part.localPosition.x + part.halfExtents.x > 0.0f) && part.localPosition.y < 2.0f;
        if (overlapsDoorGapX) gapBlocked = true;
    }
    check(!gapBlocked, "no front-wall part blocks the door gap at ground level");
}


// Kronos ("Studio Movie Mode"): the plugin's non-ImGui behaviour -- what
// it seeds, what it exposes to the viewport gizmo, and the export path
// its modal drives. The ImGui draw loop itself is not exercised here (it
// needs a live context); everything it *decides* is, which is where the
// bugs would be.

// Kronos ("Luau Project Import & Migration Validation"): require() must
// survive the path spellings and dependency shapes a real imported
// project actually contains.


// Kronos ("Instance-to-ECS Hydration"): typed decoding of the nested XML
// Roblox actually writes. Reading only element text drops every position,
// size, rotation and colour in a place file.

// Kronos ("Asset Moderation & Legal Compliance"): the filter that stops a
// place import from pulling third-party art onto this platform.

// Kronos ("Chat System"): the wire form. Serialised through one struct
// rather than inline at each of the three call sites, because a field
// added on one side and missed on another desynchronises the stream and
// corrupts every message after it.

// The Luau `TextChatService` table. Named after Roblox's own service so a
// ported chat UI needs its call sites rewritten, not its architecture.

// A real HTTP server on a real local socket, used to drive the moderation
// client without calling out to Google. Deliberately a real socket rather
// than a mocked transport: the thing most likely to be wrong is the
// actual curl request/response handling, and a mocked transport tests
// none of it.
class MockHttpServer {
public:
    explicit MockHttpServer(std::string responseBody, int statusCode = 200)
        : responseBody_(std::move(responseBody)), statusCode_(statusCode) {}

    ~MockHttpServer() { stop(); }

    bool start() {
        listenFd_ = ::socket(AF_INET, SOCK_STREAM, 0);
        if (listenFd_ < 0) return false;
        int reuse = 1;
        ::setsockopt(listenFd_, SOL_SOCKET, SO_REUSEADDR, &reuse, sizeof(reuse));

        sockaddr_in address{};
        address.sin_family = AF_INET;
        address.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
        address.sin_port = 0; // let the OS choose, so parallel tests cannot collide
        if (::bind(listenFd_, reinterpret_cast<sockaddr*>(&address), sizeof(address)) != 0) return false;
        socklen_t length = sizeof(address);
        if (::getsockname(listenFd_, reinterpret_cast<sockaddr*>(&address), &length) != 0) return false;
        port_ = ntohs(address.sin_port);
        if (::listen(listenFd_, 8) != 0) return false;

        running_ = true;
        thread_ = std::thread([this]() { serve(); });
        return true;
    }

    void stop() {
        running_ = false;
        if (listenFd_ >= 0) {
            ::shutdown(listenFd_, SHUT_RDWR);
            ::close(listenFd_);
            listenFd_ = -1;
        }
        if (thread_.joinable()) thread_.join();
    }

    [[nodiscard]] std::string baseUrl() const { return "http://127.0.0.1:" + std::to_string(port_); }
    [[nodiscard]] int requestCount() const { return requestCount_.load(); }
    [[nodiscard]] std::string lastRequestBody() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return lastBody_;
    }
    [[nodiscard]] std::string lastRequestHeaders() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return lastHeaders_;
    }
    void setDelayMillis(int millis) { delayMillis_ = millis; }

private:
    void serve() {
        while (running_) {
            const int client = ::accept(listenFd_, nullptr, nullptr);
            if (client < 0) {
                if (!running_) return;
                continue;
            }
            std::string request;
            char buffer[4096];
            // Read until the body is complete, using Content-Length --
            // a single recv() would truncate a large image payload.
            size_t contentLength = 0;
            bool haveHeaders = false;
            size_t headerEnd = 0;
            for (;;) {
                const ssize_t received = ::recv(client, buffer, sizeof(buffer), 0);
                if (received <= 0) break;
                request.append(buffer, static_cast<size_t>(received));
                if (!haveHeaders) {
                    headerEnd = request.find("\r\n\r\n");
                    if (headerEnd != std::string::npos) {
                        haveHeaders = true;
                        const std::string headers = request.substr(0, headerEnd);
                        std::string lowered = headers;
                        std::transform(lowered.begin(), lowered.end(), lowered.begin(),
                                        [](unsigned char c) { return static_cast<char>(std::tolower(c)); });
                        const size_t at = lowered.find("content-length:");
                        if (at != std::string::npos) {
                            contentLength = static_cast<size_t>(std::strtoul(headers.c_str() + at + 15, nullptr, 10));
                        }
                        {
                            std::lock_guard<std::mutex> lock(mutex_);
                            lastHeaders_ = headers;
                        }
                    }
                }
                if (haveHeaders && request.size() >= headerEnd + 4 + contentLength) break;
            }
            if (haveHeaders) {
                std::lock_guard<std::mutex> lock(mutex_);
                lastBody_ = request.substr(headerEnd + 4);
            }
            ++requestCount_;

            if (delayMillis_ > 0) std::this_thread::sleep_for(std::chrono::milliseconds(delayMillis_));

            std::string response = "HTTP/1.1 " + std::to_string(statusCode_) + " OK\r\n";
            response += "Content-Type: application/json\r\n";
            response += "Content-Length: " + std::to_string(responseBody_.size()) + "\r\n";
            response += "Connection: close\r\n\r\n";
            response += responseBody_;
            (void)::send(client, response.data(), response.size(), MSG_NOSIGNAL);
            ::close(client);
        }
    }

    std::string responseBody_;
    int statusCode_ = 200;
    int listenFd_ = -1;
    uint16_t port_ = 0;
    std::atomic<bool> running_{false};
    std::atomic<int> requestCount_{0};
    std::atomic<int> delayMillis_{0};
    std::thread thread_;
    mutable std::mutex mutex_;
    std::string lastBody_;
    std::string lastHeaders_;
};

// Wraps a Gemini structured verdict in the envelope the real API returns:
// the JSON payload arrives as TEXT inside candidates[0].content.parts[0].
std::string geminiEnvelope(bool isSafe, const char* reasonCode) {
    nlohmann::json inner;
    inner["is_safe"] = isSafe;
    inner["reason_code"] = reasonCode;
    nlohmann::json root;
    root["candidates"] = nlohmann::json::array(
        {{{"content", {{"parts", nlohmann::json::array({{{"text", inner.dump()}}})}}}}});
    return root.dump();
}

void testHttpWorkerPool() {
    MockHttpServer server(R"({"ok":true})");
    check(server.start(), "the mock HTTP server starts on a real socket");

    engine::net::HttpWorkerPool pool(3);
    check(pool.workerCount() == 3, "the worker pool really starts the requested number of workers");

    // Many concurrent requests: the point of the pool is that these do not
    // each cost a thread.
    std::vector<std::future<engine::net::HttpResponse>> futures;
    for (int i = 0; i < 12; ++i) {
        engine::net::HttpRequest request;
        request.url = server.baseUrl() + "/v1";
        request.method = "POST";
        request.body = "{\"i\":" + std::to_string(i) + "}";
        request.headers = {"Content-Type: application/json"};
        futures.push_back(pool.submit(std::move(request)));
    }
    int okCount = 0;
    for (auto& future : futures) {
        const engine::net::HttpResponse response = future.get();
        if (response.ok()) ++okCount;
    }
    check(okCount == 12, "every queued request really completes through the pool");
    check(pool.completedCount() == 12, "the pool counts completed requests");
    check(server.requestCount() == 12, "the mock server really received every request");

    // An unreachable host must resolve as a transport failure, not hang
    // and not throw -- the caller's fallback depends on telling that apart
    // from an HTTP error status.
    engine::net::HttpRequest dead;
    dead.url = "http://127.0.0.1:1/nothing";
    dead.timeoutMillis = 800;
    const engine::net::HttpResponse deadResponse = pool.submit(std::move(dead)).get();
    check(deadResponse.transportFailed, "an unreachable host is reported as a transport failure");
    check(!deadResponse.ok(), "a transport failure is not ok()");
    check(deadResponse.status == 0, "a transport failure has no HTTP status");

    // Submitting after shutdown must still resolve, or a caller waiting on
    // the future would wait forever on a promise nobody will set.
    pool.shutdown();
    engine::net::HttpRequest afterShutdown;
    afterShutdown.url = server.baseUrl();
    const engine::net::HttpResponse rejected = pool.submit(std::move(afterShutdown)).get();
    check(rejected.transportFailed, "a request submitted after shutdown resolves as a failure rather than hanging");

    server.stop();
}

void testGeminiModerationClient() {
    // --- request shape ------------------------------------------------------
    const std::string textBody = engine::safety::GeminiModerationClient::buildTextRequestBody("hello there");
    const nlohmann::json parsedRequest = nlohmann::json::parse(textBody, nullptr, false);
    check(!parsedRequest.is_discarded(), "the text request body is valid JSON");
    check(parsedRequest["generationConfig"]["responseMimeType"] == "application/json",
          "the request asks for structured JSON output");
    check(parsedRequest["generationConfig"]["responseSchema"]["properties"].contains("is_safe"),
          "the response schema constrains is_safe");
    check(parsedRequest["generationConfig"]["responseSchema"]["properties"].contains("reason_code"),
          "the response schema constrains reason_code");
    check(parsedRequest["generationConfig"]["temperature"] == 0.0,
          "moderation runs at temperature 0, so a verdict is not a coin flip");

    // --- verdict parsing ----------------------------------------------------
    engine::safety::ModerationVerdict verdict;
    check(engine::safety::GeminiModerationClient::parseVerdict(geminiEnvelope(false, "HARASSMENT"), verdict),
          "a structured verdict really parses out of the API envelope");
    check(!verdict.isSafe, "an unsafe verdict is read as unsafe");
    check(verdict.reasonCode == "HARASSMENT", "the reason code is read from the verdict");
    check(!verdict.usedFallback, "a parsed remote verdict is not marked as a fallback");

    // Malformed shapes must be refused, not guessed at. Each of these is a
    // real thing an API can return on a bad day.
    for (const char* bad : {"", "not json", "{}", R"({"candidates":[]})",
                             R"({"candidates":[{"content":{"parts":[]}}]})",
                             R"({"candidates":[{"content":{"parts":[{"text":"not json"}]}}]})"}) {
        engine::safety::ModerationVerdict ignored;
        check(!engine::safety::GeminiModerationClient::parseVerdict(bad, ignored),
              "a malformed moderation response is refused rather than guessed at");
    }

    // --- base64 -------------------------------------------------------------
    check(engine::safety::GeminiModerationClient::base64Encode({'M', 'a', 'n'}) == "TWFu",
          "base64 encodes a 3-byte group");
    check(engine::safety::GeminiModerationClient::base64Encode({'M', 'a'}) == "TWE=",
          "base64 pads a 2-byte remainder");
    check(engine::safety::GeminiModerationClient::base64Encode({'M'}) == "TQ==",
          "base64 pads a 1-byte remainder");
    // Standard base64, NOT base64url: a JSON image payload with '-'/'_'
    // would be rejected as a malformed image.
    const auto encoded = engine::safety::GeminiModerationClient::base64Encode({0xFB, 0xFF, 0xFE});
    check(encoded.find('-') == std::string::npos && encoded.find('_') == std::string::npos,
          "image payloads use standard base64, not the base64url variant");

    // --- fallback when unconfigured ----------------------------------------
    engine::net::HttpWorkerPool pool(1);
    auto localClassifier = [](const std::string& text) {
        engine::safety::ModerationVerdict local;
        local.isSafe = text.find("badword") == std::string::npos;
        local.reasonCode = local.isSafe ? "SAFE" : "LOCAL_PROFANITY";
        return local;
    };

    engine::safety::GeminiConfig unconfigured;
    unconfigured.apiKey.clear();
    engine::safety::GeminiModerationClient offline(pool, unconfigured, localClassifier);
    check(!offline.isConfigured(), "an unset GEMINI_API_KEY leaves the client unconfigured");

    auto offlineSafe = offline.classifyText("hello").get();
    check(offlineSafe.isSafe, "with no API key a clean message still passes via local filters");
    check(offlineSafe.usedFallback, "a local-only verdict is honestly marked as a fallback");
    auto offlineBad = offline.classifyText("this has badword in it").get();
    check(!offlineBad.isSafe, "with no API key the LOCAL filter still blocks what it knows");
    check(offlineBad.reasonCode == "LOCAL_PROFANITY", "the local reason code survives the fallback");

    // --- real round trip against the mock ----------------------------------
    MockHttpServer flagging(geminiEnvelope(false, "VIOLENCE"));
    check(flagging.start(), "the flagging mock server starts");
    engine::safety::GeminiConfig config;
    config.apiKey = "test-key-not-a-real-secret";
    config.endpoint = flagging.baseUrl();
    config.model = "gemini-flash-lite-latest";
    config.timeoutMillis = 3000;
    engine::safety::GeminiModerationClient client(pool, config, localClassifier);
    check(client.isConfigured(), "a configured client reports itself configured");

    auto flagged = client.classifyText("something violent").get();
    check(!flagged.isSafe, "the client really returns the mock's unsafe verdict");
    check(flagged.reasonCode == "VIOLENCE", "the client really returns the mock's reason code");
    check(!flagged.usedFallback, "a real remote verdict is not marked as a fallback");
    check(flagging.requestCount() == 1, "the client really issued one HTTP request");
    check(flagging.lastRequestBody().find("something violent") != std::string::npos,
          "the message text really reached the endpoint");
    check(flagging.lastRequestBody().find("\"text\":\"\"") == std::string::npos,
          "the classifier is not sent an EMPTY message body");
    // The key must travel in a header, never the URL -- query strings end
    // up in proxy logs and crash reports.
    std::string headers = flagging.lastRequestHeaders();
    std::transform(headers.begin(), headers.end(), headers.begin(),
                    [](unsigned char c) { return static_cast<char>(std::tolower(c)); });
    check(headers.find("x-goog-api-key: test-key-not-a-real-secret") != std::string::npos,
          "the API key is sent as a header");
    check(flagging.lastRequestHeaders().find("test-key-not-a-real-secret") != std::string::npos &&
              headers.find("get /") == std::string::npos,
          "the API key is not placed in the request line/URL");
    flagging.stop();

    // --- rate limiting falls back, and trips the cooldown -------------------
    MockHttpServer limited(R"({"error":"rate limited"})", 429);
    check(limited.start(), "the rate-limited mock server starts");
    engine::safety::GeminiConfig limitedConfig = config;
    limitedConfig.endpoint = limited.baseUrl();
    engine::safety::GeminiModerationClient limitedClient(pool, limitedConfig, localClassifier);

    auto rateLimited = limitedClient.classifyText("this has badword in it").get();
    check(rateLimited.usedFallback, "a 429 falls back to the local classifier");
    check(!rateLimited.isSafe, "the local classifier still blocks during a rate-limit fallback");
    check(limitedClient.consecutiveFailures() == 1, "a rate-limited call counts as a failure");

    for (int i = 0; i < 6; ++i) (void)limitedClient.classifyText("hello").get();
    check(limitedClient.inCooldown(), "repeated failures put the client into cooldown");
    const int requestsBeforeCooldown = limited.requestCount();
    (void)limitedClient.classifyText("hello").get();
    check(limited.requestCount() == requestsBeforeCooldown,
          "a client in cooldown stops calling the endpoint entirely rather than hammering it");
    limited.stop();

    // --- a malformed response must not crash the pipeline -------------------
    MockHttpServer garbage("<html>gateway error</html>");
    check(garbage.start(), "the malformed-response mock server starts");
    engine::safety::GeminiConfig garbageConfig = config;
    garbageConfig.endpoint = garbage.baseUrl();
    engine::safety::GeminiModerationClient garbageClient(pool, garbageConfig, localClassifier);
    auto garbled = garbageClient.classifyText("this has badword in it").get();
    check(garbled.usedFallback, "an unparseable response falls back rather than crashing");
    check(!garbled.isSafe, "the local classifier still applies when the response is unparseable");
    garbage.stop();

    pool.shutdown();
}

// Textures encoded for the vision endpoint must be a real image container.
void testTextureInspectionEncoding() {
    engine::migration::TextureConversionData texture;
    texture.width = 4;
    texture.height = 4;
    texture.rgba.assign(4 * 4 * 4, 0);
    for (size_t i = 0; i < texture.rgba.size(); i += 4) {
        texture.rgba[i + 0] = 200;
        texture.rgba[i + 3] = 255;
    }

    std::vector<uint8_t> png;
    check(engine::migration::AssetConverter::encodeRgbaAsPng(texture.rgba, 4, 4, png),
          "RGBA pixels really encode to PNG");
    check(png.size() > 8, "the encoded PNG has real content");
    // A vision API rejects anything that is not a real container, so the
    // signature and the terminating chunk both matter.
    const uint8_t signature[8] = {0x89, 'P', 'N', 'G', 0x0D, 0x0A, 0x1A, 0x0A};
    bool signatureOk = true;
    for (int i = 0; i < 8; ++i) {
        if (png[static_cast<size_t>(i)] != signature[i]) signatureOk = false;
    }
    check(signatureOk, "the encoded image carries a real PNG signature");
    const std::string asText(reinterpret_cast<const char*>(png.data()), png.size());
    check(asText.find("IHDR") != std::string::npos, "the encoded PNG has an IHDR chunk");
    check(asText.find("IDAT") != std::string::npos, "the encoded PNG has an IDAT chunk");
    check(asText.find("IEND") != std::string::npos, "the encoded PNG is terminated with IEND");

    // stb_image must be able to read back what we wrote -- the strongest
    // available check that the container is genuinely valid.
    int decodedW = 0, decodedH = 0, channels = 0;
    stbi_uc* decoded = stbi_load_from_memory(png.data(), static_cast<int>(png.size()), &decodedW, &decodedH,
                                              &channels, STBI_rgb_alpha);
    check(decoded != nullptr, "the encoded PNG really decodes again");
    check(decodedW == 4 && decodedH == 4, "the decoded PNG has the original dimensions");
    if (decoded != nullptr) {
        check(decoded[0] == 200, "pixel data survives the PNG round trip");
        stbi_image_free(decoded);
    }

    std::string base64;
    check(engine::migration::AssetConverter::encodeTextureForInspection(texture, base64),
          "a texture really encodes to a base64 payload");
    check(!base64.empty(), "the base64 payload is non-empty");
    check(base64.find('-') == std::string::npos && base64.find('_') == std::string::npos,
          "the payload is standard base64, which is what an image field requires");

    // Downscaling: a large texture must not be shipped at full size.
    engine::migration::TextureConversionData large;
    large.width = 2048;
    large.height = 1024;
    large.rgba.assign(static_cast<size_t>(2048) * 1024 * 4, 128);
    std::string largeBase64;
    check(engine::migration::AssetConverter::encodeTextureForInspection(large, largeBase64, 128),
          "a large texture encodes for inspection");
    std::vector<uint8_t> largePng;
    check(engine::migration::AssetConverter::encodeRgbaAsPng(large.rgba, 2048, 1024, largePng),
          "the full-size PNG encodes for comparison");
    check(largeBase64.size() * 3 / 4 < largePng.size(),
          "a large texture is really downscaled before inspection rather than sent at full resolution");

    // Malformed input is refused rather than reading past the buffer.
    engine::migration::TextureConversionData truncated;
    truncated.width = 64;
    truncated.height = 64;
    truncated.rgba.assign(16, 0); // far short of 64*64*4
    std::string ignoredBase64;
    check(!engine::migration::AssetConverter::encodeTextureForInspection(truncated, ignoredBase64),
          "a texture whose pixel buffer is too small is refused, not read past");
}

// The server-side interceptor: a flagged message must not reach other
// clients, and the pipeline must not stall or crash doing it.
void testChatModerationInterceptor() {
    MockHttpServer flagging(geminiEnvelope(false, "HARASSMENT"));
    check(flagging.start(), "the chat-moderation mock server starts");

    engine::net::HttpWorkerPool pool(2);
    engine::safety::GeminiConfig config;
    config.apiKey = "test-key";
    config.endpoint = flagging.baseUrl();
    config.timeoutMillis = 3000;
    auto localClassifier = [](const std::string&) { return engine::safety::ModerationVerdict{}; };
    engine::safety::GeminiModerationClient client(pool, config, localClassifier);

    constexpr uint16_t kTestPort = 17861;
    engine::core::ECS serverEcs, clientAEcs, clientBEcs;
    engine::net::NetworkSession serverSession, clientA, clientB;

    engine::net::NetworkSession::Config serverConfig;
    serverConfig.mode = engine::net::NetworkMode::Server;
    serverConfig.port = kTestPort;
    check(serverSession.initialize(serverConfig), "moderated chat: the server starts");
    serverSession.setChatModerationClient(&client);
    serverSession.setOnPlayerJoin([](engine::core::ECS& ecs, engine::net::PlayerId) -> engine::core::EntityId {
        engine::core::EntityId entity = ecs.createEntity("Player");
        ecs.addComponent<engine::core::Transform>(entity);
        return entity;
    });

    auto connect = [&](engine::net::NetworkSession& session) {
        engine::net::NetworkSession::Config config2;
        config2.mode = engine::net::NetworkMode::Client;
        config2.serverAddress = "127.0.0.1";
        config2.port = kTestPort;
        return session.initialize(config2);
    };
    check(connect(clientA), "moderated chat: client A connects");
    check(connect(clientB), "moderated chat: client B connects");

    engine::core::EntityId avatarA = clientAEcs.createEntity("A");
    clientAEcs.addComponent<engine::core::Transform>(avatarA);
    engine::core::EntityId avatarB = clientBEcs.createEntity("B");
    clientBEcs.addComponent<engine::core::Transform>(avatarB);

    auto pump = [&](int iterations) {
        for (int i = 0; i < iterations; ++i) {
            serverSession.tick(0.05f, serverEcs, engine::core::kNullEntity);
            clientA.tick(0.05f, clientAEcs, avatarA);
            clientB.tick(0.05f, clientBEcs, avatarB);
            std::this_thread::sleep_for(std::chrono::milliseconds(3));
        }
    };

    bool joined = false;
    for (int i = 0; i < 200 && !joined; ++i) {
        pump(1);
        joined = clientA.localPlayerId() != engine::net::kInvalidPlayer &&
                  clientB.localPlayerId() != engine::net::kInvalidPlayer;
    }
    check(joined, "moderated chat: both clients complete the handshake");

    std::vector<std::string> receivedByB;
    clientB.setOnChatPacketReceived(
        [&](const engine::net::ChatMessagePacket& packet) { receivedByB.push_back(packet.body); });

    clientA.sendChatMessage("you are terrible at this game");
    for (int i = 0; i < 200 && receivedByB.empty(); ++i) pump(1);

    check(!receivedByB.empty(), "a moderated message still reaches the other client (as a replacement)");
    if (!receivedByB.empty()) {
        check(receivedByB.front() == engine::net::NetworkSession::kModerationRemovedBody,
              "a flagged message's body is replaced with the moderation notice");
        check(receivedByB.front().find("terrible") == std::string::npos,
              "the flagged original text never reaches another client");
    }
    check(serverSession.chatModerationBlockedCount() == 1, "the server counts the blocked message");
    check(flagging.requestCount() >= 1, "the message really went to the moderation endpoint before broadcast");
    check(serverSession.pendingChatModerationCount() == 0, "no message is left parked after the verdict lands");

    // Dropping instead of replacing.
    serverSession.setChatModerationReplacesBody(false);
    receivedByB.clear();
    clientA.sendChatMessage("another bad one");
    for (int i = 0; i < 120; ++i) pump(1);
    check(receivedByB.empty(), "with replacement disabled, a flagged message is dropped entirely");

    serverSession.shutdown();
    clientA.shutdown();
    clientB.shutdown();
    pool.shutdown();
    flagging.stop();
}

// A safe verdict must pass through unchanged, and a dead endpoint must
// not wedge chat.
void testChatModerationPassAndTimeout() {
    engine::net::HttpWorkerPool pool(2);
    auto localClassifier = [](const std::string&) { return engine::safety::ModerationVerdict{}; };

    MockHttpServer allowing(geminiEnvelope(true, "SAFE"));
    check(allowing.start(), "the allowing mock server starts");
    engine::safety::GeminiConfig config;
    config.apiKey = "test-key";
    config.endpoint = allowing.baseUrl();
    config.timeoutMillis = 3000;
    engine::safety::GeminiModerationClient client(pool, config, localClassifier);

    constexpr uint16_t kTestPort = 17862;
    engine::core::ECS serverEcs, clientAEcs, clientBEcs;
    engine::net::NetworkSession serverSession, clientA, clientB;

    engine::net::NetworkSession::Config serverConfig;
    serverConfig.mode = engine::net::NetworkMode::Server;
    serverConfig.port = kTestPort;
    check(serverSession.initialize(serverConfig), "pass-through chat: the server starts");
    serverSession.setChatModerationClient(&client);
    serverSession.setOnPlayerJoin([](engine::core::ECS& ecs, engine::net::PlayerId) -> engine::core::EntityId {
        engine::core::EntityId entity = ecs.createEntity("Player");
        ecs.addComponent<engine::core::Transform>(entity);
        return entity;
    });

    auto connect = [&](engine::net::NetworkSession& session) {
        engine::net::NetworkSession::Config config2;
        config2.mode = engine::net::NetworkMode::Client;
        config2.serverAddress = "127.0.0.1";
        config2.port = kTestPort;
        return session.initialize(config2);
    };
    check(connect(clientA), "pass-through chat: client A connects");
    check(connect(clientB), "pass-through chat: client B connects");

    engine::core::EntityId avatarA = clientAEcs.createEntity("A");
    clientAEcs.addComponent<engine::core::Transform>(avatarA);
    engine::core::EntityId avatarB = clientBEcs.createEntity("B");
    clientBEcs.addComponent<engine::core::Transform>(avatarB);

    auto pump = [&](int iterations) {
        for (int i = 0; i < iterations; ++i) {
            serverSession.tick(0.05f, serverEcs, engine::core::kNullEntity);
            clientA.tick(0.05f, clientAEcs, avatarA);
            clientB.tick(0.05f, clientBEcs, avatarB);
            std::this_thread::sleep_for(std::chrono::milliseconds(3));
        }
    };

    bool joined = false;
    for (int i = 0; i < 200 && !joined; ++i) {
        pump(1);
        joined = clientA.localPlayerId() != engine::net::kInvalidPlayer &&
                  clientB.localPlayerId() != engine::net::kInvalidPlayer;
    }
    check(joined, "pass-through chat: both clients complete the handshake");

    std::vector<std::string> receivedByB;
    clientB.setOnChatPacketReceived(
        [&](const engine::net::ChatMessagePacket& packet) { receivedByB.push_back(packet.body); });

    clientA.sendChatMessage("hello everyone");
    for (int i = 0; i < 200 && receivedByB.empty(); ++i) pump(1);
    check(!receivedByB.empty(), "a message cleared by moderation really reaches the other client");
    if (!receivedByB.empty()) {
        check(receivedByB.front() == "hello everyone", "an approved message arrives unmodified");
    }
    check(serverSession.chatModerationBlockedCount() == 0, "an approved message is not counted as blocked");
    allowing.stop();

    // Endpoint goes away entirely. The message must still be delivered --
    // the local filters already passed it, and silently swallowing a
    // player's message because a third-party API died is a worse failure
    // than letting a locally-clean message through.
    engine::safety::GeminiConfig deadConfig = config;
    deadConfig.endpoint = "http://127.0.0.1:1";
    deadConfig.timeoutMillis = 600;
    client.setConfig(deadConfig);
    client.resetFailures();

    receivedByB.clear();
    clientA.sendChatMessage("endpoint is down now");
    for (int i = 0; i < 300 && receivedByB.empty(); ++i) pump(1);
    check(!receivedByB.empty(), "chat keeps working when the moderation endpoint is unreachable");
    if (!receivedByB.empty()) {
        check(receivedByB.front() == "endpoint is down now",
              "a locally-clean message is delivered intact when the remote classifier is unavailable");
    }
    check(serverSession.pendingChatModerationCount() == 0, "nothing is left parked after the endpoint failure");

    serverSession.shutdown();
    clientA.shutdown();
    clientB.shutdown();
    pool.shutdown();
}

void testLuauTextChatService() {
    engine::net::NetworkSession session;
    engine::core::Scripting scripting;
    check(scripting.initialize(), "TextChatService test: Scripting::initialize() succeeds");

    engine::core::ScriptChatApi chatApi(session, scripting);
    scripting.setBindingsHook([&](lua_State* L) { chatApi.registerInto(L); });

    // The table and both functions really exist in a sandboxed VM.
    std::string out = runScriptCapturingOutput(scripting, "ChatSurface", R"LUA(
        assert(type(TextChatService) == "table", "TextChatService is not a table")
        assert(type(TextChatService.SendAsync) == "function", "SendAsync is missing")
        assert(type(TextChatService.OnIncomingMessage) == "function", "OnIncomingMessage is missing")
    )LUA", engine::core::SecurityIdentity::UserScript);
    check(out.empty(), "TextChatService exposes SendAsync and OnIncomingMessage to Luau");

    // Argument validation. Each of these is a mistake a UI author will
    // actually make, and each must say what is wrong rather than failing
    // silently or truncating.
    out = runScriptCapturingOutput(scripting, "ChatValidation", R"LUA(
        local okEmpty = pcall(TextChatService.SendAsync, "")
        assert(not okEmpty, "an empty message was accepted")

        local okChannel, channelErr = pcall(TextChatService.SendAsync, "hi", "NoSuchChannel")
        assert(not okChannel, "an unknown channel was accepted")
        assert(string.find(channelErr, "General", 1, true) ~= nil,
               "the channel error does not say which channels are valid: " .. tostring(channelErr))

        local okSystem = pcall(TextChatService.SendAsync, "official notice", "System")
        assert(not okSystem, "a script was allowed to send on the System channel")

        local okLong, longErr = pcall(TextChatService.SendAsync, string.rep("x", 5000))
        assert(not okLong, "an oversized message was accepted")
        assert(string.find(longErr, "limit", 1, true) ~= nil,
               "the oversize error does not mention the limit: " .. tostring(longErr))

        -- Valid calls must not throw, even offline (there is simply no
        -- session to deliver to).
        TextChatService.SendAsync("hello")
        TextChatService.SendAsync("go left", "Team")
        TextChatService.SendAsync("psst", "Whisper")
    )LUA", engine::core::SecurityIdentity::UserScript);
    check(out.empty(), "TextChatService.SendAsync validates its arguments and refuses the System channel");

    // OnIncomingMessage really fires, with the full message table.
    //
    // Asserted through captured print() output rather than a _G flag:
    // luaL_sandbox() freezes _G, and every script gets its own fresh
    // lua_State anyway, so state cannot cross script boundaries. The
    // handler has to report from inside its own VM.
    {
        std::string captured;
        scripting.setOutputCallback([&captured](const std::string& line) { captured += line + "\n"; });
        (void)scripting.loadAndRun("ChatReceive", R"LUA(
            TextChatService.OnIncomingMessage(function(message)
                print("got|" .. tostring(message.senderId) .. "|" .. tostring(message.channel) .. "|" ..
                      tostring(message.body) .. "|" .. tostring(message.timestamp > 0))
            end)
        )LUA", engine::core::SecurityIdentity::UserScript);

        engine::net::ChatMessagePacket packet;
        packet.senderId = 77;
        packet.channelId = static_cast<uint32_t>(engine::net::ChatChannel::Team);
        packet.body = "incoming from the server";
        packet.timestampMillis = 1787400000123ull;
        chatApi.dispatchIncoming(packet);
        scripting.setOutputCallback(nullptr);

        check(captured.find("got|77|Team|incoming from the server|true") != std::string::npos,
              "an incoming chat packet reaches a Luau handler with sender, channel, body and timestamp");
    }

    // A handler that throws must not stop delivery to other subscribers:
    // one script's broken chat box should not take chat down for everyone.
    {
        std::string captured;
        scripting.setOutputCallback([&captured](const std::string& line) { captured += line + "\n"; });
        (void)scripting.loadAndRun("ChatThrower", R"LUA(
            TextChatService.OnIncomingMessage(function(message)
                error("this handler is broken")
            end)
        )LUA", engine::core::SecurityIdentity::UserScript);
        (void)scripting.loadAndRun("ChatSecond", R"LUA(
            TextChatService.OnIncomingMessage(function(message)
                print("second-handler-fired")
            end)
        )LUA", engine::core::SecurityIdentity::UserScript);

        engine::net::ChatMessagePacket packet;
        packet.senderId = 5;
        packet.body = "ping";
        packet.timestampMillis = 1787400000999ull;
        chatApi.dispatchIncoming(packet);
        scripting.setOutputCallback(nullptr);

        check(captured.find("second-handler-fired") != std::string::npos,
              "a throwing chat handler does not stop delivery to other subscribers");
    }
}

void testChatMessagePacketSerialization() {
    engine::net::ChatMessagePacket original;
    original.senderId = 4242;
    original.channelId = static_cast<uint32_t>(engine::net::ChatChannel::Team);
    original.body = "regroup at the north wall";
    original.timestampMillis = 1787400000123ull;

    engine::net::ByteWriter writer;
    original.write(writer);

    engine::net::ByteReader reader(writer.bytes().data(), writer.size());
    engine::net::ChatMessagePacket decoded;
    check(engine::net::ChatMessagePacket::read(reader, decoded), "a chat packet round-trips through the wire form");
    check(decoded.senderId == original.senderId, "sender_id survives the round trip");
    check(decoded.channelId == original.channelId, "channel_id survives the round trip");
    check(decoded.body == original.body, "message_body survives the round trip");
    check(decoded.timestampMillis == original.timestampMillis, "timestamp survives the round trip");

    // A 64-bit timestamp must not be silently narrowed -- Unix millis
    // already exceed 2^32, so a u32 field would wrap and reorder history.
    engine::net::ChatMessagePacket large;
    large.timestampMillis = 0xFFFFFFFFFFull;
    large.body = "x";
    engine::net::ByteWriter largeWriter;
    large.write(largeWriter);
    engine::net::ByteReader largeReader(largeWriter.bytes().data(), largeWriter.size());
    engine::net::ChatMessagePacket largeDecoded;
    check(engine::net::ChatMessagePacket::read(largeReader, largeDecoded), "a large timestamp round-trips");
    check(largeDecoded.timestampMillis == large.timestampMillis,
          "a timestamp beyond 2^32 is not narrowed, so chat history cannot reorder");

    // Truncated input must be refused, not half-read.
    engine::net::ByteReader truncated(writer.bytes().data(), 3);
    engine::net::ChatMessagePacket ignored;
    ignored.senderId = 999;
    check(!engine::net::ChatMessagePacket::read(truncated, ignored), "a truncated chat packet is refused");
    check(ignored.senderId == 999, "a refused packet leaves the caller's struct untouched");

    // An unknown channel id is a protocol violation. Remapping it to
    // General would deliver a team message to the whole room.
    engine::net::ChatMessagePacket bogus;
    bogus.channelId = 9999;
    bogus.body = "hi";
    engine::net::ByteWriter bogusWriter;
    bogus.write(bogusWriter);
    engine::net::ByteReader bogusReader(bogusWriter.bytes().data(), bogusWriter.size());
    engine::net::ChatMessagePacket bogusDecoded;
    check(!engine::net::ChatMessagePacket::read(bogusReader, bogusDecoded),
          "an unknown channel id is refused rather than remapped to General");

    check(engine::net::clientMaySendOn(engine::net::ChatChannel::General), "clients may send on General");
    check(engine::net::clientMaySendOn(engine::net::ChatChannel::Team), "clients may send on Team");
    check(!engine::net::clientMaySendOn(engine::net::ChatChannel::System),
          "clients may NOT originate on System, so official notices cannot be forged");
    check(std::string(engine::net::chatChannelName(engine::net::ChatChannel::Team)) == "Team",
          "channel names are stable strings for the Luau API");
    check(engine::net::currentUnixMillis() > 1600000000000ull, "the server clock produces real Unix millis");
}

// Two real clients over real local sockets: a message from one must reach
// the other through the real server relay.
void testChatMultiClientLoopback() {
    constexpr uint16_t kTestPort = 17851;
    engine::core::ECS serverEcs, clientAEcs, clientBEcs;
    engine::net::NetworkSession serverSession, clientA, clientB;

    engine::net::NetworkSession::Config serverConfig;
    serverConfig.mode = engine::net::NetworkMode::Server;
    serverConfig.port = kTestPort;
    check(serverSession.initialize(serverConfig), "chat loopback: the server starts");
    serverSession.setOnPlayerJoin([](engine::core::ECS& ecs, engine::net::PlayerId) -> engine::core::EntityId {
        engine::core::EntityId entity = ecs.createEntity("Player");
        ecs.addComponent<engine::core::Transform>(entity);
        return entity;
    });

    auto connectClient = [&](engine::net::NetworkSession& session) {
        engine::net::NetworkSession::Config config;
        config.mode = engine::net::NetworkMode::Client;
        config.serverAddress = "127.0.0.1";
        config.port = kTestPort;
        return session.initialize(config);
    };
    check(connectClient(clientA), "chat loopback: client A connects");
    check(connectClient(clientB), "chat loopback: client B connects");

    engine::core::EntityId avatarA = clientAEcs.createEntity("A");
    clientAEcs.addComponent<engine::core::Transform>(avatarA);
    engine::core::EntityId avatarB = clientBEcs.createEntity("B");
    clientBEcs.addComponent<engine::core::Transform>(avatarB);

    auto pump = [&](int iterations) {
        for (int i = 0; i < iterations; ++i) {
            serverSession.tick(0.05f, serverEcs, engine::core::kNullEntity);
            clientA.tick(0.05f, clientAEcs, avatarA);
            clientB.tick(0.05f, clientBEcs, avatarB);
            std::this_thread::sleep_for(std::chrono::milliseconds(3));
        }
    };

    bool bothJoined = false;
    for (int i = 0; i < 200 && !bothJoined; ++i) {
        pump(1);
        bothJoined = clientA.localPlayerId() != engine::net::kInvalidPlayer &&
                      clientB.localPlayerId() != engine::net::kInvalidPlayer;
    }
    check(bothJoined, "chat loopback: both clients complete the handshake");

    std::vector<engine::net::ChatMessagePacket> receivedByA;
    std::vector<engine::net::ChatMessagePacket> receivedByB;
    clientA.setOnChatPacketReceived([&](const engine::net::ChatMessagePacket& p) { receivedByA.push_back(p); });
    clientB.setOnChatPacketReceived([&](const engine::net::ChatMessagePacket& p) { receivedByB.push_back(p); });

    // A sends on General; B must receive it, and so must A (own message
    // comes back through the same server path, so what is displayed is
    // what the server actually accepted).
    clientA.sendChatMessage("hello from A");
    for (int i = 0; i < 80 && receivedByB.empty(); ++i) pump(1);

    check(!receivedByB.empty(), "a chat message really crosses the wire to the other client");
    check(!receivedByA.empty(), "the sender receives their own message back through the server");
    if (!receivedByB.empty()) {
        const auto& message = receivedByB.front();
        check(message.body == "hello from A", "the received message body is intact");
        check(message.senderId == clientA.localPlayerId(),
              "the server stamps the real sender id, not whatever the client claimed");
        check(message.channelId == static_cast<uint32_t>(engine::net::ChatChannel::General),
              "the message arrives on the channel it was sent on");
        check(message.timestampMillis > 1600000000000ull,
              "the server stamps a real timestamp on relay");
    }

    // B replies; A must receive it. Proves the relay is bidirectional and
    // not just echoing the first sender.
    const size_t beforeReply = receivedByA.size();
    clientB.sendChatMessage("hi A, this is B");
    for (int i = 0; i < 80 && receivedByA.size() == beforeReply; ++i) pump(1);
    bool sawReply = false;
    for (const auto& message : receivedByA) {
        if (message.body == "hi A, this is B") sawReply = true;
    }
    check(sawReply, "the relay is bidirectional -- B's reply reaches A");

    // Channel scoping: a Team message must not reach a player who is not
    // subscribed to Team. This is the property that makes channels worth
    // having at all.
    const engine::net::PlayerId playerA = clientA.localPlayerId();
    const engine::net::PlayerId playerB = clientB.localPlayerId();
    check(serverSession.isSubscribedToChannel(playerA, static_cast<uint32_t>(engine::net::ChatChannel::General)),
          "a player with no explicit subscription still hears General");
    check(!serverSession.isSubscribedToChannel(playerB, static_cast<uint32_t>(engine::net::ChatChannel::Team)),
          "a player is not in Team until subscribed");

    receivedByA.clear();
    receivedByB.clear();
    clientA.sendChatMessageOn(engine::net::ChatChannel::Team, "team only");
    for (int i = 0; i < 60; ++i) pump(1);
    bool bSawTeam = false;
    for (const auto& message : receivedByB) {
        if (message.body == "team only") bSawTeam = true;
    }
    check(!bSawTeam, "a Team message does NOT reach a player who is not subscribed to Team");
    bool aSawOwnTeam = false;
    for (const auto& message : receivedByA) {
        if (message.body == "team only") aSawOwnTeam = true;
    }
    check(aSawOwnTeam, "the sender still sees their own Team message");

    // Once B subscribes, the same send reaches them.
    serverSession.subscribeToChannel(playerB, engine::net::ChatChannel::Team);
    check(serverSession.isSubscribedToChannel(playerB, static_cast<uint32_t>(engine::net::ChatChannel::Team)),
          "subscribing really adds the player to the channel");
    receivedByB.clear();
    clientA.sendChatMessageOn(engine::net::ChatChannel::Team, "team again");
    for (int i = 0; i < 80; ++i) pump(1);
    bool bSawSecondTeam = false;
    for (const auto& message : receivedByB) {
        if (message.body == "team again") bSawSecondTeam = true;
    }
    check(bSawSecondTeam, "a subscribed player really receives Team messages");

    // A server-authored System notice reaches everyone.
    receivedByA.clear();
    receivedByB.clear();
    serverSession.broadcastSystemMessage("server restarting in 5 minutes");
    for (int i = 0; i < 80; ++i) pump(1);
    bool aSawSystem = false, bSawSystem = false;
    for (const auto& message : receivedByA) {
        if (message.channelId == static_cast<uint32_t>(engine::net::ChatChannel::System)) aSawSystem = true;
    }
    for (const auto& message : receivedByB) {
        if (message.channelId == static_cast<uint32_t>(engine::net::ChatChannel::System)) bSawSystem = true;
    }
    check(aSawSystem && bSawSystem, "a server System notice reaches every connected client");

    // A client attempting to originate on System must be refused. The
    // client-side guard means nothing is even sent; the server-side guard
    // in handleChatMessageServer is the authority behind it.
    receivedByB.clear();
    clientA.sendChatMessageOn(engine::net::ChatChannel::System, "forged official notice");
    for (int i = 0; i < 60; ++i) pump(1);
    bool sawForgery = false;
    for (const auto& message : receivedByB) {
        if (message.body == "forged official notice") sawForgery = true;
    }
    check(!sawForgery, "a client cannot forge a System-channel message");

    // Oversized bodies are refused rather than truncated on the wire.
    receivedByB.clear();
    clientA.sendChatMessage(std::string(engine::net::ChatMessagePacket::kMaxBodyBytes + 50, 'x'));
    for (int i = 0; i < 60; ++i) pump(1);
    bool sawOversized = false;
    for (const auto& message : receivedByB) {
        if (message.body.size() > engine::net::ChatMessagePacket::kMaxBodyBytes) sawOversized = true;
    }
    check(!sawOversized, "an oversized chat body never reaches another client");

    serverSession.shutdown();
    clientA.shutdown();
    clientB.shutdown();
}

void testAssetModerationFilter() {
    engine::migration::AssetModerationFilter filter;

    // --- proprietary URI detection -----------------------------------------
    for (const char* uri : {"rbxassetid://1234567", "rbxasset://textures/face.png",
                             "rbxthumb://type=Asset&id=1&w=150&h=150",
                             "https://www.roblox.com/asset/?id=9876",
                             "http://assetdelivery.roblox.com/v1/asset/?id=1",
                             "https://c2.rbxcdn.com/abcdef", "//rbxcdn.com/x",
                             "RBXASSETID://55555"}) {
        check(engine::migration::AssetModerationFilter::isProprietaryUri(uri),
              (std::string("a proprietary URI is detected: ") + uri).c_str());
    }
    // Things that must NOT be blocked -- a filter that eats local assets is
    // worse than no filter.
    for (const char* uri : {"assets/textures/stone.png", "./local/mesh.obj", "",
                             "https://example.com/my-own-texture.png", "C:/art/wood.png"}) {
        check(!engine::migration::AssetModerationFilter::isProprietaryUri(uri),
              (std::string("a legitimate reference is NOT blocked: ") + uri).c_str());
    }

    // --- placeholder selection ---------------------------------------------
    check(engine::migration::AssetModerationFilter::placeholderForReference("Part.MeshId rbxassetid://1") ==
              engine::migration::PlaceholderKind::UnitCubeMesh,
          "a blocked mesh reference is replaced with a cube, not a texture");
    check(engine::migration::AssetModerationFilter::placeholderForReference("Sound.SoundId rbxassetid://1") ==
              engine::migration::PlaceholderKind::SilentAudio,
          "a blocked sound reference is replaced with silent audio");
    check(engine::migration::AssetModerationFilter::placeholderForReference("Decal.Texture rbxassetid://1") ==
              engine::migration::PlaceholderKind::CheckerboardTexture,
          "a blocked texture reference is replaced with a checkerboard");

    // --- trademark metadata, whole-word ------------------------------------
    std::string term;
    check(filter.hasTrademarkedMetadata("My Roblox Tycoon", term), "a trademarked term in metadata is caught");
    check(term == "roblox", "the matched trademark term is reported");
    check(!filter.hasTrademarkedMetadata("Robert built a robust robot", term),
          "whole-word matching does not flag unrelated words that merely contain a term");

    // --- protected packages -------------------------------------------------
    std::string package;
    check(filter.isProtectedPackage("Korblox Deathspeaker", package), "a protected first-party package is caught");
    check(filter.isProtectedPackage("classic roblox avatar", package), "a multi-word protected package is caught");
    check(!filter.isProtectedPackage("My Custom Knight", package), "original content is not flagged as a package");

    // --- hash quarantine ----------------------------------------------------
    const std::string bytes = "proprietary-binary-content";
    const std::string digest = engine::migration::AssetModerationFilter::hashContent(bytes);
    check(digest.size() == 64, "content hashing produces a real SHA-256 hex digest");
    check(!filter.isQuarantined(digest), "an unknown hash is not quarantined");
    filter.quarantineHash(digest);
    check(filter.isQuarantined(digest), "a registered hash really is quarantined");
    check(filter.quarantineSize() == 1, "the quarantine registry really holds the entry");

    // Hashing CONTENT, not a name: renaming a quarantined file must not
    // launder it past the filter.
    const auto renamed = filter.evaluateContent("Workspace.Innocent", "assets/harmless.png", bytes);
    check(renamed.code == engine::migration::ModerationReasonCode::BlockedQuarantinedHash,
          "a quarantined asset is caught by content hash even under an innocuous name");
    const auto different = filter.evaluateContent("Workspace.Other", "assets/other.png", "different content");
    check(different.code == engine::migration::ModerationReasonCode::Allowed,
          "unrelated content with the same innocuous name is allowed");

    // --- reason codes are stable strings ------------------------------------
    check(std::string(engine::migration::moderationReasonCodeName(
              engine::migration::ModerationReasonCode::BlockedProprietaryCdn)) == "BLOCKED_PROPRIETARY_CDN",
          "BLOCKED_PROPRIETARY_CDN is spelled exactly as the audit expects");
    check(std::string(engine::migration::moderationReasonCodeName(
              engine::migration::ModerationReasonCode::BlockedTrademarkMetadata)) == "BLOCKED_TRADEMARK_METADATA",
          "BLOCKED_TRADEMARK_METADATA is spelled exactly as the audit expects");
    check(std::string(engine::migration::moderationReasonCodeName(
              engine::migration::ModerationReasonCode::BlockedProtectedPackage)) == "BLOCKED_PROTECTED_PACKAGE",
          "BLOCKED_PROTECTED_PACKAGE is spelled exactly as the audit expects");

    // --- generated checkerboard --------------------------------------------
    const auto checker = engine::migration::AssetModerationFilter::generateCheckerboard(8, 2);
    check(checker.size() == 8u * 8u * 4u, "the placeholder checkerboard is a real RGBA8 image");
    const bool topLeftOpaque = checker[3] == 255;
    check(topLeftOpaque, "the placeholder checkerboard is opaque");
    bool hasTwoTones = false;
    for (size_t i = 0; i + 4 < checker.size(); i += 4) {
        if (checker[i] != checker[0]) hasTwoTones = true;
    }
    check(hasTwoTones, "the placeholder checkerboard really alternates, so it reads as a placeholder");
}

// The gate at AssetConverter's entry points: blocked references must be
// swapped for placeholders WITHOUT the file ever being touched.
void testAssetConverterModerationGate() {
    engine::migration::AssetModerationFilter filter;
    engine::migration::AssetConverter converter(&filter);

    // A blocked texture converts successfully, into a checkerboard.
    engine::migration::TextureConversionData texture;
    const auto textureResult = converter.convertTexture("rbxassetid://1234567", texture);
    check(textureResult.succeeded, "a blocked texture still yields usable data rather than failing the import");
    check(textureResult.usedPlaceholder, "a blocked texture is reported as having used a placeholder");
    check(textureResult.moderationCode == engine::migration::ModerationReasonCode::BlockedProprietaryCdn,
          "a blocked texture carries the BLOCKED_PROPRIETARY_CDN reason code");
    check(texture.width == 64 && texture.height == 64, "the substituted texture is a real generated image");
    check(texture.rgba.size() == 64u * 64u * 4u, "the substituted texture has real pixel data");
    check(textureResult.outputPath.empty(),
          "a blocked texture has no output path -- nothing was fetched or written");

    // A blocked mesh becomes a real unit cube, so the scene keeps its
    // rough volume instead of leaving a hole.
    engine::migration::MeshConversionData mesh;
    const auto meshResult = converter.convertMesh("rbxassetid://999.MeshId", mesh);
    check(meshResult.succeeded && meshResult.usedPlaceholder, "a blocked mesh is swapped for a placeholder");
    check(mesh.vertices.size() == 24 && mesh.indices.size() == 36,
          "the substituted mesh is a real closed cube, not empty geometry");
    check(nearlyEqual(mesh.boundsMax.x, 0.5f), "the substituted cube has real bounds");

    // The gate runs before ANY file access: this path does not exist, and
    // a blocked reference must not produce a "file not found" -- that
    // would prove the filter ran too late.
    check(meshResult.message.find("not found") == std::string::npos,
          "moderation runs BEFORE file access, so a blocked reference never reports a missing file");

    // Local assets still convert normally through the same gated converter.
    const std::string objPath = "test_mod_cube.obj";
    {
        std::ofstream out(objPath);
        out << "v 0 0 0\nv 1 0 0\nv 1 1 0\nvn 0 0 1\nf 1//1 2//1 3//1\n";
    }
    engine::migration::MeshConversionData localMesh;
    const auto localResult = converter.convertMesh(objPath, localMesh);
    check(localResult.succeeded, "a legitimate local mesh still converts with the filter installed");
    check(!localResult.usedPlaceholder, "a legitimate local mesh is NOT replaced with a placeholder");
    std::remove(objPath.c_str());

    // The accumulated audit.
    const auto& report = converter.moderationReport();
    check(report.blockedCount == 2, "the converter's moderation report counts every block");
    check(report.allowedCount >= 1, "the converter's moderation report counts allowed assets too");
    check(report.countOf(engine::migration::ModerationReasonCode::BlockedProprietaryCdn) == 2,
          "the report breaks blocks down by reason code");
    check(report.anyBlocked(), "the report reports that something was blocked");
    check(!report.complianceNotice().empty(), "a report with blocks emits a compliance notice");
    check(report.complianceNotice().find("NOT downloaded") != std::string::npos,
          "the compliance notice states plainly that nothing was fetched");
    check(report.summary().find("BLOCKED_PROPRIETARY_CDN=2") != std::string::npos,
          "the audit summary names the reason code and its count");

    // Without a filter installed, conversion is unfiltered -- a blocked
    // URI is simply an unresolvable path.
    engine::migration::AssetConverter ungated;
    engine::migration::TextureConversionData ungatedTexture;
    const auto ungatedResult = ungated.convertTexture("rbxassetid://1234567", ungatedTexture);
    check(!ungatedResult.succeeded, "an unfiltered converter does not silently invent a placeholder");
    check(ungated.moderationReport().blockedCount == 0, "an unfiltered converter reports no moderation findings");
}

// End to end: a place file carrying proprietary references must produce a
// full audit and clean, placeholder-backed entities.
void testProjectImportModeration() {
    engine::migration::ProjectImporter importer;
    engine::safety::IPInfringementScanner scanner;

    const std::string document = R"XML(<roblox version="4">
  <Item class="Workspace" referent="W0">
    <Properties><string name="Name">Workspace</string></Properties>
    <Item class="Part" referent="P0">
      <Properties>
        <string name="Name">Billboard</string>
        <Vector3 name="size"><X>4</X><Y>4</Y><Z>1</Z></Vector3>
        <CoordinateFrame name="CFrame"><X>0</X><Y>2</Y><Z>0</Z></CoordinateFrame>
      </Properties>
      <Item class="Decal" referent="D0">
        <Properties>
          <string name="Name">Logo</string>
          <Content name="Texture">rbxassetid://1234567890</Content>
        </Properties>
      </Item>
    </Item>
    <Item class="MeshPart" referent="P1">
      <Properties>
        <string name="Name">ImportedProp</string>
        <Content name="MeshId">rbxassetid://55512345</Content>
        <Content name="TextureID">https://assetdelivery.roblox.com/v1/asset/?id=42</Content>
      </Properties>
    </Item>
    <Item class="Part" referent="P2">
      <Properties>
        <string name="Name">Korblox Leg</string>
        <Vector3 name="size"><X>1</X><Y>2</Y><Z>1</Z></Vector3>
      </Properties>
    </Item>
    <Item class="Part" referent="P3">
      <Properties>
        <string name="Name">MyOriginalCrate</string>
        <Vector3 name="size"><X>2</X><Y>2</Y><Z>2</Z></Vector3>
      </Properties>
    </Item>
  </Item>
</roblox>)XML";

    const auto report = importer.importDocument(document, scanner);
    check(report.parsed, "the moderation place file parses");

    const auto& moderation = report.moderation;
    check(moderation.anyBlocked(), "an import carrying proprietary references really reports blocks");
    check(moderation.countOf(engine::migration::ModerationReasonCode::BlockedProprietaryCdn) == 3,
          "every rbxassetid:// and CDN reference in the place is blocked");
    check(moderation.countOf(engine::migration::ModerationReasonCode::BlockedProtectedPackage) == 1,
          "a protected first-party package name is blocked from instance metadata");

    // The clean part must be untouched -- the filter has to leave original
    // content alone or authors will not trust it.
    bool flaggedOriginal = false;
    for (const auto& finding : moderation.findings) {
        if (finding.subject.find("MyOriginalCrate") != std::string::npos) flaggedOriginal = true;
    }
    check(!flaggedOriginal, "original content in the same place is not flagged");

    check(!moderation.complianceNotice().empty(), "the import emits a compliance notice");

    // Blocks surface in the ordinary diagnostics too, so they appear in
    // the Studio console alongside the migration warnings.
    bool sawCodeInDiagnostics = false;
    for (const auto& diagnostic : report.diagnostics) {
        if (diagnostic.message.find("BLOCKED_PROPRIETARY_CDN") != std::string::npos) sawCodeInDiagnostics = true;
    }
    check(sawCodeInDiagnostics, "moderation blocks appear in the import diagnostics with their reason code");

    // And the place still hydrates into clean entities.
    engine::core::ECS ecs;
    engine::migration::HydrationMeshes meshes;
    meshes.box = 0;
    meshes.capsule = 1;
    meshes.cylinder = 2;
    engine::migration::InstanceHydrator hydrator;
    const auto hydrated = hydrator.hydrate(report.tree, ecs, meshes);
    check(hydrated.partCount == 4, "a place with blocked assets still hydrates its parts");
    for (auto entity : hydrated.createdEntities) {
        const auto* renderable = ecs.tryGetComponent<engine::core::Renderable>(entity);
        if (renderable == nullptr) continue;
        check(renderable->albedoTexture == engine::core::Renderable::kInvalidHandle,
              "no imported entity carries a proprietary texture handle");
    }

    // Hash quarantine reaches the importer too.
    engine::migration::ProjectImporter quarantining;
    quarantining.quarantineAssetHash(engine::migration::AssetModerationFilter::hashContent("blocked-bytes"));
    const auto quarantinedReport = quarantining.importDocument(document, scanner);
    check(quarantinedReport.parsed, "quarantine registration does not disturb ordinary importing");
}

void testRbxlxPropertyDecoding() {
    const std::string document = R"XML(<roblox version="4">
  <Item class="Part" referent="P0">
    <Properties>
      <string name="Name">Floor</string>
      <Vector3 name="size"><X>8</X><Y>1</Y><Z>4</Z></Vector3>
      <CoordinateFrame name="CFrame">
        <X>10</X><Y>2.5</Y><Z>-3</Z>
        <R00>0</R00><R01>0</R01><R02>1</R02>
        <R10>0</R10><R11>1</R11><R12>0</R12>
        <R20>-1</R20><R21>0</R21><R22>0</R22>
      </CoordinateFrame>
      <Color3uint8 name="Color3uint8">16711680</Color3uint8>
      <float name="Reflectance">0.5</float>
      <float name="Transparency">0.25</float>
      <bool name="Anchored">true</bool>
      <token name="shape">1</token>
    </Properties>
  </Item>
</roblox>)XML";

    auto parsed = engine::migration::RbxlxParser::parse(document);
    check(parsed.has_value(), "the property-decoding document parses");
    const auto tree = engine::migration::InstanceTreeBuilder::build(*parsed);
    check(tree.size() == 1, "the property-decoding document yields one instance");
    const auto& props = tree[0].properties;

    const glm::vec3 size = engine::migration::decodeVector3(props, "size");
    check(nearlyEqual(size.x, 8.0f) && nearlyEqual(size.y, 1.0f) && nearlyEqual(size.z, 4.0f),
          "a nested <Vector3> really decodes all three components");

    const glm::vec3 position = engine::migration::decodeCFramePosition(props, "CFrame");
    check(nearlyEqual(position.x, 10.0f) && nearlyEqual(position.y, 2.5f) && nearlyEqual(position.z, -3.0f),
          "a <CoordinateFrame> position really decodes");

    // The basis above is a -90 degree yaw. Roblox writes ROWS; feeding
    // that order into glm's column-major mat3 transposes it, which
    // silently inverts every rotation in the place.
    const glm::quat rotation = engine::migration::decodeCFrameRotation(props, "CFrame");
    const glm::vec3 rotatedX = rotation * glm::vec3(1.0f, 0.0f, 0.0f);
    check(nearlyEqual(rotatedX.x, 0.0f, 1e-3f) && nearlyEqual(rotatedX.z, -1.0f, 1e-3f),
          "a CFrame basis decodes with Roblox's row convention, not its transpose");

    const glm::vec3 color = engine::migration::decodeColor3(props, "Color3uint8");
    check(nearlyEqual(color.r, 1.0f, 1e-2f) && nearlyEqual(color.g, 0.0f, 1e-2f) && nearlyEqual(color.b, 0.0f, 1e-2f),
          "a packed <Color3uint8> decodes to the right RGB");

    check(nearlyEqual(engine::migration::decodeFloat(props, "Reflectance"), 0.5f), "a <float> property decodes");
    check(engine::migration::decodeBool(props, "Anchored", false), "a <bool> property decodes");
    check(engine::migration::decodeInt(props, "shape", 99) == 1, "a <token> property decodes as an int");
    check(engine::migration::propertyType(props, "Color3uint8") == "Color3uint8",
          "the property's XML type tag is recorded so Color3 and Color3uint8 can be told apart");

    // Missing and malformed properties must fall back, never propagate a
    // NaN into a transform where it corrupts the whole scene graph.
    const glm::vec3 fallback(42.0f);
    check(engine::migration::decodeVector3(props, "NoSuchProperty", fallback) == fallback,
          "a missing Vector3 returns the fallback");
    engine::migration::PropertyMap broken;
    broken["bad.X"] = "nan";
    broken["bad.Y"] = "1";
    broken["bad.Z"] = "2";
    check(engine::migration::decodeVector3(broken, "bad", fallback) == fallback,
          "a NaN component rejects the whole vector rather than poisoning a transform");
    broken["partial.X"] = "1";
    check(engine::migration::decodeVector3(broken, "partial", fallback) == fallback,
          "a half-written vector returns the fallback rather than a half-decoded position");

    // A non-orthonormal basis is not a rotation and must not become a
    // garbage quaternion.
    engine::migration::PropertyMap skewed;
    for (const char* f : {"R00", "R01", "R02", "R10", "R11", "R12", "R20", "R21", "R22"}) {
        skewed[std::string("m.") + f] = "3";
    }
    const glm::quat identity(1.0f, 0.0f, 0.0f, 0.0f);
    check(engine::migration::decodeCFrameRotation(skewed, "m", identity) == identity,
          "a non-orthonormal basis falls back to identity rather than producing a garbage rotation");
}

// The hydration layer: ImportedInstance tree -> live ECS entities.
void testInstanceHydration() {
    const std::string document = R"XML(<roblox version="4">
  <Item class="Workspace" referent="W0">
    <Properties><string name="Name">Workspace</string></Properties>
    <Item class="Model" referent="M0">
      <Properties>
        <string name="Name">House</string>
        <CoordinateFrame name="CFrame"><X>100</X><Y>0</Y><Z>0</Z></CoordinateFrame>
      </Properties>
      <Item class="Part" referent="P0">
        <Properties>
          <string name="Name">Wall</string>
          <Vector3 name="size"><X>4</X><Y>6</Y><Z>1</Z></Vector3>
          <CoordinateFrame name="CFrame"><X>110</X><Y>3</Y><Z>0</Z></CoordinateFrame>
          <float name="Transparency">0</float>
        </Properties>
      </Item>
      <Item class="PointLight" referent="L0">
        <Properties>
          <string name="Name">Lamp</string>
          <Color3 name="Color"><R>1</R><G>0.5</G><B>0.25</B></Color3>
          <float name="Brightness">3</float>
          <float name="Range">12</float>
        </Properties>
      </Item>
      <Item class="Script" referent="S0">
        <Properties>
          <string name="Name">DoorScript</string>
          <string name="Source">print("hello")</string>
        </Properties>
      </Item>
      <Item class="Smoke" referent="X0">
        <Properties><string name="Name">Puff</string></Properties>
      </Item>
    </Item>
  </Item>
</roblox>)XML";

    auto parsed = engine::migration::RbxlxParser::parse(document);
    check(parsed.has_value(), "the hydration document parses");
    const auto tree = engine::migration::InstanceTreeBuilder::build(*parsed);

    engine::core::ECS ecs;
    engine::migration::HydrationMeshes meshes;
    meshes.box = 0;
    meshes.capsule = 1;
    meshes.cylinder = 2;

    engine::migration::InstanceHydrator hydrator;
    const auto result = hydrator.hydrate(tree, ecs, meshes);

    check(result.partCount == 1, "hydration creates a renderable entity for a Part");
    check(result.lightCount == 1, "hydration creates a Light for a PointLight");
    check(result.scriptCount == 1, "hydration attaches a Script component");
    check(result.groupCount == 2, "hydration creates group entities for Workspace and Model");
    check(result.skippedCount == 1, "an unsupported class is reported as skipped, not silently dropped");
    check(result.createdEntities.size() == 5, "hydration creates exactly the supported entities");

    engine::core::EntityId wall = engine::core::kNullEntity;
    engine::core::EntityId lamp = engine::core::kNullEntity;
    for (auto entity : result.createdEntities) {
        const auto* name = ecs.tryGetComponent<engine::core::Name>(entity);
        if (name == nullptr) continue;
        if (name->value == "Wall") wall = entity;
        if (name->value == "Lamp") lamp = entity;
    }
    check(wall != engine::core::kNullEntity, "the imported Part is findable by its authored name");

    const auto* renderable = ecs.tryGetComponent<engine::core::Renderable>(wall);
    check(renderable != nullptr, "the imported Part really has a Renderable");
    check(renderable != nullptr && renderable->meshHandle == 0,
          "the imported Part is bound to a real mesh handle, so it can actually draw");
    check(renderable != nullptr && renderable->visible, "an opaque imported Part is visible");

    // Roblox Size is a FULL extent and Kronos's box is built from
    // half-extents -- importing Size directly doubles every part.
    const auto* transform = ecs.tryGetComponent<engine::core::Transform>(wall);
    check(transform != nullptr && nearlyEqual(transform->scale.y, 3.0f),
          "a Part's Size is halved into Kronos's half-extent box scale");

    // The wall's world position is 110; its parent Model sits at 100. A
    // CFrame is WORLD-absolute but core::Transform is parent-LOCAL, so
    // the stored local must be the difference -- storing 110 would place
    // the wall at 210 once the parent composes.
    check(transform != nullptr && nearlyEqual(transform->position.x, 10.0f),
          "a world-space CFrame is converted to a parent-local Transform");
    const glm::mat4 worldMatrix = engine::core::hierarchy::computeWorldMatrix(ecs, wall);
    check(nearlyEqual(worldMatrix[3][0], 110.0f),
          "the imported Part's composed WORLD position matches the CFrame the document specified");

    const auto* wallHierarchy = ecs.tryGetComponent<engine::core::Hierarchy>(wall);
    check(wallHierarchy != nullptr && wallHierarchy->parent != engine::core::kNullEntity,
          "an imported Part is really parented to its Model");

    const auto* light = ecs.tryGetComponent<engine::core::Light>(lamp);
    check(light != nullptr && nearlyEqual(light->intensity, 3.0f), "a PointLight's Brightness becomes Light intensity");
    check(light != nullptr && nearlyEqual(light->radius, 12.0f), "a PointLight's Range becomes Light radius");
    check(light != nullptr && nearlyEqual(light->color.g, 0.5f, 1e-3f), "a PointLight's Color decodes");

    // Imported scripts must not auto-run: they almost always reference
    // Roblox APIs Kronos does not have, and running them on import sprays
    // errors over the report the author is trying to read.
    bool sawScript = false;
    for (auto entity : result.createdEntities) {
        if (const auto* script = ecs.tryGetComponent<engine::core::Script>(entity)) {
            sawScript = true;
            check(!script->autoRun, "an imported script does not auto-run by default");
            check(script->source == "print(\"hello\")", "an imported script really carries its source");
        }
    }
    check(sawScript, "hydration really attached a Script component");

    engine::core::ECS scaledEcs;
    engine::migration::HydrationOptions scaled;
    scaled.studsToUnits = 0.5f;
    const auto scaledResult = hydrator.hydrate(tree, scaledEcs, meshes, scaled);
    for (auto entity : scaledResult.createdEntities) {
        const auto* name = scaledEcs.tryGetComponent<engine::core::Name>(entity);
        if (name == nullptr || name->value != "Wall") continue;
        const auto* scaledTransform = scaledEcs.tryGetComponent<engine::core::Transform>(entity);
        check(scaledTransform != nullptr && nearlyEqual(scaledTransform->scale.y, 1.5f),
              "stud scaling really scales imported part sizes");
    }

    check(engine::migration::InstanceHydrator::isSupportedClass("Part"), "Part is a supported class");
    check(!engine::migration::InstanceHydrator::isSupportedClass("Smoke"), "Smoke is honestly reported unsupported");
}

// The asset converters, which were four "not yet implemented" stubs.
void testAssetConverters() {
    engine::migration::AssetConverter converter;

    check(engine::migration::AssetConverter::detectKind("a.obj") == engine::migration::AssetKind::Mesh,
          "detectKind classifies .obj as a mesh");
    check(engine::migration::AssetConverter::detectKind("a.png") == engine::migration::AssetKind::Texture,
          "detectKind classifies .png as a texture");
    check(engine::migration::AssetConverter::detectKind("a.zzz") == engine::migration::AssetKind::Unknown,
          "detectKind reports an unknown extension honestly");

    const std::string objPath = "test_import_cube.obj";
    {
        std::ofstream out(objPath);
        out << "v 0 0 0\nv 1 0 0\nv 1 1 0\nv 0 1 0\n";
        out << "vn 0 0 1\n";
        out << "f 1//1 2//1 3//1\nf 1//1 3//1 4//1\n";
    }
    engine::migration::MeshConversionData meshData;
    auto meshResult = converter.convertMesh(objPath, meshData);
    check(meshResult.succeeded, "convertMesh really converts a .obj");
    check(meshData.vertices.size() >= 4, "convertMesh produces real vertex data");
    check(meshData.indices.size() == 6, "convertMesh produces real index data for two triangles");
    check(nearlyEqual(meshData.boundsMax.x, 1.0f) && nearlyEqual(meshData.boundsMin.x, 0.0f),
          "convertMesh computes real bounds from the geometry");
    std::remove(objPath.c_str());

    engine::migration::MeshConversionData emptyMesh;
    auto fbxResult = converter.convertMesh("model.fbx", emptyMesh);
    check(!fbxResult.succeeded, "convertMesh refuses .fbx rather than half-parsing it");
    check(fbxResult.message.find("obj") != std::string::npos, "the .fbx refusal explains what IS supported");
    auto missingResult = converter.convertMesh("does_not_exist.obj", emptyMesh);
    check(!missingResult.succeeded && missingResult.message.find("not found") != std::string::npos,
          "convertMesh reports a missing file as missing");

    engine::migration::PropertyMap partProps;
    partProps["@type.Color3uint8"] = "Color3uint8";
    partProps["Color3uint8"] = "255";
    partProps["Reflectance"] = "1";
    partProps["Transparency"] = "0.5";
    const auto material = engine::migration::AssetConverter::materialFromProperties(partProps);
    check(nearlyEqual(material.baseColor.b, 1.0f, 1e-2f), "convertMaterial maps Color to baseColor");
    check(nearlyEqual(material.baseColor.a, 0.5f), "Roblox Transparency inverts into Kronos alpha");
    check(material.metallic > 0.0f, "Reflectance drives metallic rather than being dropped");
    check(material.roughness < 0.3f, "Reflectance drives roughness down");

    const std::string materialPath = "test_import_material.rbxmx";
    {
        std::ofstream out(materialPath);
        out << "<roblox version=\"4\"><Item class=\"Part\"><Properties>";
        out << "<float name=\"Reflectance\">0.25</float>";
        out << "<float name=\"Transparency\">0</float>";
        out << "</Properties></Item></roblox>";
    }
    engine::migration::MaterialConversionData fileMaterial;
    auto materialResult = converter.convertMaterial(materialPath, fileMaterial);
    check(materialResult.succeeded, "convertMaterial really reads a material document");
    check(fileMaterial.metallic > 0.0f, "a converted material file carries real PBR values");
    std::remove(materialPath.c_str());

    const std::string animPath = "test_import_anim.rbxmx";
    {
        std::ofstream out(animPath);
        out << "<roblox version=\"4\"><Item class=\"KeyframeSequence\">";
        out << "<Properties><string name=\"Name\">Wave</string><bool name=\"Loop\">true</bool></Properties>";
        out << "<Item class=\"Keyframe\"><Properties><float name=\"Time\">0</float></Properties>";
        out << "<Item class=\"Pose\"><Properties><string name=\"Name\">RightArm</string>";
        out << "<CoordinateFrame name=\"CFrame\"><X>0</X><Y>0</Y><Z>0</Z>";
        out << "<R00>1</R00><R01>0</R01><R02>0</R02><R10>0</R10><R11>1</R11><R12>0</R12>";
        out << "<R20>0</R20><R21>0</R21><R22>1</R22></CoordinateFrame></Properties></Item></Item>";
        out << "<Item class=\"Keyframe\"><Properties><float name=\"Time\">1.5</float></Properties>";
        out << "<Item class=\"Pose\"><Properties><string name=\"Name\">RightArm</string>";
        out << "<CoordinateFrame name=\"CFrame\"><X>2</X><Y>0</Y><Z>0</Z>";
        out << "<R00>1</R00><R01>0</R01><R02>0</R02><R10>0</R10><R11>1</R11><R12>0</R12>";
        out << "<R20>0</R20><R21>0</R21><R22>1</R22></CoordinateFrame></Properties></Item></Item>";
        out << "</Item></roblox>";
    }
    engine::migration::AnimationConversionData animData;
    auto animResult = converter.convertAnimation(animPath, animData);
    check(animResult.succeeded, "convertAnimation really converts a KeyframeSequence");
    check(animData.looping, "convertAnimation reads the Loop flag");
    check(nearlyEqual(animData.durationSeconds, 1.5f), "convertAnimation measures the real duration");
    check(!animData.channels.empty(), "convertAnimation produces real channels");
    bool sawPositionX = false;
    for (const auto& channel : animData.channels) {
        if (channel.channelName != "position.x") continue;
        sawPositionX = true;
        check(channel.keys.size() == 2, "a converted channel carries a key per keyframe");
        check(channel.keys.front().first <= channel.keys.back().first,
              "converted channel keys are sorted by time, as the samplers require");
        check(nearlyEqual(channel.keys.back().second, 2.0f), "a converted key carries its real value");
    }
    check(sawPositionX, "convertAnimation produces a position channel");
    std::remove(animPath.c_str());

    engine::migration::AnimationConversionData emptyAnim;
    auto badAnim = converter.convertAnimation("no_such_anim.rbxmx", emptyAnim);
    check(!badAnim.succeeded, "convertAnimation reports a missing file rather than an empty animation");
}

void testRequirePathsAndCycles() {
    engine::core::Scripting scripting;
    check(scripting.initialize(), "require validation: Scripting::initialize() succeeds");

    scripting.setModuleResolver([](const std::string& path, engine::core::SecurityIdentity,
                                    std::string& outSource, std::string& outError) {
        if (path == "Shared/Math") { outSource = "return { add = function(a, b) return a + b end }"; return true; }
        if (path == "A") { outSource = "local b = require(\"B\") return { name = \"A\" }"; return true; }
        if (path == "B") { outSource = "local a = require(\"A\") return { name = \"B\" }"; return true; }
        if (path == "Self") { outSource = "local s = require(\"Self\") return {}"; return true; }
        if (path == "Throws") { outSource = "error(\"module blew up\")"; return true; }
        outError = "no such module";
        return false;
    });

    // Root and relative spellings of the SAME module must resolve to the
    // same cached value, not merely each succeed -- otherwise an imported
    // project silently runs a module's side effects several times.
    std::string out = runScriptCapturingOutput(scripting, "Paths", R"LUA(
        local canonical = require("Shared/Math")
        assert(canonical.add(2, 3) == 5, "the module did not really work")
        for _, spelling in ipairs({"./Shared/Math", "Shared//Math", "Shared/./Math", "Shared/Math/"}) do
            local ok, m = pcall(require, spelling)
            assert(ok, "spelling " .. spelling .. " failed to resolve: " .. tostring(m))
            assert(m == canonical, "spelling " .. spelling .. " resolved to a DIFFERENT module instance")
        end
    )LUA", engine::core::SecurityIdentity::UserScript);
    check(out.empty(), "require() normalises root/relative path spellings to one cached module");

    // A cycle must be reported as a cycle. Before this it recursed until
    // Luau's C-stack guard fired and reported "C stack overflow", which
    // names neither module involved.
    out = runScriptCapturingOutput(scripting, "Cycle", R"LUA(
        local ok, err = pcall(require, "A")
        assert(not ok, "a circular require unexpectedly SUCCEEDED")
        assert(string.find(err, "circular dependency", 1, true) ~= nil,
               "a circular require did not report a circular dependency: " .. tostring(err))
        assert(string.find(err, "A -> B -> A", 1, true) ~= nil,
               "the cycle error did not name the chain: " .. tostring(err))
        assert(string.find(err, "C stack overflow", 1, true) == nil,
               "the cycle still blew the C stack: " .. tostring(err))
    )LUA", engine::core::SecurityIdentity::UserScript);
    check(out.empty(), "require() reports a circular dependency and names the chain instead of overflowing the stack");

    out = runScriptCapturingOutput(scripting, "SelfCycle", R"LUA(
        local ok, err = pcall(require, "Self")
        assert(not ok, "a self-require unexpectedly SUCCEEDED")
        assert(string.find(err, "circular dependency", 1, true) ~= nil,
               "a self-require was not reported as circular: " .. tostring(err))
    )LUA", engine::core::SecurityIdentity::UserScript);
    check(out.empty(), "require() reports the degenerate self-require cycle too");

    // A module that throws must not be left marked in-progress: the retry
    // has to report the module's own error again, never a false cycle.
    out = runScriptCapturingOutput(scripting, "Throwing", R"LUA(
        local ok1, err1 = pcall(require, "Throws")
        local ok2, err2 = pcall(require, "Throws")
        assert(not ok1 and not ok2, "a throwing module unexpectedly succeeded")
        assert(string.find(err2, "circular dependency", 1, true) == nil,
               "retrying a throwing module was misreported as a cycle: " .. tostring(err2))
        assert(string.find(err2, "module blew up", 1, true) ~= nil,
               "the retry lost the module's real error: " .. tostring(err2))
    )LUA", engine::core::SecurityIdentity::UserScript);
    check(out.empty(), "require() clears its in-progress marker when a module throws, so a retry is not a false cycle");

    // The traversal guard must survive normalisation -- normalising must
    // not turn a rejected path into an allowed one.
    out = runScriptCapturingOutput(scripting, "Guards", R"LUA(
        assert(not pcall(require, "../secrets"), "traversal was NOT blocked")
        assert(not pcall(require, "./../secrets"), "traversal via ./.. was NOT blocked")
        assert(not pcall(require, "/etc/passwd"), "absolute path was NOT blocked")
        assert(not pcall(require, "\\windows\\system32"), "backslash absolute path was NOT blocked")
    )LUA", engine::core::SecurityIdentity::UserScript);
    check(out.empty(), "require() path normalisation does not weaken the traversal or absolute-path guards");
}

// The API compatibility scan is what turns "crashes mid-session on a nil
// global" into "warned at import time".
void testLuauApiCompatibilityScan() {
    engine::migration::LuauApiCompatibility compat;
    check(compat.registrySize() > 0, "LuauApiCompatibility really registers APIs");

    const std::string script = R"LUA(
local Players = game:GetService("Players")
local part = Instance.new("Part")
part.Parent = workspace
world.setPosition(part, 1, 2, 3)
)LUA";
    const auto findings = compat.scan(script);

    auto found = [&](const char* id) {
        for (const auto& f : findings) {
            if (f.identifier == id) return true;
        }
        return false;
    };
    check(found("game"), "the API scan finds an unmapped `game` reference");
    check(found("Instance"), "the API scan finds an unmapped `Instance` reference");
    check(found("workspace"), "the API scan finds an unmapped `workspace` reference");
    check(found("world"), "the API scan also records the mapped Kronos APIs a script already uses");

    for (const auto& f : findings) {
        if (f.identifier == "game") {
            check(f.status == engine::migration::ApiMappingStatus::Unmapped, "`game` is classified as unmapped");
            check(f.line == 2, "the API scan reports the real 1-based line of a finding");
            check(!f.guidance.empty(), "an unmapped API finding carries real migration guidance");
        }
        if (f.identifier == "world") {
            check(f.status == engine::migration::ApiMappingStatus::Mapped, "`world` is classified as mapped");
        }
    }

    // Comments and strings must not produce findings. A substring scanner
    // reports all three of these and buries the real warnings in noise.
    const auto quiet = compat.scan(R"LUA(
-- ported from the old game, see workspace notes
local label = "Instance.new is not called here"
--[[ workspace
     game ]]
local gamemode = 1
local ungame = gamemode
)LUA");
    check(quiet.empty(), "the API scan ignores comments, strings and identifiers that merely contain an API name");

    // Method-call form.
    const auto shimmed = compat.scan("local track = humanoid:LoadAnimation(anim)");
    bool sawShim = false;
    for (const auto& f : shimmed) {
        if (f.identifier == ":LoadAnimation") {
            sawShim = true;
            check(f.status == engine::migration::ApiMappingStatus::Shimmed,
                  "a legacy call site with a compat shim is reported as shimmed, not unmapped");
        }
    }
    check(sawShim, "the API scan finds a legacy method call site");

    const auto lines = compat.buildReportLines("Workspace.Main", script);
    check(!lines.empty(), "buildReportLines produces real report lines");
    bool allTagged = true;
    for (const auto& line : lines) {
        if (line.rfind("[warn] ", 0) != 0 && line.rfind("[info] ", 0) != 0) allTagged = false;
        if (line.find("Workspace.Main:") == std::string::npos) allTagged = false;
    }
    check(allTagged, "every report line is severity-tagged and names the script and line");
}

// Full-project ingestion: the end-to-end pipeline, plus the benchmark the
// import pass is supposed to verify.
void testProjectImportPipeline() {
    engine::migration::ProjectImporter importer;
    engine::safety::IPInfringementScanner scanner;

    const std::string document = R"XML(<roblox version="4">
  <Item class="Workspace" referent="RBX0">
    <Properties><string name="Name">Workspace</string></Properties>
    <Item class="Model" referent="RBX1">
      <Properties><string name="Name">Lobby</string></Properties>
      <Item class="Part" referent="RBX2">
        <Properties><string name="Name">Floor</string></Properties>
      </Item>
      <Item class="Script" referent="RBX3">
        <Properties>
          <string name="Name">Main</string>
          <string name="Source">local p = game:GetService("Players")
local part = Instance.new("Part")</string>
        </Properties>
      </Item>
    </Item>
  </Item>
  <Item class="ReplicatedStorage" referent="RBX4">
    <Properties><string name="Name">Shared</string></Properties>
    <Item class="ModuleScript" referent="RBX5">
      <Properties>
        <string name="Name">Util</string>
        <string name="Source">return { clamp = function(v) return v end }</string>
      </Properties>
    </Item>
    <Item class="LocalScript" referent="RBX6">
      <Properties><string name="Name">Empty</string></Properties>
    </Item>
  </Item>
</roblox>)XML";

    const auto report = importer.importDocument(document, scanner);

    check(report.parsed, "ProjectImporter really parses a .rbxlx document");
    check(report.stats.instanceCount == 7, "ProjectImporter counts every instance in the hierarchy");
    check(report.stats.scriptCount == 3, "ProjectImporter counts Script, LocalScript and ModuleScript alike");
    check(report.stats.moduleScriptCount == 1, "ProjectImporter counts ModuleScripts separately");
    check(report.stats.maxDepth == 3, "ProjectImporter measures the real hierarchy depth");
    check(report.stats.totalScriptBytes > 0, "ProjectImporter really ingests script source");
    check(!report.tree.empty(), "ProjectImporter returns the built instance tree");

    // The unmapped APIs in Main must surface as warnings against the real
    // instance path, not vanish or throw.
    bool warnedAboutGame = false;
    bool warnedAboutEmptySource = false;
    for (const auto& diagnostic : report.diagnostics) {
        if (diagnostic.subject.rfind("Workspace.Lobby.Main:", 0) == 0 &&
            diagnostic.message.find("game") != std::string::npos) {
            warnedAboutGame = true;
            check(diagnostic.severity == engine::migration::ImportSeverity::Warning,
                  "an unmapped API is reported at Warning severity");
        }
        if (diagnostic.message.find("no Source property") != std::string::npos) warnedAboutEmptySource = true;
    }
    check(warnedAboutGame, "ProjectImporter warns about unmapped APIs against the real instance path");
    check(warnedAboutEmptySource, "ProjectImporter warns about a script that arrived with no Source");
    check(report.warningCount() > 0, "ProjectImporter's report really counts its warnings");
    check(!report.summary().empty(), "ProjectImporter produces a one-line summary");

    // Malformed input is a refusal, not a crash or a silent empty import.
    const auto broken = importer.importDocument("this is not xml at all", scanner);
    check(!broken.parsed, "ProjectImporter reports a malformed document as unparsed");
    check(broken.blocked, "ProjectImporter blocks a document it could not parse");
    check(broken.stats.instanceCount == 0, "a failed parse ingests nothing");
    check(broken.summary().find("import failed") != std::string::npos,
          "a failed parse says so in its summary rather than reporting an empty success");

    // An empty-but-valid document is a real, successful, empty import --
    // distinct from a parse failure.
    const auto empty = importer.importDocument("<roblox version=\"4\"></roblox>", scanner);
    check(empty.parsed, "an empty document still parses");
    check(!empty.blocked, "an empty document is not blocked");
    check(empty.stats.instanceCount == 0, "an empty document ingests no instances");

    // --- ingestion benchmark ------------------------------------------------
    // A synthetic project large enough that an accidental quadratic in the
    // walk or the scanner would show up as a timeout rather than passing
    // quietly.
    constexpr int kModels = 200;
    std::string big = "<roblox version=\"4\">";
    for (int i = 0; i < kModels; ++i) {
        big += "<Item class=\"Model\" referent=\"M" + std::to_string(i) + "\">";
        big += "<Properties><string name=\"Name\">Model" + std::to_string(i) + "</string></Properties>";
        big += "<Item class=\"Part\" referent=\"P" + std::to_string(i) + "\">";
        big += "<Properties><string name=\"Name\">Part" + std::to_string(i) + "</string></Properties></Item>";
        big += "<Item class=\"Script\" referent=\"S" + std::to_string(i) + "\">";
        big += "<Properties><string name=\"Name\">S" + std::to_string(i) + "</string>";
        big += "<string name=\"Source\">local x = game.Workspace\nworld.createEntity()\n</string>";
        big += "</Properties></Item></Item>";
    }
    big += "</roblox>";

    const auto benchmark = importer.importDocument(big, scanner);
    check(benchmark.parsed, "the import benchmark project parses");
    check(benchmark.stats.instanceCount == static_cast<size_t>(kModels) * 3,
          "the import benchmark ingests every instance in the project");
    check(benchmark.stats.scriptCount == static_cast<size_t>(kModels),
          "the import benchmark ingests every script in the project");
    check(benchmark.warningCount() >= static_cast<size_t>(kModels),
          "the import benchmark surfaces a migration warning for every script that needs one");
    // Generous on purpose: this is a regression guard against an
    // accidental quadratic, not a performance target to tune against.
    check(benchmark.stats.elapsedMilliseconds < 5000.0,
          "the import benchmark ingests a 600-instance project in well under 5 seconds");
    std::fprintf(stderr, "  [benchmark] imported %zu instances / %zu scripts in %.2f ms\n",
                 benchmark.stats.instanceCount, benchmark.stats.scriptCount,
                 benchmark.stats.elapsedMilliseconds);

    // --- IP safety severity mapping ----------------------------------------
    // A hard-block term must stop the import; a merely-flagged one must
    // not. Reporting a fuzzy match as "blocked" would be a false
    // accusation against the creator's own content.
    const std::string blockedDoc = R"XML(<roblox version="4">
  <Item class="Model" referent="B0"><Properties><string name="Name">Roblox Tycoon</string></Properties></Item>
</roblox>)XML";
    const auto blockedReport = importer.importDocument(blockedDoc, scanner);
    check(blockedReport.parsed, "the IP-blocked document still parses");
    check(blockedReport.blocked, "a hard-block trademark term really blocks the import");
    check(blockedReport.countOf(engine::migration::ImportSeverity::Blocked) > 0,
          "a hard-block term is reported at Blocked severity");

    const std::string reviewDoc = R"XML(<roblox version="4">
  <Item class="Model" referent="R0"><Properties><string name="Name">Adopt Me Clone</string></Properties></Item>
</roblox>)XML";
    const auto reviewReport = importer.importDocument(reviewDoc, scanner);
    check(!reviewReport.blocked, "a review-only IP match does NOT block the import");
    check(reviewReport.warningCount() > 0, "a review-only IP match is still reported, as a warning");

    // Roblox's own service containers must not be scanned: "ReplicatedStorage"
    // fuzzy-matches "Roblox", so without the suppression every place file
    // on the platform would carry a meaningless finding.
    const std::string servicesDoc = R"XML(<roblox version="4">
  <Item class="ReplicatedStorage" referent="S0"><Properties><string name="Name">ReplicatedStorage</string></Properties></Item>
  <Item class="Workspace" referent="S1"><Properties><string name="Name">Workspace</string></Properties></Item>
</roblox>)XML";
    const auto servicesReport = importer.importDocument(servicesDoc, scanner);
    check(!servicesReport.blocked, "an untouched service container does not block an import");
    check(servicesReport.diagnostics.empty(),
          "Roblox's own service containers produce no IP findings when still at their default names");

    // A container the creator RENAMED is theirs again, and is scanned.
    const std::string renamedDoc = R"XML(<roblox version="4">
  <Item class="ReplicatedStorage" referent="S2"><Properties><string name="Name">Roblox Tycoon</string></Properties></Item>
</roblox>)XML";
    const auto renamedReport = importer.importDocument(renamedDoc, scanner);
    check(renamedReport.blocked, "a service container renamed to a trademark term is still caught");
}


// Kronos ("Studio Movie Mode & Viewport Polish"): the interaction
// behaviours that make scrubbing and key dragging behave, none of which
// need an ImGui context to exercise.
void testMovieModeScrubbingAndKeyDrag() {
    // --- dragging a key past its neighbours ------------------------------
    std::vector<engine::cinematic::Keyframe> keys;
    keys.push_back(engine::cinematic::Keyframe{0.0f, 10.0f});
    keys.push_back(engine::cinematic::Keyframe{1.0f, 20.0f});
    keys.push_back(engine::cinematic::Keyframe{2.0f, 30.0f});

    // Drag the middle key past the last one.
    keys[1].timeSeconds = 3.0f;
    int index = engine::cinematic::reorderDraggedKeyframe(keys, 1);
    check(keys.size() == 3, "dragging a key past a neighbour keeps every key");
    check(index == 2, "reorderDraggedKeyframe returns the dragged key's new index");
    check(nearlyEqual(keys[static_cast<size_t>(index)].value, 20.0f),
          "the returned index still addresses the key that was being dragged, not a neighbour");
    check(keys[0].timeSeconds <= keys[1].timeSeconds && keys[1].timeSeconds <= keys[2].timeSeconds,
          "the track is still sorted after the drag");

    // Drag it back to the front.
    keys[static_cast<size_t>(index)].timeSeconds = -1.0f;
    index = engine::cinematic::reorderDraggedKeyframe(keys, index);
    check(index == 0, "dragging a key to the front reports index 0");
    check(nearlyEqual(keys[0].value, 20.0f), "the dragged key kept its identity across both directions");
    check(keys.size() == 3, "dragging back keeps every key");

    // The case that silently destroyed a key before: dragging one key
    // exactly onto another's time. insertKeyframe() would REPLACE it.
    keys[0].timeSeconds = keys[1].timeSeconds;
    index = engine::cinematic::reorderDraggedKeyframe(keys, 0);
    check(keys.size() == 3, "dragging a key exactly onto another's time destroys neither");
    check(index >= 0 && index < 3, "a colliding drag still returns a valid index");

    // A stale index from a key deleted mid-gesture is a no-op, not a
    // write past the end.
    const int stale = engine::cinematic::reorderDraggedKeyframe(keys, 99);
    check(stale == 99, "reorderDraggedKeyframe ignores an out-of-range index");
    check(keys.size() == 3, "an out-of-range reorder changes nothing");

    // --- scrubbing owns the transport ------------------------------------
    engine::studio::plugins::MovieModePlugin plugin;
    engine::core::ECS scrubEcs;
    plugin.sequence().setPlayhead(0.0f);
    plugin.sequence().play();

    // Not scrubbing: the transport advances normally.
    plugin.update(0.5f, scrubEcs, engine::core::kNullEntity, {});
    check(plugin.sequence().playheadSeconds() > 0.0f, "an un-scrubbed playing sequence really advances");

    // Scrubbing: the transport must NOT advance underneath the gesture.
    const float held = plugin.sequence().playheadSeconds();
    plugin.setScrubbingForTest(true);
    check(plugin.isScrubbing(), "setScrubbingForTest really puts the plugin in the scrubbing state");
    for (int frame = 0; frame < 10; ++frame) {
        plugin.update(0.016f, scrubEcs, engine::core::kNullEntity, {});
    }
    check(nearlyEqual(plugin.sequence().playheadSeconds(), held),
          "a held scrub stops the transport advancing underneath it");

    plugin.setScrubbingForTest(false);
    plugin.update(0.25f, scrubEcs, engine::core::kNullEntity, {});
    check(plugin.sequence().playheadSeconds() > held, "releasing the scrub resumes the transport");
}

void testMovieModePlugin() {
    engine::studio::plugins::MovieModePlugin plugin;

    // One track per TrackKind -- the six the sequencer models.
    const auto& tracks = plugin.sequence().tracks();
    check(tracks.size() == 6, "MovieModePlugin seeds a 6-track sequence, one per TrackKind");
    bool sawEveryKind = true;
    for (int kind = 0; kind <= static_cast<int>(engine::cinematic::TrackKind::ScriptTrigger); ++kind) {
        bool found = false;
        for (const auto& track : tracks) {
            if (static_cast<int>(track.kind) == kind) found = true;
        }
        if (!found) sawEveryKind = false;
    }
    check(sawEveryKind, "MovieModePlugin's seeded tracks cover every TrackKind");

    // Seeded with real, sampleable content rather than empty tracks.
    check(plugin.sequence().durationSeconds() > 0.0f, "MovieModePlugin's seeded sequence has a real duration");
    check(nearlyEqual(plugin.sequence().sampleChannel("Prop Transform", "y", 3.0f, -1.0f), 2.0f),
          "MovieModePlugin's seeded Transform track really samples its keyed value");

    // --- rail exposed to the viewport gizmo ------------------------------
    check(plugin.rail().pointCount() == 3, "MovieModePlugin seeds a rail with real control points");
    const glm::vec3 original = plugin.rail().points()[1].position;
    plugin.moveRailPoint(1, glm::vec3(1.0f, 2.0f, 3.0f));
    check(plugin.rail().points()[1].position == glm::vec3(1.0f, 2.0f, 3.0f),
          "MovieModePlugin::moveRailPoint moves the addressed control point");
    check(plugin.rail().pointCount() == 3, "MovieModePlugin::moveRailPoint preserves the other points");
    check(plugin.rail().points()[0].position != plugin.rail().points()[1].position,
          "MovieModePlugin::moveRailPoint leaves neighbouring points alone");
    plugin.moveRailPoint(1, original);

    // Out-of-range indices are an honest no-op, not a write past the end.
    // A viewport drag can outlive the point it grabbed.
    plugin.moveRailPoint(99, glm::vec3(50.0f));
    plugin.moveRailPoint(-1, glm::vec3(50.0f));
    check(plugin.rail().pointCount() == 3, "MovieModePlugin::moveRailPoint ignores out-of-range indices");
    bool noneFlung = true;
    for (const auto& point : plugin.rail().points()) {
        if (point.position.x >= 50.0f) noneFlung = false;
    }
    check(noneFlung, "MovieModePlugin::moveRailPoint's out-of-range no-op really wrote nothing");

    // --- playhead -> rail parameter ---------------------------------------
    plugin.sequence().setPlayhead(0.0f);
    check(nearlyEqual(plugin.railParameterAtPlayhead(), 0.0f),
          "MovieModePlugin::railParameterAtPlayhead is 0 at the start of the sequence");
    plugin.sequence().setPlayhead(plugin.sequence().durationSeconds());
    check(nearlyEqual(plugin.railParameterAtPlayhead(), 1.0f),
          "MovieModePlugin::railParameterAtPlayhead is 1 at the end of the sequence");
    // Clamped, not extrapolated: a playhead past the end must not index
    // off the rail.
    plugin.sequence().setPlayhead(plugin.sequence().durationSeconds() * 4.0f);
    check(plugin.railParameterAtPlayhead() <= 1.0f,
          "MovieModePlugin::railParameterAtPlayhead clamps past the end of the sequence");
    plugin.sequence().setPlayhead(0.0f);

    // --- the export path the modal's Render button drives ------------------
    std::string error;
    check(plugin.buildExport(error), "MovieModePlugin::buildExport accepts the default settings");
    check(error.empty(), "MovieModePlugin::buildExport reports no error on success");
    const int expectedFrames =
        engine::cinematic::exportFrameCount(plugin.exportSettings(), plugin.sequence().durationSeconds());
    check(static_cast<int>(plugin.lastExportSchedule().size()) == expectedFrames,
          "MovieModePlugin::buildExport schedules exactly exportFrameCount() frames");
    check(expectedFrames > 0, "MovieModePlugin's default export really covers the seeded sequence");

    // Motion blur must widen each job's sample list, not the frame count.
    plugin.exportSettings().motionBlur.enabled = true;
    plugin.exportSettings().motionBlur.subFrameSamples = 4;
    check(plugin.buildExport(error), "MovieModePlugin::buildExport accepts motion-blur settings");
    check(static_cast<int>(plugin.lastExportSchedule().size()) == expectedFrames,
          "MovieModePlugin's motion blur changes samples per frame, not the frame count");
    check(!plugin.lastExportSchedule().empty() && plugin.lastExportSchedule().front().sampleTimesSeconds.size() == 4,
          "MovieModePlugin's motion-blur jobs really carry their sub-frame samples");
    plugin.exportSettings().motionBlur.enabled = false;

    // Invalid settings are refused up front, and the refusal clears the
    // stale schedule rather than leaving a previous run's frames behind.
    plugin.exportSettings().channels.clear();
    check(!plugin.buildExport(error), "MovieModePlugin::buildExport refuses an export with no channels");
    check(!error.empty(), "MovieModePlugin::buildExport explains why it refused");
    check(plugin.lastExportSchedule().empty(), "MovieModePlugin::buildExport clears the schedule when it refuses");
}

